-- Native source clan_innata_private.assert_no_combat_authority(uuid,uuid) MD5 efef324b24cd6f8b0b811438d2cc8e87

CREATE OR REPLACE FUNCTION clan_innata_private.assert_no_combat_authority(p_character uuid, p_technique uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_character IS NULL OR p_technique IS NULL THEN RETURN; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_character::text||':'||p_technique::text,0));
 IF EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state s
   JOIN public.combat_v2_actors a ON a.id=s.actor_id AND a.session_id=s.session_id
   JOIN LATERAL clan_innata_private.combat_context(a.id) c ON true
   WHERE a.character_id=p_character AND s.technique_id=p_technique AND c.phase<>'closed') THEN
   RAISE EXCEPTION 'common_use_combat_panel' USING ERRCODE='40001'; END IF;
END $function$;

