CREATE OR REPLACE FUNCTION clan_innata_private.combat_actor_context(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a
   WHERE a.id=p_actor AND a.controller_user=auth.uid()) THEN
   RAISE EXCEPTION 'common_combat_actor_not_owned' USING ERRCODE='42501'; END IF;
 RETURN clan_innata_private.combat_scope(p_actor);
END $function$;

