GRANT EXECUTE ON FUNCTION clan_innata_private.combat_begin_turn(uuid) TO "postgres";

RESET ROLE;

-- Native source clan_innata_private.combat_context(uuid) MD5 1b9b6fe6d17e17a577f70b10bd5ba3fb

CREATE OR REPLACE FUNCTION clan_innata_private.combat_context(p_actor uuid)
 RETURNS clan_innata_combat_private.actor_context
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; s public.combat_v2_sessions%ROWTYPE;
 m public.master_v2_sessions%ROWTYPE; r public.combat_v2_rounds%ROWTYPE;
 t combat_panel_private.actor_turns%ROWTYPE; result clan_innata_combat_private.actor_context;
BEGIN
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 SELECT c.session_id,c.location_id,c.exchange_id,c.turn_actor_id,c.phase,c.policy_id,c.context_version,
   'ordinary_v2',c.exchange_id INTO result FROM combat_consumer_private.activities c WHERE c.session_id=a.session_id;
 IF FOUND THEN RETURN result; END IF;
 SELECT * INTO STRICT s FROM public.combat_v2_sessions WHERE id=a.session_id;
 SELECT m0.* INTO m FROM public.master_v2_sessions m0
   JOIN combat_panel_private.master_panel_sessions registered ON registered.master_session_id=m0.id
   WHERE m0.id=s.master_session_id;
 IF m.id IS NULL THEN RAISE EXCEPTION 'common_combat_context_not_registered' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.combat_v2_rounds WHERE session_id=s.id ORDER BY round_no DESC LIMIT 1;
 SELECT * INTO t FROM combat_panel_private.actor_turns WHERE round_id=r.id AND actor_id=a.id;
 result.session_id:=s.id; result.location_id:=m.location_id; result.exchange_id:=r.id;
 result.activity_kind:='master_v2'; result.personal_turn_id:=t.id;
 SELECT policy_id INTO STRICT result.policy_id FROM combat_panel_private.master_panel_sessions WHERE master_session_id=m.id;
 result.context_version:=CASE t.state WHEN 'ready' THEN 1 WHEN 'declared' THEN 2 WHEN 'ended' THEN 3 ELSE 0 END;
 result.turn_actor_id:=CASE WHEN t.state IN ('ready','declared') THEN a.id END;
 result.phase:=CASE WHEN m.stato IN ('chiusa','annullata') OR s.closed_at IS NOT NULL THEN 'closed'
   WHEN m.stato='sospesa' OR s.state='sospeso' THEN 'suspended'
   WHEN t.state='ended' THEN 'resolved'
   WHEN r.id IS NULL OR t.id IS NULL OR NOT combat_panel_private.has_master_geometry(s.id) THEN 'setup'
   WHEN r.phase='raccolta_azioni' THEN CASE WHEN t.state='ready' THEN 'action' ELSE 'committed' END
   WHEN r.phase='raccolta_difese' THEN 'defense'
   WHEN r.phase IN ('congelato','valutazione') THEN 'review'
   WHEN r.phase='risoluzione' THEN 'resolving'
   WHEN r.phase IN ('risolto','narrazione','narrato') THEN 'resolved' ELSE 'setup' END;
 RETURN result;
END $function$;

