REVOKE ALL ON FUNCTION clan_innata_private.combat_context(uuid) FROM PUBLIC,"anon","authenticated","postgres","service_role";

GRANT EXECUTE ON FUNCTION clan_innata_private.combat_context(uuid) TO "postgres";

RESET ROLE;

-- Native source clan_innata_private.combat_scope(uuid) MD5 6926b9f45706dbdbf98104a8895c3710

CREATE OR REPLACE FUNCTION clan_innata_private.combat_scope(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; c combat_consumer_private.activities%ROWTYPE;
  pg public.characters%ROWTYPE; v_test boolean;
BEGIN
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 IF NOT EXISTS(SELECT 1 FROM combat_consumer_private.activities WHERE session_id=a.session_id) THEN
   RETURN clan_innata_private.master_combat_scope(p_actor);
 END IF;
 SELECT * INTO STRICT c FROM combat_consumer_private.activities WHERE session_id=a.session_id;
 IF a.controller_user IS NULL OR a.actor_kind<>'pg'
   OR a.state<>'attivo' OR c.phase='closed'
   OR jsonb_typeof(a.mechanics_snapshot->'vita') IS DISTINCT FROM 'number'
   OR coalesce((a.mechanics_snapshot->>'vita')::integer,0)<=0 OR NOT EXISTS(
     SELECT 1 FROM combat_consumer_private.members m WHERE m.session_id=a.session_id
       AND m.actor_id=a.id AND m.character_id=a.character_id) THEN
   RAISE EXCEPTION 'common_combat_actor_not_owned' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT pg FROM public.characters WHERE id=a.character_id AND user_id=a.controller_user;
 v_test:=NOT public.combat_v2_values_written(a.session_id);
 IF v_test THEN
   IF c.policy_id<>'staff_test_no_persistent_resources_v1'
     OR NOT coalesce(a.character_id='6bceee99-974f-426b-8d92-38b43b4a4267'::uuid
   AND c.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   AND c.policy_id='staff_test_no_persistent_resources_v1' AND c.phase<>'closed'
   AND c.closed_at IS NULL AND NOT public.combat_v2_values_written(a.session_id)
   AND EXISTS(SELECT 1 FROM public.combat_v2_sessions ss WHERE ss.id=a.session_id
     AND ss.location_id=c.location_id AND ss.closed_at IS NULL
     AND ss.state NOT IN ('chiusa','annullata'))
   AND (SELECT count(*) FROM public.combat_v2_actors x
     WHERE x.session_id=a.session_id AND x.actor_kind='pg')=2
   AND (SELECT count(*) FROM combat_consumer_private.members m WHERE m.session_id=a.session_id)=2
   AND EXISTS(SELECT 1 FROM combat_consumer_private.members m
     JOIN public.combat_v2_actors x ON x.id=m.actor_id AND x.session_id=m.session_id
       AND x.character_id=m.character_id AND x.actor_kind='pg'
     JOIN public.characters staff_pg ON staff_pg.id=x.character_id AND staff_pg.user_id=x.controller_user
     WHERE m.session_id=a.session_id
     HAVING count(*)=2 AND count(DISTINCT x.controller_user)=2
       AND array_agg(DISTINCT x.character_id ORDER BY x.character_id)=ARRAY[
         '2a877f02-4993-4e65-9172-7d29f08c5b86'::uuid,'6bceee99-974f-426b-8d92-38b43b4a4267'::uuid]
       AND combat_consumer_private.staff_test_allowed(c.location_id,
         array_agg(DISTINCT x.controller_user ORDER BY x.controller_user),false)),false)
     OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.staff_profiles p
       WHERE p.session_id=a.session_id AND p.actor_id=a.id AND p.profile_version='sabaku-trasporto-l1/1')
     OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.release_gate WHERE singleton AND staff_enabled) THEN
     RAISE EXCEPTION 'common_combat_test_scope_invalid' USING ERRCODE='42501'; END IF;
 ELSE
   IF c.policy_id IS DISTINCT FROM 'free_duel_nonlethal_real_resources_v1'
     OR pg.clan IS DISTINCT FROM 'Sabaku' OR coalesce(pg.kekkei_genkai,0)<30
     OR coalesce(public._grade_rank(pg.rank),-1)<public._grade_rank('Genin')
     OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.release_gate WHERE singleton AND public_enabled)
     OR NOT EXISTS(SELECT 1 FROM public.character_abilities ca
       WHERE ca.character_id=pg.id AND ca.technique_id='001f907c-8f32-4758-8a16-ad1730e72c59' AND ca.state='attiva') THEN
     RAISE EXCEPTION 'common_combat_sabaku_not_eligible' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN jsonb_build_object('actor_id',a.id,'session_id',a.session_id,'character_id',a.character_id,
   'round_id',c.exchange_id,'context_version',c.context_version,'is_test',v_test,
   'policy_id',c.policy_id,'turn_owner',c.turn_actor_id=a.id,'phase',c.phase);
END $function$;

