CREATE OR REPLACE FUNCTION clan_innata_private.combat_state_ensure(p_actor uuid)
 RETURNS clan_innata_combat_private.combat_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; s clan_innata_combat_private.combat_state%ROWTYPE;
 stored clan_innata_combat_private.combat_state%ROWTYPE;
 t constant uuid:='001f907c-8f32-4758-8a16-ad1730e72c59';
BEGIN
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=a.session_id FOR UPDATE;
 PERFORM 1 FROM combat_consumer_private.activities WHERE session_id=a.session_id FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE id=a.id FOR UPDATE;
 -- Stessa serializzazione dei due writer Common precedenti, prima dei saldi.
 PERFORM pg_advisory_xact_lock(hashtextextended(a.character_id::text||':'||t::text,0));
 PERFORM clan_innata_private.runtime_release_assert();
 s:=clan_innata_private.combat_state_read(a.id);
 IF NOT s.is_test AND EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state other_state
   JOIN public.combat_v2_actors other_actor ON other_actor.id=other_state.actor_id
   JOIN LATERAL clan_innata_private.combat_context(other_actor.id) other_context ON true
   WHERE other_actor.character_id=a.character_id AND other_state.technique_id=t
     AND other_state.actor_id<>a.id AND NOT other_state.is_test AND other_context.phase<>'closed') THEN
   RAISE EXCEPTION 'common_combat_other_real_authority' USING ERRCODE='42501'; END IF;
 INSERT INTO clan_innata_combat_private.combat_state(session_id,actor_id,technique_id,is_test,active,state_version)
   VALUES(s.session_id,s.actor_id,s.technique_id,s.is_test,s.active,s.state_version)
   ON CONFLICT(session_id,actor_id,technique_id) DO NOTHING;
 SELECT * INTO STRICT stored FROM clan_innata_combat_private.combat_state
   WHERE session_id=a.session_id AND actor_id=a.id AND technique_id=t FOR UPDATE;
 IF (stored.is_test,stored.active,stored.state_version) IS DISTINCT FROM (s.is_test,s.active,s.state_version) THEN
   RAISE EXCEPTION 'common_combat_projection_drift' USING ERRCODE='40001'; END IF;
 RETURN stored;
END $function$;

