-- Native source clan_innata_private.combat_state_guard() MD5 9089e0831ef93a4f1ca0f6e2c2d33186

CREATE OR REPLACE FUNCTION clan_innata_private.combat_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; policy text; test boolean;
 canonical clan_innata_private.actor_state%ROWTYPE; cfg clan_innata_private.config_versions%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=NEW.actor_id AND session_id=NEW.session_id AND actor_kind='pg';
 SELECT c.policy_id INTO STRICT policy FROM clan_innata_private.combat_context(a.id) c;
 test:=policy='staff_test_no_persistent_resources_v1';
 IF policy NOT IN ('staff_test_no_persistent_resources_v1','free_duel_nonlethal_real_resources_v1','master_game_resources_v1')
   OR test IS DISTINCT FROM NOT public.combat_v2_values_written(a.session_id) OR NEW.is_test IS DISTINCT FROM test THEN
   RAISE EXCEPTION 'common_combat_storage_scope_invalid' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND (NEW.session_id,NEW.actor_id,NEW.technique_id,NEW.is_test)
   IS DISTINCT FROM (OLD.session_id,OLD.actor_id,OLD.technique_id,OLD.is_test) THEN
   RAISE EXCEPTION 'common_combat_storage_identity_changed' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND (NEW.state_version NOT IN (OLD.state_version,OLD.state_version+1)
   OR (NEW.active IS DISTINCT FROM OLD.active AND NEW.state_version<>OLD.state_version+1)) THEN
   RAISE EXCEPTION 'common_combat_state_version_invalid' USING ERRCODE='40001'; END IF;
 IF test THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(a.character_id::text||':'||NEW.technique_id::text,0));
 SELECT * INTO canonical FROM clan_innata_private.actor_state
   WHERE actor_id=a.character_id AND technique_id=NEW.technique_id FOR UPDATE;
 IF TG_OP='INSERT' THEN
   IF (NEW.active,NEW.state_version) IS DISTINCT FROM (coalesce(canonical.active,false),coalesce(canonical.state_version,0)) THEN
     RAISE EXCEPTION 'common_combat_initial_projection_invalid' USING ERRCODE='40001'; END IF;
   RETURN NEW;
 END IF;
 IF (OLD.active,OLD.state_version) IS DISTINCT FROM (coalesce(canonical.active,false),coalesce(canonical.state_version,0)) THEN
   RAISE EXCEPTION 'common_combat_canonical_drift' USING ERRCODE='40001'; END IF;
 IF NEW.state_version=OLD.state_version THEN RETURN NEW; END IF;
 SELECT * INTO STRICT cfg FROM clan_innata_private.config_versions WHERE technique_id=NEW.technique_id
   AND reviewed AND active AND (canonical.actor_id IS NULL OR config_version=canonical.config_version);
 IF cfg.activation_cost<>5 OR cfg.upkeep_cost<>5 THEN
   RAISE EXCEPTION 'common_combat_cost_config_drift' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM clan_innata_private.editorial_approvals approval
   WHERE approval.technique_id=cfg.technique_id AND approval.config_version=cfg.config_version AND approval.approved
     AND approval.approval_sha256=cfg.editorial_seal
     AND approval.approval_sha256=encode(extensions.digest(approval.canonical_preimage::text,'sha256'),'hex')
     AND approval.canonical_preimage=jsonb_build_object('technique_id',cfg.technique_id,'config_version',cfg.config_version,
       'activation_cost',cfg.activation_cost,'upkeep_cost',cfg.upkeep_cost)) THEN
   RAISE EXCEPTION 'editorial_seal_drift'; END IF;
 INSERT INTO clan_innata_private.actor_state(actor_id,technique_id,config_version,active,state_version,
   activation_paid,activation_source,activated_at)
 VALUES(a.character_id,NEW.technique_id,cfg.config_version,NEW.active,NEW.state_version,NEW.active,'panel',
   CASE WHEN NEW.active THEN clock_timestamp() END)
 ON CONFLICT(actor_id,technique_id) DO UPDATE SET active=excluded.active,state_version=excluded.state_version,
   activation_paid=CASE WHEN excluded.active THEN clan_innata_private.actor_state.activation_paid OR NOT OLD.active ELSE false END,
   activated_at=CASE WHEN excluded.active THEN coalesce(clan_innata_private.actor_state.activated_at,clock_timestamp()) END,
   updated_at=clock_timestamp();
 RETURN NEW;
END $function$;

