-- Native source clan_innata_private.combat_state_read(uuid) MD5 9b885e6418824468627d9b92d7352ce9

CREATE OR REPLACE FUNCTION clan_innata_private.combat_state_read(p_actor uuid)
 RETURNS clan_innata_combat_private.combat_state
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; s clan_innata_combat_private.combat_state%ROWTYPE;
 canonical clan_innata_private.actor_state%ROWTYPE; scope jsonb;
 t constant uuid:='001f907c-8f32-4758-8a16-ad1730e72c59';
BEGIN
 scope:=clan_innata_private.combat_scope(p_actor);
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 SELECT * INTO s FROM clan_innata_combat_private.combat_state
   WHERE session_id=a.session_id AND actor_id=a.id AND technique_id=t;
 IF s.actor_id IS NULL THEN
   s.session_id:=a.session_id; s.actor_id:=a.id; s.technique_id:=t;
   s.is_test:=(scope->>'is_test')::boolean; s.active:=false; s.state_version:=0;
 END IF;
 IF s.is_test IS DISTINCT FROM (scope->>'is_test')::boolean THEN
   RAISE EXCEPTION 'common_combat_policy_changed' USING ERRCODE='42501'; END IF;
 IF NOT s.is_test THEN
   SELECT * INTO canonical FROM clan_innata_private.actor_state WHERE actor_id=a.character_id AND technique_id=t;
   s.active:=coalesce(canonical.active,false); s.state_version:=coalesce(canonical.state_version,0);
 END IF;
 RETURN s;
END $function$;

