-- Native source clan_innata_private.current_actor() MD5 d3bd48e08d4a122417e735f9db757608

CREATE OR REPLACE FUNCTION clan_innata_private.current_actor()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'clan_innata_private'
AS $function$
declare v_actor uuid; v_count int;
begin
 perform clan_innata_private.runtime_release_assert();
 if encode(extensions.digest(convert_to(pg_get_functiondef('public.clan_genin_catalog_function_resolve_v1(uuid,text)'::regprocedure),'UTF8'),'sha256'),'hex')<>'612781e19be1b974d8fc8e7bd712c787d72dae5aa88c38d458303c7a307d353e' or encode(extensions.digest(convert_to(pg_get_functiondef('public.clan_genin_runtime_gate_context_v1(uuid,uuid)'::regprocedure),'UTF8'),'sha256'),'hex')<>'a193cd1200e99f0bb11b92f650952965ac7e19403798e81cbfe5ceaa5f53b842' or encode(extensions.digest(convert_to(pg_get_functiondef('public.clan_genin_runtime_gate_set_v1(bigint,boolean,text,uuid)'::regprocedure),'UTF8'),'sha256'),'hex')<>'98ebcb0cb3dc3d0ce370c9e9c217eb8b368eeb2b0cf3d9dab003556aef84be93' then raise exception 'runtime_dependency_body_drift'; end if;
 if (select count(*) from public.clan_genin_runtime_gate_v1)<>1
 or (select md5(string_agg(row_to_json(t)::text,'|' order by t.profile_id,t.profile_version)) from public.clan_genin_spatial_profile_registry_v1 t)<>'4bc58164c57d5eb9d1aa74b6e6c51644'
 or (select md5(string_agg(row_to_json(i)::text,'|' order by i.catalog_technique_id)) from public.clan_genin_live_inventory_pin_v1 i)<>'106159380adeee3285952621a7569bbc'
 or (select md5(string_agg(row_to_json(m)::text,'|' order by m.catalog_technique_id,m.function_id)) from public.clan_genin_catalog_function_map_v1 m)<>'ec431c078d6fb23de80b2a480d99398a'
 or (select md5(string_agg(row_to_json(g)::text,'|' order by g.gate_id)) from public.clan_genin_runtime_gate_v1 g)<>'01238f647164182ad4de70ae25747940' then raise exception 'postflight_foundation_row_drift'; end if;
 select count(*),(array_agg(cap.actor_id order by cap.actor_id))[1] into v_count,v_actor
 from clan_innata_private.controller_capabilities cap join public.characters c on c.id=cap.actor_id
 where cap.capability_id=nullif(current_setting('request.jwt.claim.capability_id',true),'')::uuid
 and cap.controller_user_id=nullif(current_setting('request.jwt.claim.sub',true),'')::uuid
 and cap.scope='innata_l1_toggle' and cap.active and cap.expires_at>clock_timestamp()
 and c.user_id=cap.controller_user_id;
 if v_count<>1 then raise exception 'actor_capability_not_exact'; end if; return v_actor;
