-- Native source clan_innata_private.master_combat_scope(uuid) MD5 273fa2a3370254b8000b23ab271f8c13

CREATE OR REPLACE FUNCTION clan_innata_private.master_combat_scope(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; pg public.characters%ROWTYPE;
 c clan_innata_combat_private.actor_context; test boolean; principals uuid[];
BEGIN
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 c:=clan_innata_private.combat_context(a.id);
 IF c.activity_kind<>'master_v2' OR c.personal_turn_id IS NULL OR c.phase IN ('closed','setup')
   OR a.actor_kind<>'pg' OR a.companion_id IS NOT NULL OR a.controller_user IS NULL
   OR a.state<>'attivo' OR jsonb_typeof(a.mechanics_snapshot->'vita') IS DISTINCT FROM 'number'
   OR coalesce((a.mechanics_snapshot->>'vita')::integer,0)<=0 THEN
   RAISE EXCEPTION 'common_master_actor_not_available' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT pg FROM public.characters WHERE id=a.character_id AND user_id=a.controller_user;
 test:=NOT public.combat_v2_values_written(a.session_id);
 IF test THEN
   SELECT array_agg(DISTINCT controller_user) INTO principals FROM public.combat_v2_actors
     WHERE session_id=a.session_id AND actor_kind='pg' AND companion_id IS NULL;
   IF c.policy_id<>'staff_test_no_persistent_resources_v1'
     OR a.character_id<>'6bceee99-974f-426b-8d92-38b43b4a4267'::uuid
     OR cardinality(principals) IS DISTINCT FROM 2
     OR NOT combat_consumer_private.staff_test_allowed(c.location_id,principals,false)
     OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.release_gate WHERE singleton AND staff_enabled)
     OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.staff_profiles WHERE session_id=a.session_id
       AND actor_id=a.id AND profile_version='sabaku-trasporto-l1/1') THEN
     RAISE EXCEPTION 'common_master_test_scope_invalid' USING ERRCODE='42501'; END IF;
 ELSE
   IF c.policy_id<>'master_game_resources_v1' OR pg.clan IS DISTINCT FROM 'Sabaku'
     OR coalesce(pg.kekkei_genkai,0)<30 OR coalesce(public._grade_rank(pg.rank),-1)<public._grade_rank('Genin')
     OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.release_gate WHERE singleton AND public_enabled)
     OR NOT EXISTS(SELECT 1 FROM public.character_abilities WHERE character_id=pg.id
       AND technique_id='001f907c-8f32-4758-8a16-ad1730e72c59' AND state='attiva') THEN
     RAISE EXCEPTION 'common_master_sabaku_not_eligible' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN jsonb_build_object('actor_id',a.id,'session_id',a.session_id,'character_id',a.character_id,
   'round_id',c.exchange_id,'personal_turn_id',c.personal_turn_id,'activity_kind',c.activity_kind,
   'context_version',c.context_version,'is_test',test,'policy_id',c.policy_id,
   'turn_owner',c.turn_actor_id=a.id,'phase',c.phase);
END $function$;

