-- Native source clan_innata_private.state_set_core(uuid,uuid,boolean,uuid,bigint,text,uuid) MD5 a304566853b657ca12cf52ea38abc18c

CREATE OR REPLACE FUNCTION clan_innata_private.state_set_core(p_actor uuid, p_technique uuid, p_desired boolean, p_request uuid, p_expected bigint, p_source text, p_source_receipt uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'clan_innata_private'
AS $function$
declare v_cfg clan_innata_private.config_versions%rowtype; v_state clan_innata_private.actor_state%rowtype;
v_fp text; v_old jsonb; v_cost int:=0; v_op text; v_result jsonb; v_chakra int;
begin
 perform clan_innata_private.assert_no_combat_authority(p_actor,p_technique);
  perform clan_innata_private.runtime_release_assert();
  if encode(extensions.digest(convert_to(pg_get_functiondef('public.clan_genin_catalog_function_resolve_v1(uuid,text)'::regprocedure),'UTF8'),'sha256'),'hex')<>'612781e19be1b974d8fc8e7bd712c787d72dae5aa88c38d458303c7a307d353e' or encode(extensions.digest(convert_to(pg_get_functiondef('public.clan_genin_runtime_gate_context_v1(uuid,uuid)'::regprocedure),'UTF8'),'sha256'),'hex')<>'a193cd1200e99f0bb11b92f650952965ac7e19403798e81cbfe5ceaa5f53b842' or encode(extensions.digest(convert_to(pg_get_functiondef('public.clan_genin_runtime_gate_set_v1(bigint,boolean,text,uuid)'::regprocedure),'UTF8'),'sha256'),'hex')<>'98ebcb0cb3dc3d0ce370c9e9c217eb8b368eeb2b0cf3d9dab003556aef84be93' then raise exception 'runtime_dependency_body_drift'; end if;
  if p_actor is null or p_technique is null or p_request is null or p_expected is null then raise exception 'invalid_request'; end if;
  if p_source not in ('panel','authorized_narrative','recovery') then raise exception 'invalid_source'; end if;
  if p_source='panel' and p_actor is distinct from clan_innata_private.current_actor() then raise exception 'actor_scope_mismatch'; end if;
  if p_source='authorized_narrative' and p_source_receipt is null then raise exception 'authority_receipt_required'; end if;
  v_fp:=encode(extensions.digest(jsonb_build_object('actor',p_actor,'technique',p_technique,'desired',p_desired,'expected',p_expected,'source',p_source,'receipt',p_source_receipt)::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended(p_actor::text||':'||p_technique::text,0));
  select * into strict v_cfg from clan_innata_private.config_versions where technique_id=p_technique and reviewed and active;
  if not exists(select 1 from clan_innata_private.editorial_approvals a where a.technique_id=v_cfg.technique_id and a.config_version=v_cfg.config_version and a.approved and a.approval_sha256=v_cfg.editorial_seal and a.approval_sha256=encode(extensions.digest(a.canonical_preimage::text,'sha256'),'hex') and a.canonical_preimage=jsonb_build_object('technique_id',v_cfg.technique_id,'config_version',v_cfg.config_version,'activation_cost',v_cfg.activation_cost,'upkeep_cost',v_cfg.upkeep_cost)) then raise exception 'editorial_seal_drift'; end if;
  if not exists(select 1 from public.clan_techniques t where t.id=p_technique and t.is_active and t.is_innata and t.level=1) then raise exception 'not_l1_innata'; end if;
  if not exists(select 1 from public.clan_genin_live_inventory_pin_v1 i where i.catalog_technique_id=p_technique and i.runtime_projection) then raise exception 'not_runtime_inventory'; end if;
  if not exists(select 1 from public.characters c join public.character_abilities ca on ca.character_id=c.id and ca.technique_id=p_technique and ca.state='attiva' where c.id=p_actor and c.rank='Genin') then raise exception 'innata_not_owned_or_grade'; end if;
  if p_source='authorized_narrative' and not exists(
    select 1 from clan_innata_private.narrative_receipts r join clan_innata_private.narrative_authorities a on a.authority_id=r.authority_id
    where r.receipt_id=p_source_receipt and r.actor_id=p_actor and r.technique_id=p_technique and r.session_id=a.session_id and r.purpose=a.purpose
    and r.authority_sha256=a.authority_sha256 and r.active and a.active
    and a.actor_id=p_actor and a.technique_id=p_technique
    and a.authority_sha256=encode(extensions.digest(a.canonical_preimage::text,'sha256'),'hex')
    and a.canonical_preimage=jsonb_build_object('actor_id',a.actor_id,'technique_id',a.technique_id,'session_id',a.session_id,'purpose',a.purpose,'authority_version',a.authority_version)
    and (r.consumed_at is null or r.consumed_request_key=p_request)
  ) then raise exception 'authority_receipt_invalid'; end if;
  select result into v_old from clan_innata_private.request_ledger where actor_id=p_actor and request_key=p_request and request_fingerprint=v_fp;
  if found then return v_old; end if;
  if exists(select 1 from clan_innata_private.request_ledger where actor_id=p_actor and request_key=p_request) then raise exception 'request_conflict'; end if;
  select * into v_state from clan_innata_private.actor_state where actor_id=p_actor and technique_id=p_technique for update;
  if not found then
    if p_expected<>0 then raise exception 'stale_state'; end if;
    v_state.state_version:=0; v_state.active:=false;
  elsif v_state.state_version<>p_expected then raise exception 'stale_state'; end if;
  if p_desired=v_state.active then
    v_op:=case when p_desired then 'already_active' else 'already_inactive' end;
    v_result:=jsonb_build_object('schema_version','clan-innata-state/1.0','technique_id',p_technique,'active',p_desired,'state_version',v_state.state_version,'chakra_spent',0,'main_action_consumed',false,'replayed',false);
    insert into clan_innata_private.request_ledger values(p_actor,p_request,v_fp,v_result,clock_timestamp());
    insert into clan_innata_private.audit(actor_id,technique_id,request_key,operation,state_version,chakra_delta,source,source_receipt_id) values(p_actor,p_technique,p_request,v_op,v_state.state_version,0,p_source,p_source_receipt);
    return v_result;
  elsif p_desired then v_op:='activate'; v_cost:=v_cfg.activation_cost;
  else v_op:='deactivate'; end if;
  select chakra into strict v_chakra from public.characters where id=p_actor for update;
  if v_cost>v_chakra then raise exception 'insufficient_chakra'; end if;
  if v_cost>0 then update public.characters set chakra=chakra-v_cost where id=p_actor; end if;
  if v_cost>0 then insert into clan_innata_private.resource_ledger(actor_id,technique_id,request_key,operation,expected_amount,committed_amount,applied_amount,balance_before,balance_after,authority_kind,authority_id) values(p_actor,p_technique,p_request,'activation',v_cost,v_cost,v_cost,v_chakra,v_chakra-v_cost,p_source,p_source_receipt); end if;
  if p_source='authorized_narrative' then update clan_innata_private.narrative_receipts set consumed_request_key=p_request,consumed_at=clock_timestamp() where receipt_id=p_source_receipt and consumed_at is null; if not found then raise exception 'authority_receipt_race'; end if; end if;
  insert into clan_innata_private.actor_state(actor_id,technique_id,config_version,active,state_version,activation_paid,activation_source,source_receipt_id,activated_at)
  values(p_actor,p_technique,v_cfg.config_version,p_desired,1,p_desired,p_source,p_source_receipt,case when p_desired then clock_timestamp() end)
  on conflict(actor_id,technique_id) do update set active=excluded.active,state_version=clan_innata_private.actor_state.state_version+1,
    activation_paid=case when excluded.active then clan_innata_private.actor_state.activation_paid or v_cost>0 else false end,
    activation_source=excluded.activation_source,source_receipt_id=excluded.source_receipt_id,
    activated_at=case when excluded.active then coalesce(clan_innata_private.actor_state.activated_at,clock_timestamp()) end,updated_at=clock_timestamp()
  returning * into v_state;
  v_result:=jsonb_build_object('schema_version','clan-innata-state/1.0','technique_id',p_technique,'active',v_state.active,'state_version',v_state.state_version,'chakra_spent',v_cost,'main_action_consumed',false,'replayed',false);
  insert into clan_innata_private.request_ledger values(p_actor,p_request,v_fp,v_result,clock_timestamp());
  insert into clan_innata_private.audit(actor_id,technique_id,request_key,operation,state_version,chakra_delta,source,source_receipt_id) values(p_actor,p_technique,p_request,v_op,v_state.state_version,-v_cost,p_source,p_source_receipt);
  return v_result;
exception when no_data_found then raise exception 'config_not_ratified';
end $function$;

