-- Native source clan_marionettisti_private.assert_jutsu_source(uuid,text,uuid) MD5 2231055fa33b3be3e2b9a21a40fa0992

CREATE OR REPLACE FUNCTION clan_marionettisti_private.assert_jutsu_source(p_owner uuid, p_source text, p_ability uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_source in('clan','jutsu') and exists(select 1 from clan_marionettisti_private.links l
  where l.owner_actor_id=p_owner and l.state='connected'
   and clan_marionettisti_private.link_path(l.instance_id,l.owner_actor_id,l.companion_actor_id))
  and (p_source is distinct from 'clan' or p_ability is distinct from 'e361f7c3-f90b-47ec-bfee-ccbda21257d9'::uuid) then
   raise exception 'fili_other_jutsu_unavailable' using errcode='22023';
 end if;
end;
$function$;

