-- Native source clan_marionettisti_private.attack_origin(uuid,uuid,uuid) MD5 3b12c93d85d321eebff0aed206cfda05

CREATE OR REPLACE FUNCTION clan_marionettisti_private.attack_origin(p_round uuid, p_owner uuid, p_target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.combat_v2_rounds%rowtype;a public.combat_v2_actors%rowtype;t public.combat_v2_actors%rowtype;
 l clan_marionettisti_private.links%rowtype;b combat_spatial.actor_states%rowtype;
 i combat_spatial.arena_instances%rowtype;
begin
 select * into strict r from public.combat_v2_rounds where id=p_round;
 select * into strict a from public.combat_v2_actors where id=p_owner;
 select * into strict t from public.combat_v2_actors where id=p_target;
 if a.session_id<>r.session_id or t.session_id<>r.session_id or a.state<>'attivo' or t.state<>'attivo' or a.team_key=t.team_key then raise exception 'marionetta_actor_target_invalid' using errcode='22023';end if;
 select * into strict l from clan_marionettisti_private.links where owner_actor_id=p_owner for share;
 if l.state<>'connected' or l.is_simulated is distinct from not public.combat_v2_values_written(r.session_id)
  or not clan_marionettisti_private.link_path(l.instance_id,p_owner,l.companion_actor_id) then raise exception 'marionetta_link_unavailable' using errcode='22023';end if;
 perform clan_marionettisti_private.assert_companion_actor(l.companion_actor_id);
 if not exists(select 1 from public.combat_v2_actors x join clan_marionettisti_private.chassis h on h.companion_id=x.companion_id
  where x.id=l.companion_actor_id and x.state='attivo' and h.operational and h.module_code='arto_rinforzato' and h.impact_kind='contundente') then raise exception 'marionetta_module_unavailable' using errcode='22023';end if;
 select * into strict i from combat_spatial.arena_instances where instance_id=l.instance_id and encounter_id=r.session_id and state='open';
 select * into strict b from combat_spatial.actor_states where instance_id=i.instance_id and actor_id=l.companion_actor_id and state='active';
 -- Solo origine meccanica: il bersaglio può essere una figura, non il corpo.
 return jsonb_build_object('instance_id',i.instance_id,'companion_actor_id',l.companion_actor_id,
  'link_version',l.link_version,'source_body_version',b.body_version,'map_version',i.map_version,
  'source_x_m',b.x_m,'source_y_m',b.y_m);
end;
$function$;

ALTER FUNCTION clan_marionettisti_private.attack_origin(uuid,uuid,uuid) OWNER TO "postgres";

