-- Native source clan_marionettisti_private.attack_source(uuid,uuid,uuid) MD5 f9bf9e3771c762dfd3c3a37b4567f040

CREATE OR REPLACE FUNCTION clan_marionettisti_private.attack_source(p_round uuid, p_owner uuid, p_target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE origin jsonb; target_body combat_spatial.actor_states%ROWTYPE;
 instance uuid; source_actor uuid; x numeric; y numeric;
BEGIN
 origin:=clan_marionettisti_private.attack_origin(p_round,p_owner,p_target);
 instance:=(origin->>'instance_id')::uuid; source_actor:=(origin->>'companion_actor_id')::uuid;
 x:=(origin->>'source_x_m')::numeric; y:=(origin->>'source_y_m')::numeric;
 SELECT * INTO STRICT target_body FROM combat_spatial.actor_states
  WHERE instance_id=instance AND actor_id=p_target AND state='active';
 IF combat_spatial.distance_m(x,y,target_body.x_m,target_body.y_m)>3
  OR combat_spatial.path_first_block_t(instance,source_actor,x,y,target_body.x_m,target_body.y_m,p_target)<1 THEN
  RAISE EXCEPTION 'marionetta_attack_out_of_range' USING ERRCODE='22023'; END IF;
 RETURN (origin-ARRAY['source_x_m','source_y_m'])
  ||jsonb_build_object('target_body_version',target_body.body_version);
END $function$;

