-- Native source clan_marionettisti_private.commit_control(jsonb,jsonb) MD5 d55889e4e1ca014e8710054bad3284cf

CREATE OR REPLACE FUNCTION clan_marionettisti_private.commit_control(p jsonb, prepared jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype;offer combat_consumer_private.offers%rowtype;
 aid uuid:=(prepared->>'actor_id')::uuid;cid uuid:=(prepared->>'principal_character_id')::uuid;
 key uuid:=(p->>'request_key')::uuid;event jsonb;eid uuid;result jsonb;envelope jsonb;label jsonb;receipt jsonb;
begin
 if prepared#>>'{offer,source_payload,sabaku_operation}' is not null then
  return clan_sabaku_private.commit_control(p,prepared);
 end if;
 select * into strict ctx from combat_consumer_private.activities where session_id=(p->>'activity_id')::uuid for update;
 select * into strict offer from combat_consumer_private.offers where id=(p->>'offer_id')::uuid for update;
 if p->>'operation'<>'control' or offer.operation<>'control' or offer.principal_character_id<>cid
  or offer.session_id<>ctx.session_id or offer.exchange_id<>ctx.exchange_id or ctx.turn_actor_id<>aid or ctx.phase<>'action' then
  perform combat_consumer_private.fail('offer_not_available',key);end if;
 event:=public.combat_v2_event_begin(offer.id,key,'combat_consumer_control',p);eid:=(event->>'event_id')::uuid;
 case offer.source_payload->>'marionetta_operation'
  when 'staff_profile' then result:=jsonb_build_object('actor_id',clan_marionettisti_private.staff_profile_bind(aid,offer.source_payload->'placement'));
  when 'real_body' then
   if exists(select 1 from public.combat_v2_declarations d join public.combat_v2_rounds r on r.id=d.round_id where r.session_id=ctx.session_id and d.actor_id=aid)
    or ctx.policy_id<>'free_duel_nonlethal_real_resources_v1' then raise exception 'companion_bind_not_at_scene_entry';end if;
   result:=jsonb_build_object('actor_id',clan_marionettisti_private.ordinary_body_bind(aid,(offer.source_payload->>'source_id')::uuid,offer.source_payload->'placement'));
  when 'relink' then result:=public.clan_marionettisti_control_v1((offer.source_payload->>'relink_offer_id')::uuid,key);
  when 'move' then result:=clan_marionettisti_private.companion_movement_commit(aid,(offer.source_payload->>'capability_id')::uuid,key,offer.id);
  else perform combat_consumer_private.fail('offer_not_available',key);
 end case;
 update combat_consumer_private.activities set context_version=context_version+1,last_action_at=clock_timestamp() where session_id=ctx.session_id;
 envelope:=combat_consumer_private.state_projection(ctx.location_id);
 label:=combat_consumer_private.display_label(ctx.session_id,aid,aid,null);
 receipt:=jsonb_build_object('receipt_id',eid,'request_key',key,'operation','control','replayed',false,
  'activity_id',ctx.session_id,'exchange_id',ctx.exchange_id,'context_version_before',ctx.context_version,
  'context_version_after',ctx.context_version+1,'declaration_id',null,'report_id',null,'report_sha256',null,
  'values_written',offer.source_payload->>'marionetta_operation'='relink' and coalesce((result->>'simulated')::boolean,true)=false,
  'display_events',jsonb_build_array(combat_consumer_private.validate_display_event(jsonb_build_object(
   'event_id',eid,'event_kind','control_changed','actor_id',aid,'display_name',label->>'display_name','label_version',label->'label_version',
   'target_actor_id',null,'target_display_name',null,'target_label_version',null,
   'summary',(label->>'display_name')||': '||(offer.viewer_projection->>'label')||'.'))));
 envelope:=jsonb_set(envelope,'{receipt}',receipt);
 update combat_consumer_private.offers set state='consumed',consumed_request_key=key where id=offer.id;
 insert into combat_consumer_private.request_receipts(principal_character_id,request_key,command_sha256,operation,event_id,viewer_envelope)
  values(cid,key,prepared->>'command_sha256','control',eid,envelope);
 return public.combat_v2_event_complete(eid,envelope);
end;
$function$;

