-- Native source clan_marionettisti_private.companion_movement_commit(uuid,uuid,uuid,uuid) MD5 a82cddfa795e03cfe0ff86104d23aef0

CREATE OR REPLACE FUNCTION clan_marionettisti_private.companion_movement_commit(p_owner uuid, p_capability uuid, p_request uuid, p_offer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l clan_marionettisti_private.links%rowtype;c combat_spatial.movement_capabilities%rowtype;
 ctx jsonb;rid uuid;prior clan_marionettisti_private.movement_receipts%rowtype;
 result jsonb;distance numeric;budget numeric;
begin
 ctx:=combat_panel_private.owner_turn_context(p_owner);rid:=(ctx->>'round_id')::uuid;
 if rid is null or not coalesce((ctx->>'can_move')::boolean,false) or not exists(
  select 1 from public.combat_v2_actors where id=p_owner and controller_user=auth.uid()) then
  raise exception 'companion_movement_turn_not_available' using errcode='42501';end if;
 perform public.combat_v2_lock_round(rid);
 ctx:=combat_panel_private.owner_turn_context(p_owner);
 if (ctx->>'round_id')::uuid is distinct from rid or not coalesce((ctx->>'can_move')::boolean,false) then
  raise exception 'companion_movement_turn_changed' using errcode='40001';end if;
 select * into prior from clan_marionettisti_private.movement_receipts where request_key=p_request;
 if found then
  if prior.owner_actor_id<>p_owner or prior.capability_id<>p_capability or prior.round_id<>rid then raise exception 'companion_move_replay_conflict';end if;
  return prior.result;
 end if;
 if not clan_marionettisti_private.owner_eligible(p_owner,false) then raise exception 'companion_move_not_eligible';end if;
 select * into strict l from clan_marionettisti_private.links where owner_actor_id=p_owner and state='connected' for update;
 perform clan_marionettisti_private.assert_companion_actor(l.companion_actor_id);
 select * into strict c from combat_spatial.movement_capabilities where capability_id=p_capability for update;
 if c.actor_id<>l.companion_actor_id or c.instance_id<>l.instance_id or c.state<>'offered'
  or not clan_marionettisti_private.link_path(l.instance_id,p_owner,l.companion_actor_id) then raise exception 'companion_move_capability_stale';end if;
 budget:=clan_marionettisti_private.movement_remaining(p_owner);
 if budget is null or combat_spatial.distance_m(c.start_x_m,c.start_y_m,c.end_x_m,c.end_y_m)>budget then raise exception 'companion_move_budget_exhausted';end if;
 result:=combat_spatial.movement_commit(c.capability_id,p_request,p_offer);
 distance:=(result->>'d_eff_m')::numeric;
 if distance is null or distance<=0 or combat_panel_private.movement_event_cost((result->>'event_id')::uuid,distance)>budget or not clan_marionettisti_private.link_path(l.instance_id,p_owner,l.companion_actor_id) then raise exception 'companion_move_invalid';end if;
 insert into clan_marionettisti_private.movement_receipts(request_key,round_id,owner_actor_id,body_actor_id,capability_id,distance_m,result)
  values(p_request,rid,p_owner,l.companion_actor_id,p_capability,distance,result);
 return result;
end;
$function$;

