-- Native source clan_marionettisti_private.companion_movement_options(uuid) MD5 e5df38cd6e11a62d7d479187e77f5700

CREATE OR REPLACE FUNCTION clan_marionettisti_private.companion_movement_options(p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l clan_marionettisti_private.links%rowtype;b combat_spatial.actor_states%rowtype;
 owner_body combat_spatial.actor_states%rowtype;ctx jsonb;rid uuid;
 budget numeric;candidate record;key text;keys text[]:='{}';opts jsonb;item jsonb;out jsonb:='[]';cap combat_spatial.movement_capabilities%rowtype;
begin
 if not clan_marionettisti_private.owner_eligible(p_owner,false) then return out;end if;
 ctx:=combat_panel_private.owner_turn_context(p_owner);
 if not coalesce((ctx->>'can_move')::boolean,false) or not exists(
  select 1 from public.combat_v2_actors where id=p_owner and controller_user=auth.uid()) then return out;end if;
 rid:=(ctx->>'round_id')::uuid;
 select * into l from clan_marionettisti_private.links where owner_actor_id=p_owner and state='connected';
 if not found or not clan_marionettisti_private.link_path(l.instance_id,p_owner,l.companion_actor_id) then return out;end if;
 perform clan_marionettisti_private.assert_companion_actor(l.companion_actor_id);
 select * into b from combat_spatial.actor_states where instance_id=l.instance_id and actor_id=l.companion_actor_id and state='active';
 select * into owner_body from combat_spatial.actor_states where instance_id=l.instance_id and actor_id=p_owner and state='active';
 if b.actor_id is null or owner_body.actor_id is null then return out;end if;
 budget:=clan_marionettisti_private.movement_remaining(p_owner);
 if budget is null or budget<=0 then return out;end if;
 -- Direzioni semantiche server. Ogni passo usa lo stesso budget ordinario,
 -- viene troncato dalle collisioni Spatial e non è movimento incluso nell'attacco.
 for candidate in select d.dx,d.dy,m.metres from (values(1,0),(0,1),(-1,0),(0,-1))d(dx,dy)
  cross join lateral generate_series(1,least(10,floor(budget)::integer))m(metres) loop
  key:='marionetta:'||rid||':'||b.body_version||':'||candidate.dx||':'||candidate.dy||':'||candidate.metres;
  if combat_spatial.distance_m(owner_body.x_m,owner_body.y_m,b.x_m+candidate.dx*candidate.metres,b.y_m+candidate.dy*candidate.metres)>10 then continue;end if;
  keys:=array_append(keys,key);
  insert into combat_spatial.movement_semantic_choices(instance_id,actor_id,choice_key,endpoint_x_m,endpoint_y_m,max_budget_m,choice_version,enabled)
   values(l.instance_id,b.actor_id,key,b.x_m+candidate.dx*candidate.metres,b.y_m+candidate.dy*candidate.metres,budget,1,true)
   on conflict(instance_id,actor_id,choice_key) do nothing;
 end loop;
 update combat_spatial.movement_semantic_choices set enabled=false,choice_version=choice_version+1
  where instance_id=l.instance_id and actor_id=b.actor_id and enabled and left(choice_key,11)='marionetta:' and not(choice_key=any(keys));
 opts:=combat_spatial.movement_options(l.instance_id,b.actor_id,budget);
 for item in select value from jsonb_array_elements(opts) loop
  if item->>'intent'=any(keys) and (item->>'distance_m')::numeric>0 then
   select * into cap from combat_spatial.movement_capabilities where capability_id=(item->>'option_id')::uuid;
   if combat_spatial.distance_m(owner_body.x_m,owner_body.y_m,cap.end_x_m,cap.end_y_m)<=10
    and combat_spatial.path_first_block_t(l.instance_id,p_owner,owner_body.x_m,owner_body.y_m,cap.end_x_m,cap.end_y_m,b.actor_id)>=1 then
    out:=out||jsonb_build_array(item);
   end if;
  end if;
 end loop;
 return out;
end;
$function$;

