-- Native source clan_marionettisti_private.consumer_defense_options(jsonb) MD5 c29a874de6fc4640ce833e8f346ba8db

CREATE OR REPLACE FUNCTION clan_marionettisti_private.consumer_defense_options(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid uuid;aid uuid;ctx combat_consumer_private.activities%rowtype;attack record;
 reaction text;offers jsonb;scene integer;
begin
 if p->>'status' is distinct from 'ready' then return p;end if;
 sid:=(p#>>'{context,activity_id}')::uuid;aid:=(p#>>'{viewer,actor_id}')::uuid;
 select * into ctx from combat_consumer_private.activities where session_id=sid and phase='defense' and turn_actor_id<>aid;
 if not found or aid is null then return p;end if;
 if not exists(select 1 from public.combat_v2_actors a join combat_consumer_private.members m
  on m.actor_id=a.id and m.session_id=a.session_id and m.character_id=a.character_id
  where a.id=aid and a.session_id=sid and a.actor_kind='pg' and a.controller_user=auth.uid() and a.state='attivo') then return p;end if;
 offers:=coalesce(p->'offers','[]');scene:=(p#>>'{context,scene_version}')::integer;
 for attack in select d.id,d.target_actor_id from public.combat_v2_declarations d
  join public.combat_v2_actors target on target.id=d.target_actor_id and target.companion_id is not null
  where d.round_id=ctx.exchange_id and d.kind='attacco' and target.session_id=sid
   and not exists(select 1 from public.combat_v2_declarations defense where defense.parent_attack_id=d.id and defense.actor_id=aid) loop
  foreach reaction in array array['schivata','parata','nessuna'] loop
   if clan_marionettisti_private.defends_body(aid,attack.target_actor_id,reaction) then
    offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,ctx.turn_actor_id,scene,'defend',
     case reaction when 'schivata' then 'Schivata della marionetta' when 'parata' then 'Parata della marionetta' else 'Nessuna difesa della marionetta' end,
     jsonb_build_object('attack_id',attack.id,'intent',jsonb_build_object('reaction',reaction))));
   end if;
  end loop;
 end loop;
 return jsonb_set(p,'{offers}',offers);
end;
$function$;

