-- Native source clan_marionettisti_private.consumer_projection(jsonb) MD5 c046a5eb52a5109a690a5b4a9f696ece

CREATE OR REPLACE FUNCTION clan_marionettisti_private.consumer_projection(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid uuid;viewer uuid;iid uuid;v combat_spatial.actor_states%rowtype;
 a record;own jsonb:=null;roster jsonb;mapactors jsonb;distance numeric;label text;
begin
 if p->>'status' is distinct from 'ready' or p#>>'{context,activity_kind}' is distinct from 'ordinary_v2' then return p;end if;
 sid:=(p#>>'{context,activity_id}')::uuid;viewer:=(p#>>'{viewer,actor_id}')::uuid;
 if viewer is null or not exists(select 1 from public.combat_v2_actors x
  join combat_consumer_private.members m on m.actor_id=x.id and m.session_id=x.session_id and m.character_id=x.character_id
  where x.id=viewer and x.session_id=sid and x.actor_kind='pg' and x.controller_user=auth.uid()) then return p;end if;
 if not exists(select 1 from public.combat_v2_actors where session_id=sid and companion_id is not null) then return p;end if;
 if not clan_marionettisti_private.roster_valid(sid) then raise exception 'companion_projection_roster_invalid';end if;
 select instance_id into iid from combat_spatial.arena_instances where encounter_id=sid and context_source='ordinary' and state='open';
 select * into v from combat_spatial.actor_states where instance_id=iid and actor_id=viewer and state='active';
 if not found then return p;end if;
 -- Stessa autorità della proiezione spaziale: non conservare coordinate PG nascoste.
 select coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb) into roster
 from jsonb_array_elements(coalesce(p->'actors','[]'::jsonb)) with ordinality as entries(item,ordinal)
 where clan_marionettisti_private.actor_visible(sid,(item->>'actor_id')::uuid,auth.uid());
 select coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb) into mapactors
 from jsonb_array_elements(coalesce(p#>'{map,actors}','[]'::jsonb)) with ordinality as entries(item,ordinal)
 where clan_marionettisti_private.actor_visible(sid,(item->>'actor_id')::uuid,auth.uid());
 for a in select x.id,x.state,x.controller_user,x.controller_version,src.source_kind,
  b.x_m,b.y_m,b.footprint_radius_m,b.body_version,b.state as body_state,h.integrity,h.integrity_max,l.state as link_state
  from public.combat_v2_actors x
  join clan_marionettisti_private.sources src on src.id=x.companion_id and src.is_active
  join clan_marionettisti_private.chassis h on h.companion_id=src.id
  join combat_spatial.actor_states b on b.instance_id=iid and b.actor_id=x.id
  left join clan_marionettisti_private.links l on l.companion_actor_id=x.id
  where x.session_id=sid and clan_marionettisti_private.actor_visible(sid,x.id,auth.uid())
  order by x.id loop
  label:=case when a.source_kind='staff' then 'Marionetta · profilo di prova L1' else 'Marionetta' end;
  distance:=round(combat_spatial.distance_m(v.x_m,v.y_m,a.x_m,a.y_m),2);
  roster:=roster||jsonb_build_array(jsonb_build_object('actor_id',a.id,'display_name',label,
   'label_version',1,'mine',false,'body_only',true,'is_turn_owner',false,
   'state',case a.state when 'attivo' then 'active' when 'fuori' then 'out' else 'withdrawn' end,
   'distance_from_viewer_m',distance));
  if a.state='attivo' and a.body_state='active' then
   mapactors:=mapactors||jsonb_build_array(jsonb_build_object('actor_id',a.id,'x_m',a.x_m,'y_m',a.y_m,
    'radius_m',a.footprint_radius_m,'body_only',true,'display_name',label));
  end if;
  if a.controller_user=auth.uid() then
   own:=jsonb_build_object('schema_version','combat-companion/1','actor_id',a.id,'display_name',label,
    'commanded_by_me',true,'passive',true,'simulated',a.source_kind='staff','integrity',a.integrity,
    'integrity_max',a.integrity_max,'link_state',case when a.state<>'attivo' then 'unavailable' else coalesce(a.link_state,'unavailable') end);
  end if;
 end loop;
 p:=jsonb_set(p,'{actors}',roster)||jsonb_build_object('companion',own);
 if jsonb_typeof(p->'map')='object' then p:=jsonb_set(p,'{map,actors}',mapactors);end if;
 return p;
end;
$function$;

