-- Native source clan_marionettisti_private.defends_body(uuid,uuid,text) MD5 699bfcd647df274e86f16cd526e51431

CREATE OR REPLACE FUNCTION clan_marionettisti_private.defends_body(p_owner uuid, p_target uuid, p_reaction text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare body public.combat_v2_actors%rowtype;owner_id uuid;l clan_marionettisti_private.links%rowtype;
begin
 if p_owner is null or p_target is null or p_reaction is null or p_reaction not in('nessuna','parata','schivata') then return false;end if;
 select * into body from public.combat_v2_actors where id=p_target and companion_id is not null;
 if not found then return false;end if;
 owner_id:=clan_marionettisti_private.assert_companion_actor(body.id);
 if owner_id<>p_owner then return false;end if;
 if p_reaction='nessuna' then return true;end if;
 if body.state<>'attivo' or not clan_marionettisti_private.owner_eligible(p_owner,false) then return false;end if;
 select * into l from clan_marionettisti_private.links where owner_actor_id=p_owner and companion_actor_id=body.id and state='connected';
 return found and clan_marionettisti_private.link_path(l.instance_id,p_owner,body.id);
end;
$function$;

