-- Native source clan_marionettisti_private.defense_snapshot(uuid,uuid,text) MD5 c39f6c167626f3dafb5f8366fe38d5fb

CREATE OR REPLACE FUNCTION clan_marionettisti_private.defense_snapshot(p_owner uuid, p_target uuid, p_reaction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.combat_v2_actors%rowtype;snapshot jsonb;
begin
 select * into strict target from public.combat_v2_actors where id=p_target;
 if target.companion_id is null then return target.mechanics_snapshot;end if;
 if not clan_marionettisti_private.defends_body(p_owner,p_target,p_reaction) then raise exception 'companion_defense_not_authorized';end if;
 select mechanics_snapshot into strict snapshot from public.combat_v2_actors where id=p_owner;
 -- Il chassis non eredita resistenza, copie o bonus corporei del controllore.
 snapshot:=snapshot||jsonb_build_object('resistenza',0,'copie_n',0,'tech_element',null);
 if p_reaction='nessuna' then
  snapshot:=snapshot||jsonb_build_object('velocita',0,'taijutsu',0,'mente',0,'ninjutsu',0,'genjutsu',0,'fuuinjutsu',0);
 end if;
 return snapshot;
end;
$function$;

