-- Native source clan_marionettisti_private.ensure_initial_link(uuid) MD5 a4b2ea5f350899deacfb64e972c01b0f

CREATE OR REPLACE FUNCTION clan_marionettisti_private.ensure_initial_link(p_owner uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.combat_v2_actors%rowtype;c public.characters%rowtype;b public.combat_v2_actors%rowtype;
 i combat_spatial.arena_instances%rowtype;l clan_marionettisti_private.links%rowtype;
begin
 select * into a from public.combat_v2_actors where id=p_owner for update;
 if not found or a.actor_kind<>'pg' or a.state<>'attivo' then return false;end if;
 select * into c from public.characters where id=a.character_id for share;
 if not found or not clan_marionettisti_private.owner_eligible(a.id,false) then return false;end if;
 select * into i from combat_spatial.arena_instances where encounter_id=a.session_id and (context_source in('marionetta_master','ordinary') or (context_source='panel_master' and exists(select 1 from public.combat_v2_sessions ms join combat_panel_private.master_panel_sessions mp on mp.master_session_id=ms.master_session_id where ms.id=a.session_id and ms.source_kind='master'))) and state='open';
 if not found then return false;end if;
 select x.* into b from public.combat_v2_actors x join clan_marionettisti_private.chassis h on h.companion_id=x.companion_id
  where x.session_id=a.session_id and x.state='attivo' and h.owner_character_id=c.id and h.operational;
 if not found then return false;end if;
 perform clan_marionettisti_private.assert_companion_actor(b.id);
 select * into l from clan_marionettisti_private.links where owner_actor_id=a.id for update;
 if found then
  if l.state='severed' then return false;end if;
  return l.companion_actor_id=b.id and l.instance_id=i.instance_id and clan_marionettisti_private.link_path(i.instance_id,a.id,b.id);
 end if;
 if not clan_marionettisti_private.link_path(i.instance_id,a.id,b.id) then return false;end if;
 insert into clan_marionettisti_private.links(owner_actor_id,companion_actor_id,instance_id,state,link_version,is_simulated)
 values(a.id,b.id,i.instance_id,'connected',1,not public.combat_v2_values_written(a.session_id));
 return true;
end;
$function$;

