-- Native source clan_marionettisti_private.freeze_offensive_profile(uuid) MD5 f46b63f7293d2691b6676e6aa7e4b739

CREATE OR REPLACE FUNCTION clan_marionettisti_private.freeze_offensive_profile(p_declaration uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.combat_v2_declarations%rowtype;r public.combat_v2_rounds%rowtype;
 a public.combat_v2_actors%rowtype;c public.characters%rowtype;
 b public.combat_v2_actors%rowtype;p clan_marionettisti_private.offensive_profiles%rowtype;
 v_profile jsonb;v_source jsonb;
begin
 select * into strict d from public.combat_v2_declarations where id=p_declaration for update;
 select * into strict r from public.combat_v2_rounds where id=d.round_id;
 select * into strict a from public.combat_v2_actors where id=d.actor_id for update;
 if d.kind<>'attacco' or a.actor_kind<>'pg' or a.companion_id is not null or a.session_id<>r.session_id
  or d.sanitized_intent->>'ability_source' is distinct from 'clan'
  or d.sanitized_intent->>'ability_id' is distinct from 'e361f7c3-f90b-47ec-bfee-ccbda21257d9' then raise exception 'marionetta_declaration_required';end if;
 select * into p from clan_marionettisti_private.offensive_profiles where declaration_id=d.id;
 if found then
  if p.profile_sha256 is distinct from public.combat_v2_sha256(p.profile) then raise exception 'marionetta_profile_corrupt';end if;
  return p.profile;
 end if;
 if r.phase<>'raccolta_azioni' then raise exception 'marionetta_snapshot_must_freeze_at_declaration';end if;
 select * into strict c from public.characters where id=a.character_id for update;
 if not clan_marionettisti_private.owner_eligible(a.id,true) then raise exception 'marionetta_ability_not_owned';end if;
 -- Autorita link/spazio e versioni fornite dal consumer Fili,non dall'intent.
 v_source:=combat_panel_private.multiplication_companion_attack_source(d.round_id,d.actor_id,d.target_actor_id,d.request_key,d.id);
 select * into strict b from public.combat_v2_actors where id=(v_source->>'companion_actor_id')::uuid;
 perform clan_marionettisti_private.assert_companion_actor(b.id);
 v_profile:=clan_marionettisti_private.offensive_values((a.mechanics_snapshot->>'kekkei_genkai')::integer,(a.mechanics_snapshot->>'ninjutsu')::integer)
  ||v_source||jsonb_build_object('declaration_id',d.id,'round_id',r.id,'session_id',r.session_id,
    'owner_actor_id',a.id,'target_actor_id',d.target_actor_id,'technique_id','e361f7c3-f90b-47ec-bfee-ccbda21257d9');
 insert into clan_marionettisti_private.offensive_profiles(declaration_id,round_id,owner_actor_id,companion_actor_id,target_actor_id,profile,profile_sha256)
 values(d.id,r.id,a.id,b.id,d.target_actor_id,v_profile,public.combat_v2_sha256(v_profile));
 return v_profile;
end;
$function$;

