CREATE OR REPLACE FUNCTION clan_marionettisti_private.is_staff_scene(p_session uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare src record;
begin
 if not exists(select 1 from clan_marionettisti_private.sources where source_kind='staff' and session_id=p_session and is_active) then return false;end if;
 for src in select id from clan_marionettisti_private.sources where source_kind='staff' and session_id=p_session and is_active loop
  perform clan_marionettisti_private.assert_source(src.id);
 end loop;
 return clan_marionettisti_private.roster_valid(p_session);
end;
$function$;

