-- Native source clan_marionettisti_private.link_path(uuid,uuid,uuid) MD5 a064f857298248b90ccc0ba0c8b1e8df

CREATE OR REPLACE FUNCTION clan_marionettisti_private.link_path(p_instance uuid, p_owner uuid, p_companion uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o combat_spatial.actor_states%rowtype;b combat_spatial.actor_states%rowtype;
begin
 select * into o from combat_spatial.actor_states where instance_id=p_instance and actor_id=p_owner and state='active';
 if not found then return false;end if;
 select * into b from combat_spatial.actor_states where instance_id=p_instance and actor_id=p_companion and state='active';
 if not found then return false;end if;
 if combat_spatial.distance_m(o.x_m,o.y_m,b.x_m,b.y_m)>10 then return false;end if;
 return combat_spatial.path_first_block_t(p_instance,p_owner,o.x_m,o.y_m,b.x_m,b.y_m,p_companion)>=1;
end;
$function$;

