CREATE OR REPLACE FUNCTION clan_marionettisti_private.offensive_values(p_kg integer, p_ninjutsu integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_kg is null or p_ninjutsu is null or p_kg<30 or p_ninjutsu<0 then raise exception 'marionetta_stats_not_eligible';end if;
 return jsonb_build_object('formula_version','marionetta-offense/1',
  'primary_stat','kekkei_genkai','secondary_stat','ninjutsu','kg',p_kg,'ninjutsu',p_ninjutsu,
  'pool',p_kg+p_ninjutsu,'power_base',15,'power_contribution',(p_kg+p_ninjutsu)/10,
  'power',15+(p_kg+p_ninjutsu)/10,'damage_base',10,
  'off',greatest(p_kg,p_ninjutsu),'damage_contribution',greatest(p_kg,p_ninjutsu)/4,
  'defense_base',10,'chakra_cost',5,'main_cost',1,'impact_kind','contundente');
end;
$function$;

