-- Native source clan_marionettisti_private.ordinary_body_bind(uuid,uuid,jsonb) MD5 c51459501ee03eff3434c37afd6db85a

CREATE OR REPLACE FUNCTION clan_marionettisti_private.ordinary_body_bind(p_owner uuid, p_source uuid, p_placement jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.combat_v2_actors%rowtype;ctx combat_consumer_private.activities%rowtype;
 src clan_marionettisti_private.sources%rowtype;h clan_marionettisti_private.chassis%rowtype;
 companion uuid:=gen_random_uuid();member record;
begin
 select * into strict a from public.combat_v2_actors where id=p_owner;
 perform 1 from public.combat_v2_sessions where id=a.session_id for update;
 select * into strict ctx from combat_consumer_private.activities where session_id=a.session_id for update;
 perform 1 from public.combat_v2_actors where session_id=a.session_id order by id for update;
 select * into strict a from public.combat_v2_actors where id=p_owner;
 if auth.uid() is null or a.controller_user is distinct from auth.uid() or ctx.turn_actor_id<>a.id
  or ctx.phase<>'action' or not clan_marionettisti_private.owner_eligible(a.id,false) then raise exception 'companion_bind_authority_invalid' using errcode='42501';end if;
 src:=clan_marionettisti_private.assert_source(p_source);
 if src.owner_character_id<>a.character_id
  or (src.source_kind='staff' and (src.session_id<>a.session_id or src.owner_actor_id<>a.id))
  or (src.source_kind='real' and ctx.policy_id<>'free_duel_nonlethal_real_resources_v1') then raise exception 'companion_bind_source_invalid';end if;
 if exists(select 1 from public.combat_v2_actors x join clan_marionettisti_private.sources s on s.id=x.companion_id
   where x.session_id=a.session_id and s.owner_character_id=a.character_id)
  or exists(select 1 from public.combat_v2_actors x join public.combat_v2_sessions s on s.id=x.session_id
   where x.companion_id=src.id and s.closed_at is null) then raise exception 'companion_already_bound';end if;
 if p_placement is null or p_placement is distinct from clan_marionettisti_private.staff_placement(a.id) then raise exception 'companion_placement_stale';end if;
 select * into strict h from clan_marionettisti_private.chassis where companion_id=src.id and operational for update;
 if h.owner_character_id<>a.character_id then raise exception 'companion_chassis_owner_drift';end if;
 insert into public.combat_v2_actors(id,session_id,actor_kind,companion_id,controller_user,team_key,state,
  position_m,initiative_snapshot,mechanics_snapshot,controller_version)
 values(companion,a.session_id,'png',src.id,a.controller_user,a.team_key,'attivo',0,0,
  jsonb_build_object('vita',h.integrity,'vita_max',h.integrity_max,'companion_passive',true,'position_authority','spatial2d'),a.controller_version);
 perform clan_marionettisti_private.assert_companion_actor(companion);
 insert into combat_spatial.actor_states(instance_id,actor_id,actor_kind,slot_key,controller_principal_id,
  projection_subject_id,x_m,y_m,footprint_radius_m,body_version,state)
 values((p_placement->>'instance_id')::uuid,companion,'PNG','COMPANION-'||a.id,a.controller_user,
  src.id,(p_placement->>'x_m')::numeric,(p_placement->>'y_m')::numeric,h.footprint_radius_m,1,'active');
 for member in select x.controller_user as principal from public.combat_v2_actors x
  join combat_consumer_private.members m on m.actor_id=x.id and m.session_id=x.session_id
  where x.session_id=a.session_id and x.actor_kind='pg' loop
  insert into combat_spatial.viewer_grants(instance_id,viewer_principal_id,subject_actor_id,can_view_map,can_view_objects,grant_version)
   values((p_placement->>'instance_id')::uuid,member.principal,companion,true,true,1);
 end loop;
 update combat_spatial.arena_instances set map_version=map_version+1 where instance_id=(p_placement->>'instance_id')::uuid;
 if not clan_marionettisti_private.ensure_initial_link(a.id) then raise exception 'companion_initial_link_failed';end if;
 perform clan_marionettisti_private.start_command_window(ctx.exchange_id);
 return companion;
end;
$function$;

