CREATE OR REPLACE FUNCTION clan_marionettisti_private.relink_options(p_round uuid, p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l clan_marionettisti_private.links%rowtype;relink_offer_id uuid;
begin
 if auth.uid() is null or not exists(select 1 from public.combat_v2_actors actor where actor.id=p_owner and actor.controller_user=auth.uid())
  or not clan_marionettisti_private.owner_eligible(p_owner,false)
  or not clan_marionettisti_private.relink_ready(p_round,p_owner) then return '[]'::jsonb;end if;
 select * into strict l from clan_marionettisti_private.links where owner_actor_id=p_owner;
 insert into clan_marionettisti_private.relink_offers(round_id,owner_actor_id,expected_link_version)
  values(p_round,p_owner,l.link_version) on conflict(round_id,owner_actor_id,expected_link_version) do nothing;
 select offer_id into strict relink_offer_id from clan_marionettisti_private.relink_offers where round_id=p_round and owner_actor_id=p_owner and expected_link_version=l.link_version;
 return jsonb_build_array(jsonb_build_object('option_id',relink_offer_id,'label','Riallaccia i Fili','chakra_cost',5,'main_cost',0));
end;
$function$;

