-- Native source clan_marionettisti_private.relink_ready(uuid,uuid) MD5 6593db9708097e7a6aa9b8a968a1d12f

CREATE OR REPLACE FUNCTION clan_marionettisti_private.relink_ready(p_round uuid, p_owner uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.combat_v2_rounds%rowtype;a public.combat_v2_actors%rowtype;
 l clan_marionettisti_private.links%rowtype;start_no bigint;needed integer;pg_chakra integer;
begin
 select * into r from public.combat_v2_rounds where id=p_round;
 select * into a from public.combat_v2_actors where id=p_owner;
 if r.id is null or a.id is null or a.session_id<>r.session_id or r.phase<>'raccolta_azioni' or a.state<>'attivo' then return false;end if;
 select * into l from clan_marionettisti_private.links where owner_actor_id=p_owner;
 if not found or l.state<>'severed' or l.cut_event_no is null
  or l.is_simulated is distinct from not public.combat_v2_values_written(r.session_id)
  or not clan_marionettisti_private.link_path(l.instance_id,p_owner,l.companion_actor_id) then return false;end if;
 if not exists(select 1 from public.combat_v2_actors b join clan_marionettisti_private.chassis h on h.companion_id=b.companion_id
  where b.id=l.companion_actor_id and b.state='attivo' and h.operational) then return false;end if;
 select event_no into start_no from clan_marionettisti_private.control_events
  where round_id=r.id and owner_actor_id=p_owner and kind='turn_started';
 if start_no is null or not exists(select 1 from clan_marionettisti_private.control_events e
  where e.owner_actor_id=p_owner and e.kind='turn_completed' and e.event_no<start_no
    and (e.payload->>'started_event_no')::bigint>l.cut_event_no) then return false;end if;
 if exists(select 1 from public.combat_v2_declarations where round_id=r.id and actor_id=p_owner and kind in('attacco','movimento','utilita','passa')) then return false;end if;
 select coalesce(sum(coalesce((d.cost_snapshot->>'chakra')::integer,0)),0) into needed
  from public.combat_v2_declarations d where d.round_id=r.id and d.actor_id=p_owner
   and not exists(select 1 from public.combat_v2_resource_ledger z where z.declaration_id=d.id and z.resource_kind='chakra');
 if not clan_marionettisti_private.owner_eligible(a.id,false) then return false;end if;
 select chakra into pg_chakra from public.characters where id=a.character_id;
 return coalesce((a.mechanics_snapshot->>'chakra')::integer,-1)>=5+needed
  and (not public.combat_v2_values_written(a.session_id) or pg_chakra>=5+needed);
end;
$function$;

