-- Native source clan_marionettisti_private.roster_valid(uuid) MD5 c5b09860e56617154e6bd4272b79e169

CREATE OR REPLACE FUNCTION clan_marionettisti_private.roster_valid(p_session uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a record;count_pg integer;count_companion integer;
begin
 if exists(select 1 from public.combat_v2_sessions ms join combat_panel_private.master_panel_sessions mp on mp.master_session_id=ms.master_session_id where ms.id=p_session and ms.source_kind='master') then return combat_panel_private.master_companion_roster_valid(p_session);end if;
 select count(*) into count_pg from public.combat_v2_actors where session_id=p_session and actor_kind='pg';
 if count_pg<>2 or (select count(*) from combat_consumer_private.members where session_id=p_session)<>2
 or (select count(*) from combat_consumer_private.members m
  join public.combat_v2_actors x on x.id=m.actor_id and x.session_id=m.session_id and x.character_id=m.character_id
  join public.characters c on c.id=x.character_id and c.user_id=x.controller_user
  where m.session_id=p_session and x.actor_kind='pg')<>2 then return false;end if;
 select count(*) into count_companion from public.combat_v2_actors where session_id=p_session and companion_id is not null;
 if count_companion>2 or (select count(*) from public.combat_v2_actors where session_id=p_session)<>2+count_companion then return false;end if;
 if exists(select 1 from public.combat_v2_actors x join clan_marionettisti_private.sources src on src.id=x.companion_id
  where x.session_id=p_session group by src.owner_character_id having count(*)>1) then return false;end if;
 for a in select * from public.combat_v2_actors where session_id=p_session and companion_id is not null loop
  if a.actor_kind<>'png' or a.initiative_snapshot<>0
   or a.mechanics_snapshot->>'companion_passive' is distinct from 'true' then return false;end if;
  perform clan_marionettisti_private.assert_companion_actor(a.id,false);
 end loop;
 return true;
end;
$function$;

