-- Native source clan_marionettisti_private.scene_slot_legal(text,integer,numeric,numeric,numeric) MD5 0542bf77cf7de7aaab86f417081d0921

CREATE OR REPLACE FUNCTION clan_marionettisti_private.scene_slot_legal(p_template text, p_version integer, p_x numeric, p_y numeric, p_radius numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t combat_spatial.arena_templates%rowtype;o record;hit numeric;
begin
 select * into strict t from combat_spatial.arena_templates where template_key=p_template and template_version=p_version;
 if p_x is null or p_y is null or p_radius is null or p_radius<=0
   or p_x-p_radius<0 or p_y-p_radius<0 or p_x+p_radius>t.width_m or p_y+p_radius>t.height_m then return false;end if;
 for o in select * from combat_spatial.arena_objects where template_key=p_template and template_version=p_version and blocks_movement loop
  if o.shape_kind='circle' then
   hit:=combat_spatial.segment_circle_first_t(p_x,p_y,p_x,p_y,(o.shape->>'cx')::numeric,(o.shape->>'cy')::numeric,(o.shape->>'radius')::numeric+p_radius);
  elsif o.shape_kind='aabb' then
   hit:=combat_spatial.segment_aabb_first_t(p_x,p_y,p_x,p_y,(o.shape->>'min_x')::numeric,(o.shape->>'min_y')::numeric,(o.shape->>'max_x')::numeric,(o.shape->>'max_y')::numeric,p_radius);
  else return false; end if;
  if hit is not null then return false;end if;
 end loop;
 return true;
end;
$function$;

