-- Native source clan_marionettisti_private.staff_close_trigger() MD5 a8b5738469717cff6a3d505df8943aa0

CREATE OR REPLACE FUNCTION clan_marionettisti_private.staff_close_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.phase='closed' and old.phase is distinct from 'closed' then
  update combat_spatial.actor_states b set state='removed',body_version=body_version+1
   from public.combat_v2_actors a join clan_marionettisti_private.sources s on s.id=a.companion_id
   where a.id=b.actor_id and a.session_id=new.session_id and b.state='active';
  update public.combat_v2_actors a set state='ritirato'
   from clan_marionettisti_private.sources s where s.id=a.companion_id and a.session_id=new.session_id;
  update clan_marionettisti_private.sources set is_active=false where source_kind='staff' and session_id=new.session_id and is_active;
 end if;
 return new;
end;
$function$;

