-- Native source clan_marionettisti_private.start_command_window(uuid) MD5 c5c0fa7101abfc77f793b73cf193de82

CREATE OR REPLACE FUNCTION clan_marionettisti_private.start_command_window(p_round uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.combat_v2_rounds%rowtype;a record;
begin
 select * into strict r from public.combat_v2_rounds where id=p_round;
 if r.phase<>'raccolta_azioni' or not clan_marionettisti_private.is_dedicated_scene(r.session_id) then return;end if;
 for a in select x.id,x.controller_version from public.combat_v2_actors x
  join clan_marionettisti_private.links l on l.owner_actor_id=x.id
  where x.session_id=r.session_id and x.state='attivo' and x.actor_kind='pg'
   and (not exists(select 1 from combat_consumer_private.activities where session_id=r.session_id)
    or exists(select 1 from combat_consumer_private.activities ctx where ctx.session_id=r.session_id
      and ctx.exchange_id=r.id and ctx.phase='action' and ctx.turn_actor_id=x.id)) loop
  insert into clan_marionettisti_private.control_events(session_id,round_id,owner_actor_id,kind,request_key,fingerprint,payload)
   values(r.session_id,r.id,a.id,'turn_started',r.id,
    public.combat_v2_sha256(jsonb_build_object('round',r.id,'owner',a.id,'controller_version',a.controller_version)),
    jsonb_build_object('authority','command-window-transition/1','controller_version',a.controller_version))
   on conflict(owner_actor_id,kind,request_key) do nothing;
 end loop;
end;
$function$;

