-- Native source clan_marionettisti_private.target_geometry_valid(uuid,uuid,uuid,jsonb) MD5 c769b1a51bff4e080f63c19b4a7a828b

CREATE OR REPLACE FUNCTION clan_marionettisti_private.target_geometry_valid(p_round uuid, p_actor uuid, p_target uuid, p_intent jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.combat_v2_rounds%rowtype;a combat_spatial.actor_states%rowtype;b combat_spatial.actor_states%rowtype;
 iid uuid;range_m integer;
begin
 select * into strict r from public.combat_v2_rounds where id=p_round;
 if p_intent->>'ability_source'='clan' and p_intent->>'ability_id'='e361f7c3-f90b-47ec-bfee-ccbda21257d9' then
  if p_intent?'target_actor_ids' and jsonb_array_length(p_intent->'target_actor_ids')<>1 then return false;end if;
  perform clan_marionettisti_private.attack_source(p_round,p_actor,p_target);return true;
 end if;
 select instance_id into iid from combat_spatial.arena_instances where encounter_id=r.session_id and state='open';
 select * into a from combat_spatial.actor_states where instance_id=iid and actor_id=p_actor and state='active';
 select * into b from combat_spatial.actor_states where instance_id=iid and actor_id=p_target and state='active';
 range_m:=case when p_intent->>'ability_source'='mano' then 2 else public._fascia_metri(p_intent#>>'{server_ability,range}') end;
 return a.actor_id is not null and b.actor_id is not null and range_m is not null
  and combat_spatial.distance_m(a.x_m,a.y_m,b.x_m,b.y_m)<=range_m
  and combat_spatial.path_first_block_t(iid,p_actor,a.x_m,a.y_m,b.x_m,b.y_m,p_target)>=1;
end;
$function$;

