-- Native source clan_sabaku_private.activity_lifecycle() MD5 723d172352b9d5ef24223292ecbc67af

CREATE OR REPLACE FUNCTION clan_sabaku_private.activity_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u record; reason text; aid uuid;
BEGIN
 IF NEW.phase IS NOT DISTINCT FROM OLD.phase AND NEW.exchange_id IS NOT DISTINCT FROM OLD.exchange_id
  AND NEW.turn_actor_id IS NOT DISTINCT FROM OLD.turn_actor_id THEN RETURN NEW; END IF;
 FOR u IN SELECT id,actor_id FROM clan_sabaku_private.transport_uses
  WHERE session_id=NEW.session_id AND state='active' ORDER BY actor_id,id
 LOOP
   reason:=clan_sabaku_private.transport_end_reason(u.id);
   IF reason IS NOT NULL THEN PERFORM clan_sabaku_private.transport_release(u.id,reason); END IF;
 END LOOP;
 IF NEW.phase='closed' THEN
   FOR aid IN SELECT actor_id FROM clan_innata_combat_private.combat_state
    WHERE session_id=NEW.session_id AND active ORDER BY actor_id
   LOOP PERFORM clan_innata_private.combat_terminal(aid,'combat_end'); END LOOP;
 ELSIF NEW.phase='action' AND NEW.exchange_id IS DISTINCT FROM OLD.exchange_id THEN
   PERFORM clan_innata_private.combat_begin_turn(NEW.turn_actor_id);
 END IF;
 RETURN NEW;
END $function$;

