CREATE OR REPLACE FUNCTION clan_sabaku_private.actor_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state WHERE actor_id=NEW.id AND session_id=NEW.session_id AND active)
   THEN RETURN NEW; END IF;
 IF coalesce((NEW.mechanics_snapshot->>'vita')::integer,0)<=0 THEN
   PERFORM clan_innata_private.combat_terminal(NEW.id,'owner_ko');
 ELSIF NEW.state<>'attivo' THEN
   PERFORM clan_innata_private.combat_terminal(NEW.id,'owner_inoperative');
 END IF;
 RETURN NEW;
END $function$;

