CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_apply_immobilization(p_capture uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE capture clan_sabaku_private.clone_captures%ROWTYPE; c clan_sabaku_private.clones%ROWTYPE; effect uuid;
BEGIN
 SELECT * INTO STRICT capture FROM clan_sabaku_private.clone_captures WHERE id=p_capture;
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=capture.clone_id;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=c.session_id FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE session_id=c.session_id AND id IN(c.actor_id,capture.target_actor_id) ORDER BY id FOR UPDATE;
 SELECT id INTO effect FROM combat_panel_private.immobilizations WHERE source_clone_capture_id=capture.id;
 IF effect IS NOT NULL THEN RETURN effect; END IF;
 IF capture.copy_hit OR capture.result->'success' IS DISTINCT FROM 'true'::jsonb THEN RETURN NULL; END IF;
 INSERT INTO combat_panel_private.immobilizations(session_id,source_clone_capture_id,source_declaration_id,
   source_actor_id,target_actor_id,applied_round_id,source_pool)
 VALUES(c.session_id,capture.id,c.declaration_id,c.actor_id,capture.target_actor_id,capture.round_id,
   c.source_kekkei_genkai+c.source_ninjutsu) RETURNING id INTO effect;
 RETURN effect;
END $function$;

