-- Native source clan_sabaku_private.clone_bind(uuid) MD5 b1eedcbee8aa1d707bd90cfe3e535366

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_bind(p_declaration uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.combat_v2_declarations%ROWTYPE; plan clan_sabaku_private.clone_plans%ROWTYPE;
BEGIN
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration;
 SELECT * INTO plan FROM clan_sabaku_private.clone_plans WHERE round_id=d.round_id AND actor_id=d.actor_id AND request_key=d.request_key FOR UPDATE;
 IF plan.id IS NULL THEN RETURN; END IF;
 IF d.kind<>'utilita' OR d.cost_snapshot->'chakra' IS DISTINCT FROM '5'::jsonb
   OR d.cost_snapshot->'damage_base' IS DISTINCT FROM '0'::jsonb
   OR d.controller_user_snapshot IS DISTINCT FROM plan.controller_user OR d.controller_version_snapshot<>plan.controller_version
   OR d.sanitized_intent#>>'{server_ability,sabaku_clone_version}' IS DISTINCT FROM 'sabaku-clone/1'
   OR d.sanitized_intent->>'ability_source' IS DISTINCT FROM 'clan'
   OR d.sanitized_intent->>'ability_id' IS DISTINCT FROM '617484d6-af7b-41c3-a37f-615b22818421'
   OR (plan.declaration_id IS NOT NULL AND plan.declaration_id<>d.id) THEN
   RAISE EXCEPTION 'sabaku_clone_declaration_invalid' USING ERRCODE='22023'; END IF;
 UPDATE clan_sabaku_private.clone_plans SET declaration_id=d.id WHERE id=plan.id;
END $function$;

