-- Native source clan_sabaku_private.clone_capture_guard() MD5 0ce56b7c0caa222e0e259ec2200bb563

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_capture_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c clan_sabaku_private.clones%ROWTYPE; a public.combat_v2_actors%ROWTYPE;
 f combat_panel_private.multiplication_formations%ROWTYPE; expected jsonb; domain text; derived integer[];
 target_x numeric; target_y numeric; event combat_spatial.spatial_events%ROWTYPE;
 cap combat_spatial.movement_capabilities%ROWTYPE; body combat_spatial.actor_states%ROWTYPE;
 path_t numeric; entry_t numeric; end_x numeric; end_y numeric; contact_point jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'sabaku_clone_capture_immutable' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=NEW.clone_id FOR UPDATE;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=NEW.target_actor_id;
 IF c.state<>'armed' OR a.session_id<>c.session_id OR a.id=c.actor_id OR a.actor_kind<>'pg'
   OR a.companion_id IS NOT NULL OR a.state<>'attivo'
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds WHERE id=NEW.round_id AND session_id=c.session_id) THEN
   RAISE EXCEPTION 'sabaku_clone_capture_scope_invalid' USING ERRCODE='22023'; END IF;
 IF NEW.formation_id IS NOT NULL THEN
   SELECT * INTO STRICT f FROM combat_panel_private.multiplication_formations WHERE id=NEW.formation_id;
   IF f.session_id<>c.session_id OR f.actor_id<>a.id OR f.state<>'active'
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(f.figures) v WHERE (v->>'figure_index')::integer=NEW.selected_index)
     OR NEW.copy_hit IS DISTINCT FROM (NEW.selected_index<>f.original_index) THEN
     RAISE EXCEPTION 'sabaku_clone_figure_invalid' USING ERRCODE='22023'; END IF;
 END IF;
 IF NEW.trigger_kind='movement' THEN
   SELECT * INTO STRICT event FROM combat_spatial.spatial_events WHERE event_id=NEW.trigger_event_id;
   SELECT * INTO STRICT cap FROM combat_spatial.movement_capabilities WHERE capability_id=(event.before_state->>'capability_id')::uuid;
   SELECT * INTO STRICT body FROM combat_spatial.actor_states WHERE instance_id=c.instance_id AND actor_id=a.id;
   IF event.event_kind<>'sabaku_clone_contact' OR event.instance_id<>c.instance_id OR event.actor_id<>a.id
     OR event.root_id<>NEW.id OR event.after_state->>'clone_id' IS DISTINCT FROM c.id::text
     OR cap.instance_id<>c.instance_id OR cap.actor_id<>a.id OR cap.state<>'offered'
     OR body.body_version<>cap.actor_body_version OR body.state<>'active'
     OR (cap.start_x_m,cap.start_y_m) IS DISTINCT FROM (body.x_m,body.y_m)
     OR event.before_state->'body_version' IS DISTINCT FROM to_jsonb(body.body_version)
     OR event.before_state->>'movement_root' IS NULL OR NEW.copy_hit OR NEW.formation_id IS NOT NULL THEN
     RAISE EXCEPTION 'sabaku_clone_contact_source_invalid' USING ERRCODE='22023'; END IF;
   path_t:=combat_spatial.path_first_block_t(c.instance_id,a.id,body.x_m,body.y_m,cap.end_x_m,cap.end_y_m);
   end_x:=body.x_m+(cap.end_x_m-body.x_m)*path_t; end_y:=body.y_m+(cap.end_y_m-body.y_m)*path_t;
   contact_point:=clan_sabaku_private.clone_path_contact(body.x_m,body.y_m,end_x,end_y,c.x_m,c.y_m);
   entry_t:=(contact_point->>'entry_t')::numeric;
   target_x:=(contact_point->>'x_m')::numeric;target_y:=(contact_point->>'y_m')::numeric;
   IF entry_t IS NULL OR event.after_state->'entry_t' IS DISTINCT FROM to_jsonb(entry_t)
     OR event.after_state->'x_m' IS DISTINCT FROM to_jsonb(target_x) OR event.after_state->'y_m' IS DISTINCT FROM to_jsonb(target_y) THEN
     RAISE EXCEPTION 'sabaku_clone_contact_geometry_invalid' USING ERRCODE='22023'; END IF;
 ELSIF NEW.formation_id IS NOT NULL THEN
   SELECT (v->>'x_m')::numeric,(v->>'y_m')::numeric INTO STRICT target_x,target_y
     FROM jsonb_array_elements(f.figures) v WHERE (v->>'figure_index')::integer=NEW.selected_index;
 ELSE
   SELECT b.x_m,b.y_m INTO STRICT target_x,target_y FROM combat_spatial.actor_states b
     WHERE b.instance_id=c.instance_id AND b.actor_id=a.id AND b.state='active';
 END IF;
 IF combat_spatial.distance_m(c.x_m,c.y_m,target_x,target_y)>2.000000001 THEN
   RAISE EXCEPTION 'sabaku_clone_trigger_out_of_range' USING ERRCODE='22023'; END IF;
 IF NEW.trigger_kind='initial_presence' AND NEW.round_id<>c.created_round_id
   OR NEW.trigger_kind='movement' AND NOT EXISTS(SELECT 1 FROM combat_spatial.spatial_events
     WHERE event_id=NEW.trigger_event_id AND instance_id=c.instance_id AND actor_id=a.id AND event_kind='sabaku_clone_contact')
   OR NEW.trigger_kind='formation_created' AND (f.id IS NULL OR f.declaration_id IS DISTINCT FROM NEW.trigger_declaration_id OR f.round_id<>NEW.round_id) THEN
   RAISE EXCEPTION 'sabaku_clone_trigger_source_invalid' USING ERRCODE='22023'; END IF;
 IF NEW.copy_hit THEN
   expected:=jsonb_build_object('schema_version','sabaku-clone-capture/1','copy_hit',true,'success',false,'damage',0);
 ELSE
   IF jsonb_typeof(a.mechanics_snapshot->'velocita') IS DISTINCT FROM 'number'
     OR jsonb_typeof(a.mechanics_snapshot->'taijutsu') IS DISTINCT FROM 'number'
     OR NEW.target_velocity IS DISTINCT FROM (a.mechanics_snapshot->>'velocita')::numeric
     OR NEW.target_taijutsu IS DISTINCT FROM (a.mechanics_snapshot->>'taijutsu')::numeric THEN
     RAISE EXCEPTION 'sabaku_clone_target_stats_invalid' USING ERRCODE='22023'; END IF;
   domain:='combat-v2/sabaku-clone-capture/1:'||c.session_id::text||':'||c.id::text||':'||NEW.id::text;
   derived:=ARRAY[public.combat_v2_derive_d10(NEW.entropy,domain,1),public.combat_v2_derive_d10(NEW.entropy,domain,2),
     public.combat_v2_derive_d10(NEW.entropy,domain,3),public.combat_v2_derive_d10(NEW.entropy,domain,4)];
   IF NEW.dice IS DISTINCT FROM derived THEN RAISE EXCEPTION 'sabaku_clone_capture_dice_invalid' USING ERRCODE='22023'; END IF;
   expected:=clan_sabaku_private.clone_capture_result(c.source_kekkei_genkai,c.source_ninjutsu,NEW.target_velocity,NEW.target_taijutsu,NEW.dice);
 END IF;
 IF NEW.result IS DISTINCT FROM expected THEN RAISE EXCEPTION 'sabaku_clone_capture_result_invalid' USING ERRCODE='22023'; END IF;
 RETURN NEW;
END $function$;

