CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_capture_result(p_kg numeric, p_ninjutsu numeric, p_velocity numeric, p_taijutsu numeric, p_dice integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE calc jsonb;
BEGIN
 -- Le quattro statistiche hanno lo stesso dominio del confronto nativo.
 PERFORM combat_panel_private.immobilization_escape_result(p_velocity,p_taijutsu,p_kg,p_dice);
 calc:=combat_panel_private.immobilization_escape_result(p_kg,p_ninjutsu,p_velocity+p_taijutsu,p_dice);
 RETURN jsonb_build_object('schema_version','sabaku-clone-capture/1','copy_hit',false,
   'capture_pool',calc->'escape_pool','target_pool',calc->'source_pool',
   'capture_total',calc->'escape_total','target_total',calc->'hold_total',
   'margin',calc->'margin','success',(calc->>'margin')::numeric>=0,'damage',0);
END $function$;

