-- Native source clan_sabaku_private.clone_commit_sand(uuid) MD5 652e1e4009a83d7388092b05282f164d

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_commit_sand(p_clone uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c clan_sabaku_private.clones%ROWTYPE; r clan_sabaku_private.reserves%ROWTYPE; scope jsonb;
BEGIN
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=p_clone;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=c.session_id FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE id=c.actor_id FOR UPDATE;
 SELECT * INTO STRICT r FROM clan_sabaku_private.reserves WHERE id=c.reserve_id FOR UPDATE;
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=p_clone FOR UPDATE;
 IF EXISTS(SELECT 1 FROM clan_sabaku_private.sand_ledger WHERE clone_id=c.id AND event_kind='commit') THEN RETURN false; END IF;
 scope:=clan_innata_private.combat_scope(c.actor_id);
 IF c.state<>'armed' OR (scope->>'session_id')::uuid IS DISTINCT FROM c.session_id
   OR (scope->>'round_id')::uuid IS DISTINCT FROM c.created_round_id
   OR r.is_test IS DISTINCT FROM (scope->>'is_test')::boolean
   OR r.character_id IS DISTINCT FROM (scope->>'character_id')::uuid
   OR (r.is_test AND (r.session_id IS DISTINCT FROM c.session_id OR r.actor_id IS DISTINCT FROM c.actor_id))
   OR NOT EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state WHERE session_id=c.session_id AND actor_id=c.actor_id
     AND technique_id='001f907c-8f32-4758-8a16-ad1730e72c59' AND active)
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE session_id=c.session_id AND round_id=c.created_round_id
     AND declaration_id=c.declaration_id AND actor_id=c.actor_id AND resource_kind='chakra' AND committed_amount=5)
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE session_id=c.session_id AND round_id=c.created_round_id
     AND declaration_id=c.declaration_id AND actor_id=c.actor_id AND resource_kind='azione_principale' AND committed_amount=1) THEN
   RAISE EXCEPTION 'sabaku_clone_commit_scope_invalid' USING ERRCODE='22023'; END IF;
 UPDATE clan_sabaku_private.reserves SET committed_amount=committed_amount+c.amount,state_version=state_version+1
   WHERE id=r.id AND current_amount-committed_amount>=c.amount;
 IF NOT FOUND THEN RAISE EXCEPTION 'sabaku_clone_sand_unavailable' USING ERRCODE='55000'; END IF;
 INSERT INTO clan_sabaku_private.sand_ledger(clone_id,event_kind,amount) VALUES(c.id,'commit',c.amount);
 RETURN true;
END $function$;

