CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_declaration_meta(p_round uuid, p_actor uuid, p_request uuid, p_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE plan clan_sabaku_private.clone_plans%ROWTYPE;
BEGIN
 SELECT * INTO plan FROM clan_sabaku_private.clone_plans WHERE round_id=p_round AND actor_id=p_actor AND request_key=p_request;
 IF p_intent->>'ability_source'='clan' AND p_intent->>'ability_id'='617484d6-af7b-41c3-a37f-615b22818421' THEN
   IF plan.id IS NULL OR p_intent IS DISTINCT FROM jsonb_build_object('kind','utilita','ability_source','clan',
     'ability_id','617484d6-af7b-41c3-a37f-615b22818421') THEN
     RAISE EXCEPTION 'sabaku_clone_plan_required' USING ERRCODE='22023'; END IF;
 ELSIF plan.id IS NULL THEN RETURN NULL;
 ELSE RAISE EXCEPTION 'sabaku_clone_plan_intent_mismatch' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a WHERE a.id=plan.actor_id
   AND a.controller_user=plan.controller_user AND a.controller_version=plan.controller_version AND a.controller_user=auth.uid()) THEN
   RAISE EXCEPTION 'sabaku_clone_controller_changed' USING ERRCODE='40001'; END IF;
 RETURN jsonb_build_object('source','clan','id','617484d6-af7b-41c3-a37f-615b22818421','name','Clone di Sabbia',
   'kind','ninjutsu','usage','principale','chakra_cost',5,'damage_base',0,'sabaku_clone_version','sabaku-clone/1');
END $function$;

