-- Native source clan_sabaku_private.clone_end_reason(uuid) MD5 73d183f225bf3914b3e24124b86badc0

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_end_reason(p_clone uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c clan_sabaku_private.clones%ROWTYPE; a public.combat_v2_actors%ROWTYPE; s public.combat_v2_sessions%ROWTYPE;
 context clan_innata_combat_private.actor_context; reserve clan_sabaku_private.reserves%ROWTYPE;
 effect combat_panel_private.immobilizations%ROWTYPE; first_round integer; completed_turns bigint;
BEGIN
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=p_clone;
 IF c.state='ended' THEN RETURN c.end_reason; END IF;
 SELECT * INTO STRICT s FROM public.combat_v2_sessions WHERE id=c.session_id;
 IF s.state IN ('chiuso','risolto','annullato') OR s.closed_at IS NOT NULL THEN RETURN 'combat_end'; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=c.actor_id AND session_id=c.session_id;
 IF a.state<>'attivo' OR coalesce((a.mechanics_snapshot->>'vita')::numeric,0)<=0 THEN RETURN 'owner_inoperative'; END IF;
 IF NOT EXISTS(SELECT 1 FROM combat_spatial.arena_instances WHERE instance_id=c.instance_id AND state='open') THEN RETURN 'combat_end'; END IF;
 IF NOT EXISTS(SELECT 1 FROM combat_spatial.actor_states WHERE instance_id=c.instance_id AND actor_id=a.id AND state='active') THEN RETURN 'owner_inoperative'; END IF;
 context:=clan_innata_private.combat_context(a.id);
 IF context.phase='closed' THEN RETURN 'combat_end'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.presence WHERE user_id=a.controller_user AND location_id=context.location_id) THEN RETURN 'owner_absent'; END IF;
 IF NOT EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state WHERE session_id=c.session_id AND actor_id=c.actor_id
   AND technique_id='001f907c-8f32-4758-8a16-ad1730e72c59' AND active) THEN RETURN 'innata_off'; END IF;
 SELECT * INTO STRICT reserve FROM clan_sabaku_private.reserves WHERE id=c.reserve_id;
 IF reserve.committed_amount<c.amount OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.sand_ledger
   WHERE clone_id=c.id AND event_kind='commit') THEN RETURN 'medium_invalid'; END IF;
 IF c.state='holding' THEN
   SELECT e.* INTO effect FROM combat_panel_private.immobilizations e JOIN clan_sabaku_private.clone_captures receipt ON receipt.id=e.source_clone_capture_id
     WHERE receipt.clone_id=c.id;
   IF effect.id IS NULL THEN RETURN 'medium_invalid'; END IF;
   IF effect.state='released' THEN
     RETURN CASE WHEN effect.release_reason='escaped' THEN 'escaped' WHEN effect.release_reason='combat_end' THEN 'combat_end' ELSE 'target_inoperative' END;
   END IF;
 END IF;
 SELECT round_no INTO STRICT first_round FROM public.combat_v2_rounds WHERE id=c.created_round_id;
 -- Ordinary e Master condividono dichiarazioni/round nativi. Un round con
 -- più righe dello stesso autore vale un solo turno; i turni altrui non contano.
 SELECT count(DISTINCT round_source.id) INTO completed_turns FROM public.combat_v2_rounds round_source
   JOIN public.combat_v2_declarations d ON d.round_id=round_source.id AND d.actor_id=c.actor_id
   WHERE round_source.session_id=c.session_id AND round_source.round_no>=first_round
     AND round_source.phase IN ('risolto','narrazione','narrato')
     AND d.kind IN ('attacco','utilita','movimento','passa') AND d.state IN ('risolta','superflua');
 IF completed_turns>=3 THEN RETURN 'duration'; END IF;
 RETURN NULL;
END $function$;

