-- Native source clan_sabaku_private.clone_identity_guard() MD5 bf0bba6eb71a3d61fe949a95e29d4e27

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.combat_v2_declarations%ROWTYPE; a public.combat_v2_actors%ROWTYPE;
 r clan_sabaku_private.reserves%ROWTYPE; kg numeric; ninjutsu numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'sabaku_clone_history_immutable' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' THEN
   IF to_jsonb(NEW)-ARRAY['state','state_version','end_reason','ended_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','state_version','end_reason','ended_at']
     OR OLD.state='ended' OR NEW.state_version<>OLD.state_version+1 OR NEW.state=OLD.state
     OR (OLD.state='holding' AND NEW.state<>'ended') THEN
     RAISE EXCEPTION 'sabaku_clone_transition_invalid' USING ERRCODE='42501'; END IF;
   IF NEW.state='holding' AND NOT EXISTS(SELECT 1 FROM clan_sabaku_private.clone_captures
     WHERE clone_id=NEW.id AND NOT copy_hit AND result->'success'='true'::jsonb) THEN
     RAISE EXCEPTION 'sabaku_clone_hold_without_capture' USING ERRCODE='22023'; END IF;
   RETURN NEW;
 END IF;
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=NEW.declaration_id;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=NEW.actor_id AND session_id=NEW.session_id;
 SELECT * INTO STRICT r FROM clan_sabaku_private.reserves WHERE id=NEW.reserve_id;
 IF a.actor_kind<>'pg' OR a.companion_id IS NOT NULL OR a.state<>'attivo' OR r.character_id<>a.character_id
   OR r.current_amount-r.committed_amount<0
   OR (r.is_test AND (r.session_id IS DISTINCT FROM a.session_id OR r.actor_id IS DISTINCT FROM a.id)) THEN
   RAISE EXCEPTION 'sabaku_clone_reserve_scope_invalid' USING ERRCODE='22023'; END IF;
 IF r.is_test THEN
   SELECT p.kekkei_genkai,p.ninjutsu INTO STRICT kg,ninjutsu FROM clan_sabaku_private.staff_profiles p
     WHERE p.session_id=a.session_id AND p.actor_id=a.id;
 ELSE
   IF jsonb_typeof(a.mechanics_snapshot->'kekkei_genkai') IS DISTINCT FROM 'number'
     OR jsonb_typeof(a.mechanics_snapshot->'ninjutsu') IS DISTINCT FROM 'number' THEN
     RAISE EXCEPTION 'sabaku_clone_source_stats_invalid' USING ERRCODE='22023'; END IF;
   kg:=(a.mechanics_snapshot->>'kekkei_genkai')::numeric;
   ninjutsu:=(a.mechanics_snapshot->>'ninjutsu')::numeric;
 END IF;
 IF NEW.source_kekkei_genkai IS DISTINCT FROM kg OR NEW.source_ninjutsu IS DISTINCT FROM ninjutsu THEN
   RAISE EXCEPTION 'sabaku_clone_source_stats_invalid' USING ERRCODE='22023'; END IF;
 IF NEW.state<>'armed' OR NEW.state_version<>1 OR d.kind<>'utilita' OR d.actor_id<>NEW.actor_id OR d.round_id<>NEW.created_round_id
   OR d.sanitized_intent->>'ability_source' IS DISTINCT FROM 'clan'
   OR d.sanitized_intent->>'ability_id' IS DISTINCT FROM '617484d6-af7b-41c3-a37f-615b22818421'
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds round_source JOIN combat_spatial.arena_instances i ON i.encounter_id=round_source.session_id
     JOIN combat_spatial.arena_templates template ON template.template_key=i.template_key AND template.template_version=i.template_version
     JOIN combat_spatial.actor_states b ON b.instance_id=i.instance_id AND b.actor_id=NEW.actor_id
     WHERE round_source.id=NEW.created_round_id AND round_source.session_id=NEW.session_id AND i.instance_id=NEW.instance_id AND i.state='open'
       AND i.map_version=NEW.map_version AND b.state='active' AND b.body_version=NEW.source_body_version
       AND NEW.x_m<=template.width_m AND NEW.y_m<=template.height_m
       AND combat_spatial.distance_m(b.x_m,b.y_m,NEW.x_m,NEW.y_m)<=3) THEN
   RAISE EXCEPTION 'sabaku_clone_source_invalid' USING ERRCODE='22023'; END IF;
 RETURN NEW;
END $function$;

