CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_immobilization_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE capture clan_sabaku_private.clone_captures%ROWTYPE; c clan_sabaku_private.clones%ROWTYPE;
BEGIN
 IF NEW.source_clone_capture_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO STRICT capture FROM clan_sabaku_private.clone_captures WHERE id=NEW.source_clone_capture_id;
 SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=capture.clone_id;
