   OR c.state='ended' OR NEW.state<>'active' OR NEW.session_id<>c.session_id OR NEW.source_actor_id<>c.actor_id
   OR NEW.source_declaration_id<>c.declaration_id OR NEW.target_actor_id<>capture.target_actor_id
   OR NEW.applied_round_id<>capture.round_id OR NEW.source_pool<>c.source_kekkei_genkai+c.source_ninjutsu THEN
   RAISE EXCEPTION 'sabaku_clone_immobilization_invalid' USING ERRCODE='22023'; END IF;
