-- Native source clan_sabaku_private.clone_movement_intercept(uuid,uuid,numeric,numeric) MD5 7c8bebc47a42b2d1e75939fd889b9f4f

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_movement_intercept(p_capability uuid, p_root uuid, p_end_x numeric, p_end_y numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE cap combat_spatial.movement_capabilities%ROWTYPE; arena combat_spatial.arena_instances%ROWTYPE;
 body combat_spatial.actor_states%ROWTYPE; a public.combat_v2_actors%ROWTYPE; c clan_sabaku_private.clones%ROWTYPE;
 context clan_innata_combat_private.actor_context; contact record; source_reason text;
 cx numeric; cy numeric; capture_id uuid; event_id uuid; entropy bytea; dice integer[]; domain text; calc jsonb; effect_id uuid;
 stop_t numeric; expected_x numeric; expected_y numeric; blocked_t numeric;
BEGIN
 SELECT * INTO STRICT cap FROM combat_spatial.movement_capabilities WHERE capability_id=p_capability;
 SELECT * INTO STRICT arena FROM combat_spatial.arena_instances WHERE instance_id=cap.instance_id;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=cap.actor_id AND session_id=arena.encounter_id;
 -- Il contratto corrente di immobilizzazione ha fonte PG fisico. Nessuna
 -- nuova immunità di prodotto viene dichiarata per PNG o compagni.
 IF a.id IS NULL OR a.actor_kind<>'pg' OR a.companion_id IS NOT NULL
   OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.clones WHERE instance_id=arena.instance_id AND state='armed') THEN
   RETURN jsonb_build_object('x_m',p_end_x,'y_m',p_end_y); END IF;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=a.session_id FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE session_id=a.session_id ORDER BY id FOR UPDATE;
 SELECT * INTO STRICT body FROM combat_spatial.actor_states WHERE instance_id=arena.instance_id AND actor_id=a.id;
 IF cap.state<>'offered' OR arena.state<>'open' OR body.state<>'active' OR a.state<>'attivo'
   OR cap.actor_body_version<>body.body_version OR (cap.start_x_m,cap.start_y_m) IS DISTINCT FROM (body.x_m,body.y_m) THEN
   RAISE EXCEPTION 'sabaku_clone_movement_stale' USING ERRCODE='40001'; END IF;
 blocked_t:=combat_spatial.path_first_block_t(arena.instance_id,a.id,body.x_m,body.y_m,cap.end_x_m,cap.end_y_m);
 expected_x:=body.x_m+(cap.end_x_m-body.x_m)*blocked_t;
 expected_y:=body.y_m+(cap.end_y_m-body.y_m)*blocked_t;
 IF p_root IS NULL OR p_end_x IS DISTINCT FROM expected_x OR p_end_y IS DISTINCT FROM expected_y THEN
   RAISE EXCEPTION 'sabaku_clone_movement_path_mismatch' USING ERRCODE='22023'; END IF;
 PERFORM clan_sabaku_private.clone_reconcile(a.session_id);
 context:=clan_innata_private.combat_context(a.id);
 FOR contact IN
   SELECT candidate.id,candidate.created_at,cp.point,(cp.point->>'entry_t')::numeric AS entry_t
   FROM clan_sabaku_private.clones candidate JOIN public.combat_v2_actors owner_actor ON owner_actor.id=candidate.actor_id
   CROSS JOIN LATERAL (SELECT clan_sabaku_private.clone_path_contact(body.x_m,body.y_m,p_end_x,p_end_y,candidate.x_m,candidate.y_m) AS point) cp
   WHERE candidate.instance_id=arena.instance_id AND candidate.state='armed' AND candidate.actor_id<>a.id
     AND owner_actor.team_key<>a.team_key AND cp.point IS NOT NULL
   ORDER BY (cp.point->>'step')::integer,candidate.created_at,candidate.id
 LOOP
   SELECT * INTO STRICT c FROM clan_sabaku_private.clones WHERE id=contact.id FOR UPDATE;
   IF c.state<>'armed' THEN CONTINUE; END IF;
   source_reason:=clan_sabaku_private.clone_end_reason(c.id);
   IF source_reason IS NOT NULL THEN PERFORM clan_sabaku_private.clone_release(c.id,source_reason); CONTINUE; END IF;
   cx:=(contact.point->>'x_m')::numeric;
   cy:=(contact.point->>'y_m')::numeric;
   capture_id:=gen_random_uuid(); event_id:=gen_random_uuid();
   domain:='combat-v2/sabaku-clone-capture/1:'||c.session_id::text||':'||c.id::text||':'||capture_id::text;
   entropy:=extensions.gen_random_bytes(32);
   dice:=ARRAY[public.combat_v2_derive_d10(entropy,domain,1),public.combat_v2_derive_d10(entropy,domain,2),
     public.combat_v2_derive_d10(entropy,domain,3),public.combat_v2_derive_d10(entropy,domain,4)];
   calc:=clan_sabaku_private.clone_capture_result(c.source_kekkei_genkai,c.source_ninjutsu,
     (a.mechanics_snapshot->>'velocita')::numeric,(a.mechanics_snapshot->>'taijutsu')::numeric,dice);
   -- Root del contatto = ricevuta di cattura; il root del movimento e la
   -- capability nativa restano esplicitamente vincolati nei fatti privati.
   INSERT INTO combat_spatial.spatial_events(event_id,instance_id,event_kind,root_id,actor_id,before_state,after_state,narrator_payload,created_at)
   VALUES(event_id,arena.instance_id,'sabaku_clone_contact',capture_id,a.id,
     jsonb_build_object('capability_id',cap.capability_id,'movement_root',p_root,'body_version',body.body_version),
     jsonb_build_object('clone_id',c.id,'x_m',cx,'y_m',cy,'entry_t',contact.entry_t),
     jsonb_build_object('before','spostamento','impact','innesco della trappola','after','confronto di presa'),clock_timestamp());
   INSERT INTO clan_sabaku_private.clone_captures(id,clone_id,round_id,target_actor_id,trigger_kind,trigger_event_id,
     copy_hit,target_velocity,target_taijutsu,entropy,dice,result)
   VALUES(capture_id,c.id,context.exchange_id,a.id,'movement',event_id,false,
     (a.mechanics_snapshot->>'velocita')::numeric,(a.mechanics_snapshot->>'taijutsu')::numeric,entropy,dice,calc);
   IF (calc->>'success')::boolean THEN
     effect_id:=clan_sabaku_private.clone_apply_immobilization(capture_id);
     IF effect_id IS NULL THEN RAISE EXCEPTION 'sabaku_clone_hold_missing' USING ERRCODE='22023'; END IF;
     UPDATE clan_sabaku_private.clones SET state='holding',state_version=state_version+1 WHERE id=c.id;
     stop_t:=contact.entry_t;
     EXIT;
   ELSE PERFORM clan_sabaku_private.clone_release(c.id,'capture_failed'); END IF;
 END LOOP;
 IF stop_t IS NOT NULL THEN RETURN jsonb_build_object('x_m',cx,'y_m',cy); END IF;
 RETURN jsonb_build_object('x_m',p_end_x,'y_m',p_end_y);
END $function$;

