-- Native source clan_sabaku_private.clone_offers(uuid,bigint,jsonb) MD5 78954ce491332db13d281b4de98739c9

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_offers(p_context uuid, p_expected bigint, p_view jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_panel_private.contexts%ROWTYPE; b combat_spatial.actor_states%ROWTYPE;
 arena combat_spatial.arena_instances%ROWTYPE; template combat_spatial.arena_templates%ROWTYPE;
 offer_id uuid; directions uuid; direction_id uuid; points uuid; direction record; point record;
 point_count integer; step_limit integer;
BEGIN
 c:=combat_panel_private.owned_context(p_context,p_expected);
 IF c.command_actor_id IS NULL OR c.round_id IS NULL OR c.activity_kind NOT IN ('ordinary_v2','master_v2')
   OR p_view#>>'{context,phase}' IS DISTINCT FROM 'action' OR p_view#>>'{viewer,can_command}' IS DISTINCT FROM 'true' THEN RETURN; END IF;
 BEGIN
   IF NOT clan_sabaku_private.clone_ready(c.command_actor_id) THEN RETURN; END IF;
 EXCEPTION WHEN insufficient_privilege THEN RETURN; END;
 IF EXISTS(SELECT 1 FROM combat_panel_private.offers WHERE context_id=c.id AND context_version=c.context_version
   AND state='offered' AND source_payload->>'dispatch'='sabaku_clone') THEN RETURN; END IF;
 SELECT * INTO STRICT arena FROM combat_spatial.arena_instances WHERE encounter_id=c.activity_id AND state='open'
   AND context_source IN ('ordinary','panel_master');
 SELECT * INTO STRICT b FROM combat_spatial.actor_states WHERE instance_id=arena.instance_id AND actor_id=c.command_actor_id AND state='active';
 SELECT * INTO STRICT template FROM combat_spatial.arena_templates WHERE template_key=arena.template_key AND template_version=arena.template_version;
 offer_id:=combat_panel_private.create_offer(c.id,c.context_version,'action','declare','Clone di Sabbia · 5 chakra · 5 sabbia',true,
   jsonb_build_object('adapter',c.activity_kind,'dispatch','sabaku_clone','kind','utilita'));
 directions:=combat_panel_private.add_group(offer_id,'Direzione del piazzamento','mode','single',1,1);
 FOR direction IN SELECT * FROM (VALUES
   (0,'here','Qui',0,0),(1,'north','Nord',0,-1),(2,'northeast','Nord-est',1,-1),(3,'east','Est',1,0),
   (4,'southeast','Sud-est',1,1),(5,'south','Sud',0,1),(6,'southwest','Sud-ovest',-1,1),
   (7,'west','Ovest',-1,0),(8,'northwest','Nord-ovest',-1,-1)) AS v(ordinal,key,label,dx,dy) ORDER BY ordinal LOOP
   step_limit:=CASE WHEN direction.key='here' THEN 0 WHEN direction.dx<>0 AND direction.dy<>0 THEN 1 ELSE 3 END;
   SELECT count(*) INTO point_count FROM generate_series(CASE WHEN direction.key='here' THEN 0 ELSE 1 END,step_limit) n
     WHERE b.x_m+n*direction.dx BETWEEN 0 AND template.width_m AND b.y_m+n*direction.dy BETWEEN 0 AND template.height_m;
   IF point_count=0 THEN CONTINUE; END IF;
   direction_id:=combat_panel_private.add_choice(directions,direction.label,jsonb_build_object('clone_direction',direction.key));
   points:=combat_panel_private.add_group(offer_id,'Distanza del piazzamento','generic','single',1,1,direction_id);
   FOR point IN SELECT b.x_m+n*direction.dx AS x,b.y_m+n*direction.dy AS y,
       combat_spatial.distance_m(b.x_m,b.y_m,b.x_m+n*direction.dx,b.y_m+n*direction.dy) AS metres
     FROM generate_series(CASE WHEN direction.key='here' THEN 0 ELSE 1 END,step_limit) n
     WHERE b.x_m+n*direction.dx BETWEEN 0 AND template.width_m AND b.y_m+n*direction.dy BETWEEN 0 AND template.height_m ORDER BY n LOOP
     PERFORM combat_panel_private.add_choice(points,CASE WHEN point.metres=0 THEN 'Posizione attuale' ELSE point.metres::integer::text||' m' END,
       jsonb_build_object('clone_position',jsonb_build_object('instance_id',arena.instance_id,'map_version',arena.map_version,
         'body_version',b.body_version,'x_m',point.x,'y_m',point.y)),point.metres);
   END LOOP;
 END LOOP;
END $function$;

