-- Native source clan_sabaku_private.clone_path_contact(numeric,numeric,numeric,numeric,numeric,numeric) MD5 a41bb2cd5f1f4a85067f96cd9f7ed473

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_path_contact(p_x0 numeric, p_y0 numeric, p_x1 numeric, p_y1 numeric, p_clone_x numeric, p_clone_y numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE point record;total numeric;v numeric;
BEGIN
 FOREACH v IN ARRAY ARRAY[p_x0,p_y0,p_x1,p_y1,p_clone_x,p_clone_y] LOOP
  IF v IS NULL OR v IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) OR v<>round(v) THEN
   RAISE EXCEPTION 'integer_clone_coordinate_invalid' USING ERRCODE='22023';END IF;
 END LOOP;
 total:=abs(p_x1-p_x0)+abs(p_y1-p_y0);
 FOR point IN SELECT * FROM combat_spatial.integer_path_points(p_x0,p_y0,p_x1,p_y1) ORDER BY step LOOP
  IF abs(point.x_m-p_clone_x)+abs(point.y_m-p_clone_y)<=2 THEN
   RETURN jsonb_build_object('x_m',point.x_m,'y_m',point.y_m,'step',point.step,
    'entry_t',CASE WHEN total=0 THEN 0 ELSE point.step/total END);
  END IF;
 END LOOP;
 RETURN NULL;
END $function$;

