CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_plan_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'sabaku_clone_plan_history_immutable' USING ERRCODE='42501'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.declaration_id IS NOT NULL OR NEW.result IS NOT NULL THEN
     RAISE EXCEPTION 'sabaku_clone_plan_initial_state_invalid' USING ERRCODE='22023'; END IF;
 ELSIF to_jsonb(NEW)-ARRAY['declaration_id','result','resolved_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['declaration_id','result','resolved_at']
   OR OLD.result IS NOT NULL
   OR (OLD.declaration_id IS NOT NULL AND NEW.declaration_id IS DISTINCT FROM OLD.declaration_id) THEN
   RAISE EXCEPTION 'sabaku_clone_plan_immutable' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $function$;

