CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_prepare(p_round uuid, p_actor uuid, p_instance uuid, p_map_version bigint, p_body_version bigint, p_x numeric, p_y numeric, p_request uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; r public.combat_v2_rounds%ROWTYPE;
 old_plan clan_sabaku_private.clone_plans%ROWTYPE; new_id uuid;
BEGIN
 IF auth.uid() IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'sabaku_clone_auth_required' USING ERRCODE='42501'; END IF;
 PERFORM public.combat_v2_lock_round(p_round);
 SELECT * INTO STRICT r FROM public.combat_v2_rounds WHERE id=p_round FOR UPDATE;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor AND session_id=r.session_id FOR UPDATE;
 IF a.controller_user IS DISTINCT FROM auth.uid() OR a.actor_kind<>'pg' OR a.companion_id IS NOT NULL THEN
   RAISE EXCEPTION 'sabaku_clone_actor_not_controlled' USING ERRCODE='42501'; END IF;
 SELECT * INTO old_plan FROM clan_sabaku_private.clone_plans WHERE round_id=p_round AND actor_id=p_actor;
 IF old_plan.id IS NOT NULL THEN
   IF old_plan.request_key=p_request AND old_plan.controller_user=auth.uid() AND old_plan.controller_version=a.controller_version
     AND old_plan.instance_id=p_instance AND old_plan.map_version=p_map_version AND old_plan.body_version=p_body_version
     AND old_plan.x_m=p_x AND old_plan.y_m=p_y THEN RETURN old_plan.id; END IF;
   RAISE EXCEPTION 'sabaku_clone_plan_conflict' USING ERRCODE='40001'; END IF;
 PERFORM clan_sabaku_private.clone_reconcile(r.session_id);
 IF r.phase<>'raccolta_azioni' OR NOT clan_sabaku_private.clone_ready(a.id)
   OR (clan_innata_private.combat_scope(a.id)->>'round_id')::uuid IS DISTINCT FROM r.id THEN
   RAISE EXCEPTION 'sabaku_clone_not_available' USING ERRCODE='40001'; END IF;
 IF p_x IS NULL OR p_y IS NULL OR p_x<0 OR p_y<0
   OR p_x IN ('NaN'::numeric,'Infinity'::numeric) OR p_y IN ('NaN'::numeric,'Infinity'::numeric)
   OR NOT EXISTS(SELECT 1 FROM combat_spatial.arena_instances i
     JOIN combat_spatial.arena_templates t ON t.template_key=i.template_key AND t.template_version=i.template_version
     JOIN combat_spatial.actor_states b ON b.instance_id=i.instance_id
     WHERE i.instance_id=p_instance AND i.encounter_id=r.session_id AND i.state='open' AND i.map_version=p_map_version
       AND b.actor_id=a.id AND b.state='active' AND b.body_version=p_body_version
       AND p_x<=t.width_m AND p_y<=t.height_m AND combat_spatial.distance_m(b.x_m,b.y_m,p_x,p_y)<=3) THEN
   RAISE EXCEPTION 'sabaku_clone_placement_invalid' USING ERRCODE='40001'; END IF;
 INSERT INTO clan_sabaku_private.clone_plans(session_id,round_id,actor_id,request_key,controller_user,controller_version,
   instance_id,map_version,body_version,x_m,y_m)
 VALUES(r.session_id,r.id,a.id,p_request,a.controller_user,a.controller_version,p_instance,p_map_version,p_body_version,p_x,p_y)
 RETURNING id INTO new_id;
 RETURN new_id;
END $function$;

