CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_ready(p_actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE scope jsonb; a public.combat_v2_actors%ROWTYPE; c clan_innata_combat_private.actor_context;
 r clan_sabaku_private.reserves%ROWTYPE;
BEGIN
 scope:=clan_innata_private.combat_scope(p_actor);
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 c:=clan_innata_private.combat_context(a.id);
 r:=clan_sabaku_private.reserve_for_actor(a.id);
 RETURN c.phase='action' AND c.turn_actor_id=a.id AND a.companion_id IS NULL
   AND coalesce((a.mechanics_snapshot->>'chakra')::integer,0)>=5
   AND r.id IS NOT NULL AND r.current_amount-r.committed_amount>=5
   AND EXISTS(SELECT 1 FROM public.presence WHERE user_id=a.controller_user AND location_id=c.location_id)
   AND EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state WHERE session_id=a.session_id AND actor_id=a.id
     AND technique_id='001f907c-8f32-4758-8a16-ad1730e72c59' AND active)
   AND ((scope->>'is_test')::boolean OR EXISTS(SELECT 1 FROM public.character_abilities
     WHERE character_id=a.character_id AND technique_id='617484d6-af7b-41c3-a37f-615b22818421' AND state='attiva'))
   AND NOT EXISTS(SELECT 1 FROM clan_marionettisti_private.links WHERE owner_actor_id=a.id AND state='connected')
   AND NOT EXISTS(SELECT 1 FROM clan_sabaku_private.clones WHERE session_id=a.session_id AND actor_id=a.id AND state<>'ended')
   AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=c.exchange_id AND actor_id=a.id
     AND kind IN ('attacco','utilita','movimento','passa'))
   AND EXISTS(SELECT 1 FROM combat_spatial.arena_instances i JOIN combat_spatial.actor_states b ON b.instance_id=i.instance_id
     WHERE i.encounter_id=a.session_id AND i.context_source IN ('ordinary','panel_master') AND i.state='open'
       AND b.actor_id=a.id AND b.state='active');
END $function$;

