-- Native source clan_sabaku_private.clone_reconcile(uuid) MD5 f9af15e53e40a9998ac1c23e90a2e693

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_reconcile(p_session uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c record; reason text; released integer:=0;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM clan_sabaku_private.clones WHERE session_id=p_session AND state<>'ended') THEN RETURN 0; END IF;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=p_session FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE session_id=p_session ORDER BY id FOR UPDATE;
 FOR c IN SELECT id FROM clan_sabaku_private.clones WHERE session_id=p_session AND state<>'ended' ORDER BY actor_id,id LOOP
   reason:=clan_sabaku_private.clone_end_reason(c.id);
   IF reason IS NOT NULL AND clan_sabaku_private.clone_release(c.id,reason) THEN released:=released+1; END IF;
 END LOOP;
 RETURN released;
END $function$;

