-- Native source clan_sabaku_private.clone_record_interrupted_movement(uuid,uuid,uuid) MD5 d15b38055e319778b087cee5eb812386

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_record_interrupted_movement(p_capability uuid, p_round uuid, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE info jsonb; receipt jsonb; context clan_innata_combat_private.actor_context;
BEGIN
 info:=clan_sabaku_private.clone_movement_interruption(p_capability);
 IF info IS NULL THEN RAISE EXCEPTION 'sabaku_clone_interruption_missing' USING ERRCODE='22023'; END IF;
 context:=clan_innata_private.combat_context(p_actor);
 IF context.exchange_id IS DISTINCT FROM p_round OR NOT EXISTS(SELECT 1 FROM combat_spatial.movement_capabilities
   WHERE capability_id=p_capability AND actor_id=p_actor AND state='committed') THEN
   RAISE EXCEPTION 'sabaku_clone_interruption_scope_invalid' USING ERRCODE='22023'; END IF;
 -- A zero metri il costo è zero e basta l'evento spaziale/cattura. Il ledger
 -- esistente conserva il CHECK distance_m>0 e non riceve metri artificiali.
 IF (info->>'distance_m')::numeric=0 THEN RETURN; END IF;
 IF EXISTS(SELECT 1 FROM clan_marionettisti_private.movement_receipts WHERE capability_id=p_capability) THEN RETURN; END IF;
 SELECT result INTO STRICT receipt FROM combat_spatial.request_receipts
   WHERE operation='movement_commit' AND result->>'event_id'=info->>'event_id';
 INSERT INTO clan_marionettisti_private.movement_receipts(request_key,round_id,owner_actor_id,body_actor_id,capability_id,distance_m,result)
 VALUES(md5(p_capability::text||':clone-interruption')::uuid,p_round,p_actor,p_actor,p_capability,(info->>'distance_m')::numeric,receipt);
END $function$;

