RESET ROLE;

-- Native source clan_sabaku_private.clone_resolve_creation(uuid) MD5 f91299141f1f9f8a604f8aeecbc5f4c7

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_resolve_creation(p_declaration uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.combat_v2_declarations%ROWTYPE; plan clan_sabaku_private.clone_plans%ROWTYPE;
 a public.combat_v2_actors%ROWTYPE; reserve clan_sabaku_private.reserves%ROWTYPE;
 c clan_innata_combat_private.actor_context; new_id uuid; kg numeric; ninjutsu numeric; reason text; creation_result jsonb;
BEGIN
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration FOR UPDATE;
 SELECT * INTO STRICT plan FROM clan_sabaku_private.clone_plans WHERE declaration_id=d.id FOR UPDATE;
 IF plan.result IS NOT NULL THEN RETURN plan.result; END IF;
 IF d.kind<>'utilita' OR d.state<>'congelata' OR d.actor_id<>plan.actor_id OR d.round_id<>plan.round_id
   OR d.sanitized_intent#>>'{server_ability,sabaku_clone_version}' IS DISTINCT FROM 'sabaku-clone/1'
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds WHERE id=d.round_id AND session_id=plan.session_id AND phase='risoluzione') THEN
   RAISE EXCEPTION 'sabaku_clone_resolution_invalid' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=d.actor_id FOR UPDATE;
 c:=clan_innata_private.combat_context(a.id);
 IF a.state<>'attivo' OR coalesce((a.mechanics_snapshot->>'vita')::numeric,0)<=0 THEN reason:='owner_inoperative';
 ELSIF NOT EXISTS(SELECT 1 FROM public.presence WHERE user_id=a.controller_user AND location_id=c.location_id) THEN reason:='owner_absent';
 ELSIF NOT EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state WHERE session_id=plan.session_id AND actor_id=a.id
   AND technique_id='001f907c-8f32-4758-8a16-ad1730e72c59' AND active) THEN reason:='innata_off';
 ELSIF NOT EXISTS(SELECT 1 FROM combat_spatial.arena_instances i JOIN combat_spatial.actor_states b ON b.instance_id=i.instance_id
   WHERE i.instance_id=plan.instance_id AND i.encounter_id=plan.session_id AND i.state='open' AND i.map_version=plan.map_version
     AND b.actor_id=a.id AND b.state='active' AND b.body_version=plan.body_version) THEN reason:='placement_changed';
 ELSIF EXISTS(SELECT 1 FROM clan_sabaku_private.clones WHERE session_id=plan.session_id AND actor_id=a.id AND state<>'ended') THEN reason:='clone_already_active';
 END IF;
 IF reason IS NULL THEN
   reserve:=clan_sabaku_private.reserve_for_actor(a.id);
   IF reserve.id IS NULL OR reserve.current_amount-reserve.committed_amount<5 THEN reason:='sand_unavailable'; END IF;
 END IF;
 IF reason IS NOT NULL THEN
   creation_result:=jsonb_build_object('kind','utilita','sabaku_clone',jsonb_build_object('schema_version','sabaku-clone/1',
     'created',false,'reason',reason,'chakra_cost',5,'main_cost',1,'sand_committed',0,'refund',false));
 ELSE
   IF reserve.is_test THEN
     SELECT p.kekkei_genkai,p.ninjutsu INTO STRICT kg,ninjutsu FROM clan_sabaku_private.staff_profiles p WHERE p.session_id=plan.session_id AND p.actor_id=a.id;
   ELSE kg:=(a.mechanics_snapshot->>'kekkei_genkai')::numeric; ninjutsu:=(a.mechanics_snapshot->>'ninjutsu')::numeric; END IF;
   -- La carica chakra e la principale sono già nel ledger nativo. Inserimento
   -- entità e impegno sabbia sono contigui: nessun trigger di turno vede metà creazione.
   INSERT INTO clan_sabaku_private.clones(session_id,actor_id,declaration_id,created_round_id,instance_id,reserve_id,
     map_version,source_body_version,x_m,y_m,source_kekkei_genkai,source_ninjutsu)
   VALUES(plan.session_id,a.id,d.id,plan.round_id,plan.instance_id,reserve.id,plan.map_version,plan.body_version,plan.x_m,plan.y_m,kg,ninjutsu)
   RETURNING id INTO new_id;
   PERFORM clan_sabaku_private.clone_commit_sand(new_id);
   PERFORM clan_sabaku_private.clone_trigger_nearby(new_id,plan.round_id,'initial_presence');
   creation_result:=jsonb_build_object('kind','utilita','sabaku_clone',jsonb_build_object('schema_version','sabaku-clone/1',
     'created',true,'clone_id',new_id,'chakra_cost',5,'main_cost',1,'sand_committed',5,'refund',false,
     'state',(SELECT state FROM clan_sabaku_private.clones WHERE id=new_id),
     'capture_id',(SELECT id FROM clan_sabaku_private.clone_captures WHERE clone_id=new_id)));
 END IF;
 UPDATE clan_sabaku_private.clone_plans SET result=creation_result,resolved_at=clock_timestamp() WHERE id=plan.id;
 RETURN creation_result;
END $function$;

