CREATE OR REPLACE FUNCTION clan_sabaku_private.consumer_options(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE aid uuid:=(p#>>'{viewer,actor_id}')::uuid; sid uuid:=(p#>>'{context,activity_id}')::uuid;
 c combat_consumer_private.activities%ROWTYPE; a public.combat_v2_actors%ROWTYPE;
 s clan_innata_combat_private.combat_state%ROWTYPE; offers jsonb:=coalesce(p->'offers','[]'::jsonb);
 scene integer:=(p#>>'{context,scene_version}')::integer; scope jsonb;
BEGIN
 IF aid IS NULL OR sid IS NULL OR p->>'status'<>'ready' THEN RETURN p; END IF;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=aid AND session_id=sid
  AND actor_kind='pg' AND state='attivo' AND controller_user=auth.uid();
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM combat_consumer_private.members
   WHERE session_id=sid AND actor_id=aid AND character_id=a.character_id) THEN RETURN p; END IF;
 SELECT * INTO STRICT c FROM combat_consumer_private.activities WHERE session_id=sid;
 IF coalesce(a.character_id='6bceee99-974f-426b-8d92-38b43b4a4267'::uuid
   AND c.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   AND c.policy_id='staff_test_no_persistent_resources_v1' AND c.phase<>'closed'
   AND c.closed_at IS NULL AND NOT public.combat_v2_values_written(a.session_id)
   AND EXISTS(SELECT 1 FROM public.combat_v2_sessions ss WHERE ss.id=a.session_id
     AND ss.location_id=c.location_id AND ss.closed_at IS NULL
     AND ss.state NOT IN ('chiusa','annullata'))
   AND (SELECT count(*) FROM public.combat_v2_actors x
     WHERE x.session_id=a.session_id AND x.actor_kind='pg')=2
   AND (SELECT count(*) FROM combat_consumer_private.members m WHERE m.session_id=a.session_id)=2
   AND EXISTS(SELECT 1 FROM combat_consumer_private.members m
     JOIN public.combat_v2_actors x ON x.id=m.actor_id AND x.session_id=m.session_id
       AND x.character_id=m.character_id AND x.actor_kind='pg'
     JOIN public.characters staff_pg ON staff_pg.id=x.character_id AND staff_pg.user_id=x.controller_user
     WHERE m.session_id=a.session_id
     HAVING count(*)=2 AND count(DISTINCT x.controller_user)=2
       AND array_agg(DISTINCT x.character_id ORDER BY x.character_id)=ARRAY[
         '2a877f02-4993-4e65-9172-7d29f08c5b86'::uuid,'6bceee99-974f-426b-8d92-38b43b4a4267'::uuid]
       AND combat_consumer_private.staff_test_allowed(c.location_id,
         array_agg(DISTINCT x.controller_user ORDER BY x.controller_user),false)),false)
  AND c.phase='action' AND c.turn_actor_id=aid AND c.policy_id='staff_test_no_persistent_resources_v1'
  AND NOT public.combat_v2_values_written(sid)
  AND EXISTS(SELECT 1 FROM clan_sabaku_private.release_gate WHERE singleton AND staff_enabled)
  AND NOT EXISTS(SELECT 1 FROM clan_sabaku_private.staff_profiles WHERE session_id=sid AND actor_id=aid)
  AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=c.exchange_id AND actor_id=aid)
  AND NOT EXISTS(SELECT 1 FROM clan_marionettisti_private.sources WHERE session_id=sid AND owner_actor_id=aid)
  AND NOT clan_sabaku_private.narrative_pending(sid) THEN
   offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,null,scene,'control',
     'Prepara la prova Sabaku: giara personale',jsonb_build_object('sabaku_operation','staff_profile','expected_state',0)));
   RETURN jsonb_set(p,'{offers}',offers);
 END IF;
 BEGIN scope:=clan_innata_private.combat_actor_context(aid);
 EXCEPTION WHEN insufficient_privilege THEN RETURN p; END;
 s:=clan_innata_private.combat_state_ensure(aid);
 IF s.active THEN PERFORM clan_sabaku_private.reserve_ensure(aid); END IF;
 IF coalesce(s.active,false) THEN
   offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,null,scene,'control',
     'Spegni Controllo della Sabbia · gratuito',
     jsonb_build_object('sabaku_operation','deactivate','expected_state',s.state_version)));
 ELSIF c.phase='action' AND c.turn_actor_id=aid AND coalesce((a.mechanics_snapshot->>'chakra')::integer,0)>=5
   AND NOT EXISTS(SELECT 1 FROM clan_marionettisti_private.links WHERE owner_actor_id=aid AND state='connected') THEN
   offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,null,scene,'control',
     'Attiva Controllo della Sabbia · 5 chakra',
     jsonb_build_object('sabaku_operation','activate','expected_state',coalesce(s.state_version,0))));
 END IF;
 IF clan_sabaku_private.transport_ready(aid) THEN
   offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,null,scene,'control',
     'Trasporto di Sabbia · 5 chakra e 5 sabbia impegnata',
     jsonb_build_object('sabaku_operation','transport','expected_state',s.state_version)));
 END IF;
 RETURN clan_sabaku_private.consumer_projection(jsonb_set(p,'{offers}',offers));
END $function$;

