CREATE OR REPLACE FUNCTION clan_sabaku_private.consumer_projection(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE view jsonb; aid uuid;
BEGIN
 IF p->>'status'<>'ready' THEN RETURN p||jsonb_build_object('sabaku_transport',null); END IF;
 aid:=(p#>>'{viewer,actor_id}')::uuid;
 view:=clan_sabaku_private.owner_projection(aid);
 p:=p||jsonb_build_object('sabaku_transport',view);
 IF coalesce((view#>>'{innata,active}')::boolean,false) THEN
   -- Il server autorizza solo l'offerta OFF in questa finestra; l'abilitazione
   -- del form non crea permessi per dichiarazioni o altri controlli.
   p:=jsonb_set(p,'{viewer,can_command}','true'::jsonb,false);
 END IF;
 RETURN p;
END $function$;

