CREATE OR REPLACE FUNCTION clan_sabaku_private.master_bind(p_actor uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; result jsonb; receipt uuid:=gen_random_uuid();
BEGIN
 IF p_request IS NULL OR NOT coalesce(clan_sabaku_private.master_bind_ready(p_actor),false) THEN
   RAISE EXCEPTION 'sabaku_master_bind_not_ready' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor FOR UPDATE;
 result:=jsonb_build_object('receipt_id',receipt,'operation','staff_profile','main_action_consumed',false,
   'is_test',true,'values_written',false,'replayed',false);
 INSERT INTO clan_sabaku_private.staff_profiles(session_id,actor_id,request_id,receipt_id,bind_result)
   VALUES(a.session_id,a.id,p_request,receipt,result);
 INSERT INTO clan_sabaku_private.reserves(character_id,session_id,actor_id,is_test,capacity,current_amount)
   VALUES(a.character_id,a.session_id,a.id,true,15,15);
 PERFORM clan_innata_private.combat_state_ensure(a.id);
 RETURN result;
END $function$;

