CREATE OR REPLACE FUNCTION clan_sabaku_private.master_bind_ready(p_actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; c clan_innata_combat_private.actor_context;
 principals uuid[];
BEGIN
 IF auth.uid() IS NULL THEN RETURN false; END IF;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=p_actor AND controller_user=auth.uid()
   AND actor_kind='pg' AND companion_id IS NULL AND state='attivo'
   AND character_id='6bceee99-974f-426b-8d92-38b43b4a4267';
 IF NOT FOUND THEN RETURN false; END IF;
 c:=clan_innata_private.combat_context(a.id);
 IF c.activity_kind<>'master_v2' OR c.phase<>'action' OR c.turn_actor_id IS DISTINCT FROM a.id
   OR c.policy_id<>'staff_test_no_persistent_resources_v1' OR public.combat_v2_values_written(a.session_id)
   OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.release_gate WHERE singleton AND staff_enabled)
   OR EXISTS(SELECT 1 FROM clan_sabaku_private.staff_profiles WHERE session_id=a.session_id AND actor_id=a.id)
   OR EXISTS(SELECT 1 FROM clan_marionettisti_private.sources WHERE session_id=a.session_id AND owner_actor_id=a.id)
   OR EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=c.exchange_id AND actor_id=a.id)
   OR jsonb_typeof(a.mechanics_snapshot->'chakra') IS DISTINCT FROM 'number'
   OR jsonb_typeof(a.mechanics_snapshot->'vita') IS DISTINCT FROM 'number'
   OR coalesce((a.mechanics_snapshot->>'chakra')::integer,-1)<0
   OR coalesce((a.mechanics_snapshot->>'vita')::integer,0)<=0 THEN RETURN false; END IF;
 SELECT array_agg(DISTINCT a0.controller_user) INTO principals FROM public.combat_v2_actors a0
   JOIN public.characters pg ON pg.id=a0.character_id AND pg.user_id=a0.controller_user
   WHERE a0.session_id=a.session_id AND a0.actor_kind='pg' AND a0.companion_id IS NULL;
 RETURN cardinality(principals)=2
   AND (SELECT count(*) FROM public.combat_v2_actors WHERE session_id=a.session_id AND actor_kind='pg')=2
   AND coalesce(combat_consumer_private.staff_test_allowed(c.location_id,principals,false),false)
   AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors WHERE session_id=a.session_id
     AND (controller_user IS NULL OR NOT(controller_user=ANY(principals))));
EXCEPTION WHEN insufficient_privilege THEN RETURN false;
END $function$;

