CREATE OR REPLACE FUNCTION clan_sabaku_private.master_panel_projection(p_actor uuid, p_panel_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c clan_innata_combat_private.actor_context; src jsonb; result jsonb;
BEGIN
 IF p_actor IS NULL THEN RETURN NULL; END IF;
 src:=clan_sabaku_private.owner_projection(p_actor);
 IF src IS NULL THEN RETURN NULL; END IF;
 c:=clan_innata_private.combat_context(p_actor);
 IF c.activity_kind<>'master_v2' OR c.personal_turn_id IS NULL THEN
   RAISE EXCEPTION 'sabaku_master_projection_scope_invalid' USING ERRCODE='22023'; END IF;
