 -- dati sostituisce la scadenza con la vera identita del turno personale.
 result:=clan_sabaku_private.panel_view_from_ordinary(src,c.context_version,p_panel_version,
   c.exchange_id,(src->>'is_test')::boolean);
 IF (src#>>'{transport,active}')::boolean THEN
   result:=jsonb_set(result,'{transport,expires_context}',jsonb_build_object(
     'kind','master_actor_turn','id',c.personal_turn_id,'label','Fine del tuo turno'));
 END IF;
 RETURN result;
END $function$;

