CREATE OR REPLACE FUNCTION clan_sabaku_private.off_offer_valid(p_offer uuid, p_actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE scope jsonb;
BEGIN
 scope:=clan_innata_private.combat_actor_context(p_actor);
