-- Native source clan_sabaku_private.owner_projection(uuid) MD5 55fb821773db499e8c5153e334bada8c

CREATE OR REPLACE FUNCTION clan_sabaku_private.owner_projection(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE scope jsonb; r clan_sabaku_private.reserves%ROWTYPE;
 s clan_innata_combat_private.combat_state%ROWTYPE; u clan_sabaku_private.transport_uses%ROWTYPE;
BEGIN
 IF p_actor IS NULL OR auth.uid() IS NULL THEN RETURN NULL; END IF;
 BEGIN scope:=clan_innata_private.combat_actor_context(p_actor);
 EXCEPTION WHEN insufficient_privilege THEN RETURN NULL; END;
 r:=clan_sabaku_private.reserve_for_actor(p_actor);
 -- Nessun numero di giara inventato per un owner non ancora inizializzato.
 IF r.id IS NULL THEN RETURN NULL; END IF;
 s:=clan_innata_private.combat_state_read(p_actor);
 SELECT * INTO u FROM clan_sabaku_private.transport_uses WHERE actor_id=p_actor
  AND session_id=(scope->>'session_id')::uuid AND round_id=(scope->>'round_id')::uuid
  AND state='active' AND coalesce(s.active,false)
  AND clan_sabaku_private.transport_end_reason(id) IS NULL;
 RETURN jsonb_build_object('contract_version','sabaku-transport-view/1',
  'context_version',(scope->>'context_version')::bigint,'is_test',(scope->>'is_test')::boolean,
  'innata',jsonb_build_object('active',coalesce(s.active,false),'activation_chakra',5,'upkeep_chakra',5,'deactivation_chakra',0),
  'reserve',jsonb_build_object('current',r.current_amount,'committed',r.committed_amount,
    'capacity',r.capacity,'available',r.current_amount-r.committed_amount),
  'transport',jsonb_build_object('active',u.id IS NOT NULL,'activation_chakra',5,'sand_commit',5,'upkeep_chakra',0,
    'movement_bonus_m',CASE WHEN u.id IS NOT NULL THEN 5 ELSE 0 END,'expires_round_id',u.round_id));
END $function$;

