-- Native source clan_sabaku_private.panel_view_from_ordinary(jsonb,bigint,bigint,uuid,boolean) MD5 c2431841db8675890f51aed555d75ae6

CREATE OR REPLACE FUNCTION clan_sabaku_private.panel_view_from_ordinary(p_source jsonb, p_source_version bigint, p_panel_version bigint, p_exchange uuid, p_simulated boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE innate jsonb; reserve jsonb; transport jsonb; active boolean; key text; value numeric;
BEGIN
 IF p_source IS NULL OR p_source='null'::jsonb THEN RETURN NULL; END IF;
 IF jsonb_typeof(p_source) IS DISTINCT FROM 'object'
   OR p_source->>'contract_version' IS DISTINCT FROM 'sabaku-transport-view/1'
   OR p_source-ARRAY['contract_version','context_version','is_test','innata','reserve','transport']<>'{}'::jsonb
   OR p_source_version IS NULL OR p_source_version NOT BETWEEN 0 AND 9007199254740991
   OR p_panel_version IS NULL OR p_panel_version NOT BETWEEN 1 AND 9007199254740991
   OR p_source->'context_version' IS DISTINCT FROM to_jsonb(p_source_version)
   OR p_simulated IS NULL OR p_source->'is_test' IS DISTINCT FROM to_jsonb(p_simulated) THEN
   RAISE EXCEPTION 'sabaku_panel_source_invalid' USING ERRCODE='22023'; END IF;
 innate:=p_source->'innata'; reserve:=p_source->'reserve'; transport:=p_source->'transport';
 IF jsonb_typeof(innate) IS DISTINCT FROM 'object'
   OR jsonb_typeof(innate->'active') IS DISTINCT FROM 'boolean'
   OR innate-'active' IS DISTINCT FROM '{"activation_chakra":5,"upkeep_chakra":5,"deactivation_chakra":0}'::jsonb
   OR jsonb_typeof(reserve) IS DISTINCT FROM 'object'
   OR reserve-ARRAY['current','committed','capacity','available']<>'{}'::jsonb
   OR jsonb_typeof(transport) IS DISTINCT FROM 'object'
   OR jsonb_typeof(transport->'active') IS DISTINCT FROM 'boolean'
   OR transport-ARRAY['active','movement_bonus_m','expires_round_id']
     IS DISTINCT FROM '{"activation_chakra":5,"sand_commit":5,"upkeep_chakra":0}'::jsonb THEN
   RAISE EXCEPTION 'sabaku_panel_fields_invalid' USING ERRCODE='22023'; END IF;
 FOREACH key IN ARRAY ARRAY['current','committed','capacity','available'] LOOP
   IF jsonb_typeof(reserve->key) IS DISTINCT FROM 'number' THEN
     RAISE EXCEPTION 'sabaku_panel_reserve_invalid' USING ERRCODE='22023'; END IF;
   value:=(reserve->>key)::numeric;
   IF value NOT BETWEEN 0 AND 9007199254740991 OR value<>trunc(value) THEN
     RAISE EXCEPTION 'sabaku_panel_reserve_invalid' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF (reserve->>'committed')::numeric>(reserve->>'current')::numeric
   OR (reserve->>'current')::numeric>(reserve->>'capacity')::numeric
   OR (reserve->>'available')::numeric<>(reserve->>'current')::numeric-(reserve->>'committed')::numeric THEN
   RAISE EXCEPTION 'sabaku_panel_reserve_invalid' USING ERRCODE='22023'; END IF;
 active:=(transport->>'active')::boolean;
 IF transport->'movement_bonus_m' IS DISTINCT FROM to_jsonb(CASE WHEN active THEN 5 ELSE 0 END) THEN
   RAISE EXCEPTION 'sabaku_panel_bonus_invalid' USING ERRCODE='22023'; END IF;
 IF active THEN
   IF NOT (innate->>'active')::boolean OR p_exchange IS NULL
     OR jsonb_typeof(transport->'expires_round_id') IS DISTINCT FROM 'string'
     OR (transport->>'expires_round_id')::uuid IS DISTINCT FROM p_exchange THEN
     RAISE EXCEPTION 'sabaku_panel_expiry_invalid' USING ERRCODE='22023'; END IF;
 ELSIF transport->'expires_round_id' IS DISTINCT FROM 'null'::jsonb THEN
   RAISE EXCEPTION 'sabaku_panel_expiry_invalid' USING ERRCODE='22023';
 END IF;
 RETURN p_source||jsonb_build_object('contract_version','sabaku-transport-view/2',
   'context_version',p_panel_version,'transport',(transport-'expires_round_id')||
     jsonb_build_object('expires_context',CASE WHEN active THEN jsonb_build_object(
       'kind','ordinary_exchange','id',p_exchange,'label','Fine di questo turno') ELSE NULL END));
END $function$;

