CREATE OR REPLACE FUNCTION clan_sabaku_private.presence_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE aid uuid;
BEGIN
 IF TG_OP='UPDATE' AND NEW.location_id IS NOT DISTINCT FROM OLD.location_id
   AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id THEN RETURN NEW; END IF;
 FOR aid IN SELECT s.actor_id FROM clan_innata_combat_private.combat_state s
  JOIN public.combat_v2_actors a ON a.id=s.actor_id AND a.session_id=s.session_id
  JOIN LATERAL clan_innata_private.combat_context(a.id) c ON true
  WHERE s.active AND a.controller_user=OLD.user_id AND c.location_id=OLD.location_id
  ORDER BY s.session_id,s.actor_id
 LOOP PERFORM clan_innata_private.combat_terminal(aid,'owner_absent'); END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$;

