-- Native source clan_sabaku_private.reserve_ensure(uuid) MD5 fa3662d78df8a9bf76cbf7d63c93f2e9

CREATE OR REPLACE FUNCTION clan_sabaku_private.reserve_ensure(p_actor uuid)
 RETURNS clan_sabaku_private.reserves
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; scope jsonb;
 r clan_sabaku_private.reserves%ROWTYPE; kg integer; maximum integer;
BEGIN
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=a.session_id FOR UPDATE;
 PERFORM 1 FROM combat_consumer_private.activities WHERE session_id=a.session_id FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE id=a.id FOR UPDATE;
 scope:=clan_innata_private.combat_scope(a.id);
 IF (scope->>'is_test')::boolean THEN
   -- Il bind è l'unico inizializzatore del campione. Non ricreare una giara
   -- mancante e non trasferire qui capacità o quantità del personaggio reale.
   SELECT * INTO STRICT r FROM clan_sabaku_private.reserves
    WHERE session_id=a.session_id AND actor_id=a.id AND is_test FOR UPDATE;
   RETURN r;
 END IF;
 -- Il lock della scheda serializza anche due sessioni dello stesso owner.
 SELECT kekkei_genkai INTO STRICT kg FROM public.characters WHERE id=a.character_id FOR UPDATE;
 maximum:=10+5*floor(kg::numeric/20)::integer;
 INSERT INTO clan_sabaku_private.reserves(character_id,is_test,capacity,current_amount)
  VALUES(a.character_id,false,maximum,maximum)
  ON CONFLICT(character_id) WHERE NOT is_test DO NOTHING;
 SELECT * INTO STRICT r FROM clan_sabaku_private.reserves
  WHERE character_id=a.character_id AND NOT is_test FOR UPDATE;
 IF maximum<r.current_amount THEN
   -- Non distruggere sabbia con una correzione amministrativa della KG.
   RAISE EXCEPTION 'sabaku_capacity_below_existing_reserve' USING ERRCODE='22023';
 END IF;
 IF maximum<>r.capacity THEN
   UPDATE clan_sabaku_private.reserves SET capacity=maximum,state_version=state_version+1
    WHERE id=r.id RETURNING * INTO r;
 END IF;
 RETURN r;
END $function$;

