-- Native source clan_sabaku_private.reserve_identity_guard() MD5 b95b48145493a12f7f23e256c1cbd0bb

CREATE OR REPLACE FUNCTION clan_sabaku_private.reserve_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.character_id IS DISTINCT FROM OLD.character_id
   OR NEW.session_id IS DISTINCT FROM OLD.session_id OR NEW.actor_id IS DISTINCT FROM OLD.actor_id
   OR NEW.is_test IS DISTINCT FROM OLD.is_test OR NEW.initialized_at IS DISTINCT FROM OLD.initialized_at) THEN
   RAISE EXCEPTION 'sabaku_reserve_identity_immutable' USING ERRCODE='22023';
 END IF;
 IF NEW.is_test AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a
   JOIN clan_sabaku_private.staff_profiles p ON p.actor_id=a.id AND p.session_id=a.session_id
   JOIN LATERAL clan_innata_private.combat_context(a.id) c ON true
   WHERE a.id=NEW.actor_id AND a.session_id=NEW.session_id AND a.character_id=NEW.character_id
     AND c.policy_id='staff_test_no_persistent_resources_v1' AND NOT public.combat_v2_values_written(a.session_id)) THEN
   RAISE EXCEPTION 'sabaku_reserve_test_scope_invalid' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $function$;

