-- Native source clan_sabaku_private.transport_commit_resources(uuid,uuid,uuid,bigint) MD5 83469e1616229b0e3481e98fe221e24e

CREATE OR REPLACE FUNCTION clan_sabaku_private.transport_commit_resources(p_actor uuid, p_round uuid, p_request uuid, p_expected_state bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; c clan_innata_combat_private.actor_context;
 r clan_sabaku_private.reserves%ROWTYPE; u clan_sabaku_private.transport_uses%ROWTYPE;
 scope jsonb; fp text; payment jsonb; result jsonb; use_id uuid:=gen_random_uuid();
BEGIN
 IF p_round IS NULL OR p_request IS NULL OR p_expected_state IS NULL THEN
   RAISE EXCEPTION 'sabaku_transport_request_invalid' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=a.session_id FOR UPDATE;
 PERFORM 1 FROM combat_consumer_private.activities WHERE session_id=a.session_id FOR UPDATE;
 c:=clan_innata_private.combat_context(a.id);
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor FOR UPDATE;
 scope:=clan_innata_private.combat_scope(a.id);
 fp:=public.combat_v2_sha256(jsonb_build_object('actor',a.id,'round',p_round,
   'operation','transport','expected_state',p_expected_state));
 SELECT * INTO u FROM clan_sabaku_private.transport_uses
  WHERE session_id=a.session_id AND actor_id=a.id AND request_id=p_request;
 IF FOUND THEN
   IF u.request_fingerprint<>fp THEN RAISE EXCEPTION 'sabaku_transport_request_conflict' USING ERRCODE='22023'; END IF;
   RETURN u.result||jsonb_build_object('replayed',true);
 END IF;
 IF c.exchange_id<>p_round OR c.phase<>'action' OR c.turn_actor_id<>a.id
  OR EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=p_round AND actor_id=a.id)
  OR EXISTS(SELECT 1 FROM clan_marionettisti_private.movement_receipts WHERE round_id=p_round AND owner_actor_id=a.id)
  OR EXISTS(SELECT 1 FROM combat_panel_private.master_movement_receipts WHERE round_id=p_round AND owner_actor_id=a.id)
  OR EXISTS(SELECT 1 FROM clan_sabaku_private.transport_uses WHERE round_id=p_round AND actor_id=a.id)
  OR NOT EXISTS(SELECT 1 FROM public.presence WHERE user_id=a.controller_user AND location_id=c.location_id)
  OR coalesce((a.mechanics_snapshot->>'vita')::integer,0)<=0 THEN
   RAISE EXCEPTION 'sabaku_transport_not_at_turn_start' USING ERRCODE='55000'; END IF;
 r:=clan_sabaku_private.reserve_ensure(a.id);
 IF r.current_amount-r.committed_amount<5 THEN
   RAISE EXCEPTION 'sabaku_insufficient_available_sand' USING ERRCODE='22023'; END IF;
 payment:=clan_innata_private.combat_transition(a.id,'transport',p_request,p_expected_state);
 -- Una ricevuta Common già esistente senza uso associato indica un percorso
 -- incompleto: fallire invece di ricostruire a posteriori un impegno.
 IF (payment->>'replayed')::boolean THEN RAISE EXCEPTION 'sabaku_orphan_chakra_receipt'; END IF;
 result:=jsonb_build_object('contract_version','sabaku-transport-use/1',
  'receipt_id',payment->'receipt_id','chakra_spent',5,'sand_committed',5,
  'main_action_consumed',false,'is_test',(scope->>'is_test')::boolean,
  'values_written',payment->'values_written','replayed',false);
 UPDATE clan_sabaku_private.reserves SET committed_amount=committed_amount+5,state_version=state_version+1
  WHERE id=r.id AND current_amount-committed_amount>=5;
 IF NOT FOUND THEN RAISE EXCEPTION 'sabaku_reserve_race' USING ERRCODE='40001'; END IF;
 INSERT INTO clan_sabaku_private.transport_uses(id,reserve_id,session_id,round_id,actor_id,
  request_id,request_fingerprint,chakra_receipt_id,result)
  VALUES(use_id,r.id,a.session_id,p_round,a.id,p_request,fp,(payment->>'receipt_id')::uuid,result);
 INSERT INTO clan_sabaku_private.sand_ledger(use_id,event_kind,amount) VALUES(use_id,'commit',5);
 RETURN result;
END $function$;

