-- Native source clan_sabaku_private.transport_end_reason(uuid) MD5 99cf6920dc44eaab36fe076d2bedfb8d

CREATE OR REPLACE FUNCTION clan_sabaku_private.transport_end_reason(p_use uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u clan_sabaku_private.transport_uses%ROWTYPE; a public.combat_v2_actors%ROWTYPE;
 c clan_innata_combat_private.actor_context; r clan_sabaku_private.reserves%ROWTYPE;
BEGIN
 SELECT * INTO STRICT u FROM clan_sabaku_private.transport_uses WHERE id=p_use;
 IF u.state='released' THEN RETURN u.release_reason; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=u.actor_id;
 c:=clan_innata_private.combat_context(a.id);
 IF c.phase='closed' OR EXISTS(SELECT 1 FROM public.combat_v2_sessions
   WHERE id=u.session_id AND closed_at IS NOT NULL) THEN RETURN 'combat_end'; END IF;
 IF coalesce((a.mechanics_snapshot->>'vita')::integer,0)<=0 THEN RETURN 'owner_ko'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.presence WHERE user_id=a.controller_user AND location_id=c.location_id) THEN
   RETURN 'owner_absent'; END IF;
 IF a.state<>'attivo' OR NOT EXISTS(SELECT 1 FROM combat_spatial.actor_states b
   JOIN combat_spatial.arena_instances i ON i.instance_id=b.instance_id
   WHERE i.encounter_id=u.session_id AND i.state='open' AND b.actor_id=a.id AND b.state='active') THEN
   RETURN 'owner_inoperative'; END IF;
 IF NOT EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state WHERE session_id=u.session_id
   AND actor_id=u.actor_id AND technique_id='001f907c-8f32-4758-8a16-ad1730e72c59' AND active) THEN
   RETURN 'innata_off'; END IF;
 IF c.exchange_id<>u.round_id OR c.turn_actor_id<>a.id OR c.phase='resolved' THEN RETURN 'turn_end'; END IF;
 SELECT * INTO r FROM clan_sabaku_private.reserves WHERE id=u.reserve_id;
 IF r.id IS NULL OR r.character_id<>a.character_id OR r.committed_amount<u.amount
   OR r.current_amount<r.committed_amount THEN RETURN 'medium_invalid'; END IF;
 RETURN NULL;
END $function$;

