CREATE OR REPLACE FUNCTION clan_sabaku_private.transport_movement_bonus(p_actor uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE scope jsonb; u clan_sabaku_private.transport_uses%ROWTYPE;
BEGIN
 -- Un attore di altro clan mantiene il suo percorso corrente. La lettura
 -- non attiva tecniche né inizializza risorse; solo il server paga e impegna.
 BEGIN scope:=clan_innata_private.combat_scope(p_actor);
 EXCEPTION WHEN insufficient_privilege THEN RETURN 0; END;
 SELECT * INTO u FROM clan_sabaku_private.transport_uses WHERE actor_id=p_actor
   AND session_id=(scope->>'session_id')::uuid AND state='active';
 IF u.id IS NULL OR clan_sabaku_private.transport_end_reason(u.id) IS NOT NULL THEN RETURN 0; END IF;
 RETURN 5;
END $function$;

