CREATE OR REPLACE FUNCTION clan_sabaku_private.transport_ready(p_actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; c clan_innata_combat_private.actor_context;
 r clan_sabaku_private.reserves%ROWTYPE; scope jsonb;
BEGIN
 scope:=clan_innata_private.combat_scope(p_actor);
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor;
 c:=clan_innata_private.combat_context(a.id);
 r:=clan_sabaku_private.reserve_for_actor(a.id);
 RETURN c.phase='action' AND c.turn_actor_id=a.id
  AND combat_panel_private.movement_block_reason(a.id) IS NULL
  AND coalesce((a.mechanics_snapshot->>'vita')::integer,0)>0
  AND coalesce((a.mechanics_snapshot->>'chakra')::integer,0)>=5
  AND r.id IS NOT NULL AND r.current_amount-r.committed_amount>=5
  AND EXISTS(SELECT 1 FROM public.presence WHERE user_id=a.controller_user AND location_id=c.location_id)
  AND EXISTS(SELECT 1 FROM combat_spatial.actor_states b JOIN combat_spatial.arena_instances i
    ON i.instance_id=b.instance_id WHERE i.encounter_id=a.session_id AND i.state='open'
    AND i.context_source IN ('ordinary','panel_master') AND b.actor_id=a.id AND b.state='active')
  AND EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state WHERE session_id=a.session_id
    AND actor_id=a.id AND technique_id='001f907c-8f32-4758-8a16-ad1730e72c59' AND active)
  AND ((scope->>'is_test')::boolean OR EXISTS(SELECT 1 FROM public.character_abilities
    WHERE character_id=a.character_id AND technique_id='67846562-a0da-414a-820c-4b576a0a2eb6' AND state='attiva'))
  AND NOT EXISTS(SELECT 1 FROM clan_marionettisti_private.links WHERE owner_actor_id=a.id AND state='connected')
  AND NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=c.exchange_id AND actor_id=a.id)
  AND NOT EXISTS(SELECT 1 FROM clan_marionettisti_private.movement_receipts WHERE round_id=c.exchange_id AND owner_actor_id=a.id)
  AND NOT EXISTS(SELECT 1 FROM combat_panel_private.master_movement_receipts WHERE round_id=c.exchange_id AND owner_actor_id=a.id)
  AND NOT EXISTS(SELECT 1 FROM clan_sabaku_private.transport_uses WHERE round_id=c.exchange_id AND actor_id=a.id);
END $function$;

