 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u clan_sabaku_private.transport_uses%ROWTYPE;
BEGIN
 SELECT * INTO STRICT u FROM clan_sabaku_private.transport_uses WHERE id=p_use;
 PERFORM 1 FROM clan_sabaku_private.reserves WHERE id=u.reserve_id FOR UPDATE;
 SELECT * INTO STRICT u FROM clan_sabaku_private.transport_uses WHERE id=p_use FOR UPDATE;
 IF u.state='released' THEN RETURN false; END IF;
 IF p_reason IS NULL OR p_reason NOT IN ('turn_end','owner_ko','owner_absent','owner_inoperative','medium_invalid','combat_end','innata_off') THEN
   RAISE EXCEPTION 'sabaku_release_reason_invalid' USING ERRCODE='22023'; END IF;
 UPDATE clan_sabaku_private.reserves SET committed_amount=committed_amount-u.amount,state_version=state_version+1
   WHERE id=u.reserve_id AND committed_amount>=u.amount;
 IF NOT FOUND THEN RAISE EXCEPTION 'sabaku_reserve_commit_drift'; END IF;
 UPDATE clan_sabaku_private.transport_uses SET state='released',release_reason=p_reason,released_at=clock_timestamp() WHERE id=u.id;
 INSERT INTO clan_sabaku_private.sand_ledger(use_id,event_kind,amount) VALUES(u.id,'release',u.amount);
 RETURN true;
END $function$;

