-- Native source combat_consumer_private.accept_invitation(uuid,uuid) MD5 50531d6a0a9e60ae50fb6f58f458e954

CREATE OR REPLACE FUNCTION combat_consumer_private.accept_invitation(p_invitation uuid, p_request uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare inv combat_consumer_private.invitations%rowtype;
  prof combat_consumer_private.scene_profiles%rowtype;
  opener public.characters%rowtype; recipient public.characters%rowtype;
  distance numeric; result jsonb; sid uuid; xid uuid; turn_id uuid;
  first_initiative integer; second_initiative integer; retries integer:=0; test_room boolean;
begin
  select location_id into sid from combat_consumer_private.invitations where id=p_invitation;
  perform 1 from public.locations where id=sid for update;
  select * into inv from combat_consumer_private.invitations where id=p_invitation for update;
  if inv.id is null or inv.state<>'pending' or inv.created_at<clock_timestamp()-interval '24 hours' then
    perform combat_consumer_private.fail('offer_not_available',p_request);
  end if;
  perform 1 from public.characters where id in (inv.opener_character_id,inv.recipient_character_id) order by id for update;
  select * into opener from public.characters where id=inv.opener_character_id;
  select * into recipient from public.characters where id=inv.recipient_character_id;
  if not combat_consumer_private.runtime_allowed(inv.location_id,opener.user_id)
    or not combat_consumer_private.runtime_allowed(inv.location_id,recipient.user_id)
    or auth.uid() is distinct from recipient.user_id or opener.user_id is null
    or opener.id=recipient.id or coalesce(opener.vita,0)<=0 or coalesce(recipient.vita,0)<=0 then
    perform combat_consumer_private.fail('not_participant',p_request);
  end if;
  if not public._combat_presente(opener.user_id,inv.location_id)
    or not public._combat_presente(recipient.user_id,inv.location_id) then
    perform combat_consumer_private.fail('presence_required',p_request);
  end if;
  select is_test into test_room from public.locations where id=inv.location_id and is_active;
  if not found or (coalesce(test_room,false) and not public._puo_test_room()) then
    perform combat_consumer_private.fail('not_participant',p_request);
  end if;
  select * into prof from combat_consumer_private.scene_profiles
    where id=inv.scene_profile_id and location_id=inv.location_id and enabled for share;
  if prof.id is null or inv.geometry_sha256<>prof.geometry_sha256
    or inv.scene_version<>prof.producer_version or prof.geometry_sha256 is distinct from
    combat_consumer_private.scene_fingerprint(prof.template_key,prof.template_version) then
    perform combat_consumer_private.fail('scene_not_configured',p_request);
  end if;
  select combat_spatial.distance_m(a.x_m,a.y_m,b.x_m,b.y_m) into distance
    from combat_spatial.arena_slots a join combat_spatial.arena_slots b
      on b.template_key=a.template_key and b.template_version=a.template_version
    where a.template_key=prof.template_key and a.template_version=prof.template_version
      and a.slot_key=prof.fighter_one_slot and b.slot_key=prof.fighter_two_slot
      and a.actor_kind='PG' and b.actor_kind='PG';
  if distance is null or distance<0 or distance>1000 then
    perform combat_consumer_private.fail('scene_not_configured',p_request);
  end if;
  -- position_m conserva la compatibilità intera del core; autorità distanza 2D
  -- nei corpi, non questa proiezione. Tecniche 1D non vengono offerte.
  insert into combat_consumer_private.open_authorizations
    values(p_request,inv.id,recipient.id,opener.id,inv.location_id,round(distance)::integer,txid_current(),'prepared');
  result:=public.combat_v2_ordinary_open(inv.location_id,opener.id,round(distance)::integer,p_request);
  sid:=(result#>>'{data,encounter_id}')::uuid; xid:=(result#>>'{data,round_id}')::uuid;
  if sid is null or xid is null then raise exception 'ordinary_open_result_invalid'; end if;
  -- Iniziativa una volta, con formula e pareggi del duello esistente.
  loop
    first_initiative:=(floor(random()*20)+1)::integer+coalesce(opener.velocita,0)/10;
    second_initiative:=(floor(random()*20)+1)::integer+coalesce(recipient.velocita,0)/10;
    exit when first_initiative<>second_initiative or retries>20;
    retries:=retries+1;
  end loop;
  update public.combat_v2_actors set initiative_snapshot=case character_id
    when opener.id then first_initiative else second_initiative end where session_id=sid;
  select id into turn_id from public.combat_v2_actors where session_id=sid and character_id=
    case when first_initiative>=second_initiative then opener.id else recipient.id end;
  insert into combat_consumer_private.activities(session_id,location_id,scene_profile_id,
    opener_character_id,exchange_id,turn_actor_id,phase,policy_id)
    values(sid,inv.location_id,prof.id,opener.id,xid,turn_id,'action',case when test_room then
      'staff_test_no_persistent_resources_v1' else 'free_duel_nonlethal_real_resources_v1' end);
  insert into combat_consumer_private.members(session_id,actor_id,character_id,fighter_slot)
    select sid,id,character_id,case when character_id=opener.id then 1 else 2 end
    from public.combat_v2_actors where session_id=sid;
  perform combat_consumer_private.place_fighters(sid);
  insert into combat_consumer_private.narrative_authorities(session_id) values(sid);
  update combat_consumer_private.invitations set state='accepted',accept_request_key=p_request,
    session_id=sid,decided_at=clock_timestamp(),context_version=context_version+1 where id=inv.id;
  update combat_consumer_private.open_authorizations set state='consumed' where request_key=p_request;
  return sid;
end $function$;

