-- Native source combat_consumer_private.approach_capabilities(uuid,uuid,uuid) MD5 3bcaff4362b8b8b2ceec7519588e45c0

CREATE OR REPLACE FUNCTION combat_consumer_private.approach_capabilities(p_session uuid, p_actor uuid, p_target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype;
  instance combat_spatial.arena_instances%rowtype;
  actor combat_spatial.actor_states%rowtype; target combat_spatial.actor_states%rowtype;
  budget numeric; distance numeric; step numeric; travel numeric; target_prefix text; choice text;
  keys text[]:='{}'; options jsonb; result jsonb:='[]'; item jsonb;
begin
  select * into ctx from combat_consumer_private.activities where session_id=p_session;
  if ctx.phase<>'action' or ctx.turn_actor_id<>p_actor or not exists(
    select 1 from combat_consumer_private.members m join public.characters c on c.id=m.character_id
    where m.session_id=p_session and m.actor_id=p_actor and c.user_id=auth.uid()) then
    perform combat_consumer_private.fail('not_participant');
  end if;
  select * into instance from combat_spatial.arena_instances where encounter_id=p_session and state='open' for update;
  if instance.instance_id is null or instance.context_source<>'ordinary' then
    perform combat_consumer_private.fail('scene_not_configured');
  end if;
  select * into actor from combat_spatial.actor_states where instance_id=instance.instance_id and actor_id=p_actor and state='active';
  select * into target from combat_spatial.actor_states where instance_id=instance.instance_id and actor_id=p_target and state='active';
  if actor.actor_id is null or target.actor_id is null or p_actor=p_target then
    perform combat_consumer_private.fail('not_participant');
  end if;
  select clan_marionettisti_private.movement_remaining(p_actor) into budget
    from public.combat_v2_actors where id=p_actor and session_id=p_session and state='attivo';
  distance:=combat_spatial.distance_m(actor.x_m,actor.y_m,target.x_m,target.y_m);
  target_prefix:='ordinary_approach:'||ctx.exchange_id::text||':'||actor.body_version||':'||target.actor_id||':'||target.body_version||':'||budget||':'||instance.map_version||':';
  update combat_spatial.movement_semantic_choices sc
    set enabled=false,choice_version=sc.choice_version+1
    where sc.instance_id=instance.instance_id and sc.actor_id=p_actor and sc.enabled
      and left(sc.choice_key,18)='ordinary_approach:'
      and not exists (
        select 1 from combat_spatial.actor_states other
        cross join lateral (select 'ordinary_approach:'||ctx.exchange_id::text||':'||actor.body_version||':'||other.actor_id||':'||other.body_version||':'||budget||':'||instance.map_version||':' as prefix) valid
        where other.instance_id=instance.instance_id and other.state='active' and other.actor_id<>p_actor
          and left(sc.choice_key,length(valid.prefix))=valid.prefix
      );
  if budget is null or budget<=0 or distance<=actor.footprint_radius_m+target.footprint_radius_m then return result; end if;
  for step in
    select metres from (
      select generate_series(5::numeric,floor(budget),5::numeric) as metres
      union select budget
      union select least(budget,greatest(0,distance-2))
    ) choices where metres>0 and metres<=budget order by metres
  loop
    travel:=least(step,distance);
    choice:=target_prefix||step;
    keys:=array_append(keys,choice);
    insert into combat_spatial.movement_semantic_choices
      (instance_id,actor_id,choice_key,endpoint_x_m,endpoint_y_m,max_budget_m,choice_version,enabled)
      values(instance.instance_id,p_actor,choice,
        round(actor.x_m+(target.x_m-actor.x_m)*travel/distance,2),
        round(actor.y_m+(target.y_m-actor.y_m)*travel/distance,2),budget,1,true)
      on conflict(instance_id,actor_id,choice_key) do update
        set endpoint_x_m=excluded.endpoint_x_m,endpoint_y_m=excluded.endpoint_y_m,
          max_budget_m=excluded.max_budget_m,enabled=true,
          choice_version=movement_semantic_choices.choice_version+1
        where not movement_semantic_choices.enabled
          or movement_semantic_choices.endpoint_x_m is distinct from excluded.endpoint_x_m
          or movement_semantic_choices.endpoint_y_m is distinct from excluded.endpoint_y_m
          or movement_semantic_choices.max_budget_m is distinct from excluded.max_budget_m;
    exit when travel=distance;
  end loop;
  update combat_spatial.movement_semantic_choices sc set enabled=false,choice_version=sc.choice_version+1
    where sc.instance_id=instance.instance_id and sc.actor_id=p_actor and sc.enabled
      and left(sc.choice_key,length(target_prefix))=target_prefix and not(sc.choice_key=any(keys));
  options:=combat_spatial.movement_options(instance.instance_id,p_actor,budget);
  for item in select value from jsonb_array_elements(options) loop
    if item->>'intent'=any(keys) and (item->>'distance_m')::numeric>0 then
      result:=result||jsonb_build_array(item);
    end if;
  end loop;
  return result;
end $function$;

