CREATE OR REPLACE FUNCTION combat_consumer_private.assert_dispatch(p_round uuid, p_request uuid, p_operation text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cid uuid; ctx combat_consumer_private.activities%rowtype;
begin
  if not combat_consumer_private.owns_round(p_round) then return; end if;
  select id into cid from public.characters where user_id=auth.uid();
  if cid is null or not combat_consumer_private.runtime_allowed((select s.location_id
    from public.combat_v2_sessions s join public.combat_v2_rounds r on r.session_id=s.id
    where r.id=p_round),auth.uid()) then
    perform combat_consumer_private.fail('adapter_not_ready',p_request);
  end if;
  select c.* into ctx from combat_consumer_private.activities c
    join public.combat_v2_rounds r on r.session_id=c.session_id where r.id=p_round;
  if ctx.exchange_id<>p_round or ctx.phase='closed' then
    perform combat_consumer_private.fail('context_stale',p_request);
  end if;
  if not exists(select 1 from combat_consumer_private.dispatch_authorizations d
    where d.request_key=p_request and d.round_id=p_round and d.operation=p_operation
      and d.principal_character_id=cid and d.transaction_id=txid_current() and d.state='prepared') then
    perform combat_consumer_private.fail('offer_not_available',p_request);
  end if;
  if (select count(*) from combat_consumer_private.members where session_id=ctx.session_id)<>2
    or not clan_marionettisti_private.roster_valid(ctx.session_id) then
    perform combat_consumer_private.fail('activity_scope_invalid',p_request);
  end if;
end $function$;

