CREATE OR REPLACE FUNCTION combat_consumer_private.attach_master(p_location uuid, p_title text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype; authority combat_consumer_private.narrative_authorities%rowtype;
  event jsonb; mid uuid; result jsonb;
begin
  if auth.uid() is null or not public.master_v2_is_master(auth.uid()) then
    perform combat_consumer_private.fail('not_participant',p_request);
  end if;
  perform 1 from public.locations where id=p_location for update;
  select * into ctx from combat_consumer_private.activities where location_id=p_location and phase<>'closed';
  if ctx.session_id is null then perform combat_consumer_private.fail('activity_scope_invalid',p_request); end if;
  perform public.combat_v2_lock_round(ctx.exchange_id);
  select * into ctx from combat_consumer_private.activities where session_id=ctx.session_id for update;
  select * into authority from combat_consumer_private.narrative_authorities where session_id=ctx.session_id for update;
  event:=public.combat_v2_event_begin(ctx.session_id,p_request,'ordinary_master_attach',jsonb_build_object('title',p_title));
  if (event->>'replay')::boolean then return event->'result'; end if;
  if authority.session_id is null or authority.mode='human' or exists(
    select 1 from public.combat_v2_actors where session_id=ctx.session_id and controller_user=auth.uid())
    or exists(select 1 from public.master_v2_sessions where location_id=p_location and stato not in ('chiusa','annullata')) then
    perform combat_consumer_private.fail('not_participant',p_request);
  end if;
  mid:=gen_random_uuid();
  insert into combat_consumer_private.master_admission_permits(master_id,session_id,location_id,owner_user,transaction_id,state)
    values(mid,ctx.session_id,p_location,auth.uid(),txid_current(),'prepared');
  insert into public.master_v2_sessions(id,location_id,tipo,stato,master_user,titolo,owner_kind)
    values(mid,p_location,'duello','in_corso',auth.uid(),btrim(p_title),'human');
  if not exists(select 1 from combat_consumer_private.master_admission_permits
    where master_id=mid and transaction_id=txid_current() and state='consumed') then
    raise exception 'ordinary_master_permit_not_consumed'; end if;
  update combat_consumer_private.narrative_authorities set mode='human',master_session_id=mid,
    control_version=control_version+1 where session_id=ctx.session_id;
  update combat_consumer_private.activities set context_version=context_version+1 where session_id=ctx.session_id;
  update combat_consumer_private.narrative_claims set state='failed',failure_code='control_changed'
    where session_id=ctx.session_id and state='claimed';
  update combat_consumer_private.offers set state='revoked' where session_id=ctx.session_id and state='offered';
  result:=public.combat_v2_envelope(p_request,jsonb_build_object('master_session_id',mid,
    'encounter_id',ctx.session_id,'control_version',1,'state','in_corso','narrative_only',true));
  return public.combat_v2_event_complete((event->>'event_id')::uuid,result);
end $function$;

