CREATE OR REPLACE FUNCTION combat_consumer_private.attach_movement(p_offer jsonb, p_caps jsonb, p_actor uuid, p_target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parent combat_consumer_private.offers%rowtype; cap combat_spatial.movement_capabilities%rowtype;
  target combat_spatial.actor_states%rowtype; item jsonb; moves jsonb:='[]'; oid uuid;
  projection jsonb; required boolean; selection jsonb; figure jsonb;
begin
  select * into parent from combat_consumer_private.offers where id=(p_offer->>'offer_id')::uuid;
  if parent.operation<>'declare' or not exists(select 1 from public.characters c
    join combat_consumer_private.members m on m.character_id=c.id
    where c.id=parent.principal_character_id and c.user_id=auth.uid()
      and m.session_id=parent.session_id and m.actor_id=p_actor) then
    perform combat_consumer_private.fail('not_participant');
  end if;
  if parent.source_payload?'multiplication_attack_target' then
    selection:=parent.source_payload->'multiplication_attack_target';
    if selection->>'target_actor_id' is distinct from p_target::text
      or parent.source_payload#>>'{intent,kind}' is distinct from 'attacco'
      or parent.source_payload#>>'{intent,ability_source}' is distinct from 'mano' then
      perform combat_consumer_private.fail('offer_not_available');end if;
    figure:=combat_panel_private.multiplication_target_figure(p_actor,p_target,(selection->>'formation_id')::uuid,
      (selection->>'state_version')::bigint,(selection->>'figure_index')::integer)->'figure';
    required:=(figure->>'distance_m')::numeric>2 or not (figure->>'path_clear')::boolean;
  else required:=p_target is not null and not combat_consumer_private.melee_eligible(parent.session_id,p_actor,p_target);end if;
  for item in select value from jsonb_array_elements(p_caps) loop
    select c.* into cap from combat_spatial.movement_capabilities c
      join combat_spatial.arena_instances i on i.instance_id=c.instance_id
      where c.capability_id=(item->>'option_id')::uuid and c.actor_id=p_actor and c.state='offered'
        and i.encounter_id=parent.session_id and i.map_version=parent.scene_version and c.map_version=i.map_version;
    if cap.capability_id is null then continue; end if;
    if figure is not null then
      if combat_spatial.distance_m(cap.end_x_m,cap.end_y_m,(figure->>'x_m')::numeric,(figure->>'y_m')::numeric)>2
        or combat_spatial.path_first_block_t(cap.instance_id,p_actor,cap.end_x_m,cap.end_y_m,
          (figure->>'x_m')::numeric,(figure->>'y_m')::numeric,p_target)<1 then continue;end if;
    elsif p_target is not null then
      select * into target from combat_spatial.actor_states
        where instance_id=cap.instance_id and actor_id=p_target and state='active';
      if target.actor_id is null or combat_spatial.distance_m(cap.end_x_m,cap.end_y_m,target.x_m,target.y_m)>2
        or combat_spatial.path_first_block_t(cap.instance_id,p_actor,cap.end_x_m,cap.end_y_m,target.x_m,target.y_m,p_target)<1 then
        continue;
      end if;
    end if;
    oid:=gen_random_uuid();
    projection:=jsonb_build_object('offer_id',oid,'label','Avvicinati','distance_m',(item->>'distance_m')::numeric);
    insert into combat_consumer_private.offers(id,location_id,session_id,exchange_id,principal_character_id,
      context_version,scene_version,operation,offer_kind,parent_offer_id,source_payload,viewer_projection)
      values(oid,parent.location_id,parent.session_id,parent.exchange_id,parent.principal_character_id,
        parent.context_version,parent.scene_version,'declare','movement',parent.id,
        jsonb_build_object('capability_id',cap.capability_id),projection);
    moves:=moves||jsonb_build_array(projection);
  end loop;
  if required and jsonb_array_length(moves)=0 then
    update combat_consumer_private.offers set state='revoked' where id=parent.id;
    return null;
  end if;
  projection:=jsonb_set(jsonb_set(p_offer,'{movement_required}',to_jsonb(required)),'{movement_options}',moves);
  update combat_consumer_private.offers set viewer_projection=projection where id=parent.id;
  return projection;
end $function$;

