CREATE OR REPLACE FUNCTION combat_consumer_private.can_close(p_session uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype; cid uuid; aid uuid; expected_actor uuid;
begin
  if auth.uid() is null then return false; end if;
  select * into ctx from combat_consumer_private.activities where session_id=p_session;
  if ctx.session_id is null or ctx.phase='closed' then return false; end if;
  select id into cid from public.characters where user_id=auth.uid();
  if public.is_staff() or cid=ctx.opener_character_id then return true; end if;
  select m.actor_id into aid from combat_consumer_private.members m
    join public.combat_v2_actors a on a.id=m.actor_id and a.state='attivo'
    where m.session_id=p_session and m.character_id=cid;
  if aid is null or ctx.phase not in ('action','defense') then return false; end if;
  if ctx.phase='action' then expected_actor:=ctx.turn_actor_id;
  else select actor_id into expected_actor from combat_consumer_private.members
    where session_id=p_session and actor_id<>ctx.turn_actor_id; end if;
  return aid<>expected_actor and ctx.last_action_at<=clock_timestamp()-interval '10 minutes';
end $function$;

