 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype;
  prof combat_consumer_private.scene_profiles%rowtype; s public.combat_v2_sessions%rowtype;
  claim combat_consumer_private.scene_claims%rowtype; iid uuid;
begin
  select * into s from public.combat_v2_sessions where id=p_session for update;
  select * into ctx from combat_consumer_private.activities where session_id=p_session for update;
  if ctx.session_id is null or s.source_kind<>'ordinary' or s.master_session_id is not null
    or s.location_id<>ctx.location_id or s.state not in ('preparazione','in_corso') then
    raise exception using errcode='22023',message='ordinary_authority_invalid';
  end if;
  select * into prof from combat_consumer_private.scene_profiles
    where id=ctx.scene_profile_id and location_id=ctx.location_id and enabled for share;
  if prof.id is null or prof.geometry_sha256 is distinct from
    combat_consumer_private.scene_fingerprint(prof.template_key,prof.template_version)
    or not exists(select 1 from combat_spatial.arena_templates where template_key=prof.template_key
      and template_version=prof.template_version and status='ready') then
    raise exception using errcode='22023',message='scene_not_configured';
  end if;
  if combat_spatial.template_errors(prof.template_key,prof.template_version)<>'[]'::jsonb then
    raise exception using errcode='22023',message='scene_template_invalid';
  end if;
  select * into claim from combat_consumer_private.scene_claims where session_id=p_session;
  if claim.id is not null then
    if claim.scene_profile_id<>prof.id or claim.template_key<>prof.template_key
      or claim.template_version<>prof.template_version or claim.producer_version<>prof.producer_version then
      raise exception using errcode='22023',message='scene_claim_stale';
    end if;
    select instance_id into iid from combat_spatial.arena_instances
      where ordinary_claim_id=claim.id and encounter_id=p_session and context_source='ordinary' and state='open';
    if iid is null then raise exception using errcode='22023',message='scene_claim_incomplete'; end if;
    return iid;
  end if;
  if exists(select 1 from combat_spatial.arena_instances where encounter_id=p_session) then
    raise exception using errcode='22023',message='scene_authority_conflict';
  end if;
  insert into combat_consumer_private.scene_claims
    (session_id,scene_profile_id,template_key,template_version,producer_version)
    values(p_session,prof.id,prof.template_key,prof.template_version,prof.producer_version)
    returning * into claim;
  iid:=gen_random_uuid();
  insert into combat_spatial.arena_instances
    (instance_id,master_session_id,encounter_id,binding_id,template_key,template_version,
      map_version,state,context_source,ordinary_claim_id)
    values(iid,null,p_session,null,prof.template_key,prof.template_version,1,'open','ordinary',claim.id);
  insert into combat_spatial.object_states(instance_id,object_key,state,state_version)
    select iid,object_key,case when substitutable then 'available' else 'blocked' end,1
    from combat_spatial.arena_objects where template_key=prof.template_key and template_version=prof.template_version;
  return iid;
end $function$;

