-- Native source combat_consumer_private.close_from_master(uuid,bigint,uuid,jsonb) MD5 96fb689a3a8d6ac64bad41ed06448aec

CREATE OR REPLACE FUNCTION combat_consumer_private.close_from_master(p_master uuid, p_expected bigint, p_request uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.master_v2_sessions%rowtype; sid uuid; event jsonb; result jsonb;
begin
  if auth.uid() is null then perform combat_consumer_private.fail('not_participant',p_request); end if;
  if p_request is null then perform combat_consumer_private.fail('identifier_invalid'); end if;
  perform public.master_v2_lock_scope(p_master);
  select * into m from public.master_v2_sessions where id=p_master;
  if m.owner_kind is distinct from 'human' or (m.master_user is distinct from auth.uid()
    and not public.combat_v2_is_admin(auth.uid())) then perform combat_consumer_private.fail('not_participant',p_request); end if;
  select session_id into sid from combat_consumer_private.narrative_authorities where master_session_id=p_master;
  if sid is null then perform combat_consumer_private.fail('activity_scope_invalid',p_request); end if;
  event:=public.combat_v2_event_begin(p_master,p_request,'ordinary_master_close',p_payload,p_expected);
  if (event->>'replay')::boolean then return event->'result'; end if;
  if p_expected is null or m.control_version<>p_expected or m.stato not in ('in_corso','sospesa') then
    perform combat_consumer_private.fail('context_stale',p_request);
  end if;
  -- Il controllo narrativo non possiede una REC o una missione da finalizzare.
  if coalesce((p_payload->>'close_role')::boolean,false) or p_payload->>'outcome' is not null then
    perform combat_consumer_private.fail('activity_scope_invalid',p_request);
  end if;
  if p_payload->>'via'='scene_close' and length(btrim(coalesce(p_payload->>'reason','')))<3 then
    perform combat_consumer_private.fail('command_shape_invalid',p_request);
  end if;
  perform combat_consumer_private.close_session(sid);
  result:=public.combat_v2_envelope(p_request,jsonb_build_object('state','chiusa','encounter_id',sid,
    'master_session_id',p_master,'narrative_only',true,'completed_steps',0));
  return public.combat_v2_event_complete((event->>'event_id')::uuid,result);
end $function$;

