CREATE OR REPLACE FUNCTION combat_consumer_private.close_narrative_control(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare mid uuid;
begin
  -- Il chiamante close_session possiede già il lock Common e quello activity.
  select master_session_id into mid from combat_consumer_private.narrative_authorities
    where session_id=p_session for update;
  if mid is not null then
    update public.master_v2_sessions set stato='chiusa',closed_at=clock_timestamp(),
      close_reason='duello_ordinary_chiuso',control_version=control_version+1
      where id=mid and stato not in ('chiusa','annullata');
  end if;
  update combat_consumer_private.narrative_claims set state='failed',failure_code='session_closed'
    where session_id=p_session and state='claimed';
end $function$;

