-- Native source combat_consumer_private.close_session(uuid) MD5 b5dec2d335f47fff70c65d1b15c07d5c

CREATE OR REPLACE FUNCTION combat_consumer_private.close_session(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype;
begin
  perform 1 from public.combat_v2_sessions where id=p_session for update;
  select * into ctx from combat_consumer_private.activities where session_id=p_session for update;
  if ctx.session_id is null then raise exception 'ordinary_authority_invalid'; end if;
  if ctx.phase='closed' then return; end if;
  update public.combat_v2_sessions set state='chiuso',closed_at=clock_timestamp() where id=p_session;
  update combat_consumer_private.activities set phase='closed',closed_at=clock_timestamp(),
    context_version=context_version+1 where session_id=p_session;
  update combat_consumer_private.offers set state='revoked'
    where session_id=p_session and state='offered';
  update combat_spatial.arena_instances set state='closed',map_version=map_version+1 where encounter_id=p_session;
  perform combat_consumer_private.close_narrative_control(p_session);
  -- Round, dichiarazioni, referti e risorse persistono immutati.
end $function$;

