CREATE OR REPLACE FUNCTION combat_consumer_private.commit_close(p jsonb, prepared jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid uuid:=(p->>'activity_id')::uuid; key uuid:=(p->>'request_key')::uuid;
  cid uuid:=(prepared->>'principal_character_id')::uuid; envelope jsonb; event jsonb; receipt jsonb;
begin
  if not combat_consumer_private.can_close(sid) then perform combat_consumer_private.fail('not_participant',key); end if;
  envelope:=combat_consumer_private.state_projection((p->>'location_id')::uuid);
  if envelope->>'status'<>'ready' then perform combat_consumer_private.fail('adapter_not_ready',key); end if;
  event:=public.combat_v2_event_begin((p->>'offer_id')::uuid,key,'combat_consumer_close',p);
  perform combat_consumer_private.close_session(sid);
  envelope:=jsonb_set(jsonb_set(jsonb_set(jsonb_set(envelope,'{context,phase}','"closed"'),
    '{context,version}',to_jsonb((p->>'context_version')::bigint+1)),
    '{viewer,can_command}','false'),'{offers}','[]');
  receipt:=jsonb_build_object('receipt_id',event->'event_id','request_key',key,'operation','close','replayed',false,
    'activity_id',sid,'exchange_id',p->'exchange_id','context_version_before',p->'context_version',
    'context_version_after',(p->>'context_version')::bigint+1,'declaration_id',null,'report_id',null,
    'report_sha256',null,'values_written',false,'display_events','[]'::jsonb);
  envelope:=jsonb_set(envelope,'{receipt}',receipt);
  update combat_consumer_private.offers set state='consumed',consumed_request_key=key where id=(p->>'offer_id')::uuid;
  insert into combat_consumer_private.request_receipts(principal_character_id,request_key,command_sha256,operation,event_id,viewer_envelope)
    values(cid,key,prepared->>'command_sha256','close',(event->>'event_id')::uuid,envelope);
  return public.combat_v2_event_complete((event->>'event_id')::uuid,envelope);
end $function$;

