-- Native source combat_consumer_private.commit_movement(uuid,uuid,uuid,uuid) MD5 04fb3f519337a14e51976c58284fd16e

CREATE OR REPLACE FUNCTION combat_consumer_private.commit_movement(p_parent uuid, p_movement uuid, p_actor uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare parent combat_consumer_private.offers%rowtype; movement combat_consumer_private.offers%rowtype;
  cap combat_spatial.movement_capabilities%rowtype; instance combat_spatial.arena_instances%rowtype;
  actor combat_spatial.actor_states%rowtype; result jsonb; budget numeric;
begin
  select * into parent from combat_consumer_private.offers where id=p_parent for update;
  select * into movement from combat_consumer_private.offers where id=p_movement for update;
  if parent.id is null or movement.parent_offer_id is distinct from parent.id
    or parent.operation<>'declare' or movement.offer_kind<>'movement' or movement.state<>'offered'
    or movement.principal_character_id<>parent.principal_character_id then
    perform combat_consumer_private.fail('offer_not_available',p_request);
  end if;
  select * into cap from combat_spatial.movement_capabilities
    where capability_id=(movement.source_payload->>'capability_id')::uuid for update;
  select * into instance from combat_spatial.arena_instances where instance_id=cap.instance_id for update;
  select * into actor from combat_spatial.actor_states where instance_id=cap.instance_id and actor_id=p_actor for update;
  select clan_marionettisti_private.movement_remaining(p_actor) into budget
    from public.combat_v2_actors where id=p_actor and session_id=parent.session_id and state='attivo';
  if cap.capability_id is null or cap.actor_id<>p_actor or cap.state<>'offered'
    or instance.encounter_id<>parent.session_id or instance.context_source<>'ordinary' or instance.state<>'open'
    or cap.map_version<>instance.map_version or instance.map_version<>movement.scene_version
    or cap.actor_body_version<>actor.body_version or actor.state<>'active'
    or budget is null or combat_spatial.distance_m(cap.start_x_m,cap.start_y_m,cap.end_x_m,cap.end_y_m)>budget then
    perform combat_consumer_private.fail('context_stale',p_request);
  end if;
  result:=combat_spatial.movement_commit(cap.capability_id,p_request,p_parent);
  if (coalesce((result->>'d_eff_m')::numeric,0)<=0 AND clan_sabaku_private.clone_movement_interruption(cap.capability_id) IS NULL)
    or combat_panel_private.movement_event_cost((result->>'event_id')::uuid,(result->>'d_eff_m')::numeric)>budget then
    perform combat_consumer_private.fail('movement_not_permitted',p_request);
  end if;
  update combat_consumer_private.offers set state='consumed',consumed_request_key=p_request where id=p_movement;
  if (result->>'d_eff_m')::numeric>0 then
  insert into clan_marionettisti_private.movement_receipts(request_key,round_id,owner_actor_id,body_actor_id,capability_id,distance_m,result)
   values(p_request,parent.exchange_id,p_actor,p_actor,cap.capability_id,(result->>'d_eff_m')::numeric,result);
  end if;
  return result;
end $function$;

