-- Native source combat_consumer_private.display_label(uuid,uuid,uuid,bigint) MD5 3c04b898862a6a7a97fffbf68d6dc394

CREATE OR REPLACE FUNCTION combat_consumer_private.display_label(p_session uuid, p_subject uuid, p_viewer uuid, p_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare display text;
begin
  -- Ordinary exact2PG: nessun registro reveal/PNG né proiezione multisource.
  if p_version is not null and p_version<>1 then
    raise exception using errcode='22023',message='label_version_invalid';
  end if;
  select nullif(btrim(c.name),'') into display
    from combat_consumer_private.members m
    join public.combat_v2_actors a on a.id=m.actor_id and a.session_id=m.session_id
    join public.characters c on c.id=m.character_id and c.id=a.character_id
    where m.session_id=p_session and m.actor_id=p_subject and a.actor_kind='pg'
      and exists(select 1 from combat_consumer_private.members v
        where v.session_id=p_session and v.actor_id=p_viewer);
  if display is null then
    select case src.source_kind when 'staff' then 'Marionetta · profilo di prova L1' else 'Marionetta' end into display
    from public.combat_v2_actors a join clan_marionettisti_private.sources src on src.id=a.companion_id and src.is_active
    where a.id=p_subject and a.session_id=p_session
      and exists(select 1 from public.combat_v2_actors viewer where viewer.id=p_viewer and viewer.session_id=p_session
       and viewer.actor_kind='pg' and viewer.controller_user=auth.uid())
      and clan_marionettisti_private.actor_visible(p_session,p_subject,auth.uid());
  end if;
  if display is null then
    raise exception using errcode='22023',message='name_projection_missing';
  end if;
  -- Il replay consuma la proiezione congelata nella receipt, non questa lettura.
  return jsonb_build_object('display_name',display,'label_version',1);
end $function$;

