-- Native source combat_consumer_private.fail(text,uuid) MD5 8f7519396d3aba37fe2da21cb32770d2

CREATE OR REPLACE FUNCTION combat_consumer_private.fail(p_code text, p_request uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare message_it text; status integer:=409;
begin
  case p_code
    when 'authentication_required' then message_it:='Accedi prima di inviare una scelta.';status:=401;
    when 'command_shape_invalid' then message_it:='Formato della scelta non valido.';status:=422;
    when 'command_keys_invalid' then message_it:='La scelta contiene campi non consentiti.';status:=422;
    when 'contract_version_invalid' then message_it:='Aggiorna il pannello prima di inviare.';status:=422;
    when 'operation_invalid' then message_it:='Operazione non consentita.';status:=422;
    when 'identifier_invalid' then message_it:='Riferimento della scelta non valido.';status:=422;
    when 'context_version_invalid' then message_it:='Versione del contesto non valida.';status:=422;
    when 'narrative_text_invalid' then message_it:='Il testo narrativo non è valido.';status:=422;
    when 'activity_scope_invalid' then message_it:='Scelta riferita a un altro scontro.';status:=422;
    when 'exchange_scope_invalid' then message_it:='Scelta riferita a un altro scambio.';status:=422;
    when 'movement_not_permitted' then message_it:='Questa risposta non ammette movimento.';status:=422;
    when 'name_projection_missing' then message_it:='Nome della sorgente non disponibile: collegamento da correggere.';
    when 'not_participant' then message_it:='Non puoi comandare questo combattente.';status:=403;
    when 'presence_required' then message_it:='Devi essere ancora nel luogo dello scontro.';status:=403;
    when 'context_stale' then message_it:='La situazione è cambiata: aggiorna le opzioni.';
    when 'offer_not_available' then message_it:='La scelta non è più disponibile.';
    when 'request_key_conflict' then message_it:='La richiesta è già associata a una scelta diversa.';
    when 'adapter_not_ready' then message_it:='Questo collegamento non è ancora disponibile.';
    when 'scene_not_configured' then message_it:='La scena spaziale non è ancora configurata.';
    else raise exception using errcode='P0001',message='CONSUMER_ERROR_CODE_NOT_CANONICAL';
  end case;
  -- Shape PostgREST: message obbligatorio; details contiene solo metadati sanitizzati.
  raise sqlstate 'PGRST' using message=jsonb_build_object('code',p_code,
    'message',message_it,'details',jsonb_build_object('retryable',false,
      'request_key',p_request,'details_sanitized','{}'::jsonb)::text)::text,
    detail=jsonb_build_object('status',status,'headers','{}'::jsonb)::text;
end $function$;

