CREATE OR REPLACE FUNCTION combat_consumer_private.is_service_request()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare claims jsonb;
begin
  if current_setting('role',true) is distinct from 'service_role' then return false; end if;
  begin
    claims:=nullif(current_setting('request.jwt.claims',true),'')::jsonb;
  exception when invalid_text_representation then return false;
  end;
  return coalesce(jsonb_typeof(claims)='object' and claims->>'role'='service_role',false);
end $function$;

