-- Native source combat_consumer_private.master_uses_ordinary_claim(master_v2_sessions,master_v2_sessions,text) MD5 e72fd0210f10a0bbd015d2becf9989c8

CREATE OR REPLACE FUNCTION combat_consumer_private.master_uses_ordinary_claim(p_new master_v2_sessions, p_old master_v2_sessions, p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare permit combat_consumer_private.master_admission_permits%rowtype; sid uuid;
begin
  if p_operation='INSERT' then
    select * into permit from combat_consumer_private.master_admission_permits
      where master_id=p_new.id for update;
    if permit.master_id is null then return false; end if;
    if permit.state<>'prepared' or permit.transaction_id<>txid_current()
      or permit.owner_user is distinct from auth.uid()
      or p_new.master_user is distinct from permit.owner_user
      or p_new.location_id is distinct from permit.location_id
      or p_new.owner_kind is distinct from 'human' or p_new.tipo is distinct from 'duello'
      or p_new.stato is distinct from 'in_corso' or p_new.mission_id is not null
      or p_new.quest_kind is not null or not public.master_v2_is_master(auth.uid())
      or not coalesce((select enabled from combat_consumer_private.runtime_config where singleton),false)
      or not exists(select 1 from combat_consumer_private.activities c
        join combat_consumer_private.narrative_authorities a on a.session_id=c.session_id
        join combat_gate_private.location_claims g on g.location_id=c.location_id
          and g.claimant_kind='combat_v2_ordinary' and g.claimant_session_id=c.session_id and g.released_at is null
        where c.session_id=permit.session_id and c.location_id=permit.location_id
          and c.phase<>'closed' and a.mode<>'human' and a.master_session_id is null)
      or exists(select 1 from public.combat_v2_actors where session_id=permit.session_id and controller_user=auth.uid())
    then raise exception 'ordinary_master_permit_invalid'; end if;
    update combat_consumer_private.master_admission_permits set state='consumed' where master_id=permit.master_id;
    return true;
  end if;
  select a.session_id into sid from combat_consumer_private.narrative_authorities a
    join combat_consumer_private.master_admission_permits p on p.master_id=a.master_session_id
      and p.session_id=a.session_id and p.state='consumed'
    where a.master_session_id=p_old.id;
  if sid is null then return false; end if;
  if p_new.location_id is distinct from p_old.location_id then raise exception 'SESSION_LOCATION_IMMUTABLE'; end if;
  if p_old.stato in ('chiusa','annullata') and p_new.stato not in ('chiusa','annullata')
    then raise exception 'SESSION_REOPEN_FORBIDDEN'; end if;
  -- Il solo claim meccanico appartiene all'ordinary: la sua chiusura lo rilascia.
  return true;
end $function$;

