-- Native source combat_consumer_private.opening_state(uuid) MD5 47507fd4169e36731f35d81085988881

CREATE OR REPLACE FUNCTION combat_consumer_private.opening_state(p_location uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cid uuid; prof combat_consumer_private.scene_profiles%rowtype;
  inv combat_consumer_private.invitations%rowtype; test_room boolean;
begin
  if auth.uid() is null then perform combat_consumer_private.fail('authentication_required'); end if;
  if not combat_consumer_private.runtime_allowed(p_location,auth.uid()) then
    return combat_consumer_private.blocked('adapter_not_ready');
  end if;
  select id into cid from public.characters where user_id=auth.uid() and vita>0;
  if cid is null or not public._combat_presente(auth.uid(),p_location) then
    return combat_consumer_private.blocked('not_participant');
  end if;
  select is_test into test_room from public.locations where id=p_location and is_active;
  if not found or (coalesce(test_room,false) and not public._puo_test_room()) then
    return combat_consumer_private.blocked('not_participant');
  end if;
  if public._personaggio_impegnato_meccanicamente(cid)
    or exists(select 1 from public.combat_sessions where location_id=p_location and state='aperto')
    or exists(select 1 from public.master_v2_sessions where location_id=p_location and stato not in ('chiusa','annullata'))
    or exists(select 1 from public.combat_v2_sessions where location_id=p_location and state not in ('chiuso','annullato')) then
    return combat_consumer_private.blocked('not_participant');
  end if;
  select * into prof from combat_consumer_private.scene_profiles where location_id=p_location and enabled;
  if prof.id is null or prof.geometry_sha256 is distinct from
    combat_consumer_private.scene_fingerprint(prof.template_key,prof.template_version)
    or not exists(select 1 from combat_spatial.arena_templates where template_key=prof.template_key
      and template_version=prof.template_version and status='ready')
    or combat_spatial.template_errors(prof.template_key,prof.template_version)<>'[]'::jsonb then
    return combat_consumer_private.blocked('scene_not_configured');
  end if;
  select * into inv from combat_consumer_private.invitations where location_id=p_location and state='pending';
  if inv.id is not null and cid not in (inv.opener_character_id,inv.recipient_character_id) then
    return combat_consumer_private.blocked('not_participant');
  end if;
  if inv.id is not null and (inv.scene_profile_id<>prof.id or inv.geometry_sha256<>prof.geometry_sha256
    or inv.scene_version<>prof.producer_version) then
    return combat_consumer_private.blocked('scene_not_configured');
  end if;
  return jsonb_build_object('schema_version','combat-consumer/1','status','ready','reason_code',null,
    'context',jsonb_build_object('activity_kind','ordinary_v2','activity_id',inv.id,
      'exchange_id',null,'round_no',1,'phase','waiting_join','version',coalesce(inv.context_version,1),
      'scene_version',prof.producer_version,'policy_id',case when test_room then
        'staff_test_no_persistent_resources_v1' else 'free_duel_nonlethal_real_resources_v1' end),
    'viewer',jsonb_build_object('actor_id',null,'can_command',true),
    'actors','[]'::jsonb,'offers','[]'::jsonb,'receipt',null);
end $function$;

