-- Native source combat_consumer_private.place_fighters(uuid) MD5 7f8ab725ce64feee7455791a35d2990a

CREATE OR REPLACE FUNCTION combat_consumer_private.place_fighters(p_session uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx combat_consumer_private.activities%rowtype;
  prof combat_consumer_private.scene_profiles%rowtype;
  iid uuid; n integer; radius numeric;
begin
  perform 1 from public.combat_v2_sessions where id=p_session for update;
  select * into ctx from combat_consumer_private.activities where session_id=p_session for update;
  if ctx.session_id is null then
    raise exception using errcode='22023',message='ordinary_authority_invalid';
  end if;
  perform 1 from public.combat_v2_actors where session_id=p_session order by id for update;
  select count(*) into n from combat_consumer_private.members m
    join public.combat_v2_actors a on a.id=m.actor_id and a.session_id=m.session_id
    join public.characters c on c.id=m.character_id and c.id=a.character_id
    where m.session_id=p_session and a.actor_kind='pg' and a.state='attivo'
      and a.controller_user=c.user_id;
  if n<>2 or (select count(*) from public.combat_v2_actors where session_id=p_session)<>2 then
    raise exception using errcode='22023',message='ordinary_roster_invalid';
  end if;
  select * into prof from combat_consumer_private.scene_profiles
    where id=ctx.scene_profile_id and location_id=ctx.location_id and enabled for share;
  if prof.id is null then raise exception using errcode='22023',message='scene_not_configured'; end if;
  select count(*) into n from combat_spatial.arena_slots
    where template_key=prof.template_key and template_version=prof.template_version
      and slot_key in (prof.fighter_one_slot,prof.fighter_two_slot) and actor_kind='PG';
  if n<>2 then raise exception using errcode='22023',message='ordinary_slots_invalid'; end if;
  iid:=combat_consumer_private.claim_scene(p_session);
  perform 1 from combat_spatial.arena_instances where instance_id=iid for update;
  select count(*) into n from combat_spatial.actor_states where instance_id=iid;
  if n>0 then
    -- Replay non riposiziona corpi già mossi e non riattiva attori rimossi.
    if n<>2 or exists(select 1 from combat_spatial.actor_states b
      where b.instance_id=iid and not exists(
        select 1 from combat_consumer_private.members m
        join public.combat_v2_actors a on a.id=m.actor_id and a.session_id=m.session_id
        where m.session_id=p_session and m.actor_id=b.actor_id and b.actor_kind='PG'
          and b.controller_principal_id=a.controller_user
          and b.projection_subject_id=m.character_id
          and b.slot_key=case m.fighter_slot when 1 then prof.fighter_one_slot else prof.fighter_two_slot end)) then
      raise exception using errcode='22023',message='ordinary_bodies_conflict';
    end if;
    return iid;
  end if;
  select actor_radius_m into radius from combat_spatial.arena_templates
    where template_key=prof.template_key and template_version=prof.template_version;
  insert into combat_spatial.actor_states
    (instance_id,actor_id,actor_kind,slot_key,controller_principal_id,projection_subject_id,
      x_m,y_m,footprint_radius_m,body_version,state)
    select iid,a.id,'PG',s.slot_key,a.controller_user,m.character_id,
      s.x_m,s.y_m,radius,1,'active'
    from combat_consumer_private.members m
    join public.combat_v2_actors a on a.id=m.actor_id and a.session_id=m.session_id
    join combat_spatial.arena_slots s on s.template_key=prof.template_key
      and s.template_version=prof.template_version
      and s.slot_key=case m.fighter_slot when 1 then prof.fighter_one_slot else prof.fighter_two_slot end
    where m.session_id=p_session;
  return iid;
end $function$;

