-- Native source combat_consumer_private.prepare_command(jsonb) MD5 d3f9f43abf9d4a1bdd3f0f8de7d187b9

CREATE OR REPLACE FUNCTION combat_consumer_private.prepare_command(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p jsonb; cid uuid; key uuid; loc uuid; sid uuid; xid uuid; fingerprint text;
  prior combat_consumer_private.request_receipts%rowtype;
  offer combat_consumer_private.offers%rowtype; move combat_consumer_private.offers%rowtype;
  ctx combat_consumer_private.activities%rowtype; a public.combat_v2_actors%rowtype;
  invitation combat_consumer_private.invitations%rowtype;
  scene integer;
begin
  if auth.uid() is null then perform combat_consumer_private.fail('authentication_required'); end if;
  begin
    p:=combat_consumer_private.validate_command(p_command);
  exception when sqlstate '22023' then
    perform combat_consumer_private.fail(sqlerrm);
  end;
  key:=(p->>'request_key')::uuid;loc:=(p->>'location_id')::uuid;
  sid:=(p->>'activity_id')::uuid;xid:=(p->>'exchange_id')::uuid;
  select id into cid from public.characters where user_id=auth.uid();
  if cid is null then perform combat_consumer_private.fail('not_participant',key); end if;
  -- Serializza la chiave indipendentemente dalla vita dell'offerta. Il replay
  -- riusa la proiezione originaria, non esegue nuovamente un comando operativo.
  perform pg_advisory_xact_lock(hashtextextended('consumer-request:'||cid::text||':'||key::text,731));
  fingerprint:=public.combat_v2_sha256(p);
  select * into prior from combat_consumer_private.request_receipts
    where principal_character_id=cid and request_key=key;
  if prior.request_key is not null then
    if prior.command_sha256<>fingerprint or prior.operation<>p->>'operation' then
      perform combat_consumer_private.fail('request_key_conflict',key);
    end if;
    return jsonb_build_object('replayed',true,'envelope',
      jsonb_set(prior.viewer_envelope,'{receipt,replayed}','true'::jsonb,false));
  end if;
  if not combat_consumer_private.runtime_allowed(loc,auth.uid()) then
    perform combat_consumer_private.fail('adapter_not_ready',key);
  end if;
  -- Invito non è una sessione Combat: nessun PG arruolato prima del consenso.
  if sid is not null and p->>'operation' in ('join','close') then
    perform 1 from public.locations where id=loc for update;
    select * into invitation from combat_consumer_private.invitations where id=sid for update;
    if invitation.id is not null then
      if invitation.location_id<>loc or invitation.context_version<>(p->>'context_version')::bigint
        or invitation.state<>'pending' or xid is not null
        or (p->>'operation'='join' and cid<>invitation.recipient_character_id)
        or (p->>'operation'='close' and cid not in (invitation.opener_character_id,invitation.recipient_character_id))
        or (p->>'operation'='join' and invitation.created_at<clock_timestamp()-interval '24 hours') then
        perform combat_consumer_private.fail('offer_not_available',key);
      end if;
    end if;
  end if;
  -- Ordine del core rispettato per sessioni esistenti: sessione/round/attori/PG.
  if sid is not null and invitation.id is null then
    select * into ctx from combat_consumer_private.activities where session_id=sid;
    if ctx.session_id is null or ctx.location_id<>loc then
      perform combat_consumer_private.fail('activity_scope_invalid',key);
    end if;
    if ctx.exchange_id is not null then
      perform public.combat_v2_lock_round(ctx.exchange_id);
    else
      perform 1 from public.combat_v2_sessions where id=sid for update;
    end if;
    select * into ctx from combat_consumer_private.activities where session_id=sid for update;
    if ctx.context_version<>(p->>'context_version')::bigint
      or ctx.exchange_id is distinct from xid then
      perform combat_consumer_private.fail('context_stale',key);
    end if;
    if p->>'operation' not in ('join') then
      select x.* into a from public.combat_v2_actors x
        join combat_consumer_private.members m on m.session_id=x.session_id and m.actor_id=x.id
        where m.session_id=sid and m.character_id=cid and x.controller_user=auth.uid() and x.actor_kind='pg';
      if a.id is null and not (p->>'operation'='close' and public.is_staff()) then
        perform combat_consumer_private.fail('not_participant',key);
      end if;
      if p->>'operation'='declare' and
        (ctx.phase<>'action' or ctx.turn_actor_id<>a.id or a.state<>'attivo') then
        perform combat_consumer_private.fail('offer_not_available',key);
      end if;
      if p->>'operation'='defend' and
        (ctx.phase<>'defense' or ctx.turn_actor_id=a.id or a.state<>'attivo') then
        perform combat_consumer_private.fail('offer_not_available',key);
      end if;
    elsif ctx.phase<>'waiting_join' then
      perform combat_consumer_private.fail('offer_not_available',key);
    end if;
  end if;
  if p->>'operation'<>'close' and not exists(select 1 from public.presence where user_id=auth.uid() and location_id=loc) then
    perform combat_consumer_private.fail('presence_required',key);
  end if;
  select * into offer from combat_consumer_private.offers where id=(p->>'offer_id')::uuid for update;
  if offer.id is null or offer.state<>'offered' or offer.principal_character_id<>cid
    or offer.location_id<>loc or coalesce(offer.session_id,offer.invitation_id) is distinct from sid
    or offer.exchange_id is distinct from xid or offer.context_version<>(p->>'context_version')::bigint
    or offer.operation<>p->>'operation' or offer.offer_kind='movement' then
    perform combat_consumer_private.fail('offer_not_available',key);
  end if;
  if sid is not null and invitation.id is null then
    select map_version into scene from combat_spatial.arena_instances where encounter_id=sid and state='open';
    if scene is null or scene<>offer.scene_version then
      perform combat_consumer_private.fail('context_stale',key);
    end if;
  end if;
  -- Eccezione solo per l'offerta OFF generata dal server e gia verificata
  -- per identita, sessione, scambio, versione e mappa. Nessun flag client.
  if p->>'operation'='control' and (a.state<>'attivo' or ctx.phase='closed' or
    ((ctx.phase<>'action' or ctx.turn_actor_id<>a.id) and
     not clan_sabaku_private.off_offer_valid(offer.id,a.id))) then
    perform combat_consumer_private.fail('offer_not_available',key);
  end if;
  if jsonb_typeof(offer.viewer_projection->'movement_required') is distinct from 'boolean'
    or ((offer.viewer_projection->>'movement_required')::boolean and p->>'movement_offer_id' is null) then
    perform combat_consumer_private.fail('movement_not_permitted',key);
  end if;
  if p->>'movement_offer_id' is not null then
    select * into move from combat_consumer_private.offers where id=(p->>'movement_offer_id')::uuid for update;
    if move.id is null or move.state<>'offered' or move.offer_kind<>'movement'
      or move.parent_offer_id<>offer.id or move.principal_character_id<>cid
      or move.session_id is distinct from sid or move.exchange_id is distinct from xid
      or move.context_version<>offer.context_version or move.scene_version<>offer.scene_version then
      perform combat_consumer_private.fail('offer_not_available',key);
    end if;
  end if;
  -- Payload PRIVATO per il dispatcher: mai restituirlo dalla RPC pubblica.
  -- Non segna consumed: questa scrittura compete alla stessa transazione di
  -- dichiarazione/messaggio/risorse/receipt dopo il successo del consumer.
  return jsonb_build_object('replayed',false,'principal_character_id',cid,
    'actor_id',a.id,'command_sha256',fingerprint,'offer',to_jsonb(offer),
    'movement_offer',case when move.id is null then null else to_jsonb(move) end);
end $function$;

