-- Native source combat_consumer_private.record_message(uuid,uuid) MD5 34852e31180a84e2ce10926ed590f968

CREATE OR REPLACE FUNCTION combat_consumer_private.record_message(p_declaration uuid, p_message uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists(select 1 from public.combat_v2_declarations d
    join public.combat_v2_actors a on a.id=d.actor_id
    join public.combat_v2_sessions s on s.id=a.session_id
    join public.messages m on m.id=p_message and m.character_id=a.character_id and m.location_id=s.location_id
    where d.id=p_declaration and a.controller_user=auth.uid()) then
    perform combat_consumer_private.fail('not_participant');
  end if;
  insert into combat_consumer_private.declaration_messages values(p_declaration,p_message,public._combat_narrative_sha(p_message));
end $function$;

