-- Native source combat_consumer_private.state_projection(uuid) MD5 9bc166e5c0ca7767c1db8bd644389d8d

CREATE OR REPLACE FUNCTION combat_consumer_private.state_projection(p_location uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); cid uuid; viewer uuid; label_viewer uuid;
  ctx combat_consumer_private.activities%rowtype;
  body combat_spatial.actor_states%rowtype; viewer_body combat_spatial.actor_states%rowtype;
  a record; label jsonb; roster jsonb:='[]'; instance uuid; scene_version integer;
  viewer_map jsonb:=null;
  narrative jsonb:=null; narrative_state text; narrative_reason text; report_state text;
  claim_state text; claim_reason text; claim_expires timestamptz;
  own_resources jsonb:=null; own_snapshot jsonb; simulated boolean; k text; valid_resources boolean;
begin
  if uid is null then raise exception using errcode='28000',message='authentication_required'; end if;
  select id into cid from public.characters where user_id=uid;
  if cid is null and not public.is_staff() then return combat_consumer_private.blocked('not_participant')||jsonb_build_object('narrative',null); end if;
  if not combat_consumer_private.runtime_allowed(p_location,uid) then
    return combat_consumer_private.blocked('adapter_not_ready')||jsonb_build_object('narrative',null);
  end if;
  if exists(select 1 from public.combat_sessions where location_id=p_location and state='aperto') then
    return combat_consumer_private.blocked('legacy_session_active')||jsonb_build_object('narrative',null);
  end if;
  select * into ctx from combat_consumer_private.activities
    where location_id=p_location and phase<>'closed' order by created_at desc limit 1;
  if ctx.session_id is null then
    if not exists(select 1 from combat_consumer_private.scene_profiles
      where location_id=p_location and enabled) then
      return combat_consumer_private.blocked('scene_not_configured')||jsonb_build_object('narrative',null);
    end if;
    return combat_consumer_private.opening_state(p_location)||jsonb_build_object('narrative',null);
  end if;
  select m.actor_id into viewer from combat_consumer_private.members m
    join public.combat_v2_actors actor_row on actor_row.id=m.actor_id and actor_row.session_id=m.session_id
    where m.session_id=ctx.session_id and m.character_id=cid and actor_row.controller_user=uid;
  label_viewer:=viewer;
  if viewer is null then
    if not public.is_staff() then return combat_consumer_private.blocked('not_participant')||jsonb_build_object('narrative',null); end if;
    select actor_id into label_viewer from combat_consumer_private.members where session_id=ctx.session_id order by fighter_slot limit 1;
  end if;
  select instance_id,map_version into instance,scene_version
    from combat_spatial.arena_instances where encounter_id=ctx.session_id and state='open';
  if instance is null then return combat_consumer_private.blocked('scene_not_configured')||jsonb_build_object('narrative',null); end if;
  select * into viewer_body from combat_spatial.actor_states
    where instance_id=instance and actor_id=viewer;
  if viewer is not null and not found then return combat_consumer_private.blocked('scene_not_configured')||jsonb_build_object('narrative',null); end if;

  -- Nessun fallback a characters: le riserve del combattimento sono autoritative.
  -- Un Master osservatore senza proprio attore non riceve riserve di altri PG.
  if viewer is not null then
    select x.mechanics_snapshot into own_snapshot
    from public.combat_v2_actors x
    where x.id=viewer and x.session_id=ctx.session_id
      and x.character_id=cid and x.controller_user=uid and x.actor_kind='pg';
    select case
      when l.is_test and ctx.policy_id='staff_test_no_persistent_resources_v1' then true
      when not l.is_test and ctx.policy_id='free_duel_nonlethal_real_resources_v1' then false
      else null end into simulated
    from public.locations l where l.id=ctx.location_id and l.is_active;
    valid_resources:=own_snapshot is not null and simulated is not null;
    foreach k in array array['vita','vita_max','chakra','chakra_max'] loop
      if jsonb_typeof(own_snapshot->k) is distinct from 'number'
        or coalesce(own_snapshot->>k,'') !~ '^[0-9]{1,9}$' then
        valid_resources:=false;
      end if;
    end loop;
    if valid_resources then
      if (own_snapshot->>'vita_max')::integer>0
        and (own_snapshot->>'chakra_max')::integer>0
        and (own_snapshot->>'vita')::integer<=(own_snapshot->>'vita_max')::integer
        and (own_snapshot->>'chakra')::integer<=(own_snapshot->>'chakra_max')::integer then
        own_resources:=jsonb_build_object(
          'pv',jsonb_build_object('current',(own_snapshot->>'vita')::integer,'max',(own_snapshot->>'vita_max')::integer),
          'chakra',jsonb_build_object('current',(own_snapshot->>'chakra')::integer,'max',(own_snapshot->>'chakra_max')::integer),
          'simulated',simulated);
      end if;
    end if;
  end if;
  for a in select x.id,x.state,m.role from public.combat_v2_actors x
    join combat_consumer_private.members m on m.session_id=x.session_id and m.actor_id=x.id
    where x.session_id=ctx.session_id order by x.id loop
    -- Exact2PG: nome dall'identità reale, non dal mechanics_snapshot privato.
    begin
      label:=combat_consumer_private.display_label(ctx.session_id,a.id,label_viewer,null);
    exception when sqlstate '22023' then
      if sqlerrm='name_projection_missing' then
        return combat_consumer_private.blocked('name_projection_missing')||jsonb_build_object('narrative',null);
      end if;
      raise;
    end;
    select * into body from combat_spatial.actor_states
      where instance_id=instance and actor_id=a.id and state='active';
    roster:=roster||jsonb_build_array(jsonb_build_object(
      'actor_id',a.id,'display_name',label->>'display_name','label_version',label->'label_version',
      'mine',a.id=viewer,'state',case a.state when 'attivo' then 'active' when 'fuori' then 'out' else 'withdrawn' end,
      'is_turn_owner',a.id=ctx.turn_actor_id,
      'distance_from_viewer_m',case when viewer is null or a.id=viewer or body.actor_id is null then null else
        round(combat_spatial.distance_m(viewer_body.x_m,viewer_body.y_m,body.x_m,body.y_m),2) end));
  end loop;

  -- Perimetro visibile esplicito: arena neutra exact2PG, non mappe missioni.
  -- L'osservatore staff non eredita il POV di un combattente.
  if viewer is not null and viewer_body.state='active' then
    select jsonb_build_object(
      'schema_version','combat-map/1','map_version',i.map_version,
      'readonly',true,'label','Arena neutra',
      'bounds',jsonb_build_object('width_m',t.width_m,'height_m',t.height_m),
      'pov',jsonb_build_object('actor_id',viewer,'x_m',viewer_body.x_m,
        'y_m',viewer_body.y_m,'radius_m',viewer_body.footprint_radius_m),
      'actors',(select coalesce(jsonb_agg(jsonb_build_object(
        'actor_id',ast.actor_id,'x_m',ast.x_m,'y_m',ast.y_m,
        'radius_m',ast.footprint_radius_m) order by ast.actor_id),'[]'::jsonb)
        from combat_spatial.actor_states ast
        join combat_consumer_private.members mem on mem.session_id=ctx.session_id and mem.actor_id=ast.actor_id
        join public.combat_v2_actors act on act.id=mem.actor_id and act.session_id=mem.session_id
        where ast.instance_id=i.instance_id and ast.state='active' and act.state='attivo' and act.actor_kind='pg'),
      'objects',(select coalesce(jsonb_agg(jsonb_build_object(
        'object_id',md5(i.instance_id::text||obj.object_key||os.state_version)::uuid,
        'label',obj.semantic_label,'x_m',pos.x,'y_m',pos.y,
        'radius_m',(obj.shape->>'radius')::numeric,
        'distance_from_viewer_m',round(combat_spatial.distance_m(viewer_body.x_m,viewer_body.y_m,pos.x,pos.y),2),
        'state',os.state,
        'substitution_anchor_available',obj.substitutable and os.state='available') order by obj.object_key),'[]'::jsonb)
        from combat_spatial.arena_objects obj
        join combat_spatial.object_states os on os.instance_id=i.instance_id and os.object_key=obj.object_key
        cross join lateral (select
          case when os.state='consumed_non_substitutable' then os.proxy_x_m else (obj.shape->>'cx')::numeric end x,
          case when os.state='consumed_non_substitutable' then os.proxy_y_m else (obj.shape->>'cy')::numeric end y) pos
        where obj.template_key=t.template_key and obj.template_version=t.template_version
          and obj.object_key in ('LOG-A','LOG-B') and obj.shape_kind='circle'
          and pos.x is not null and pos.y is not null))
    into viewer_map
    from combat_spatial.arena_instances i
    join combat_spatial.arena_templates t on t.template_key=i.template_key and t.template_version=i.template_version
    where i.instance_id=instance and i.encounter_id=ctx.session_id
      and i.context_source='ordinary' and i.state='open'
      and t.template_key='ordinary_neutral_v1' and t.template_version=1
      and t.geometry_hash='1920b919137f4f58de6d71af2811061a'
      and combat_spatial.template_errors(t.template_key,t.template_version)='[]'::jsonb
      and exists(select 1 from public.combat_v2_actors mine
        where mine.id=viewer and mine.session_id=ctx.session_id and mine.character_id=cid
          and mine.controller_user=uid and mine.actor_kind='pg' and mine.state='attivo')
      and (select count(*) from combat_consumer_private.members mem where mem.session_id=ctx.session_id)=2;
  end if;
  -- Solo metadati sanitizzati dello scambio corrente; nessuna mutazione o autorità nuova.
  if ctx.phase='resolved' then
    select r.narration_state,n.state,n.failure_code,n.expires_at
      into report_state,claim_state,claim_reason,claim_expires
    from public.combat_v2_rounds round_row
    join public.combat_v2_round_reports r on r.round_id=round_row.id
    left join combat_consumer_private.narrative_claims n
      on n.session_id=ctx.session_id and n.round_id=ctx.exchange_id
      and n.report_id=r.id and n.report_sha256=r.mechanics_sha256
    where round_row.id=ctx.exchange_id and round_row.session_id=ctx.session_id;
    narrative_state:=case
      when report_state='pubblicata' or claim_state='completed' then 'published'
      when report_state='ritirata' or claim_state='failed' then 'failed'
      when claim_state='expired' or (claim_state='claimed' and claim_expires<=statement_timestamp()) then 'expired'
      when claim_state='claimed' then 'running'
      else 'waiting' end;
    narrative_reason:=case
      when narrative_state='expired' then 'timeout'
      when narrative_state='failed' then case
        when report_state='ritirata' then 'narration_unavailable'
        when claim_reason in ('validation_rejected','provider_error','configuration_mismatch','timeout','context_changed') then claim_reason
        else 'narration_unavailable' end
      else null end;
    if combat_consumer_private.scene_public_state_v2(ctx.exchange_id) is not null then
      narrative_state:=combat_consumer_private.scene_public_state_v2(ctx.exchange_id)->>'state';
      narrative_reason:=combat_consumer_private.scene_public_state_v2(ctx.exchange_id)->>'reason_code';
    end if;
    narrative:=jsonb_build_object('schema_version','combat-narrative-state/1',
      'activity_id',ctx.session_id,'exchange_id',ctx.exchange_id,
      'state',narrative_state,'reason_code',narrative_reason);
  end if;
  return clan_sabaku_private.consumer_projection(clan_marionettisti_private.consumer_projection(jsonb_build_object('schema_version','combat-consumer/1','status','ready','reason_code',null,
    'context',jsonb_build_object('activity_kind','ordinary_v2','activity_id',ctx.session_id,
      'exchange_id',ctx.exchange_id,'round_no',ctx.round_no,'phase',ctx.phase,
      'version',ctx.context_version,'scene_version',scene_version,'policy_id',ctx.policy_id),
    'viewer',jsonb_build_object('actor_id',viewer,'resources',own_resources,'can_command',combat_consumer_private.can_close(ctx.session_id) or exists(
      select 1 from public.combat_v2_actors where session_id=ctx.session_id and id=viewer and state='attivo'
        and ((ctx.phase='action' and viewer=ctx.turn_actor_id) or (ctx.phase='defense' and viewer<>ctx.turn_actor_id)))),
    'map',viewer_map,'actors',roster,'offers','[]'::jsonb,'receipt',null,'narrative',narrative)));
end $function$;

