-- Native source combat_consumer_private.validate_command(jsonb) MD5 06ce9007e069dc10d3ba556faca8721e

CREATE OR REPLACE FUNCTION combat_consumer_private.validate_command(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text; op text; n numeric;
  keys constant text[]:=array['schema_version','operation','location_id','activity_id',
    'exchange_id','context_version','offer_id','movement_offer_id','request_key','narrative_text'];
begin
  if p is null or jsonb_typeof(p)<>'object' then
    raise exception using errcode='22023',message='command_shape_invalid';
  end if;
  if not (p ?& keys) or exists(select 1 from jsonb_object_keys(p) x where not(x=any(keys))) then
    raise exception using errcode='22023',message='command_keys_invalid';
  end if;
  if p->>'schema_version' is distinct from 'combat-consumer-command/1' then
    raise exception using errcode='22023',message='contract_version_invalid';
  end if;
  op:=p->>'operation';
  if op is null or op not in ('open','join','declare','defend','control','close') then
    raise exception using errcode='22023',message='operation_invalid';
  end if;
  foreach k in array array['location_id','offer_id','request_key'] loop
    if jsonb_typeof(p->k)<>'string' or (p->>k) !~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
      raise exception using errcode='22023',message='identifier_invalid';
    end if;
    perform (p->>k)::uuid;
  end loop;
  foreach k in array array['activity_id','exchange_id','movement_offer_id'] loop
    if p->k<>'null'::jsonb then
      if jsonb_typeof(p->k)<>'string' or (p->>k) !~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
        raise exception using errcode='22023',message='identifier_invalid';
      end if;
      perform (p->>k)::uuid;
    end if;
  end loop;
  if jsonb_typeof(p->'context_version')<>'number' then
    raise exception using errcode='22023',message='context_version_invalid';
  end if;
  n:=(p->>'context_version')::numeric;
  if n<1 or n<>trunc(n) or n>9007199254740991 then
    raise exception using errcode='22023',message='context_version_invalid';
  end if;
  if jsonb_typeof(p->'narrative_text')<>'string' then
    raise exception using errcode='22023',message='narrative_text_invalid';
  end if;
  if (op='open') is distinct from (p->'activity_id'='null'::jsonb) then
    raise exception using errcode='22023',message='activity_scope_invalid';
  end if;
  if op in ('open','join') and p->'exchange_id'<>'null'::jsonb then
    raise exception using errcode='22023',message='exchange_scope_invalid';
  end if;
  if op in ('declare','defend','control') and p->'exchange_id'='null'::jsonb then
    raise exception using errcode='22023',message='exchange_scope_invalid';
  end if;
  if op<>'declare' and p->'movement_offer_id'<>'null'::jsonb then
    raise exception using errcode='22023',message='movement_not_permitted';
  end if;
  return p;
end $function$;

