CREATE OR REPLACE FUNCTION combat_consumer_private.validate_display_event(e jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare prefix text; aid jsonb; nam jsonb; ver jsonb;
  keys constant text[]:=array['event_id','event_kind','actor_id','display_name',
    'label_version','target_actor_id','target_display_name','target_label_version','summary'];
begin
  if e is null or jsonb_typeof(e)<>'object' then
    raise exception using errcode='22023',message='display_event_shape_invalid';
  end if;
  if not(e ?& keys) or exists(select 1 from jsonb_object_keys(e) x where not(x=any(keys))) then
    raise exception using errcode='22023',message='display_event_shape_invalid';
  end if;
  if jsonb_typeof(e->'event_id')<>'string' or e->>'event_kind' is null
    or e->>'event_kind' not in ('movement','action_declared','defense_resolved','control_changed','combat_closed')
    or jsonb_typeof(e->'summary')<>'string' then
    raise exception using errcode='22023',message='display_event_shape_invalid';
  end if;
  perform (e->>'event_id')::uuid;
  foreach prefix in array array['','target_'] loop
    aid:=e->(prefix||'actor_id'); nam:=e->(prefix||'display_name'); ver:=e->(prefix||'label_version');
    if aid='null'::jsonb then
      if nam<>'null'::jsonb or ver<>'null'::jsonb then
        raise exception using errcode='22023',message='name_projection_missing';
      end if;
    else
      if jsonb_typeof(aid)<>'string' or jsonb_typeof(nam)<>'string'
        or length(btrim(nam#>>'{}'))=0 or jsonb_typeof(ver)<>'number' then
        raise exception using errcode='22023',message='name_projection_missing';
      end if;
      perform (aid#>>'{}')::uuid;
      if (ver#>>'{}')::numeric<1 or (ver#>>'{}')::numeric<>trunc((ver#>>'{}')::numeric) then
        raise exception using errcode='22023',message='label_version_invalid';
      end if;
    end if;
  end loop;
  return e;
end $function$;

