-- Native source combat_gate_private.claim_acquire(text,uuid,uuid,text) MD5 95f71c6e5b4527120d9d0e1c307befe0

CREATE OR REPLACE FUNCTION combat_gate_private.claim_acquire(p_kind text, p_session uuid, p_location uuid, p_origin text DEFAULT 'trigger'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_claim uuid;
begin
  if p_kind not in ('v1','combat_v2_ordinary','master_v2')
     or p_session is null or p_location is null
     or p_origin not in ('trigger','backfill','repair') then
    raise exception using errcode='22023', message='CLAIM_INPUT_INVALID';
  end if;
  -- Ogni porta, inclusa V1 immutata, acquisisce prima la location. Questo
  -- impedisce il ciclo location-FK/claim tra RPC concorrenti.
  perform 1 from public.locations l
   where l.id=p_location and l.is_active
   order by l.id for update;
  if not found then
    raise exception using errcode='P0001', message='LOCATION_NOT_ACTIVE';
  end if;
  insert into combat_gate_private.location_claims(
    location_id,claimant_kind,claimant_session_id,origin
  ) values (p_location,p_kind,p_session,p_origin)
  returning claim_id into v_claim;
  return v_claim;
exception when unique_violation then
  if p_kind='v1' then
    raise exception using errcode='P0001', message='Qui c''è già uno scontro aperto: entra in quello.';
  end if;
  raise exception using errcode='P0001', message='scontro_gia_aperto_nel_luogo';
end
$function$;

