CREATE OR REPLACE FUNCTION combat_gate_private.claim_release(p_kind text, p_session uuid, p_location uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_n integer;
begin
  perform set_config('combat_gate.release_claim','on',true);
  update combat_gate_private.location_claims
     set released_at=clock_timestamp(), release_reason=left(coalesce(nullif(btrim(p_reason),''),'terminale'),200)
   where location_id=p_location and claimant_kind=p_kind
     and claimant_session_id=p_session and released_at is null;
  get diagnostics v_n=row_count;
  perform set_config('combat_gate.release_claim','off',true);
  if v_n<>1 then
    raise exception using errcode='P0001', message='CLAIM_MISSING_FAIL_CLOSED';
  end if;
end
$function$;

