CREATE OR REPLACE FUNCTION combat_gate_private.claims_append_only_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op='TRUNCATE' or tg_op='DELETE' then
    raise exception using errcode='55000', message='CLAIM_HISTORY_APPEND_ONLY';
  end if;
  if current_setting('combat_gate.release_claim',true) is distinct from 'on'
     or old.released_at is not null
     or new.released_at is null
     or new.location_id is distinct from old.location_id
     or new.claimant_kind is distinct from old.claimant_kind
     or new.claimant_session_id is distinct from old.claimant_session_id
     or new.acquired_at is distinct from old.acquired_at
     or new.origin is distinct from old.origin
     or new.claim_id is distinct from old.claim_id
     or new.release_reason is null
     or btrim(new.release_reason)='' then
    raise exception using errcode='55000', message='CLAIM_HISTORY_APPEND_ONLY';
  end if;
  return new;
end
$function$;

