-- Native source combat_gate_private.master_claim_trigger() MD5 9813c9aa62b7e0ab16e8ec5d4f4ae309

CREATE OR REPLACE FUNCTION combat_gate_private.master_claim_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if combat_consumer_private.master_uses_ordinary_claim(new,case when tg_op='UPDATE' then old else null::public.master_v2_sessions end,tg_op) then return new; end if;
  if tg_op='INSERT' then
    if new.stato not in ('chiusa','annullata') then
      perform combat_gate_private.claim_acquire('master_v2',new.id,new.location_id,'trigger');
    end if;
    return new;
  end if;
  if new.location_id is distinct from old.location_id then
    raise exception using errcode='P0001', message='SESSION_LOCATION_IMMUTABLE';
  end if;
  if old.stato in ('chiusa','annullata') and new.stato not in ('chiusa','annullata') then
    raise exception using errcode='P0001', message='SESSION_REOPEN_FORBIDDEN';
  end if;
  if old.stato not in ('chiusa','annullata') and new.stato in ('chiusa','annullata') then
    perform combat_gate_private.claim_release('master_v2',old.id,old.location_id,'master_'||new.stato);
  end if;
  return new;
end
$function$;

