-- Native source combat_gate_private.v2_claim_trigger() MD5 d1d386dc90cceb83d49ab2b24b97876e

CREATE OR REPLACE FUNCTION combat_gate_private.v2_claim_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op='INSERT' then
    if new.state not in ('chiuso','annullato') then
      if new.source_kind='master' then
        perform combat_gate_private.master_claim_assert(new.master_session_id,new.location_id);
      else
        perform combat_gate_private.claim_acquire('combat_v2_ordinary',new.id,new.location_id,'trigger');
      end if;
    end if;
    return new;
  end if;
  if new.location_id is distinct from old.location_id
     or new.source_kind is distinct from old.source_kind
     or new.master_session_id is distinct from old.master_session_id then
    raise exception using errcode='P0001', message='SESSION_IDENTITY_IMMUTABLE';
  end if;
  if old.state in ('chiuso','annullato') and new.state not in ('chiuso','annullato') then
    raise exception using errcode='P0001', message='SESSION_REOPEN_FORBIDDEN';
  end if;
  if old.source_kind='ordinary'
     and old.state not in ('chiuso','annullato') and new.state in ('chiuso','annullato') then
    perform combat_gate_private.claim_release('combat_v2_ordinary',old.id,old.location_id,'v2_'||new.state);
  end if;
  return new;
end
$function$;

