CREATE OR REPLACE FUNCTION combat_panel_private.actor_distance(p_left uuid, p_right uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE sid uuid; iid uuid; distance numeric;
BEGIN
 SELECT a.session_id INTO sid FROM public.combat_v2_actors a
   JOIN public.combat_v2_actors b ON b.session_id=a.session_id AND b.id=p_right WHERE a.id=p_left;
 IF sid IS NULL THEN RAISE EXCEPTION 'panel_geometry_actor_scope_invalid' USING ERRCODE='22023'; END IF;
 IF NOT combat_panel_private.has_master_geometry(sid) THEN
   RAISE EXCEPTION 'panel_master_geometry_required' USING ERRCODE='22023'; END IF;
 SELECT instance_id INTO STRICT iid FROM combat_spatial.arena_instances WHERE encounter_id=sid AND state='open';
 SELECT combat_spatial.distance_m(a.x_m,a.y_m,b.x_m,b.y_m) INTO distance
   FROM combat_spatial.actor_states a JOIN combat_spatial.actor_states b ON b.instance_id=a.instance_id
   WHERE a.instance_id=iid AND a.actor_id=p_left AND b.actor_id=p_right AND a.state='active' AND b.state='active';
 IF distance IS NULL THEN RAISE EXCEPTION 'panel_geometry_body_missing' USING ERRCODE='22023'; END IF;
 RETURN distance;
END $function$;

