   JOIN combat_spatial.arena_instances i ON i.instance_id=b.instance_id AND i.encounter_id=sid AND i.state='open'
   WHERE b.actor_id=coverage.protected_actor_id AND b.state='active';
 IF NOT FOUND THEN RAISE EXCEPTION 'panel_coverage_geometry_missing' USING ERRCODE='22023'; END IF;
