-- Native source combat_panel_private.close_master_activity(uuid,text,text,boolean,bigint,uuid) MD5 a1ff099a86407f09b3f0e6d73eccd5b4

CREATE OR REPLACE FUNCTION combat_panel_private.close_master_activity(p_master uuid, p_outcome text, p_note text, p_close_role boolean, p_version bigint, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions%ROWTYPE; protected boolean; remaining integer; step integer; result jsonb;
BEGIN
 PERFORM public.master_v2_lock_scope(p_master);
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_master FOR UPDATE;
 IF auth.uid() IS NULL OR (m.master_user IS DISTINCT FROM auth.uid() AND NOT public.combat_v2_is_admin(auth.uid())) THEN
   RAISE EXCEPTION 'panel_master_authority_required' USING ERRCODE='42501'; END IF;
 IF m.control_version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'panel_context_stale' USING ERRCODE='40001'; END IF;
 SELECT is_test INTO STRICT protected FROM public.locations WHERE id=m.location_id AND is_active;
 IF protected AND (coalesce(p_close_role,false) OR m.mission_id IS NOT NULL OR EXISTS(
   SELECT 1 FROM public.mission_run_state WHERE master_session_id=m.id)) THEN
   RAISE EXCEPTION 'panel_test_persistent_closure_unavailable' USING ERRCODE='42501'; END IF;
 SELECT count(*) INTO remaining FROM public.master_v2_closure_steps WHERE session_id=m.id AND state<>'completato';
 FOR step IN 1..remaining+1 LOOP
   result:=public.master_v2_close(m.id,p_outcome,p_note,coalesce(p_close_role,false),p_version,p_request);
   IF EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE id=m.id AND stato='chiusa' AND closed_at IS NOT NULL)
     AND NOT EXISTS(SELECT 1 FROM public.master_v2_closure_steps WHERE session_id=m.id AND state<>'completato') THEN
     RETURN result;
   END IF;
   IF result#>>'{data,next_retry_same_key}' IS DISTINCT FROM 'true' THEN EXIT; END IF;
 END LOOP;
 RAISE EXCEPTION 'panel_activity_closure_incomplete' USING ERRCODE='40001';
END $function$;

