   IF payload ? 'movement_capability_id' THEN
     IF capability IS NOT NULL THEN RAISE EXCEPTION 'panel_movement_selection_conflict' USING ERRCODE='22023'; END IF;
     capability:=(payload->>'movement_capability_id')::uuid;
   END IF;
 END LOOP;
 operation:=o.source_payload->>'companion_operation';
 IF operation='bind' AND capability IS NULL AND cardinality(selected)=0 THEN
   result:=combat_panel_private.master_companion_bind(a.id,(o.source_payload->>'source_id')::uuid,o.source_payload->'placement');
   IF result->'main_cost' IS DISTINCT FROM '0'::jsonb OR result->'values_written' IS DISTINCT FROM 'false'::jsonb THEN
     RAISE EXCEPTION 'panel_companion_bind_result_invalid' USING ERRCODE='22023'; END IF;
 ELSIF operation='move' AND capability IS NOT NULL THEN
   result:=clan_marionettisti_private.companion_movement_commit(a.id,capability,key,o.id);
 ELSIF operation='relink' AND capability IS NULL AND cardinality(selected)=0 THEN
   result:=public.clan_marionettisti_control_v1((o.source_payload->>'relink_offer_id')::uuid,key);
   IF result->'main_cost' IS DISTINCT FROM '0'::jsonb OR jsonb_typeof(result->'simulated') IS DISTINCT FROM 'boolean' THEN
     RAISE EXCEPTION 'panel_companion_relink_result_invalid' USING ERRCODE='22023'; END IF;
   written:=NOT (result->>'simulated')::boolean;
 ELSE RAISE EXCEPTION 'panel_companion_operation_invalid' USING ERRCODE='22023'; END IF;
 SELECT value->>'display_name' INTO label FROM jsonb_array_elements(env->'actors') WHERE value->>'actor_id'=a.id::text;
 event:=jsonb_build_object('event_id',event_id,'event_kind','control_changed','actor_id',a.id,'display_name',label,
   'label_version',c.context_version,'target_actor_id',NULL,'target_display_name',NULL,'target_label_version',NULL,
   'summary',CASE operation WHEN 'bind' THEN 'Marionetta collegata alla scena.' WHEN 'move' THEN 'Marionetta spostata di '||round((result->>'d_eff_m')::numeric,0)::text||' m.' ELSE 'Fili di Chakra riallacciati.' END);
 env:=combat_panel_private.master_projection(c.location_id,a.id);
 receipt:=jsonb_build_object('receipt_id',event_id,'request_key',key,'operation','control','replayed',false,
   'activity_id',c.activity_id,'round_id',c.round_id,'context_version_before',o.context_version,
   'context_version_after',env#>'{context,version}','declaration_id',NULL,'report_id',NULL,
   'values_written',written,'display_events',jsonb_build_array(event));
 env:=jsonb_set(env,'{receipt}',receipt);
 UPDATE combat_panel_private.offers SET state='consumed',consumed_request_key=key WHERE id=o.id;
 INSERT INTO combat_panel_private.request_receipts(principal_user,request_key,command_fingerprint,offer_id,event_id,viewer_envelope)
   VALUES(uid,key,fp,o.id,event_id,env);
 RETURN env;
END $function$;

