-- Native source combat_panel_private.commit_master_open(jsonb) MD5 4fd28bd6ca5dfe2998de1b7bff683340

CREATE OR REPLACE FUNCTION combat_panel_private.commit_master_open(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p jsonb; uid uuid:=auth.uid(); request_id uuid; fingerprint text; result jsonb; env jsonb; resolved jsonb;
 previous combat_panel_private.request_receipts%ROWTYPE; o combat_panel_private.offers%ROWTYPE;
 c combat_panel_private.contexts%ROWTYPE; selected uuid[]; payload jsonb; mission_id uuid; quest_kind text;
 title text; session_type text; master_id uuid; event_id uuid:=gen_random_uuid(); receipt jsonb;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000'; END IF;
 p:=combat_panel_private.validate_command(p_command); request_id:=(p->>'request_key')::uuid; fingerprint:=public.combat_v2_sha256(p);
 PERFORM pg_advisory_xact_lock(hashtextextended('panel-request:'||uid::text||':'||request_id::text,731));
 SELECT * INTO previous FROM combat_panel_private.request_receipts WHERE principal_user=uid AND request_key=request_id;
 IF previous.request_key IS NOT NULL THEN
   IF previous.command_fingerprint<>fingerprint THEN RAISE EXCEPTION 'panel_request_key_conflict' USING ERRCODE='22023'; END IF;
   RETURN jsonb_set(previous.viewer_envelope,'{receipt,replayed}','true',false);
 END IF;
 SELECT * INTO o FROM combat_panel_private.offers WHERE id=(p->>'offer_id')::uuid AND principal_user=uid
   AND kind='administration' AND operation='open' AND source_payload->>'dispatch'='master_session_open'
   AND source_payload->>'adapter' IN ('ordinary_v2','master_v2');
 IF o.id IS NULL THEN RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE id=o.context_id AND principal_user=uid;
 IF c.location_id IS DISTINCT FROM (p->>'location_id')::uuid OR c.activity_id IS NOT NULL OR c.round_id IS NOT NULL
   OR p->>'activity_id' IS NOT NULL THEN RAISE EXCEPTION 'panel_activity_scope_invalid' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.locations WHERE id=c.location_id FOR UPDATE;
 IF NOT combat_panel_private.master_open_available(c.location_id) THEN
   RAISE EXCEPTION 'panel_master_open_unavailable' USING ERRCODE='40001'; END IF;
 IF combat_panel_private.location_adapter(c.location_id) IS DISTINCT FROM o.source_payload->>'adapter' THEN
   RAISE EXCEPTION 'panel_context_stale' USING ERRCODE='40001'; END IF;
 env:=CASE o.source_payload->>'adapter' WHEN 'master_v2' THEN combat_panel_private.master_projection(c.location_id,c.command_actor_id)
   ELSE combat_panel_private.ordinary_projection(c.location_id,c.command_actor_id) END;
 PERFORM 1 FROM combat_panel_private.contexts WHERE id=c.id FOR UPDATE;
 c:=combat_panel_private.owned_context(c.id,(p->>'context_version')::bigint);
 SELECT * INTO STRICT o FROM combat_panel_private.offers WHERE id=o.id FOR UPDATE;
 IF o.state<>'offered' OR o.context_version<>c.context_version OR o.source_fingerprint IS DISTINCT FROM c.source_fingerprint
   OR o.scene_version IS DISTINCT FROM c.scene_version OR o.source_payload->>'policy_id' IS DISTINCT FROM combat_panel_private.master_entry_policy(c.location_id) THEN
   RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='40001'; END IF;
 SELECT coalesce(array_agg(value::uuid),'{}') INTO selected FROM jsonb_array_elements_text(p->'selected_option_ids');
 resolved:=combat_panel_private.resolve_selections(o.id,selected,p->'inputs');
 FOR payload IN SELECT choice->'payload' FROM jsonb_array_elements(resolved->'groups') groups(g)
   CROSS JOIN LATERAL jsonb_array_elements(g->'options') choices(choice) LOOP
   IF payload ? 'mission_id' THEN
     IF mission_id IS NOT NULL THEN RAISE EXCEPTION 'panel_mission_selection_conflict' USING ERRCODE='22023'; END IF;
     mission_id:=(payload->>'mission_id')::uuid;
   ELSIF payload ? 'quest_kind' THEN
     IF quest_kind IS NOT NULL THEN RAISE EXCEPTION 'panel_quest_selection_conflict' USING ERRCODE='22023'; END IF;
     quest_kind:=payload->>'quest_kind';
   ELSE RAISE EXCEPTION 'panel_open_selection_invalid' USING ERRCODE='22023'; END IF;
 END LOOP;
 title:=resolved#>>'{inputs,title}'; session_type:=o.source_payload->>'session_type';
 IF coalesce((o.source_payload->>'mission_required')::boolean,false) THEN
   IF mission_id IS NULL OR quest_kind IS NOT NULL OR o.source_payload->>'policy_id'<>'master_game_resources_v1' THEN
     RAISE EXCEPTION 'panel_mission_selection_invalid' USING ERRCODE='22023'; END IF;
   SELECT m.title INTO title FROM public.missions m WHERE m.id=mission_id AND m.status IN ('aperta','programmata');
   IF title IS NULL THEN RAISE EXCEPTION 'panel_mission_changed' USING ERRCODE='40001'; END IF;
 ELSIF mission_id IS NOT NULL THEN RAISE EXCEPTION 'panel_mission_not_offered' USING ERRCODE='22023'; END IF;
 result:=public.master_v2_session_open(c.location_id,session_type,mission_id,title,request_id,quest_kind);
 master_id:=(result#>>'{data,master_session_id}')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.master_v2_sessions m JOIN combat_panel_private.master_panel_sessions registered
   ON registered.master_session_id=m.id WHERE m.id=master_id AND m.location_id=c.location_id AND m.master_user=uid
   AND m.owner_kind='human' AND m.stato='preparazione' AND registered.policy_id=o.source_payload->>'policy_id') THEN
   RAISE EXCEPTION 'panel_master_open_result_invalid' USING ERRCODE='22023'; END IF;
 env:=combat_panel_private.master_projection(c.location_id,NULL);
 receipt:=jsonb_build_object('receipt_id',event_id,'request_key',request_id,'operation','open','replayed',false,
   'activity_id',master_id,'round_id',NULL,'context_version_before',o.context_version,
   'context_version_after',env#>'{context,version}','declaration_id',NULL,'report_id',NULL,
   'values_written',false,'display_events','[]'::jsonb);
 env:=jsonb_set(env,'{receipt}',receipt);
 UPDATE combat_panel_private.offers SET state='consumed',consumed_request_key=request_id WHERE id=o.id;
 INSERT INTO combat_panel_private.request_receipts(principal_user,request_key,command_fingerprint,offer_id,event_id,viewer_envelope)
   VALUES(uid,request_id,fingerprint,o.id,event_id,env);
 RETURN env;
END $function$;

