 SELECT * INTO prior FROM combat_panel_private.request_receipts WHERE principal_user=uid AND request_key=key;
 IF prior.request_key IS NOT NULL THEN
   IF prior.command_fingerprint<>fp THEN
     RAISE EXCEPTION 'panel_request_key_conflict' USING ERRCODE='22023'; END IF;
   RETURN jsonb_set(prior.viewer_envelope,'{receipt,replayed}','true',false);
 END IF;
 SELECT * INTO o FROM combat_panel_private.offers WHERE id=(p->>'offer_id')::uuid AND principal_user=uid;
 IF o.id IS NULL OR o.source_payload->>'adapter' IS DISTINCT FROM 'ordinary_v2' THEN
   RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE id=o.context_id AND principal_user=uid;
 IF c.location_id IS DISTINCT FROM (p->>'location_id')::uuid
   OR c.activity_id IS DISTINCT FROM (p->>'activity_id')::uuid THEN
   RAISE EXCEPTION 'panel_activity_scope_invalid' USING ERRCODE='22023'; END IF;
 -- Il lock del motore precede quello del POV, come ordinary_options.
 IF c.round_id IS NOT NULL THEN PERFORM public.combat_v2_lock_round(c.round_id);
 ELSE PERFORM 1 FROM public.locations WHERE id=c.location_id FOR UPDATE; END IF;
 env:=combat_panel_private.ordinary_projection(c.location_id,c.command_actor_id);
 IF env->>'status' IS DISTINCT FROM 'ready' THEN
   RAISE EXCEPTION 'panel_source_not_ready' USING ERRCODE='40001'; END IF;
 PERFORM 1 FROM combat_panel_private.contexts WHERE id=c.id FOR UPDATE;
 c:=combat_panel_private.owned_context(c.id,(p->>'context_version')::bigint);
 SELECT * INTO STRICT o FROM combat_panel_private.offers WHERE id=o.id FOR UPDATE;
 IF o.state<>'offered' OR o.context_version<>c.context_version
   OR o.source_fingerprint IS DISTINCT FROM c.source_fingerprint
   OR o.scene_version IS DISTINCT FROM c.scene_version THEN
   RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='40001'; END IF;
 IF o.requires_role AND length(btrim(p->>'narrative_text'))=0 THEN
   RAISE EXCEPTION 'panel_role_required' USING ERRCODE='22023'; END IF;
 IF o.kind='control' AND length(btrim(p->>'narrative_text'))<>0 THEN
   RAISE EXCEPTION 'panel_control_has_no_role' USING ERRCODE='22023'; END IF;
 SELECT coalesce(array_agg((value#>>'{}')::uuid),'{}'::uuid[]) INTO selected
   FROM jsonb_array_elements(p->'selected_option_ids');
 resolved:=combat_panel_private.resolve_selections(o.id,selected,p->'inputs');
 IF resolved->'inputs'<>'{}'::jsonb THEN
   RAISE EXCEPTION 'panel_ordinary_input_not_supported' USING ERRCODE='22023'; END IF;
 source_offer:=(o.source_payload->>'source_offer_id')::uuid;
 FOR payload IN SELECT choice->'payload' FROM jsonb_array_elements(resolved->'groups') AS groups(g)
   CROSS JOIN LATERAL jsonb_array_elements(g->'options') AS choices(choice) LOOP
   IF payload ? 'multiplication_random_sources' THEN
    IF random_payload IS NOT NULL THEN RAISE EXCEPTION 'panel_source_selection_conflict' USING ERRCODE='22023'; END IF;
    random_payload:=payload->'multiplication_random_sources';
   END IF;
   IF payload ? 'source_offer_id' THEN
     source_choice_count:=source_choice_count+1;
     IF source_offer IS NOT NULL OR source_choice_count>1 THEN
       RAISE EXCEPTION 'panel_source_selection_conflict' USING ERRCODE='22023'; END IF;
     source_offer:=(payload->>'source_offer_id')::uuid;
   END IF;
   IF payload ? 'movement_offer_id' THEN
     movement_count:=movement_count+1;
     IF movement_count>1 THEN RAISE EXCEPTION 'panel_movement_selection_conflict' USING ERRCODE='22023'; END IF;
     source_move:=(payload->>'movement_offer_id')::uuid;
   END IF;
 END LOOP;
 IF random_payload IS NOT NULL THEN
  IF source_offer IS NOT NULL OR source_move IS NOT NULL OR o.operation<>'declare'
   OR o.source_payload->>'dispatch' NOT IN ('multiplication_ordinary_attack','multiplication_companion_attack') THEN
   RAISE EXCEPTION 'panel_source_selection_conflict' USING ERRCODE='22023'; END IF;
  drawn:=combat_panel_private.multiplication_choose_ordinary_source(c.id,c.context_version,random_payload,key);
  source_offer:=(drawn->>'source_offer_id')::uuid;source_move:=(drawn->>'movement_offer_id')::uuid;
 END IF;
 IF source_offer IS NULL THEN RAISE EXCEPTION 'panel_source_selection_required' USING ERRCODE='22023'; END IF;
 source_command:=jsonb_build_object('schema_version','combat-consumer-command/1',
   'operation',o.operation,'location_id',c.location_id,'activity_id',o.source_payload->'source_activity_id',
   'exchange_id',o.source_payload->'source_exchange_id','context_version',o.source_payload->'source_context_version',
   'offer_id',source_offer,'movement_offer_id',source_move,'request_key',key,'narrative_text',p->'narrative_text');
 IF o.operation='defend' THEN
   SELECT (source_payload->>'attack_id')::uuid INTO defense_parent FROM combat_consumer_private.offers
     WHERE id=source_offer AND session_id=c.activity_id AND exchange_id=c.round_id AND operation='defend';
   PERFORM combat_panel_private.multiplication_register_defense_selections(c.round_id,c.command_actor_id,key,resolved,NULL,defense_parent);
 END IF;
 src:=combat_panel_private.consumer_commit_authoritative(source_command);
 IF jsonb_typeof(src->'receipt') IS DISTINCT FROM 'object'
   OR src#>>'{receipt,request_key}' IS DISTINCT FROM key::text
   OR src#>>'{receipt,operation}' IS DISTINCT FROM o.operation THEN
   RAISE EXCEPTION 'panel_source_receipt_invalid'; END IF;
 -- La chiusura restituisce la propria vista finale; non rileggerla come
 -- un nuovo invito. Il payload meccanico non passa al browser.
 env:=combat_panel_private.normalize_ordinary(c.location_id,NULL,src);
 receipt:=jsonb_build_object('receipt_id',src#>'{receipt,receipt_id}',
   'request_key',key,'operation',o.operation,'replayed',false,
   'activity_id',src#>'{receipt,activity_id}','round_id',src#>'{receipt,exchange_id}',
   'context_version_before',o.context_version,'context_version_after',env#>'{context,version}',
   'declaration_id',src#>'{receipt,declaration_id}','report_id',src#>'{receipt,report_id}',
   'values_written',src#>'{receipt,values_written}','display_events',src#>'{receipt,display_events}');
 env:=jsonb_set(env,'{receipt}',receipt);
 UPDATE combat_panel_private.offers SET state='consumed',consumed_request_key=key WHERE id=o.id;
 INSERT INTO combat_panel_private.request_receipts(principal_user,request_key,command_fingerprint,offer_id,event_id,viewer_envelope)
   VALUES(uid,key,fp,o.id,(src#>>'{receipt,receipt_id}')::uuid,env);
 RETURN env;
END $function$;

