-- Native source combat_panel_private.consumer_state_authoritative(uuid) MD5 d5dfe1b216f579de3ba0de02b3a63190

CREATE OR REPLACE FUNCTION combat_panel_private.consumer_state_authoritative(p_location uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); cid uuid; envelope jsonb; entry_allowed boolean:=false;
begin
  envelope:=combat_consumer_private.state_projection(p_location);
  select id into cid from public.characters where user_id=uid;
  if envelope->>'status'='ready' and uid is not null and cid is not null then
    entry_allowed:=coalesce(public._combat_presente(uid,p_location),false)
      and exists(select 1 from public.locations where id=p_location and is_active
        and (not coalesce(is_test,false) or public._puo_test_room()));
  end if;
  return envelope||jsonb_build_object('entry',jsonb_build_object(
    'allowed',coalesce(entry_allowed,false),'principal_id',uid,
    'character_id',cid,'location_id',p_location));
end $function$;

