CREATE OR REPLACE FUNCTION combat_panel_private.coverage_geometry_valid(p_coverage uuid, p_defender uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE frozen combat_panel_private.coverage_geometry%ROWTYPE; coverage public.combat_v2_defense_coverages%ROWTYPE;
 protected combat_spatial.actor_states%ROWTYPE; sid uuid;
BEGIN
 SELECT * INTO STRICT coverage FROM public.combat_v2_defense_coverages WHERE id=p_coverage;
 SELECT session_id INTO STRICT sid FROM public.combat_v2_rounds WHERE id=coverage.round_id;
 SELECT * INTO frozen FROM combat_panel_private.coverage_geometry WHERE coverage_id=coverage.id;
 IF frozen.coverage_id IS NULL OR frozen.protected_actor_id<>coverage.protected_actor_id
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE id=coverage.defense_declaration_id
     AND actor_id=p_defender AND round_id=coverage.round_id) THEN RETURN false; END IF;
 SELECT b.* INTO protected FROM combat_spatial.actor_states b JOIN combat_spatial.arena_instances i
   ON i.instance_id=b.instance_id AND i.encounter_id=sid AND i.state='open'
   WHERE b.instance_id=frozen.instance_id AND b.actor_id=frozen.protected_actor_id AND b.state='active';
 IF protected.actor_id IS NULL OR (protected.x_m,protected.y_m) IS DISTINCT FROM (frozen.protected_x_m,frozen.protected_y_m) THEN RETURN false; END IF;
 RETURN combat_panel_private.actor_distance(p_defender,protected.actor_id)<=2;
END $function$;

