CREATE OR REPLACE FUNCTION combat_panel_private.create_offer(p_context uuid, p_expected bigint, p_kind text, p_operation text, p_label text, p_requires_role boolean, p_source jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_panel_private.contexts%ROWTYPE; oid uuid;
BEGIN
 PERFORM 1 FROM combat_panel_private.contexts WHERE id=p_context FOR UPDATE;
 c:=combat_panel_private.owned_context(p_context,p_expected);
 INSERT INTO combat_panel_private.offers(context_id,principal_user,actor_id,context_version,scene_version,
   source_fingerprint,kind,operation,label,requires_role,source_payload)
  VALUES(c.id,c.principal_user,CASE WHEN p_kind='administration' THEN NULL ELSE c.command_actor_id END,
    c.context_version,c.scene_version,c.source_fingerprint,p_kind,p_operation,p_label,p_requires_role,p_source)
  RETURNING id INTO oid;
 RETURN oid;
END $function$;

