-- Native source combat_panel_private.immobilization_apply_from_attack(uuid) MD5 9e1051a8a3f5be6c691a7c667efa2b3a

CREATE OR REPLACE FUNCTION combat_panel_private.immobilization_apply_from_attack(p_attack_target uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.combat_v2_attack_targets%ROWTYPE; d public.combat_v2_declarations%ROWTYPE;
 a public.combat_v2_actors%ROWTYPE; r public.combat_v2_rounds%ROWTYPE; result uuid; pool numeric;
BEGIN
 SELECT * INTO STRICT t FROM public.combat_v2_attack_targets WHERE id=p_attack_target;
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=t.attack_declaration_id;
 -- Nessuna tecnica acquisisce una presa solo per il nome o una descrizione.
 IF NOT EXISTS(SELECT 1 FROM combat_panel_private.immobilization_profiles p
   WHERE p.ability_source=d.sanitized_intent->>'ability_source'
     AND p.ability_id::text=d.sanitized_intent->>'ability_id' AND p.reviewed AND p.is_active) THEN RETURN NULL; END IF;
 IF t.state<>'risolta' OR jsonb_typeof(t.outcome->'success') IS DISTINCT FROM 'boolean'
   OR NOT (t.outcome->>'success')::boolean THEN RETURN NULL; END IF;
 SELECT * INTO STRICT r FROM public.combat_v2_rounds WHERE id=t.round_id;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=r.session_id AND state='in_corso' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'immobilization_session_invalid' USING ERRCODE='40001'; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=t.target_actor_id AND session_id=r.session_id FOR UPDATE;
 IF a.actor_kind<>'pg' OR a.companion_id IS NOT NULL OR a.state<>'attivo' THEN RETURN NULL; END IF;
 IF d.round_id<>t.round_id OR d.kind<>'attacco' OR d.actor_id=a.id
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_actors WHERE id=d.actor_id AND session_id=r.session_id)
   OR jsonb_typeof(t.outcome#>'{raw,pool_att}') IS DISTINCT FROM 'number' THEN
   RAISE EXCEPTION 'immobilization_source_invalid' USING ERRCODE='22023'; END IF;
 pool:=(t.outcome#>>'{raw,pool_att}')::numeric;
 IF pool<0 OR pool IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
   RAISE EXCEPTION 'immobilization_source_pool_invalid' USING ERRCODE='22023'; END IF;
 SELECT id INTO result FROM combat_panel_private.immobilizations WHERE source_attack_target_id=t.id;
 IF result IS NOT NULL THEN RETURN result; END IF;
 INSERT INTO combat_panel_private.immobilizations(session_id,source_attack_target_id,source_declaration_id,
   source_actor_id,target_actor_id,applied_round_id,source_pool)
 VALUES(r.session_id,t.id,d.id,d.actor_id,a.id,r.id,pool) RETURNING id INTO result;
 RETURN result;
END $function$;

