-- Native source combat_panel_private.immobilization_escape_result(numeric,numeric,numeric,integer[]) MD5 9e813e0c58b7e220728c88587c0d9ea8

CREATE OR REPLACE FUNCTION combat_panel_private.immobilization_escape_result(p_strength numeric, p_taijutsu numeric, p_source_pool numeric, p_dice integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE pool numeric; escape_total numeric; hold_total numeric;
BEGIN
 IF p_strength IS NULL OR p_taijutsu IS NULL OR p_source_pool IS NULL
   OR least(p_strength,p_taijutsu,p_source_pool)<0
   OR p_strength IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
   OR p_taijutsu IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
   OR p_source_pool IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
   OR p_dice IS NULL OR array_ndims(p_dice) IS DISTINCT FROM 1
   OR array_lower(p_dice,1) IS DISTINCT FROM 1 OR array_upper(p_dice,1) IS DISTINCT FROM 4
   OR EXISTS(SELECT 1 FROM unnest(p_dice) d WHERE d IS NULL OR d NOT BETWEEN 1 AND 10) THEN
   RAISE EXCEPTION 'immobilization_escape_values_invalid' USING ERRCODE='22023';
 END IF;
 pool:=p_strength+p_taijutsu;
 escape_total:=floor(pool/5)+p_dice[1]+p_dice[2];
 hold_total:=floor(p_source_pool/5)+p_dice[3]+p_dice[4];
 RETURN jsonb_build_object('schema_version','immobilization-escape/1','escape_pool',pool,
   'source_pool',p_source_pool,'escape_dice',jsonb_build_array(p_dice[1],p_dice[2]),
   'hold_dice',jsonb_build_array(p_dice[3],p_dice[4]),'escape_total',escape_total,
   'hold_total',hold_total,'margin',escape_total-hold_total,'success',escape_total>hold_total,
   'main_cost',1,'chakra_cost',0);
END $function$;

