-- Native source combat_panel_private.immobilization_prepare_escape(uuid,uuid,uuid,uuid) MD5 ef665dedd6e3e320efdefe59144e4e0d

CREATE OR REPLACE FUNCTION combat_panel_private.immobilization_prepare_escape(p_round uuid, p_actor uuid, p_effect uuid, p_request uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; r public.combat_v2_rounds%ROWTYPE;
 e combat_panel_private.immobilizations%ROWTYPE; old_plan combat_panel_private.immobilization_escape_plans%ROWTYPE;
 result uuid; strength numeric; taijutsu numeric;
BEGIN
 IF auth.uid() IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'immobilization_escape_auth_required' USING ERRCODE='42501'; END IF;
 PERFORM public.combat_v2_lock_round(p_round);
 SELECT * INTO STRICT r FROM public.combat_v2_rounds WHERE id=p_round FOR UPDATE;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor AND session_id=r.session_id FOR UPDATE;
 IF a.actor_kind<>'pg' OR a.companion_id IS NOT NULL OR a.controller_user IS DISTINCT FROM auth.uid() THEN
   RAISE EXCEPTION 'immobilization_escape_actor_not_controlled' USING ERRCODE='42501'; END IF;
 IF a.state<>'attivo' OR r.phase<>'raccolta_azioni'
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=r.session_id AND state='in_corso') THEN
   RAISE EXCEPTION 'immobilization_escape_phase_invalid' USING ERRCODE='40001'; END IF;
 IF NOT (combat_panel_private.has_master_geometry(r.session_id) OR EXISTS(
   SELECT 1 FROM combat_consumer_private.activities WHERE session_id=r.session_id AND exchange_id=r.id)) THEN
   RAISE EXCEPTION 'immobilization_escape_scope_invalid' USING ERRCODE='22023'; END IF;
 SELECT * INTO old_plan FROM combat_panel_private.immobilization_escape_plans WHERE round_id=p_round AND actor_id=p_actor;
 IF old_plan.id IS NOT NULL THEN
   IF old_plan.request_key=p_request AND old_plan.effect_id=p_effect
     AND old_plan.controller_user=auth.uid() AND old_plan.controller_version=a.controller_version THEN RETURN old_plan.id; END IF;
   RAISE EXCEPTION 'immobilization_escape_already_declared' USING ERRCODE='40001'; END IF;
 IF EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=p_round AND actor_id=p_actor
   AND kind IN ('attacco','movimento','utilita','passa')) THEN
   RAISE EXCEPTION 'immobilization_escape_main_spent' USING ERRCODE='40001'; END IF;
 SELECT * INTO STRICT e FROM combat_panel_private.immobilizations WHERE id=p_effect AND target_actor_id=p_actor AND session_id=r.session_id FOR UPDATE;
 IF e.state<>'active' OR NOT combat_panel_private.immobilization_active(p_actor) THEN
   RAISE EXCEPTION 'immobilization_escape_effect_stale' USING ERRCODE='40001'; END IF;
 IF jsonb_typeof(a.mechanics_snapshot->'forza') IS DISTINCT FROM 'number'
   OR jsonb_typeof(a.mechanics_snapshot->'taijutsu') IS DISTINCT FROM 'number' THEN
   RAISE EXCEPTION 'immobilization_escape_snapshot_invalid' USING ERRCODE='22023'; END IF;
 strength:=(a.mechanics_snapshot->>'forza')::numeric; taijutsu:=(a.mechanics_snapshot->>'taijutsu')::numeric;
 -- Validazione condivisa senza generare dadi: questi valori non sono un tiro.
 PERFORM combat_panel_private.immobilization_escape_result(strength,taijutsu,e.source_pool,ARRAY[1,1,1,1]);
 INSERT INTO combat_panel_private.immobilization_escape_plans(session_id,round_id,actor_id,effect_id,request_key,
   controller_user,controller_version,strength,taijutsu)
 VALUES(r.session_id,r.id,a.id,e.id,p_request,auth.uid(),a.controller_version,strength,taijutsu) RETURNING id INTO result;
 RETURN result;
END $function$;

