   RAISE EXCEPTION 'immobilization_release_reason_invalid' USING ERRCODE='22023'; END IF;
 SELECT r.session_id INTO STRICT session_id FROM public.combat_v2_declarations d JOIN public.combat_v2_rounds r ON r.id=d.round_id WHERE d.id=p_declaration;
