 UPDATE combat_panel_private.immobilizations SET state='released',release_reason=p_reason,released_at=clock_timestamp()
   WHERE source_declaration_id=p_declaration AND state='active';
 GET DIAGNOSTICS changed=ROW_COUNT;
 RETURN changed;
END $function$;

