 SET search_path TO ''
AS $function$
DECLARE plan combat_panel_private.immobilization_escape_plans%ROWTYPE; d public.combat_v2_declarations%ROWTYPE;
 e combat_panel_private.immobilizations%ROWTYPE; a public.combat_v2_actors%ROWTYPE;
 escape_outcome jsonb; calc jsonb; rng jsonb; entropy bytea; context text; dice integer[]; reason text;
BEGIN
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration FOR UPDATE;
 SELECT * INTO STRICT plan FROM combat_panel_private.immobilization_escape_plans WHERE declaration_id=d.id FOR UPDATE;
 IF plan.result IS NOT NULL THEN RETURN plan.result; END IF;
 IF d.kind<>'utilita' OR d.state<>'congelata' OR d.round_id<>plan.round_id OR d.actor_id<>plan.actor_id
   OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds WHERE id=d.round_id AND session_id=plan.session_id AND phase='risoluzione')
   OR d.sanitized_intent#>>'{server_ability,immobilization_escape_version}' IS DISTINCT FROM 'immobilization-escape/1' THEN
   RAISE EXCEPTION 'immobilization_escape_resolution_invalid' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=plan.actor_id AND session_id=plan.session_id FOR UPDATE;
 SELECT * INTO STRICT e FROM combat_panel_private.immobilizations WHERE id=plan.effect_id AND target_actor_id=a.id AND session_id=plan.session_id FOR UPDATE;
 IF a.state<>'attivo' OR coalesce((a.mechanics_snapshot->>'vita')::numeric,0)<=0 THEN reason:='actor_inoperative';
 ELSIF e.state<>'active' THEN reason:='hold_already_ended'; END IF;
 IF reason IS NOT NULL THEN
   escape_outcome:=jsonb_build_object('kind','utilita','immobilization_escape',jsonb_build_object('schema_version','immobilization-escape/1',
     'attempted',false,'reason',reason,'main_cost',1,'chakra_cost',0,'refund',false));
 ELSE
   context:='combat-v2/immobilization-escape/1:'||plan.session_id::text||':'||plan.round_id::text||':'||d.id::text;
   entropy:=extensions.gen_random_bytes(32);
   dice:=ARRAY[public.combat_v2_derive_d10(entropy,context,1),public.combat_v2_derive_d10(entropy,context,2),
     public.combat_v2_derive_d10(entropy,context,3),public.combat_v2_derive_d10(entropy,context,4)];
   calc:=combat_panel_private.immobilization_escape_result(plan.strength,plan.taijutsu,e.source_pool,dice);
   rng:=combat_v2_private.rng_seal(plan.session_id,plan.round_id,d.id,'escape',context,entropy,calc);
   IF (calc->>'success')::boolean THEN
     UPDATE combat_panel_private.immobilizations SET state='released',release_reason='escaped',released_at=clock_timestamp() WHERE id=e.id AND state='active';
   END IF;
   escape_outcome:=jsonb_build_object('kind','utilita','immobilization_escape',calc||jsonb_build_object('attempted',true),
     'rng_audit',rng,'still_immobilized',combat_panel_private.immobilization_active(a.id));
 END IF;
 UPDATE combat_panel_private.immobilization_escape_plans SET result=escape_outcome,resolved_at=clock_timestamp() WHERE id=plan.id;
 RETURN escape_outcome;
END $function$;

