CREATE OR REPLACE FUNCTION combat_panel_private.immobilization_result_label(p_outcome jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE value jsonb:=p_outcome->'immobilization_escape';
BEGIN
 IF jsonb_typeof(value) IS DISTINCT FROM 'object' OR value->>'schema_version' IS DISTINCT FROM 'immobilization-escape/1' THEN RETURN ''; END IF;
 IF value->>'attempted'='false' THEN
   RETURN CASE value->>'reason' WHEN 'hold_already_ended' THEN ' · presa già terminata'
     WHEN 'actor_inoperative' THEN ' · liberazione non eseguita: personaggio fuori combattimento' ELSE '' END;
 END IF;
 IF jsonb_typeof(value->'success') IS DISTINCT FROM 'boolean' THEN RETURN ''; END IF;
 RETURN CASE WHEN (value->>'success')::boolean THEN ' · presa sciolta' ELSE ' · tentativo fallito: la presa rimane' END
   ||CASE WHEN (value->>'success')::boolean AND p_outcome->>'still_immobilized'='true' THEN ' · resta un’altra immobilizzazione' ELSE '' END;
END $function$;

