-- Native source combat_panel_private.impervious_integer_interval(numeric,numeric,numeric,numeric,text,jsonb) MD5 324d4e6db5c2ca4b8febb9352c7732e1

CREATE OR REPLACE FUNCTION combat_panel_private.impervious_integer_interval(p_x1 numeric, p_y1 numeric, p_x2 numeric, p_y2 numeric, p_kind text, p_shape jsonb)
 RETURNS numeric[]
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE dx numeric:=p_x2-p_x1;dy numeric:=p_y2-p_y1;distance numeric;
 origin numeric;delta numeric;minimum numeric;maximum numeric;nlo numeric;nhi numeric;den numeric;
 lo_n numeric:=0;lo_d numeric:=1;hi_n numeric;hi_d numeric:=1;
 cx numeric;cy numeric;radius numeric;a numeric;b numeric;c numeric;disc numeric;
 left_i integer;right_i integer;mid integer;first_boundary integer;last_boundary integer;
 vertex_n numeric;vertex_d numeric;q numeric;predicate boolean;
BEGIN
 -- Solo validazione della shape: nessun risultato razionale viene riusato.
 PERFORM combat_panel_private.impervious_segment_interval(p_x1,p_y1,p_x2,p_y2,p_kind,p_shape);
 IF p_x1<>round(p_x1) OR p_y1<>round(p_y1) OR p_x2<>round(p_x2) OR p_y2<>round(p_y2) THEN
  RAISE EXCEPTION 'integer_terrain_endpoint_invalid' USING ERRCODE='22023';END IF;
 distance:=abs(dx)+abs(dy);hi_n:=distance;IF distance=0 THEN RETURN NULL;END IF;
 IF distance>10000 THEN RAISE EXCEPTION 'integer_path_too_long' USING ERRCODE='22023';END IF;
 IF p_kind='aabb' THEN
  -- Frazioni esatte come coppie numeratore/denominatore: confronti tramite
  -- prodotti incrociati e quantizzazione finale con div/mod, senza divisione.
  FOR axis IN 1..2 LOOP
   origin:=CASE axis WHEN 1 THEN p_x1 ELSE p_y1 END;delta:=CASE axis WHEN 1 THEN dx ELSE dy END;
   minimum:=(p_shape->>CASE axis WHEN 1 THEN 'min_x' ELSE 'min_y' END)::numeric;
   maximum:=(p_shape->>CASE axis WHEN 1 THEN 'max_x' ELSE 'max_y' END)::numeric;
   IF delta=0 THEN IF origin<minimum OR origin>maximum THEN RETURN NULL;END IF;
   ELSE
    den:=abs(delta);
    nlo:=distance*CASE WHEN delta>0 THEN minimum-origin ELSE origin-maximum END;
    nhi:=distance*CASE WHEN delta>0 THEN maximum-origin ELSE origin-minimum END;
    IF nlo*lo_d>lo_n*den THEN lo_n:=nlo;lo_d:=den;END IF;
    IF nhi*hi_d<hi_n*den THEN hi_n:=nhi;hi_d:=den;END IF;
    IF hi_n*lo_d<=lo_n*hi_d THEN RETURN NULL;END IF;
   END IF;
  END LOOP;
  RETURN ARRAY[div(lo_n,lo_d),div(hi_n,hi_d)+CASE WHEN mod(hi_n,hi_d)=0 THEN 0 ELSE 1 END];
 END IF;
 -- Cerchio: Q(s)=a*s²+b*D*s+c*D². Si confrontano i confini
 -- interi con le radici senza calcolarle: solo polinomio e vertice razionale.
 cx:=(p_shape->>'cx')::numeric;cy:=(p_shape->>'cy')::numeric;radius:=(p_shape->>'radius')::numeric;
 a:=dx*dx+dy*dy;b:=2*((p_x1-cx)*dx+(p_y1-cy)*dy);c:=(p_x1-cx)*(p_x1-cx)+(p_y1-cy)*(p_y1-cy)-radius*radius;
 disc:=b*b-4*a*c;IF disc<=0 THEN RETURN NULL;END IF;
 vertex_n:=-b*distance;vertex_d:=2*a;
 -- Esiste interno prima di D e dopo0? Le uguaglianze alle radici sono escluse.
 q:=a*distance*distance+b*distance*distance+c*distance*distance;
 IF NOT (distance*vertex_d>=vertex_n OR q<0) THEN RETURN NULL;END IF;
 IF NOT (0<=vertex_n OR c*distance*distance<0) THEN RETURN NULL;END IF;
 left_i:=0;right_i:=distance::integer;
 WHILE left_i<right_i LOOP
  mid:=(left_i+right_i)/2;q:=a*mid::numeric*mid+b*distance*mid+c*distance*distance;
  predicate:=mid*vertex_d>=vertex_n OR q<0;
  IF predicate THEN right_i:=mid;ELSE left_i:=mid+1;END IF;
 END LOOP;
 first_boundary:=left_i;
 left_i:=0;right_i:=distance::integer;
 WHILE left_i<right_i LOOP
  mid:=(left_i+right_i+1)/2;q:=a*mid::numeric*mid+b*distance*mid+c*distance*distance;
  predicate:=mid*vertex_d<=vertex_n OR q<0;
  IF predicate THEN left_i:=mid;ELSE right_i:=mid-1;END IF;
 END LOOP;
 last_boundary:=left_i;
 RETURN ARRAY[greatest(0,first_boundary-1)::numeric,least(distance,last_boundary+1)];
END $function$;

