-- Native source combat_panel_private.impervious_map_objects(uuid,uuid) MD5 7dc2c3572fb26df7712c9775b2f3a91c

CREATE OR REPLACE FUNCTION combat_panel_private.impervious_map_objects(p_instance uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i combat_spatial.arena_instances%ROWTYPE;b combat_spatial.actor_states%ROWTYPE;result jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000'; END IF;
 SELECT * INTO STRICT i FROM combat_spatial.arena_instances WHERE instance_id=p_instance AND state='open';
 IF NOT combat_panel_private.shared_movement_scope(i.instance_id)
   OR NOT EXISTS(SELECT 1 FROM combat_spatial.viewer_grants WHERE instance_id=i.instance_id
     AND viewer_principal_id=auth.uid() AND can_view_map AND can_view_objects) THEN RETURN '[]'::jsonb; END IF;
 SELECT * INTO STRICT b FROM combat_spatial.actor_states WHERE instance_id=i.instance_id
   AND actor_id=p_actor AND controller_principal_id=auth.uid() AND state='active';
 PERFORM combat_panel_private.impervious_regions(i.instance_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object(
   'object_id',md5(i.instance_id::text||o.object_key||os.state_version)::uuid,
   'label',o.semantic_label,'state',os.state,'shape_kind',o.shape_kind,'shape',o.shape,
   'x_m',center.x,'y_m',center.y,
   'radius_m',CASE WHEN o.shape_kind='circle' THEN (o.shape->>'radius')::numeric ELSE NULL END,
   'distance_from_viewer_m',round(combat_spatial.distance_m(b.x_m,b.y_m,center.x,center.y),2),
   'substitution_anchor_available',false,'is_impervious',true) ORDER BY o.object_key),'[]'::jsonb)
 INTO result FROM combat_spatial.arena_objects o
 JOIN combat_spatial.object_states os ON os.instance_id=i.instance_id AND os.object_key=o.object_key
 CROSS JOIN LATERAL (SELECT (combat_spatial.shape_center(o.shape_kind,o.shape))[0]::numeric AS x,
   (combat_spatial.shape_center(o.shape_kind,o.shape))[1]::numeric AS y) center
 WHERE o.template_key=i.template_key AND o.template_version=i.template_version
   AND o.is_impervious AND os.state='available';
 RETURN result||combat_panel_private.instance_terrain_map_objects(i.instance_id,p_actor);
END $function$;

