-- Native source combat_panel_private.impervious_path_profile(numeric,numeric,numeric,numeric,jsonb,numeric) MD5 5bfe33d038f8dcd50e2500bc29b4f20b

CREATE OR REPLACE FUNCTION combat_panel_private.impervious_path_profile(p_x1 numeric, p_y1 numeric, p_x2 numeric, p_y2 numeric, p_regions jsonb, p_budget numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE region jsonb; span numeric[]; spans jsonb:='[]'::jsonb; merged jsonb:='[]'::jsonb;
 lo numeric;hi numeric;start_t numeric;end_t numeric;distance numeric;impervious numeric:=0;
 cursor_m numeric:=0;allowed numeric:=0;spent numeric:=0;available numeric;part numeric;taken numeric;budget_blocked boolean:=false;
BEGIN
 IF jsonb_typeof(p_regions) IS DISTINCT FROM 'array'
  OR (p_budget IS NOT NULL AND (p_budget<0 OR p_budget IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric))) THEN
  RAISE EXCEPTION 'panel_terrain_profile_invalid' USING ERRCODE='22023'; END IF;
 -- Convalida anche un percorso privo di zone senza accedere ad attori o sessioni.
 PERFORM combat_panel_private.impervious_integer_interval(p_x1,p_y1,p_x2,p_y2,'aabb',
  jsonb_build_object('min_x',0,'min_y',0,'max_x',1,'max_y',1));
 distance:=combat_spatial.distance_m(p_x1,p_y1,p_x2,p_y2);
 FOR region IN SELECT value FROM jsonb_array_elements(p_regions) LOOP
  IF jsonb_typeof(region) IS DISTINCT FROM 'object' OR region-ARRAY['shape_kind','shape']<>'{}'::jsonb THEN
   RAISE EXCEPTION 'panel_terrain_profile_invalid' USING ERRCODE='22023'; END IF;
  span:=combat_panel_private.impervious_integer_interval(p_x1,p_y1,p_x2,p_y2,region->>'shape_kind',region->'shape');
  IF span IS NOT NULL AND distance>0 AND span[2]>span[1] THEN
   -- Quantize occupied movement units before merging, so overlapping areas
   -- charge the same integer unit only once.
   spans:=spans||jsonb_build_array(jsonb_build_object(
    'lo',span[1],'hi',span[2]));
  END IF;
 END LOOP;
 FOR region IN SELECT value FROM jsonb_array_elements(spans) ORDER BY (value->>'lo')::numeric,(value->>'hi')::numeric LOOP
  lo:=(region->>'lo')::numeric;hi:=(region->>'hi')::numeric;
  IF start_t IS NULL THEN start_t:=lo;end_t:=hi;
  ELSIF lo<=end_t THEN end_t:=greatest(end_t,hi);
  ELSE merged:=merged||jsonb_build_array(jsonb_build_object('lo',start_t,'hi',end_t));start_t:=lo;end_t:=hi;
  END IF;
 END LOOP;
 IF start_t IS NOT NULL THEN merged:=merged||jsonb_build_array(jsonb_build_object('lo',start_t,'hi',end_t)); END IF;
 SELECT coalesce(sum((value->>'hi')::numeric-(value->>'lo')::numeric),0) INTO impervious FROM jsonb_array_elements(merged);
 available:=floor(coalesce(p_budget,distance+impervious));
 FOR region IN SELECT value FROM jsonb_array_elements(merged) LOOP
  lo:=(region->>'lo')::numeric;hi:=(region->>'hi')::numeric;
  part:=greatest(0,lo-cursor_m);taken:=least(part,greatest(0,available-spent));
  allowed:=allowed+taken;spent:=spent+taken;
  IF taken<part THEN EXIT; END IF;
  part:=hi-lo;taken:=floor(least(part,greatest(0,available-spent)/2));
  allowed:=allowed+taken;spent:=spent+taken*2;cursor_m:=hi;
  IF taken<part THEN budget_blocked:=true;EXIT; END IF;
 END LOOP;
 IF spent<available AND NOT budget_blocked THEN
  taken:=least(greatest(0,distance-cursor_m),available-spent);allowed:=allowed+taken;spent:=spent+taken;
 END IF;
 RETURN jsonb_build_object('distance_m',distance,'impervious_distance_m',impervious,
  'required_budget_m',distance+impervious,'allowed_distance_m',allowed,'budget_cost_m',spent,
  'allowed_t',CASE WHEN distance=0 THEN 1 ELSE allowed/distance END,'impervious_unit_intervals',merged,
  'impervious_intervals',(SELECT coalesce(jsonb_agg(jsonb_build_object('lo',(r->>'lo')::numeric/nullif(distance,0),'hi',(r->>'hi')::numeric/nullif(distance,0))),'[]'::jsonb) FROM jsonb_array_elements(merged)r));
END $function$;

