-- Native source combat_panel_private.impervious_regions(uuid) MD5 55637a8681aa9af91f0b6f4bdd5de7b0

CREATE OR REPLACE FUNCTION combat_panel_private.impervious_regions(p_instance uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i combat_spatial.arena_instances%ROWTYPE;t combat_spatial.arena_templates%ROWTYPE;
 o record; regions jsonb:='[]'::jsonb; s jsonb; configured jsonb;
BEGIN
 SELECT * INTO STRICT i FROM combat_spatial.arena_instances WHERE instance_id=p_instance AND state='open';
 SELECT * INTO STRICT t FROM combat_spatial.arena_templates WHERE template_key=i.template_key AND template_version=i.template_version;
 FOR o IN SELECT a.* FROM combat_spatial.arena_objects a
   JOIN combat_spatial.object_states os ON os.instance_id=i.instance_id AND os.object_key=a.object_key
   WHERE a.template_key=i.template_key AND a.template_version=i.template_version AND a.is_impervious
     AND os.state='available' ORDER BY a.object_key LOOP
   s:=o.shape;
   -- Il validatore puro rifiuta shape e numeri malformati prima dei confronti.
   PERFORM combat_panel_private.impervious_segment_interval(0,0,0,0,o.shape_kind,s);
   IF o.object_kind<>'region' OR o.blocks_movement OR o.substitutable
     OR (o.shape_kind='aabb' AND ((s->>'min_x')::numeric<0 OR (s->>'min_y')::numeric<0
       OR (s->>'max_x')::numeric>t.width_m OR (s->>'max_y')::numeric>t.height_m))
     OR (o.shape_kind='circle' AND ((s->>'cx')::numeric-(s->>'radius')::numeric<0
       OR (s->>'cy')::numeric-(s->>'radius')::numeric<0
       OR (s->>'cx')::numeric+(s->>'radius')::numeric>t.width_m
       OR (s->>'cy')::numeric+(s->>'radius')::numeric>t.height_m)) THEN
     RAISE EXCEPTION 'panel_impervious_area_invalid' USING ERRCODE='22023'; END IF;
   regions:=regions||jsonb_build_array(jsonb_build_object('shape_kind',o.shape_kind,'shape',s));
 END LOOP;
 SELECT c.regions INTO configured FROM combat_panel_private.instance_terrain_configs c
  WHERE instance_id=i.instance_id ORDER BY map_version DESC LIMIT 1;
 configured:=combat_panel_private.validate_instance_terrain(coalesce(configured,'[]'::jsonb),t.width_m,t.height_m);
 SELECT regions||coalesce(jsonb_agg(jsonb_build_object('shape_kind',value->>'shape_kind','shape',value->'shape')
   ORDER BY value->>'key'),'[]'::jsonb) INTO regions FROM jsonb_array_elements(configured);
 RETURN regions;
END $function$;

