CREATE OR REPLACE FUNCTION combat_panel_private.impervious_segment_interval(p_x1 numeric, p_y1 numeric, p_x2 numeric, p_y2 numeric, p_kind text, p_shape jsonb)
 RETURNS numeric[]
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE value numeric; dx numeric:=p_x2-p_x1;dy numeric:=p_y2-p_y1;
 lo numeric:=0;hi numeric:=1;origin numeric;delta numeric;minimum numeric;maximum numeric;
 near_t numeric;far_t numeric;cx numeric;cy numeric;radius numeric;a numeric;b numeric;c numeric;discriminant numeric;
BEGIN
 FOREACH value IN ARRAY ARRAY[p_x1,p_y1,p_x2,p_y2] LOOP
  IF value IS NULL OR value IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
   RAISE EXCEPTION 'panel_terrain_geometry_invalid' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF jsonb_typeof(p_shape) IS DISTINCT FROM 'object' OR p_kind IS NULL OR p_kind NOT IN ('aabb','circle') THEN
  RAISE EXCEPTION 'panel_terrain_geometry_invalid' USING ERRCODE='22023'; END IF;
 IF p_kind='aabb' THEN
  IF p_shape-ARRAY['min_x','min_y','max_x','max_y']<>'{}'::jsonb
   OR NOT p_shape?&ARRAY['min_x','min_y','max_x','max_y']
   OR EXISTS(SELECT 1 FROM jsonb_each(p_shape) s WHERE jsonb_typeof(s.value)<>'number') THEN
   RAISE EXCEPTION 'panel_terrain_geometry_invalid' USING ERRCODE='22023'; END IF;
  IF (p_shape->>'min_x')::numeric>=(p_shape->>'max_x')::numeric
   OR (p_shape->>'min_y')::numeric>=(p_shape->>'max_y')::numeric THEN
   RAISE EXCEPTION 'panel_terrain_geometry_invalid' USING ERRCODE='22023'; END IF;
  FOR axis IN 1..2 LOOP
   origin:=CASE axis WHEN 1 THEN p_x1 ELSE p_y1 END;
   delta:=CASE axis WHEN 1 THEN dx ELSE dy END;
   minimum:=(p_shape->>CASE axis WHEN 1 THEN 'min_x' ELSE 'min_y' END)::numeric;
   maximum:=(p_shape->>CASE axis WHEN 1 THEN 'max_x' ELSE 'max_y' END)::numeric;
   IF delta=0 THEN
    IF origin<minimum OR origin>maximum THEN RETURN NULL; END IF;
   ELSE
    near_t:=(minimum-origin)/delta;far_t:=(maximum-origin)/delta;
    lo:=greatest(lo,least(near_t,far_t));hi:=least(hi,greatest(near_t,far_t));
    IF hi<=lo THEN RETURN NULL; END IF;
   END IF;
  END LOOP;
 ELSE
  IF p_shape-ARRAY['cx','cy','radius']<>'{}'::jsonb OR NOT p_shape?&ARRAY['cx','cy','radius']
   OR EXISTS(SELECT 1 FROM jsonb_each(p_shape) s WHERE jsonb_typeof(s.value)<>'number') THEN
   RAISE EXCEPTION 'panel_terrain_geometry_invalid' USING ERRCODE='22023'; END IF;
  cx:=(p_shape->>'cx')::numeric;cy:=(p_shape->>'cy')::numeric;radius:=(p_shape->>'radius')::numeric;
  IF radius<=0 THEN RAISE EXCEPTION 'panel_terrain_geometry_invalid' USING ERRCODE='22023'; END IF;
  a:=dx*dx+dy*dy;c:=(p_x1-cx)^2+(p_y1-cy)^2-radius^2;
  IF a=0 THEN RETURN CASE WHEN c<=0 THEN ARRAY[0::numeric,1::numeric] ELSE NULL END; END IF;
  b:=2*((p_x1-cx)*dx+(p_y1-cy)*dy);discriminant:=b*b-4*a*c;
  IF discriminant<=0 THEN RETURN NULL; END IF;
  lo:=greatest(0,(-b-sqrt(discriminant))/(2*a));hi:=least(1,(-b+sqrt(discriminant))/(2*a));
 END IF;
 RETURN CASE WHEN hi>lo THEN ARRAY[lo,hi] ELSE NULL END;
END $function$;

