CREATE OR REPLACE FUNCTION combat_panel_private.instance_terrain_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i combat_spatial.arena_instances%ROWTYPE;t combat_spatial.arena_templates%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'panel_terrain_history_immutable' USING ERRCODE='55000'; END IF;
 SELECT * INTO STRICT i FROM combat_spatial.arena_instances WHERE instance_id=NEW.instance_id FOR UPDATE;
 IF i.state<>'open' OR i.map_version<>NEW.map_version THEN
  RAISE EXCEPTION 'panel_terrain_config_stale' USING ERRCODE='40001'; END IF;
 SELECT * INTO STRICT t FROM combat_spatial.arena_templates
  WHERE template_key=i.template_key AND template_version=i.template_version;
 NEW.regions:=combat_panel_private.validate_instance_terrain(NEW.regions,t.width_m,t.height_m);
 RETURN NEW;
END $function$;

