-- Native source combat_panel_private.integer_movement_endpoint(uuid,uuid,numeric,numeric,numeric,numeric,numeric,jsonb) MD5 cc4dd81d82af713a1b533ef881322cdd

CREATE OR REPLACE FUNCTION combat_panel_private.integer_movement_endpoint(p_instance uuid, p_actor uuid, p_x0 numeric, p_y0 numeric, p_x1 numeric, p_y1 numeric, p_budget numeric, p_regions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE point record;profile jsonb;answer jsonb;
BEGIN
 IF p_budget IS NULL OR p_budget<0 OR p_budget IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
  RAISE EXCEPTION 'integer_movement_budget_invalid' USING ERRCODE='22023';END IF;
 IF p_x0<>round(p_x0) OR p_y0<>round(p_y0) THEN
  RAISE EXCEPTION 'integer_movement_origin_not_reconciled' USING ERRCODE='40001';END IF;
 answer:=jsonb_build_object('x_m',p_x0,'y_m',p_y0,'distance_m',0,'cost_m',0);
 -- Il primo punto non raggiungibile termina il percorso: non si salta oltre
 -- un ostacolo cercando un successivo punto apparentemente libero.
 FOR point IN SELECT * FROM combat_spatial.integer_path_points(p_x0,p_y0,p_x1,p_y1) ORDER BY step LOOP
  IF point.distance_m=0 THEN CONTINUE;END IF;
  IF combat_spatial.path_first_block_t(p_instance,p_actor,p_x0,p_y0,point.x_m,point.y_m)<1 THEN EXIT;END IF;
  profile:=combat_panel_private.impervious_path_profile(p_x0,p_y0,point.x_m,point.y_m,p_regions);
  IF (profile->>'required_budget_m')::numeric>floor(p_budget) THEN EXIT;END IF;
  answer:=jsonb_build_object('x_m',point.x_m,'y_m',point.y_m,'distance_m',point.distance_m,
    'cost_m',(profile->>'required_budget_m')::numeric);
 END LOOP;
 RETURN answer;
END $function$;

