-- Native source combat_panel_private.master_companion_bind(uuid,uuid,jsonb) MD5 12534a5a52612f578c1d92475c529fb7

CREATE OR REPLACE FUNCTION combat_panel_private.master_companion_bind(p_owner uuid, p_source uuid, p_placement jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; i combat_spatial.arena_instances%ROWTYPE;
 m public.master_v2_sessions%ROWTYPE; claim combat_panel_private.master_scene_claims%ROWTYPE;
 src clan_marionettisti_private.sources%ROWTYPE; h clan_marionettisti_private.chassis%ROWTYPE;
 ctx jsonb; rid uuid; companion uuid:=gen_random_uuid(); snapshot jsonb; abilities jsonb; new_source uuid;
BEGIN
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_owner AND controller_user=auth.uid()
   AND actor_kind='pg' AND companion_id IS NULL AND state='attivo';
 ctx:=combat_panel_private.owner_turn_context(a.id); rid:=(ctx->>'round_id')::uuid;
 IF rid IS NULL OR ctx->>'activity_kind' IS DISTINCT FROM 'master_v2' OR NOT coalesce((ctx->>'can_move')::boolean,false) THEN
   RAISE EXCEPTION 'panel_companion_bind_turn_invalid' USING ERRCODE='42501'; END IF;
 PERFORM public.combat_v2_lock_round(rid);
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_owner AND controller_user=auth.uid() AND state='attivo' FOR UPDATE;
 ctx:=combat_panel_private.owner_turn_context(a.id);
 IF (ctx->>'round_id')::uuid IS DISTINCT FROM rid OR NOT coalesce((ctx->>'can_move')::boolean,false) THEN
   RAISE EXCEPTION 'panel_companion_bind_turn_changed' USING ERRCODE='40001'; END IF;
 SELECT * INTO STRICT i FROM combat_spatial.arena_instances
   WHERE encounter_id=a.session_id AND context_source='panel_master' AND state='open' FOR UPDATE;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=i.master_session_id;
 SELECT * INTO STRICT claim FROM combat_panel_private.master_scene_claims WHERE id=i.panel_claim_id;
 IF combat_panel_private.access_reason(m.location_id,'master_v2') IS NOT NULL
   OR EXISTS(SELECT 1 FROM public.combat_v2_actors b JOIN clan_marionettisti_private.sources s ON s.id=b.companion_id
     WHERE b.session_id=a.session_id AND s.owner_character_id=a.character_id)
   OR EXISTS(SELECT 1 FROM public.combat_v2_declarations d JOIN public.combat_v2_rounds r ON r.id=d.round_id
     WHERE r.session_id=a.session_id AND d.actor_id=a.id)
   OR EXISTS(SELECT 1 FROM clan_sabaku_private.staff_profiles WHERE session_id=a.session_id AND actor_id=a.id) THEN
   RAISE EXCEPTION 'panel_companion_bind_not_at_entry' USING ERRCODE='42501'; END IF;
 IF p_placement IS NULL OR p_placement IS DISTINCT FROM combat_panel_private.master_companion_placement(a.id) THEN
   RAISE EXCEPTION 'panel_companion_placement_changed' USING ERRCODE='40001'; END IF;
 IF p_source IS NULL THEN
   IF NOT combat_panel_private.master_staff_companion_scope(a.session_id)
     OR EXISTS(SELECT 1 FROM public.combat_v2_actors WHERE session_id=a.session_id AND actor_kind='pg'
       AND character_id NOT IN ('6bceee99-974f-426b-8d92-38b43b4a4267'::uuid,'2a877f02-4993-4e65-9172-7d29f08c5b86'::uuid))
     OR NOT EXISTS(SELECT 1 FROM clan_marionettisti_private.release_gate WHERE singleton AND staff_enabled)
     OR EXISTS(SELECT 1 FROM clan_marionettisti_private.sources WHERE session_id=a.session_id AND owner_actor_id=a.id) THEN
     RAISE EXCEPTION 'panel_companion_staff_bind_not_allowed' USING ERRCODE='42501'; END IF;
   snapshot:=a.mechanics_snapshot;
   IF jsonb_typeof(snapshot->'chakra') IS DISTINCT FROM 'number' OR jsonb_typeof(snapshot->'vita') IS DISTINCT FROM 'number'
     OR (snapshot->>'chakra')::integer<0 OR (snapshot->>'vita')::integer<=0 THEN
     RAISE EXCEPTION 'panel_companion_staff_resources_invalid' USING ERRCODE='22023'; END IF;
   -- Profilo canonico Staff L1; PV/chakra correnti preservati, nessuna scheda PG.
   SELECT coalesce(jsonb_agg(j),'[]') INTO abilities FROM jsonb_array_elements(coalesce(snapshot->'abilities','[]')) j
     WHERE j->>'source' IS DISTINCT FROM 'clan';
   abilities:=abilities||jsonb_build_array(
     jsonb_build_object('id','4d742b75-2592-4379-81c0-07ddf436f32b','source','clan','name','Padronanza dei Fili e delle Marionette','chakra_cost',0,'consumption_type','passiva','usage','passiva','defensive',false),
     jsonb_build_object('id','bfe4b934-5979-4e5a-8bff-982f9c41cfe7','source','clan','name','Fili di Chakra','chakra_cost',0,'consumption_type','passiva','usage','passiva','defensive',false),
     jsonb_build_object('id','e361f7c3-f90b-47ec-bfee-ccbda21257d9','source','clan','name','Marionetta da Combattimento','chakra_cost',5,'consumption_type','ad_utilizzo','usage','principale','kind','fisico','damage_base',10,'range','contatto','max_range',3,'defensive',false,'di_scena',false,'diversivo',false));
   new_source:=gen_random_uuid();
   INSERT INTO clan_marionettisti_private.sources(id,source_kind,session_id,owner_actor_id,owner_character_id,profile_version)
     VALUES(new_source,'staff',a.session_id,a.id,a.character_id,'marionetta-l1/1');
   src:=clan_marionettisti_private.assert_source(new_source);
   INSERT INTO clan_marionettisti_private.chassis(companion_id,owner_character_id) VALUES(src.id,a.character_id);
   UPDATE public.combat_v2_actors SET mechanics_snapshot=snapshot||jsonb_build_object(
     'kekkei_genkai',30,'ninjutsu',30,'abilities',abilities,'staff_profile','marionetta-l1/1') WHERE id=a.id;
 ELSE
   IF NOT public.combat_v2_values_written(a.session_id) OR claim.policy_id<>'master_game_resources_v1'
     OR NOT clan_marionettisti_private.owner_eligible(a.id,false) THEN
     RAISE EXCEPTION 'panel_companion_real_bind_not_allowed' USING ERRCODE='42501'; END IF;
   src:=clan_marionettisti_private.assert_source(p_source);
   IF src.source_kind<>'real' OR src.owner_character_id<>a.character_id THEN
     RAISE EXCEPTION 'panel_companion_real_owner_mismatch' USING ERRCODE='42501'; END IF;
 END IF;
 PERFORM 1 FROM clan_marionettisti_private.sources WHERE id=src.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.combat_v2_actors b JOIN public.combat_v2_sessions s ON s.id=b.session_id
   WHERE b.companion_id=src.id AND s.closed_at IS NULL) THEN
   RAISE EXCEPTION 'panel_companion_already_bound' USING ERRCODE='40001'; END IF;
 SELECT * INTO STRICT h FROM clan_marionettisti_private.chassis WHERE companion_id=src.id AND operational FOR UPDATE;
 IF h.owner_character_id<>a.character_id OR h.footprint_radius_m<>(p_placement->>'radius_m')::numeric THEN
   RAISE EXCEPTION 'panel_companion_chassis_changed' USING ERRCODE='40001'; END IF;
 INSERT INTO public.combat_v2_actors(id,session_id,actor_kind,companion_id,controller_user,team_key,state,
   position_m,initiative_snapshot,mechanics_snapshot,controller_version)
   VALUES(companion,a.session_id,'png',src.id,a.controller_user,a.team_key,'attivo',0,0,
     jsonb_build_object('vita',h.integrity,'vita_max',h.integrity_max,'companion_passive',true,'position_authority','spatial2d'),a.controller_version);
 PERFORM clan_marionettisti_private.assert_companion_actor(companion);
 INSERT INTO combat_spatial.actor_states(instance_id,actor_id,actor_kind,slot_key,controller_principal_id,
   projection_subject_id,x_m,y_m,footprint_radius_m,body_version,state)
   VALUES(i.instance_id,companion,'PNG','COMPANION-'||a.id,a.controller_user,gen_random_uuid(),
     (p_placement->>'x_m')::numeric,(p_placement->>'y_m')::numeric,h.footprint_radius_m,1,'active');
 -- Stessa policy di visibilita congelata nel bind della mappa, Master corrente.
 INSERT INTO combat_spatial.viewer_grants(instance_id,viewer_principal_id,subject_actor_id,can_view_map,can_view_objects,grant_version)
   SELECT i.instance_id,viewers.uid,companion,true,viewers.uid=m.master_user OR claim.visibility_mode='participants',1
   FROM (SELECT m.master_user AS uid UNION SELECT ca.controller_user FROM public.combat_v2_actors ca
     WHERE ca.session_id=a.session_id AND ca.controller_user IS NOT NULL
       AND (claim.visibility_mode='participants' OR ca.id=a.id)) viewers;
 UPDATE combat_spatial.arena_instances SET map_version=map_version+1 WHERE instance_id=i.instance_id;
 IF NOT clan_marionettisti_private.ensure_initial_link(a.id)
   OR NOT combat_panel_private.master_companion_roster_valid(a.session_id) THEN
   RAISE EXCEPTION 'panel_companion_initial_binding_failed' USING ERRCODE='40001'; END IF;
 PERFORM clan_marionettisti_private.start_command_window(rid);
 RETURN jsonb_build_object('actor_id',companion,'main_cost',0,'values_written',false,'simulated',src.source_kind='staff');
END $function$;

