-- Native source combat_panel_private.master_companion_control_offers(uuid,bigint,jsonb) MD5 eda47e0333a48d353a963829888ea204

CREATE OR REPLACE FUNCTION combat_panel_private.master_companion_control_offers(p_context uuid, p_expected bigint, p_source jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_panel_private.contexts%ROWTYPE; ctx jsonb; item jsonb; moves jsonb:='[]'; move jsonb;
 native clan_marionettisti_private.relink_offers%ROWTYPE; cap combat_spatial.movement_capabilities%ROWTYPE;
 oid uuid; direction_group uuid; direction_id uuid; distance_group uuid; direction text;
BEGIN
 c:=combat_panel_private.owned_context(p_context,p_expected);
 IF c.activity_kind<>'master_v2' OR c.command_actor_id IS NULL OR c.round_id IS NULL THEN RETURN; END IF;
 IF p_source->>'actor' IS DISTINCT FROM c.command_actor_id::text OR p_source->>'round' IS DISTINCT FROM c.round_id::text THEN
   RAISE EXCEPTION 'panel_companion_native_source_invalid' USING ERRCODE='22023'; END IF;
 ctx:=combat_panel_private.owner_turn_context(c.command_actor_id);
 IF NOT coalesce((ctx->>'can_move')::boolean,false) THEN RETURN; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(coalesce(p_source->'companion_controls','[]')) LOOP
   SELECT * INTO native FROM clan_marionettisti_private.relink_offers WHERE offer_id=(item->>'option_id')::uuid
     AND round_id=c.round_id AND owner_actor_id=c.command_actor_id;
   IF native.offer_id IS NULL OR NOT clan_marionettisti_private.relink_ready(c.round_id,c.command_actor_id) THEN
     RAISE EXCEPTION 'panel_companion_relink_source_changed' USING ERRCODE='40001'; END IF;
   PERFORM combat_panel_private.create_offer(c.id,c.context_version,'control','control','Riallaccia i Fili · 5 chakra',false,
     jsonb_build_object('adapter','master_v2','dispatch','companion_control','companion_operation','relink',
       'relink_offer_id',native.offer_id));
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(clan_marionettisti_private.companion_movement_options(c.command_actor_id)) LOOP
   SELECT * INTO STRICT cap FROM combat_spatial.movement_capabilities WHERE capability_id=(item->>'option_id')::uuid;
   direction:=CASE WHEN cap.end_x_m=cap.start_x_m AND cap.end_y_m<cap.start_y_m THEN 'up'
     WHEN cap.end_x_m=cap.start_x_m AND cap.end_y_m>cap.start_y_m THEN 'down'
     WHEN cap.end_y_m=cap.start_y_m AND cap.end_x_m<cap.start_x_m THEN 'left'
     WHEN cap.end_y_m=cap.start_y_m AND cap.end_x_m>cap.start_x_m THEN 'right' END;
   IF direction IS NULL THEN RAISE EXCEPTION 'panel_companion_direction_invalid' USING ERRCODE='22023'; END IF;
   moves:=moves||jsonb_build_array(jsonb_build_object('capability_id',cap.capability_id,
     'direction',direction,'distance_m',item->'distance_m'));
 END LOOP;
 IF jsonb_array_length(moves)=0 THEN RETURN; END IF;
 oid:=combat_panel_private.create_offer(c.id,c.context_version,'control','control','Muovi la marionetta',false,
   jsonb_build_object('adapter','master_v2','dispatch','companion_control','companion_operation','move'));
 direction_group:=combat_panel_private.add_group(oid,'Direzione','movement_direction','single',1,1);
 FOREACH direction IN ARRAY ARRAY['up','right','down','left'] LOOP
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(moves) WHERE value->>'direction'=direction) THEN CONTINUE; END IF;
   direction_id:=combat_panel_private.add_choice(direction_group,CASE direction WHEN 'up' THEN 'Su' WHEN 'right' THEN 'Destra'
     WHEN 'down' THEN 'Giù' ELSE 'Sinistra' END,jsonb_build_object('direction',direction),NULL,direction);
   distance_group:=combat_panel_private.add_group(oid,'Distanza','movement_distance','single',1,1,direction_id);
   FOR move IN SELECT DISTINCT ON ((value->>'distance_m')::numeric) value FROM jsonb_array_elements(moves)
     WHERE value->>'direction'=direction ORDER BY (value->>'distance_m')::numeric,value->>'capability_id' LOOP
     PERFORM combat_panel_private.add_choice(distance_group,(move->>'distance_m')::numeric::integer::text||' m',
       jsonb_build_object('movement_capability_id',move->'capability_id'),(move->>'distance_m')::numeric,direction);
   END LOOP;
 END LOOP;
END $function$;

