CREATE OR REPLACE FUNCTION combat_panel_private.master_companion_placement(p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; i combat_spatial.arena_instances%ROWTYPE;
 b combat_spatial.actor_states%ROWTYPE; pos record; xx numeric; yy numeric; ctx jsonb;
BEGIN
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=p_owner AND actor_kind='pg'
   AND state='attivo' AND companion_id IS NULL AND controller_user=auth.uid();
 IF a.id IS NULL THEN RETURN NULL; END IF;
 ctx:=combat_panel_private.owner_turn_context(a.id);
 IF ctx->>'activity_kind' IS DISTINCT FROM 'master_v2' OR NOT coalesce((ctx->>'can_move')::boolean,false) THEN RETURN NULL; END IF;
 SELECT * INTO i FROM combat_spatial.arena_instances WHERE encounter_id=a.session_id AND context_source='panel_master' AND state='open';
 SELECT * INTO b FROM combat_spatial.actor_states WHERE instance_id=i.instance_id AND actor_id=a.id AND state='active';
 IF b.actor_id IS NULL THEN RETURN NULL; END IF;
 -- Stesso ordine deterministico del posizionamento L1 gia rilasciato.
 FOR pos IN SELECT * FROM (VALUES(1,2,0),(2,0,2),(3,-2,0),(4,0,-2)) v(ord,dx,dy) ORDER BY ord LOOP
   xx:=b.x_m+pos.dx; yy:=b.y_m+pos.dy;
   IF clan_marionettisti_private.scene_slot_legal(i.template_key,i.template_version,xx,yy,0.5)
     AND NOT EXISTS(SELECT 1 FROM combat_spatial.actor_states other WHERE other.instance_id=i.instance_id
       AND other.state='active' AND combat_spatial.distance_m(xx,yy,other.x_m,other.y_m)<=0.5+other.footprint_radius_m)
     AND combat_spatial.path_first_block_t(i.instance_id,a.id,b.x_m,b.y_m,xx,yy,NULL)>=1 THEN
     RETURN jsonb_build_object('instance_id',i.instance_id,'map_version',i.map_version,
       'owner_body_version',b.body_version,'x_m',xx,'y_m',yy,'radius_m',0.5);
   END IF;
 END LOOP;
 RETURN NULL;
END $function$;

