CREATE OR REPLACE FUNCTION combat_panel_private.master_lifecycle_ack(p_context uuid, p_master uuid, p_before jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_panel_private.contexts%ROWTYPE; m public.master_v2_sessions%ROWTYPE; env jsonb; phase text; label text; sv bigint;
BEGIN
 SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE id=p_context AND principal_user=auth.uid() FOR UPDATE;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_master AND location_id=c.location_id;
 IF c.activity_kind<>'master_v2' OR p_before#>>'{context,activity_id}' IS DISTINCT FROM c.activity_id::text
   OR NOT(c.activity_id=m.id OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=c.activity_id AND master_session_id=m.id)) THEN
   RAISE EXCEPTION 'panel_lifecycle_scope_invalid' USING ERRCODE='22023'; END IF;
 IF m.stato IN ('chiusa','annullata') THEN phase:='closed'; label:='Scena chiusa';
 ELSIF m.stato='sospesa' THEN phase:='suspended'; label:='Gestione aggiornata · scontro sospeso';
 ELSE RAISE EXCEPTION 'panel_lifecycle_state_invalid' USING ERRCODE='22023'; END IF;
 SELECT map_version INTO sv FROM combat_spatial.arena_instances WHERE encounter_id=c.activity_id AND context_source='panel_master';
 UPDATE combat_panel_private.contexts SET context_version=context_version+1,scene_version=sv,
   source_fingerprint=public.combat_v2_sha256(jsonb_build_object('ack',p_request,'state',m.stato,'control',m.control_version)),
   updated_at=clock_timestamp() WHERE id=c.id RETURNING * INTO c;
 UPDATE combat_panel_private.offers SET state='revoked' WHERE context_id=c.id AND state='offered';
 env:=p_before||jsonb_build_object('actors','[]'::jsonb,'map',null,'offers','[]'::jsonb,
   'movement_explanations',null,'multiplication',null,'companion',null,'sabaku_transport',null,'narrative',null,'round_details',null,'receipt',null,
   'viewer',jsonb_build_object('command_actor_id',null,'controlled_actors','[]'::jsonb,
     'is_master',m.master_user=auth.uid(),'is_admin',public.combat_v2_is_admin(auth.uid()),'can_command',false));
 env:=jsonb_set(env,'{context}',(env->'context')||jsonb_build_object('phase',phase,'phase_label',label,
   'version',c.context_version,'scene_version',sv));
 RETURN env;
END $function$;

