-- Native source combat_panel_private.master_open_offers(uuid,bigint) MD5 34d905ffaedc869d5db5dc9dcdd0af56

CREATE OR REPLACE FUNCTION combat_panel_private.master_open_offers(p_context uuid, p_expected bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_panel_private.contexts%ROWTYPE; oid uuid; gid uuid; item record; base jsonb; policy text;
BEGIN
 c:=combat_panel_private.owned_context(p_context,p_expected);
 IF c.activity_id IS NOT NULL OR c.round_id IS NOT NULL OR NOT combat_panel_private.master_open_available(c.location_id) THEN RETURN; END IF;
 IF EXISTS(SELECT 1 FROM combat_panel_private.offers WHERE context_id=c.id AND context_version=c.context_version
   AND state='offered' AND source_payload->>'dispatch'='master_session_open') THEN RETURN; END IF;
 policy:=combat_panel_private.master_entry_policy(c.location_id);
 -- L'adapter resta quello del contesto vuoto. L'apertura restituisce poi
 -- il nuovo contesto Master; il client non sceglie o fabbrica un adapter.
 base:=jsonb_build_object('adapter',combat_panel_private.location_adapter(c.location_id),'dispatch','master_session_open','policy_id',policy);
 oid:=combat_panel_private.create_offer(c.id,c.context_version,'administration','open','Apri una Regia per duello',false,
   base||jsonb_build_object('session_type','duello'));
 PERFORM combat_panel_private.add_input(oid,'Titolo','title',true,100);
 oid:=combat_panel_private.create_offer(c.id,c.context_version,'administration','open','Apri una quest',false,
   base||jsonb_build_object('session_type','quest'));
 PERFORM combat_panel_private.add_input(oid,'Titolo','title',true,100);
 gid:=combat_panel_private.add_group(oid,'Tipologia della quest','mode','single',1,1);
 PERFORM combat_panel_private.add_choice(gid,'Quest one-shot',jsonb_build_object('quest_kind','one_shot'));
 PERFORM combat_panel_private.add_choice(gid,'Quest di trama',jsonb_build_object('quest_kind','trama'));
 -- La simulazione Staff non viene collegata a missioni/progressione reali.
 IF policy='master_game_resources_v1' AND EXISTS(SELECT 1 FROM public.missions WHERE status IN ('aperta','programmata')) THEN
   oid:=combat_panel_private.create_offer(c.id,c.context_version,'administration','open','Apri una missione',false,
     base||jsonb_build_object('session_type','quest','mission_required',true));
   gid:=combat_panel_private.add_group(oid,'Missione','generic','single',1,1);
   FOR item IN SELECT id,title,grado FROM public.missions WHERE status IN ('aperta','programmata') ORDER BY title,id LOOP
     PERFORM combat_panel_private.add_choice(gid,item.title||' · '||coalesce(item.grado,'—'),jsonb_build_object('mission_id',item.id));
   END LOOP;
 END IF;
END $function$;

