-- Native source combat_panel_private.master_placement_offers(uuid,bigint,jsonb) MD5 197494ed17110cea20371a4a31f35ca6

CREATE OR REPLACE FUNCTION combat_panel_private.master_placement_offers(p_context uuid, p_expected bigint, p_source jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_panel_private.contexts%ROWTYPE; m public.master_v2_sessions%ROWTYPE;
 profile record; actor record; placement record; claim uuid; issued jsonb; oid uuid; gid uuid;
BEGIN
 c:=combat_panel_private.owned_context(p_context,p_expected);
 SELECT * INTO m FROM public.master_v2_sessions WHERE id=(p_source#>>'{master,id}')::uuid AND location_id=c.location_id;
 IF m.id IS NULL OR m.master_user IS DISTINCT FROM auth.uid() OR m.owner_kind<>'human'
   OR m.stato NOT IN ('preparazione','in_corso') OR c.round_id IS NULL THEN RETURN; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=c.activity_id AND master_session_id=m.id AND closed_at IS NULL)
   OR EXISTS(SELECT 1 FROM combat_spatial.arena_instances WHERE encounter_id=c.activity_id OR master_session_id=m.id)
   OR EXISTS(SELECT 1 FROM public.combat_v2_declarations d JOIN public.combat_v2_rounds r ON r.id=d.round_id WHERE r.session_id=c.activity_id)
   THEN RETURN; END IF;
 FOR profile IN SELECT p.* FROM combat_panel_private.master_scene_profiles p
   JOIN combat_spatial.arena_templates t ON t.template_key=p.template_key AND t.template_version=p.template_version
   JOIN public.locations l ON l.id=p.location_id AND l.is_active
   WHERE p.location_id=c.location_id AND p.enabled AND t.status='ready'
     AND ((l.is_test AND p.policy_id='staff_test_no_persistent_resources_v1')
       OR (NOT l.is_test AND p.policy_id='master_game_resources_v1'))
     AND p.geometry_fingerprint=t.geometry_hash ORDER BY p.label,p.id LOOP
   claim:=md5(c.id::text||':'||c.context_version||':'||profile.id)::uuid;
   issued:=combat_panel_private.master_scene_offer(c.activity_id,profile.id,claim);
   -- Un profilo senza almeno uno slot valido per ogni corpo non è una scelta
   -- eseguibile. Il bind ricontrolla poi anche le collisioni fra corpi.
   IF EXISTS(SELECT 1 FROM public.combat_v2_actors a WHERE a.session_id=c.activity_id AND a.state='attivo'
     AND NOT EXISTS(SELECT 1 FROM combat_panel_private.master_placement_options WHERE claim_id=claim AND actor_id=a.id)) THEN CONTINUE; END IF;
   oid:=combat_panel_private.create_offer(c.id,c.context_version,'administration','administration','Prepara mappa · '||profile.label,false,
     jsonb_build_object('adapter','master_v2','dispatch','place_scene','master_session_id',m.id,
       'control_version',m.control_version,'claim_id',claim));
   FOR actor IN SELECT a.id,coalesce(nullif(item.value->>'name',''),'Partecipante') AS label
     FROM public.combat_v2_actors a JOIN LATERAL jsonb_array_elements(p_source->'actors') item(value)
       ON item.value->>'id'=a.id::text WHERE a.session_id=c.activity_id AND a.state='attivo' ORDER BY a.id LOOP
     gid:=combat_panel_private.add_group(oid,'Posizione di '||actor.label,'generic','single',1,1);
     FOR placement IN SELECT * FROM combat_panel_private.master_placement_options WHERE claim_id=claim AND actor_id=actor.id ORDER BY slot_key LOOP
       PERFORM combat_panel_private.add_choice(gid,placement.slot_key||' · '||placement.x_m::integer::text||' m, '||placement.y_m::integer::text||' m',
         jsonb_build_object('placement_option_id',placement.id));
     END LOOP;
   END LOOP;
 END LOOP;
END $function$;

