-- Native source combat_panel_private.master_scene_bind(uuid,uuid[],uuid) MD5 7d586b43553b8ce3328eefde861e586b

CREATE OR REPLACE FUNCTION combat_panel_private.master_scene_bind(p_claim uuid, p_options uuid[], p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE claim combat_panel_private.master_scene_claims%ROWTYPE; s public.combat_v2_sessions%ROWTYPE;
 m public.master_v2_sessions%ROWTYPE; prior combat_panel_private.master_scene_receipts%ROWTYPE;
 fp text; iid uuid; result jsonb; body record; profile combat_panel_private.master_scene_profiles%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR p_request IS NULL OR coalesce(cardinality(p_options),0)=0
   OR array_position(p_options,NULL) IS NOT NULL
   OR cardinality(p_options)<>(SELECT count(DISTINCT x) FROM unnest(p_options) AS x) THEN
   RAISE EXCEPTION 'panel_scene_bind_request_invalid' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT claim FROM combat_panel_private.master_scene_claims WHERE id=p_claim;
 SELECT * INTO STRICT s FROM public.combat_v2_sessions WHERE id=claim.encounter_id FOR UPDATE;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=s.master_session_id FOR UPDATE;
 IF s.source_kind<>'master' OR s.closed_at IS NOT NULL OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
   OR m.master_user IS DISTINCT FROM auth.uid() OR claim.authority_principal_id IS DISTINCT FROM auth.uid()
   OR claim.master_session_id<>m.id OR claim.authority_control_version<>m.control_version THEN
   RAISE EXCEPTION 'panel_master_authority_stale' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('panel-scene:'||auth.uid()::text||':'||p_request::text,731));
 fp:=public.combat_v2_sha256(jsonb_build_object('claim',p_claim,'options',
   (SELECT jsonb_agg(x ORDER BY x) FROM unnest(p_options) AS x)));
 SELECT * INTO prior FROM combat_panel_private.master_scene_receipts
   WHERE claim_id=p_claim OR (principal_user=auth.uid() AND request_key=p_request);
 IF FOUND THEN
   IF prior.claim_id<>p_claim OR prior.request_key<>p_request OR prior.command_fingerprint<>fp
     OR prior.principal_user IS DISTINCT FROM auth.uid() THEN
     RAISE EXCEPTION 'panel_scene_bind_replay_conflict' USING ERRCODE='22023'; END IF;
   RETURN prior.result||jsonb_build_object('replayed',true);
 END IF;
 SELECT * INTO STRICT profile FROM combat_panel_private.master_scene_profiles WHERE id=claim.profile_id AND enabled FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM public.locations l WHERE l.id=s.location_id AND l.is_active
   AND ((l.is_test AND claim.policy_id='staff_test_no_persistent_resources_v1'
      AND combat_consumer_private.staff_test_allowed(l.id,ARRAY[auth.uid()],false))
     OR (NOT l.is_test AND claim.policy_id='master_game_resources_v1'))) THEN
   RAISE EXCEPTION 'panel_master_policy_mismatch' USING ERRCODE='42501'; END IF;
 IF (profile.profile_version,profile.location_id,profile.template_key,profile.template_version,
     profile.geometry_fingerprint,profile.policy_id,profile.visibility_mode)
   IS DISTINCT FROM (claim.profile_version,s.location_id,claim.template_key,claim.template_version,
     claim.geometry_fingerprint,claim.policy_id,claim.visibility_mode)
   OR claim.geometry_fingerprint IS DISTINCT FROM combat_spatial.geometry_fingerprint(claim.template_key,claim.template_version)
   OR combat_spatial.template_errors(claim.template_key,claim.template_version)<>'[]'::jsonb THEN
   RAISE EXCEPTION 'panel_scene_profile_stale' USING ERRCODE='40001'; END IF;
 PERFORM 1 FROM public.combat_v2_actors WHERE session_id=s.id ORDER BY id FOR UPDATE;
 IF claim.policy_id='staff_test_no_persistent_resources_v1' AND
   (m.mission_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.mission_run_state WHERE master_session_id=m.id)
    OR NOT combat_consumer_private.staff_test_allowed(s.location_id,ARRAY(
      SELECT auth.uid() UNION SELECT a.controller_user FROM public.combat_v2_actors a WHERE a.session_id=s.id),false)) THEN
   RAISE EXCEPTION 'panel_master_test_roster_or_mission_invalid' USING ERRCODE='42501'; END IF;
 IF claim.roster_fingerprint IS DISTINCT FROM combat_panel_private.master_roster_fingerprint(s.id)
   OR EXISTS(SELECT 1 FROM public.combat_v2_declarations d JOIN public.combat_v2_rounds r ON r.id=d.round_id WHERE r.session_id=s.id)
   OR EXISTS(SELECT 1 FROM combat_spatial.arena_instances WHERE encounter_id=s.id OR master_session_id=m.id) THEN
   RAISE EXCEPTION 'panel_scene_roster_or_phase_stale' USING ERRCODE='40001'; END IF;
 IF (SELECT count(*) FROM combat_panel_private.master_placement_options WHERE claim_id=p_claim AND id=ANY(p_options))<>cardinality(p_options)
   OR EXISTS(SELECT 1 FROM combat_panel_private.master_placement_options WHERE id=ANY(p_options) GROUP BY actor_id HAVING count(*)<>1)
   OR EXISTS(SELECT 1 FROM public.combat_v2_actors a WHERE a.session_id=s.id AND a.state='attivo'
     AND NOT EXISTS(SELECT 1 FROM combat_panel_private.master_placement_options o WHERE o.id=ANY(p_options) AND o.actor_id=a.id))
   OR EXISTS(SELECT 1 FROM combat_panel_private.master_placement_options o JOIN public.combat_v2_actors a ON a.id=o.actor_id
     WHERE o.id=ANY(p_options) AND (a.session_id<>s.id OR a.state<>'attivo')) THEN
   RAISE EXCEPTION 'panel_scene_roster_selection_invalid' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM combat_panel_private.master_placement_options a
   JOIN combat_panel_private.master_placement_options b ON a.id<b.id
   WHERE a.id=ANY(p_options) AND b.id=ANY(p_options)
     AND (a.slot_key=b.slot_key OR combat_spatial.distance_m(a.x_m,a.y_m,b.x_m,b.y_m)<=a.radius_m+b.radius_m)) THEN
   RAISE EXCEPTION 'panel_scene_placement_collision' USING ERRCODE='22023'; END IF;
 FOR body IN SELECT * FROM combat_panel_private.master_placement_options WHERE id=ANY(p_options) LOOP
   IF NOT clan_marionettisti_private.scene_slot_legal(claim.template_key,claim.template_version,body.x_m,body.y_m,body.radius_m) THEN
     RAISE EXCEPTION 'panel_scene_placement_stale' USING ERRCODE='40001'; END IF;
 END LOOP;
 iid:=gen_random_uuid();
 INSERT INTO combat_spatial.arena_instances(instance_id,master_session_id,encounter_id,binding_id,
   template_key,template_version,map_version,state,context_source,panel_claim_id)
   VALUES(iid,m.id,s.id,NULL,claim.template_key,claim.template_version,1,'open','panel_master',claim.id);
 INSERT INTO combat_spatial.actor_states(instance_id,actor_id,actor_kind,slot_key,controller_principal_id,
   projection_subject_id,x_m,y_m,footprint_radius_m,body_version,state)
   SELECT iid,a.id,upper(a.actor_kind),o.slot_key,coalesce(a.controller_user,m.master_user),
     gen_random_uuid(),o.x_m,o.y_m,o.radius_m,1,'active'
   FROM combat_panel_private.master_placement_options o JOIN public.combat_v2_actors a ON a.id=o.actor_id
   WHERE o.id=ANY(p_options);
 -- Il profilo esplicita la visibilita: nessun grant preso in prestito dalla
 -- marionetta. Nessun profilo e attivo o creato da questa migrazione.
 INSERT INTO combat_spatial.viewer_grants(instance_id,viewer_principal_id,subject_actor_id,can_view_map,can_view_objects,grant_version)
   SELECT iid,viewers.uid,b.actor_id,true,viewers.uid=m.master_user OR claim.visibility_mode='participants',1
   FROM combat_spatial.actor_states b CROSS JOIN LATERAL (
     SELECT m.master_user AS uid
     UNION SELECT a.controller_user FROM public.combat_v2_actors a WHERE a.session_id=s.id AND a.controller_user IS NOT NULL
       AND (claim.visibility_mode='participants' OR a.id=b.actor_id)
   ) viewers WHERE b.instance_id=iid;
 INSERT INTO combat_spatial.object_states(instance_id,object_key,state,state_version)
   SELECT iid,object_key,CASE WHEN substitutable THEN 'available' ELSE 'blocked' END,1
   FROM combat_spatial.arena_objects WHERE template_key=claim.template_key AND template_version=claim.template_version;
 FOR body IN SELECT * FROM combat_spatial.actor_states WHERE instance_id=iid LOOP
   IF combat_spatial.path_first_block_t(iid,body.actor_id,body.x_m,body.y_m,body.x_m,body.y_m,NULL)<1 THEN
     RAISE EXCEPTION 'panel_scene_final_occupancy_invalid' USING ERRCODE='22023'; END IF;
 END LOOP;
 result:=jsonb_build_object('instance_id',iid,'claim_id',claim.id,'map_version',1,'replayed',false);
 INSERT INTO combat_panel_private.master_scene_receipts(claim_id,principal_user,request_key,command_fingerprint,instance_id,result)
   VALUES(claim.id,auth.uid(),p_request,fp,iid,result);
 RETURN result;
END $function$;

