RESET ROLE;

-- Native source combat_panel_private.master_scene_offer(uuid,uuid,uuid) MD5 fcd13e660a4448db951ff86e2f43bcb2

CREATE OR REPLACE FUNCTION combat_panel_private.master_scene_offer(p_encounter uuid, p_profile uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s public.combat_v2_sessions%ROWTYPE; m public.master_v2_sessions%ROWTYPE;
 profile combat_panel_private.master_scene_profiles%ROWTYPE; claim combat_panel_private.master_scene_claims%ROWTYPE;
 t combat_spatial.arena_templates%ROWTYPE; roster_fp text; actor record; slot record; radius numeric;
BEGIN
 IF auth.uid() IS NULL OR p_request IS NULL THEN
   RAISE EXCEPTION 'panel_master_authority_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT s FROM public.combat_v2_sessions WHERE id=p_encounter FOR UPDATE;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=s.master_session_id FOR UPDATE;
 IF s.source_kind<>'master' OR s.closed_at IS NOT NULL OR m.closed_at IS NOT NULL
   OR m.suspended_at IS NOT NULL OR m.owner_kind<>'human' OR m.master_user IS DISTINCT FROM auth.uid() THEN
   RAISE EXCEPTION 'panel_master_authority_stale' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT profile FROM combat_panel_private.master_scene_profiles
   WHERE id=p_profile AND location_id=s.location_id AND enabled FOR SHARE;
 SELECT * INTO STRICT t FROM combat_spatial.arena_templates WHERE template_key=profile.template_key
   AND template_version=profile.template_version AND status='ready' FOR SHARE;
 IF t.geometry_hash IS DISTINCT FROM profile.geometry_fingerprint
   OR t.geometry_hash IS DISTINCT FROM combat_spatial.geometry_fingerprint(t.template_key,t.template_version)
   OR combat_spatial.template_errors(t.template_key,t.template_version)<>'[]'::jsonb THEN
   RAISE EXCEPTION 'panel_master_geometry_not_ready' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.locations l WHERE l.id=s.location_id AND l.is_active
   AND ((l.is_test AND profile.policy_id='staff_test_no_persistent_resources_v1'
      AND combat_consumer_private.staff_test_allowed(l.id,ARRAY[auth.uid()],false))
     OR (NOT l.is_test AND profile.policy_id='master_game_resources_v1'))) THEN
   RAISE EXCEPTION 'panel_master_policy_mismatch' USING ERRCODE='42501'; END IF;
 roster_fp:=combat_panel_private.master_roster_fingerprint(s.id);
 IF profile.policy_id='staff_test_no_persistent_resources_v1' AND
   (m.mission_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.mission_run_state WHERE master_session_id=m.id)
    OR NOT combat_consumer_private.staff_test_allowed(s.location_id,ARRAY(
      SELECT auth.uid() UNION SELECT a.controller_user FROM public.combat_v2_actors a WHERE a.session_id=s.id),false)) THEN
   RAISE EXCEPTION 'panel_master_test_roster_or_mission_invalid' USING ERRCODE='42501'; END IF;
 SELECT * INTO claim FROM combat_panel_private.master_scene_claims WHERE id=p_request;
 IF FOUND THEN
   IF (claim.profile_id,claim.profile_version,claim.master_session_id,claim.encounter_id,
     claim.authority_principal_id,claim.authority_control_version,claim.geometry_fingerprint,
     claim.roster_fingerprint,claim.policy_id,claim.visibility_mode)
     IS DISTINCT FROM (profile.id,profile.profile_version,m.id,s.id,auth.uid(),m.control_version,
       t.geometry_hash,roster_fp,profile.policy_id,profile.visibility_mode) THEN
     RAISE EXCEPTION 'panel_scene_offer_replay_conflict' USING ERRCODE='22023'; END IF;
 ELSE
   IF EXISTS(SELECT 1 FROM combat_spatial.arena_instances WHERE encounter_id=s.id OR master_session_id=m.id)
     OR EXISTS(SELECT 1 FROM public.combat_v2_declarations d JOIN public.combat_v2_rounds r ON r.id=d.round_id
       WHERE r.session_id=s.id) THEN
     RAISE EXCEPTION 'panel_scene_requires_unbound_pre_declaration' USING ERRCODE='22023'; END IF;
   INSERT INTO combat_panel_private.master_scene_claims(id,profile_id,profile_version,master_session_id,
     encounter_id,template_key,template_version,authority_principal_id,authority_control_version,
     geometry_fingerprint,roster_fingerprint,policy_id,visibility_mode)
     VALUES(p_request,profile.id,profile.profile_version,m.id,s.id,t.template_key,t.template_version,
       auth.uid(),m.control_version,t.geometry_hash,roster_fp,profile.policy_id,profile.visibility_mode);
   FOR actor IN SELECT id,actor_kind,companion_id FROM public.combat_v2_actors
     WHERE session_id=s.id AND state='attivo' ORDER BY id LOOP
     radius:=CASE WHEN actor.companion_id IS NOT NULL THEN 0.5 ELSE t.actor_radius_m END;
     FOR slot IN SELECT * FROM combat_spatial.arena_slots WHERE template_key=t.template_key
       AND template_version=t.template_version AND actor_kind=upper(actor.actor_kind) ORDER BY slot_key LOOP
       IF clan_marionettisti_private.scene_slot_legal(t.template_key,t.template_version,round(slot.x_m),round(slot.y_m),radius) THEN
         INSERT INTO combat_panel_private.master_placement_options(claim_id,actor_id,slot_key,x_m,y_m,radius_m)
           VALUES(p_request,actor.id,slot.slot_key,round(slot.x_m),round(slot.y_m),radius);
       END IF;
     END LOOP;
   END LOOP;
 END IF;
 RETURN jsonb_build_object('claim_id',p_request,'options',(SELECT coalesce(jsonb_agg(jsonb_build_object(
   'option_id',id,'actor_id',actor_id,'slot',slot_key) ORDER BY actor_id,slot_key),'[]'::jsonb)
   FROM combat_panel_private.master_placement_options WHERE claim_id=p_request));
END $function$;

