-- Native source combat_panel_private.master_spatial_checkpoint_trigger() MD5 5f4c5b9dfb52141cf293abeff4aacfe0

CREATE OR REPLACE FUNCTION combat_panel_private.master_spatial_checkpoint_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE facts jsonb; saved combat_panel_private.master_spatial_checkpoints%ROWTYPE;
BEGIN
 IF TG_TABLE_SCHEMA='combat_panel_private' THEN
   RAISE EXCEPTION 'panel_spatial_checkpoint_immutable' USING ERRCODE='42501'; END IF;
 IF TG_OP='INSERT' THEN
   IF EXISTS(SELECT 1 FROM combat_spatial.arena_instances WHERE master_session_id=NEW.master_session_id AND context_source='panel_master') THEN
     facts:=combat_panel_private.master_spatial_facts(NEW.master_session_id);
     INSERT INTO combat_panel_private.master_spatial_checkpoints(checkpoint_id,master_session_id,facts,sha256)
       VALUES(NEW.id,NEW.master_session_id,facts,public.combat_v2_sha256(facts));
   END IF;
 ELSIF OLD.translation_applied_at IS NULL AND NEW.translation_applied_at IS NOT NULL THEN
   SELECT * INTO saved FROM combat_panel_private.master_spatial_checkpoints WHERE checkpoint_id=NEW.id;
   IF saved.checkpoint_id IS NOT NULL OR EXISTS(SELECT 1 FROM combat_spatial.arena_instances
     WHERE master_session_id=NEW.master_session_id AND context_source='panel_master') THEN
     facts:=combat_panel_private.master_spatial_facts(NEW.master_session_id);
     IF saved.checkpoint_id IS NULL OR saved.master_session_id IS DISTINCT FROM NEW.master_session_id
       OR saved.sha256 IS DISTINCT FROM public.combat_v2_sha256(saved.facts)
       OR saved.sha256 IS DISTINCT FROM public.combat_v2_sha256(facts) THEN
       RAISE EXCEPTION 'panel_spatial_checkpoint_changed' USING ERRCODE='40001'; END IF;
   END IF;
 END IF;
 RETURN NEW;
END $function$;

