-- Native source combat_panel_private.master_staff_companion_scope(uuid) MD5 584a00bfedf0280c6665065f66336cbb

CREATE OR REPLACE FUNCTION combat_panel_private.master_staff_companion_scope(p_session uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE location uuid; principals uuid[];
BEGIN
 SELECT m.location_id INTO location FROM public.combat_v2_sessions s
   JOIN public.master_v2_sessions m ON m.id=s.master_session_id
   JOIN combat_panel_private.master_panel_sessions p ON p.master_session_id=m.id
   WHERE s.id=p_session AND s.source_kind='master' AND s.closed_at IS NULL
     AND m.stato NOT IN ('chiusa','annullata') AND s.location_id=m.location_id
     AND p.policy_id='staff_test_no_persistent_resources_v1'
     AND NOT public.combat_v2_values_written(s.id);
 IF location IS NULL THEN RETURN false; END IF;
 SELECT array_agg(DISTINCT a.controller_user) INTO principals FROM public.combat_v2_actors a
   JOIN public.characters pg ON pg.id=a.character_id AND pg.user_id=a.controller_user
   WHERE a.session_id=p_session AND a.actor_kind='pg' AND a.companion_id IS NULL;
 RETURN cardinality(principals) IS NOT DISTINCT FROM 2
   AND (SELECT count(*) FROM public.combat_v2_actors WHERE session_id=p_session AND actor_kind='pg')=2
   AND coalesce(combat_consumer_private.staff_test_allowed(location,principals,false),false)
   AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors WHERE session_id=p_session
     AND (controller_user IS NULL OR NOT(controller_user=ANY(principals))));
END $function$;

