-- Native source combat_panel_private.movement_event_cost(uuid,numeric) MD5 044d22f406e57182667434a57593526f

CREATE OR REPLACE FUNCTION combat_panel_private.movement_event_cost(p_event uuid, p_legacy_distance numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE cost numeric;
BEGIN
 IF p_legacy_distance IS NULL OR p_legacy_distance<0
   OR p_legacy_distance IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
   RAISE EXCEPTION 'panel_movement_ledger_invalid' USING ERRCODE='22023'; END IF;
 SELECT cost_m INTO cost FROM combat_panel_private.movement_cost_receipts WHERE event_id=p_event;
 -- Le ricevute precedenti al rilascio non avevano sovraccosto del percorso.
 RETURN coalesce(cost,p_legacy_distance);
END $function$;

