-- Native source combat_panel_private.movement_regions_for_body(uuid,uuid) MD5 ead340b84ff231af3173cb28db302871

CREATE OR REPLACE FUNCTION combat_panel_private.movement_regions_for_body(p_instance uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE companion uuid;
BEGIN
 SELECT a.companion_id INTO companion FROM public.combat_v2_actors a
   JOIN combat_spatial.arena_instances i ON i.encounter_id=a.session_id AND i.instance_id=p_instance AND i.state='open'
   JOIN combat_spatial.actor_states b ON b.instance_id=i.instance_id AND b.actor_id=a.id AND b.state='active'
   WHERE a.id=p_actor AND a.state='attivo';
 IF NOT FOUND THEN RAISE EXCEPTION 'panel_movement_body_invalid' USING ERRCODE='22023'; END IF;
 IF companion IS NOT NULL THEN RETURN '[]'::jsonb; END IF;
 -- La stessa attivazione server che assegna il bonus rende il corpo esente.
 -- Una riga ancora active ma scaduta non basta; non leggere flag del client.
 IF EXISTS(SELECT 1 FROM clan_sabaku_private.transport_uses u
   JOIN combat_spatial.arena_instances i ON i.encounter_id=u.session_id AND i.instance_id=p_instance
   WHERE u.actor_id=p_actor AND u.state='active'
     AND clan_sabaku_private.transport_end_reason(u.id) IS NULL) THEN
   RETURN '[]'::jsonb;
 END IF;
 RETURN combat_panel_private.impervious_regions(p_instance);
END $function$;

