-- Native source combat_panel_private.multiplication_actor_end() MD5 390e5a2262affd6c56270631bdcf6232

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_actor_end()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE fid uuid;
BEGIN
 IF NEW.state<>'attivo' OR coalesce((NEW.mechanics_snapshot->>'vita')::numeric,0)<=0 THEN
   FOR fid IN SELECT id FROM combat_panel_private.multiplication_formations
     WHERE actor_id=NEW.id AND state='active' ORDER BY id LOOP
     PERFORM combat_panel_private.multiplication_finish(fid,'owner_inoperative');
   END LOOP;
 END IF;
 RETURN NEW;
END $function$;

