-- Native source combat_panel_private.multiplication_actor_recognizes(uuid) MD5 b5908f52e601da394638190799c667f2

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_actor_recognizes(p_actor uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE;
BEGIN
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=p_actor AND state='attivo' AND companion_id IS NULL;
 IF a.id IS NULL THEN RETURN false; END IF;
 IF NOT public.combat_v2_values_written(a.session_id) THEN
   -- In Staff non si leggono attivazioni reali del PG per simulare gli occhi.
   RETURN EXISTS(SELECT 1 FROM clan_innata_combat_private.combat_state st
     JOIN public.clan_techniques t ON t.id=st.technique_id AND t.is_active AND t.rivela_originale
     WHERE st.actor_id=a.id AND st.session_id=a.session_id AND st.is_test AND st.active);
 END IF;
 IF a.character_id IS NULL THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM clan_innata_private.actor_state st
   JOIN clan_innata_private.config_versions cfg USING(technique_id,config_version)
   JOIN public.clan_techniques t ON t.id=st.technique_id AND t.is_active AND t.rivela_originale
   WHERE st.actor_id=a.character_id AND st.active AND cfg.reviewed AND cfg.active);
END $function$;

