-- Native source combat_panel_private.multiplication_add_attack_figures(uuid,uuid,jsonb,numeric,text) MD5 df84796cdd964bbd196f34e7252fc661

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_add_attack_figures(p_offer uuid, p_parent uuid, p_geometry jsonb, p_range numeric, p_label text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE gid uuid; figure jsonb; eligible jsonb;
BEGIN
 IF p_geometry IS NULL THEN RETURN; END IF;
 IF p_range IS NULL OR p_range<0 OR p_range IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
   RAISE EXCEPTION 'panel_multiplication_target_range_invalid' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_geometry->'figures')
   WHERE (value->>'distance_m')::numeric<=p_range AND (value->>'path_clear')::boolean) THEN
   RAISE EXCEPTION 'panel_multiplication_target_not_available' USING ERRCODE='22023'; END IF;
 gid:=combat_panel_private.add_group(p_offer,'Figura di '||p_label,'generic','single',1,1,p_parent);
 SELECT jsonb_agg(value->'figure_index' ORDER BY (value->>'figure_index')::integer) INTO eligible
  FROM jsonb_array_elements(p_geometry->'figures')
  WHERE (value->>'distance_m')::numeric<=p_range AND (value->>'path_clear')::boolean;
 PERFORM combat_panel_private.add_choice(gid,'Estrazione del server',jsonb_build_object(
  'multiplication_attack_target',jsonb_build_object('target_actor_id',p_geometry->'target_actor_id',
   'formation_id',p_geometry->'formation_id','state_version',p_geometry->'state_version',
   'attack_origin',coalesce(p_geometry->>'attack_origin','actor'),'selection_kind','server_random',
   'eligible_indices',eligible,'range_m',p_range)));

 FOR figure IN SELECT value FROM jsonb_array_elements(p_geometry->'figures')
   WHERE (value->>'distance_m')::numeric<=p_range AND (value->>'path_clear')::boolean
   ORDER BY (value->>'figure_index')::integer LOOP
   PERFORM combat_panel_private.add_choice(gid,
     'Figura '||(figure->>'figure_index')||' · '||round((figure->>'distance_m')::numeric)||' m',
     jsonb_build_object('multiplication_attack_target',jsonb_build_object(
       'target_actor_id',p_geometry->'target_actor_id','formation_id',p_geometry->'formation_id',
       'state_version',p_geometry->'state_version','figure_index',figure->'figure_index','attack_origin',coalesce(p_geometry->>'attack_origin','actor'))),
     (figure->>'distance_m')::numeric);
 END LOOP;
END $function$;

