CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_assault_draw_layouts(p_variants jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v jsonb;selection jsonb;authority jsonb;result jsonb;
BEGIN
 IF jsonb_typeof(p_variants) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'panel_multiplication_draw_variants_invalid' USING ERRCODE='22023'; END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(p_variants) LOOP
  selection:=v->'selection';
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR jsonb_typeof(v->'layouts') IS DISTINCT FROM 'array'
   OR jsonb_typeof(selection) IS DISTINCT FROM 'object'
   OR selection-ARRAY['target_actor_id','formation_id','state_version','figure_index']<>'{}'::jsonb
   OR NOT selection?&ARRAY['target_actor_id','formation_id','state_version','figure_index']
   OR jsonb_typeof(selection->'target_actor_id') IS DISTINCT FROM 'string'
   OR jsonb_typeof(selection->'formation_id') IS DISTINCT FROM 'string'
   OR jsonb_typeof(selection->'state_version') IS DISTINCT FROM 'number'
   OR jsonb_typeof(selection->'figure_index') IS DISTINCT FROM 'number'
   OR (selection->>'state_version')::bigint<=0 OR (selection->>'figure_index')::integer<=0 THEN
   RAISE EXCEPTION 'panel_multiplication_draw_variants_invalid' USING ERRCODE='22023'; END IF;
  IF authority IS NULL THEN authority:=selection-'figure_index';
  ELSIF authority IS DISTINCT FROM selection-'figure_index' THEN
   RAISE EXCEPTION 'panel_multiplication_draw_variants_mixed' USING ERRCODE='22023'; END IF;
 END LOOP;
 WITH flat AS (
  SELECT DISTINCT (v.value#>>'{selection,figure_index}')::integer AS enemy_index,
   l.value-'original_options' AS layout,o.value AS original
  FROM jsonb_array_elements(p_variants) v(value)
  CROSS JOIN LATERAL jsonb_array_elements(v.value->'layouts') l(value)
  CROSS JOIN LATERAL jsonb_array_elements(l.value->'original_options') o(value)
 ), options AS (
  SELECT layout,original||jsonb_build_object('assault_draw',authority||jsonb_build_object(
    'eligible_indices',jsonb_agg(to_jsonb(enemy_index) ORDER BY enemy_index))) AS original
  FROM flat GROUP BY layout,original
 ), layouts AS (
  SELECT layout||jsonb_build_object('original_options',jsonb_agg(original ORDER BY (original->>'figure_index')::integer)) AS value
  FROM options GROUP BY layout
 )
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'direction',(value->>'extent_m')::numeric,value->'figures'),'[]'::jsonb)
  INTO result FROM layouts;
 RETURN result;
END $function$;

