CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_attack_draw_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'panel_multiplication_draw_history_immutable' USING ERRCODE='55000'; END IF;
 IF OLD.random_seed IS NOT NULL AND
  (NEW.random_seed,NEW.random_indices,NEW.random_range_m,NEW.selected_index,NEW.formation_id,NEW.formation_version,
   NEW.round_id,NEW.actor_id,NEW.target_actor_id,NEW.request_key,NEW.principal_user,NEW.prepared_transaction,NEW.controller_version)
  IS DISTINCT FROM
  (OLD.random_seed,OLD.random_indices,OLD.random_range_m,OLD.selected_index,OLD.formation_id,OLD.formation_version,
   OLD.round_id,OLD.actor_id,OLD.target_actor_id,OLD.request_key,OLD.principal_user,OLD.prepared_transaction,OLD.controller_version) THEN
  RAISE EXCEPTION 'panel_multiplication_draw_history_immutable' USING ERRCODE='55000'; END IF;
 IF OLD.random_seed IS NULL AND NEW.random_seed IS NOT NULL AND
  (OLD.attack_target_id IS NOT NULL OR OLD.choice_id IS NOT NULL OR OLD.prepared_transaction<>txid_current()) THEN
  RAISE EXCEPTION 'panel_multiplication_draw_binding_closed' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $function$;

