CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_attack_facts(p_target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.combat_v2_attack_targets%ROWTYPE; d public.combat_v2_declarations%ROWTYPE;
 fid uuid; formation_role text; item jsonb; facts jsonb:='[]'::jsonb;
BEGIN
 SELECT * INTO STRICT t FROM public.combat_v2_attack_targets WHERE id=p_target;
 PERFORM public.combat_v2_lock_round(t.round_id);
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=t.attack_declaration_id AND round_id=t.round_id;
 FOR fid,formation_role IN SELECT f.id,CASE WHEN f.mode='assalto' AND f.declaration_id=d.id AND f.actor_id=d.actor_id
   THEN 'attacking' ELSE 'targeted' END FROM combat_panel_private.multiplication_formations f
   WHERE ((f.mode='assalto' AND f.declaration_id=d.id AND f.actor_id=d.actor_id)
      OR (f.mode IN ('diversivo','copertura','assalto') AND f.actor_id=t.target_actor_id))
    AND f.session_id=(SELECT session_id FROM public.combat_v2_rounds WHERE id=t.round_id)
    AND (f.state='active' OR EXISTS(SELECT 1 FROM combat_panel_private.multiplication_resolutions r
      WHERE r.formation_id=f.id AND r.attack_target_id=t.id))
   ORDER BY f.id LOOP
   item:=combat_panel_private.multiplication_resolve_choice(fid,t.id);
   IF item IS NOT NULL THEN facts:=facts||jsonb_build_array(item||jsonb_build_object('role',formation_role)); END IF;
 END LOOP;
 RETURN facts;
END $function$;

