 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE plan combat_panel_private.multiplication_ordinary_draw_plans%ROWTYPE;
 aim combat_panel_private.multiplication_attack_aims%ROWTYPE;
BEGIN
 SELECT * INTO plan FROM combat_panel_private.multiplication_ordinary_draw_plans
  WHERE request_key=p_request AND target_actor_id=p_target;
 IF plan.request_key IS NULL THEN RETURN; END IF;
 IF plan.principal_user IS DISTINCT FROM auth.uid() OR plan.prepared_transaction<>txid_current()
  OR plan.source_offer_id IS DISTINCT FROM p_source OR plan.movement_offer_id IS DISTINCT FROM p_movement THEN
  RAISE EXCEPTION 'panel_multiplication_draw_binding_invalid' USING ERRCODE='40001'; END IF;
 SELECT * INTO STRICT aim FROM combat_panel_private.multiplication_attack_aims
  WHERE request_key=p_request AND target_actor_id=p_target FOR UPDATE;
 IF (aim.round_id,aim.actor_id,aim.principal_user,aim.prepared_transaction,aim.formation_id,aim.formation_version,aim.selected_index)
  IS DISTINCT FROM (plan.round_id,plan.actor_id,plan.principal_user,plan.prepared_transaction,plan.formation_id,plan.formation_version,plan.selected_index)
  OR aim.attack_target_id IS NOT NULL OR aim.choice_id IS NOT NULL THEN
  RAISE EXCEPTION 'panel_multiplication_draw_binding_invalid' USING ERRCODE='40001'; END IF;
 IF aim.random_seed IS NOT NULL THEN
  IF (aim.random_seed,aim.random_indices,aim.random_range_m) IS DISTINCT FROM (plan.random_seed,plan.random_indices,plan.range_m) THEN
   RAISE EXCEPTION 'panel_multiplication_draw_binding_invalid' USING ERRCODE='40001'; END IF;
  RETURN;
 END IF;
 UPDATE combat_panel_private.multiplication_attack_aims SET random_seed=plan.random_seed,
  random_indices=plan.random_indices,random_range_m=plan.range_m
  WHERE request_key=p_request AND target_actor_id=p_target;
