-- Native source combat_panel_private.multiplication_chooser(uuid,uuid) MD5 ebd611e9dadd95b913d8976f2b35c386

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_chooser(p_formation uuid, p_target uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f combat_panel_private.multiplication_formations%ROWTYPE;
 t public.combat_v2_attack_targets%ROWTYPE; d public.combat_v2_declarations%ROWTYPE; chooser uuid;
BEGIN
 SELECT * INTO STRICT f FROM combat_panel_private.multiplication_formations WHERE id=p_formation;
 SELECT * INTO STRICT t FROM public.combat_v2_attack_targets WHERE id=p_target;
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=t.attack_declaration_id AND round_id=t.round_id AND kind='attacco';
 IF NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds r WHERE r.id=d.round_id AND r.session_id=f.session_id) THEN
   RAISE EXCEPTION 'panel_multiplication_attack_scope_invalid' USING ERRCODE='22023'; END IF;
 IF f.mode='assalto' AND f.declaration_id=d.id AND f.actor_id=d.actor_id THEN
   -- Chi difende davvero, anche in copertura di un alleato, sceglie la figura.
   SELECT defense.actor_id INTO chooser FROM public.combat_v2_defense_coverages c
     JOIN public.combat_v2_declarations defense ON defense.id=c.defense_declaration_id
     WHERE c.attack_target_id=t.id AND defense.round_id=d.round_id;
   chooser:=coalesce(chooser,t.target_actor_id);
 ELSIF f.mode IN ('diversivo','copertura','assalto') AND f.actor_id=t.target_actor_id THEN
   chooser:=d.actor_id;
 ELSE RAISE EXCEPTION 'panel_multiplication_formation_not_targeted' USING ERRCODE='22023'; END IF;
 RETURN chooser;
END $function$;

