CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_combat_end()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE fid uuid;
BEGIN
 IF NEW.state IN ('chiuso','annullato') OR NEW.closed_at IS NOT NULL THEN
   FOR fid IN SELECT id FROM combat_panel_private.multiplication_formations
     WHERE session_id=NEW.id AND state='active' ORDER BY id LOOP
     PERFORM combat_panel_private.multiplication_finish(fid,'combat_end');
   END LOOP;
 END IF;
 RETURN NEW;
END $function$;

