-- Native source combat_panel_private.multiplication_companion_frozen_source(uuid) MD5 58dce4fe83a72ec59184ddabe1e76a98

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_companion_frozen_source(p_declaration uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE profile clan_marionettisti_private.offensive_profiles%ROWTYPE;
 d public.combat_v2_declarations%ROWTYPE; aim combat_panel_private.multiplication_attack_aims%ROWTYPE;
 selection jsonb; figure jsonb; origin jsonb; target_version bigint; x numeric; y numeric;
BEGIN
 SELECT * INTO STRICT profile FROM clan_marionettisti_private.offensive_profiles
  WHERE declaration_id=p_declaration FOR SHARE;
 SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration;
 IF profile.profile_sha256 IS DISTINCT FROM public.combat_v2_sha256(profile.profile)
  OR d.round_id<>profile.round_id OR d.actor_id<>profile.owner_actor_id
  OR d.target_actor_id<>profile.target_actor_id OR d.kind<>'attacco'
  OR d.sanitized_intent->>'ability_source' IS DISTINCT FROM 'clan'
  OR d.sanitized_intent->>'ability_id' IS DISTINCT FROM 'e361f7c3-f90b-47ec-bfee-ccbda21257d9' THEN
  RAISE EXCEPTION 'marionetta_profile_corrupt';
 END IF;
 selection:=profile.profile->'multiplication_attack_target';
 IF selection IS NULL THEN
   RETURN clan_marionettisti_private.attack_source(d.round_id,d.actor_id,d.target_actor_id);
 END IF;
 SELECT * INTO STRICT aim FROM combat_panel_private.multiplication_attack_aims
  WHERE request_key=d.request_key AND target_actor_id=d.target_actor_id;
 IF aim.round_id<>d.round_id OR aim.actor_id<>d.actor_id OR aim.choice_id IS NULL
  OR aim.geometry->>'attack_origin' IS DISTINCT FROM 'marionetta'
  OR selection->>'formation_id' IS DISTINCT FROM aim.formation_id::text
  OR (selection->>'formation_version')::bigint IS DISTINCT FROM aim.formation_version
  OR (selection->>'figure_index')::integer IS DISTINCT FROM aim.selected_index
  OR NOT EXISTS(SELECT 1 FROM public.combat_v2_attack_targets WHERE id=aim.attack_target_id
    AND attack_declaration_id=d.id AND round_id=d.round_id AND target_actor_id=d.target_actor_id) THEN
  RAISE EXCEPTION 'panel_multiplication_aim_binding_invalid' USING ERRCODE='40001';
 END IF;
 -- Le figure restano immutabili anche dopo consumo/scadenza della formazione.
 SELECT point INTO STRICT figure FROM combat_panel_private.multiplication_formations f
  CROSS JOIN LATERAL jsonb_array_elements(f.figures) AS points(point)
  JOIN public.combat_v2_rounds r ON r.id=d.round_id
  WHERE f.id=aim.formation_id AND f.actor_id=d.target_actor_id AND f.session_id=r.session_id
    AND (point->>'figure_index')::integer=aim.selected_index;
 IF figure->'x_m' IS DISTINCT FROM selection->'x_m'
   OR figure->'y_m' IS DISTINCT FROM selection->'y_m' THEN
   RAISE EXCEPTION 'marionetta_profile_corrupt';
 END IF;
 origin:=clan_marionettisti_private.attack_origin(d.round_id,d.actor_id,d.target_actor_id);
 IF (origin->>'instance_id',origin->>'companion_actor_id',origin->>'link_version')
  IS DISTINCT FROM (profile.profile->>'instance_id',profile.profile->>'companion_actor_id',profile.profile->>'link_version') THEN
  RAISE EXCEPTION 'marionetta_source_stale' USING ERRCODE='22023';
 END IF;
 SELECT body_version INTO STRICT target_version FROM combat_spatial.actor_states
  WHERE instance_id=(origin->>'instance_id')::uuid AND actor_id=d.target_actor_id AND state='active';
 x:=(selection->>'x_m')::numeric; y:=(selection->>'y_m')::numeric;
 IF combat_spatial.distance_m((origin->>'source_x_m')::numeric,(origin->>'source_y_m')::numeric,x,y)>3
  OR combat_spatial.path_first_block_t((origin->>'instance_id')::uuid,(origin->>'companion_actor_id')::uuid,
    (origin->>'source_x_m')::numeric,(origin->>'source_y_m')::numeric,x,y,d.target_actor_id)<1 THEN
  RAISE EXCEPTION 'marionetta_attack_out_of_range' USING ERRCODE='22023';
 END IF;
 RETURN (origin-ARRAY['source_x_m','source_y_m'])||jsonb_build_object(
  'target_body_version',target_version,'multiplication_attack_target',selection);
END $function$;

