CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_companion_target_figure(p_round uuid, p_owner uuid, p_target uuid, p_formation uuid, p_version bigint, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE geometry jsonb; figure jsonb;
BEGIN
 geometry:=combat_panel_private.multiplication_companion_target_geometry(p_round,p_owner,p_target);
 IF geometry IS NULL OR geometry->>'formation_id' IS DISTINCT FROM p_formation::text
   OR (geometry->>'state_version')::bigint IS DISTINCT FROM p_version THEN
   RAISE EXCEPTION 'panel_multiplication_target_stale' USING ERRCODE='40001'; END IF;
 SELECT value INTO figure FROM jsonb_array_elements(geometry->'figures')
  WHERE (value->>'figure_index')::integer=p_index;
 IF figure IS NULL THEN RAISE EXCEPTION 'panel_multiplication_target_figure_invalid' USING ERRCODE='22023'; END IF;
 RETURN (geometry-'figures')||jsonb_build_object('figure',figure);
END $function$;

