-- Native source combat_panel_private.multiplication_effect(jsonb,text) MD5 6de54cf745850272c4e11627bd1e55b9

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_effect(p_facts jsonb, p_reaction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE spent boolean:=false; intercepted boolean:=false; item jsonb;
BEGIN
 IF jsonb_typeof(p_facts) IS DISTINCT FROM 'array' OR p_reaction IS NULL THEN
   RAISE EXCEPTION 'panel_multiplication_facts_invalid' USING ERRCODE='22023'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_facts) LOOP
   IF item->>'schema_version' IS DISTINCT FROM 'combat-multiplication-resolution/1'
     OR item->>'mode' IS NULL OR item->>'mode' NOT IN ('assalto','diversivo','copertura')
     OR item->>'role' IS NULL OR item->>'role' NOT IN ('attacking','targeted')
     OR (item->>'role'='attacking' AND item->>'mode'<>'assalto')
     OR item->>'outcome' IS NULL OR item->>'outcome' NOT IN ('copy_hit','original_found') THEN
     RAISE EXCEPTION 'panel_multiplication_facts_invalid' USING ERRCODE='22023'; END IF;
   IF item->>'outcome'='copy_hit' THEN
     IF item->>'role'='attacking' THEN spent:=p_reaction<>'nessuna';
     ELSE intercepted:=true; END IF;
   END IF;
 END LOOP;
 RETURN jsonb_build_object('declared_reaction',p_reaction,
   'effective_reaction',CASE WHEN spent THEN 'nessuna' ELSE p_reaction END,
   'defense_spent_on_copy',spent,'copy_intercepted',intercepted);
END $function$;

