-- Native source combat_panel_private.multiplication_formation_projection(jsonb,integer,integer,integer) MD5 6f30c9d411310851529f2ec1306a1397

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_formation_projection(p_figures jsonb, p_copy_count integer, p_copy_cap integer, p_original_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE figures jsonb;
BEGIN
 IF NOT combat_panel_private.multiplication_formation_valid(p_figures,p_copy_count,p_copy_cap,p_original_index) THEN
   RAISE EXCEPTION 'panel_multiplication_formation_invalid' USING ERRCODE='22023'; END IF;
 SELECT jsonb_agg(jsonb_build_object('figure_index',(f->>'figure_index')::integer,
   'x_m',(f->>'x_m')::numeric,'y_m',(f->>'y_m')::numeric) ORDER BY (f->>'figure_index')::integer)
   INTO figures FROM jsonb_array_elements(p_figures) f;
 -- Lo stesso insieme di figure ha una proiezione identica per ogni originale.
 RETURN jsonb_build_object('schema_version','combat-multiplication-figures/2','figures',figures);
END $function$;

