-- Native source combat_panel_private.multiplication_line_figures(numeric,numeric,integer,integer,numeric,integer) MD5 eebda0cdd3f2a4b3465d665137f9b5db

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_line_figures(p_x numeric, p_y numeric, p_dx integer, p_dy integer, p_extent numeric, p_copies integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE d numeric; points jsonb:='[]'::jsonb;
BEGIN
 IF p_x IS NULL OR p_y IS NULL OR p_dx IS NULL OR p_dy IS NULL OR abs(p_dx)+abs(p_dy)<>1
   OR p_extent IS NULL OR p_extent<=0 OR p_copies IS NULL OR p_copies<1
   OR p_x IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
   OR p_y IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
   OR p_extent IN ('NaN'::numeric,'Infinity'::numeric) THEN
   RAISE EXCEPTION 'panel_multiplication_layout_input_invalid' USING ERRCODE='22023'; END IF;
 FOR n IN 0..p_copies LOOP
   d:=round(p_extent-least(5,p_extent)*n/p_copies);
   points:=points||jsonb_build_array(jsonb_build_object('figure_index',n+1,'x_m',p_x+p_dx*d,'y_m',p_y+p_dy*d));
 END LOOP;
 RETURN points;
END $function$;

