-- Native source combat_panel_private.multiplication_mask_map(jsonb,jsonb) MD5 bbd0e03f84e612dc13e6d0722863f681

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_mask_map(p_map jsonb, p_view jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE bodies jsonb;
BEGIN
 IF p_map IS NULL OR p_view IS NULL THEN RETURN p_map; END IF;
 -- L'indice privato e disponibile solo al controllore corrente del corpo.
 -- Negli altri POV si mostrano le figure, mai un secondo marker sull'originale.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_view->'formations') f
   WHERE f->'original_index'='null'::jsonb AND f->>'actor_id'=p_map#>>'{pov,actor_id}') THEN
   RAISE EXCEPTION 'panel_multiplication_private_pov_conflict' USING ERRCODE='42501'; END IF;
 SELECT coalesce(jsonb_agg(b ORDER BY ordinal),'[]'::jsonb) INTO bodies
 FROM jsonb_array_elements(p_map->'actors') WITH ORDINALITY bodies(b,ordinal)
 WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_view->'formations') f
   WHERE f->'original_index'='null'::jsonb AND f->>'actor_id'=b->>'actor_id');
 RETURN jsonb_set(p_map,'{actors}',bodies);
END $function$;

