-- Native source combat_panel_private.multiplication_prepare_selected_aims(uuid,uuid,uuid,uuid[],jsonb) MD5 bb19ec3c37b303a9d3a6f34cbfb4e59c

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_prepare_selected_aims(p_round uuid, p_actor uuid, p_request uuid, p_targets uuid[], p_resolved jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE payload jsonb; selection jsonb; target uuid; seen uuid[]:=ARRAY[]::uuid[];
BEGIN
 FOR payload IN SELECT choice->'payload' FROM jsonb_array_elements(p_resolved->'groups') AS groups(g)
   CROSS JOIN LATERAL jsonb_array_elements(g->'options') AS choices(choice) LOOP
   IF NOT payload ? 'multiplication_attack_target' THEN CONTINUE; END IF;
   selection:=payload->'multiplication_attack_target'; target:=(selection->>'target_actor_id')::uuid;
   IF target IS NULL OR NOT coalesce(target=ANY(p_targets),false) OR target=ANY(seen) THEN
     RAISE EXCEPTION 'panel_multiplication_target_selection_conflict' USING ERRCODE='22023'; END IF;
   seen:=array_append(seen,target);
   IF coalesce(selection->>'attack_origin','actor') NOT IN ('actor','marionetta') THEN
     RAISE EXCEPTION 'panel_attack_origin_invalid' USING ERRCODE='22023'; END IF;
   IF selection->>'selection_kind'='server_random' THEN
    PERFORM combat_panel_private.multiplication_prepare_attack_draw(p_round,p_actor,target,
     (selection->>'formation_id')::uuid,(selection->>'state_version')::bigint,
     selection->'eligible_indices',(selection->>'range_m')::numeric,p_request,
     coalesce(selection->>'attack_origin'='marionetta',false));
   ELSE
   PERFORM combat_panel_private.multiplication_prepare_attack_aim_for_source(p_round,p_actor,target,
     (selection->>'formation_id')::uuid,(selection->>'state_version')::bigint,
     (selection->>'figure_index')::integer,p_request,coalesce(selection->>'attack_origin'='marionetta',false));
   END IF;
 END LOOP;
END $function$;

