-- Native source combat_panel_private.multiplication_random_figure(integer,bytea) MD5 9d90310f9b09edcf34b62bc9c9cdab8c

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_random_figure(p_count integer, p_seed bytea)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE bytes bytea; word bigint; lim bigint;
BEGIN
 IF p_count IS NULL OR p_count<1 OR p_seed IS NULL OR octet_length(p_seed)<>32 THEN
   RAISE EXCEPTION 'panel_multiplication_rng_input_invalid' USING ERRCODE='22023'; END IF;
 lim:=(4294967296::bigint/p_count)*p_count;
 -- Rejection sampling uniforme, riproducibile dal seed privato del ledger.
 FOR counter IN 0..255 LOOP
   bytes:=extensions.digest(p_seed||decode('6d756c7469706c69636174696f6e2d6669677572652f313a','hex')||pg_catalog.int4send(counter),'sha256');
   word:=get_byte(bytes,0)::bigint*16777216+get_byte(bytes,1)::bigint*65536+get_byte(bytes,2)::bigint*256+get_byte(bytes,3);
   IF word<lim THEN RETURN (word%p_count+1)::integer; END IF;
 END LOOP;
 RAISE EXCEPTION 'panel_multiplication_rng_exhausted';
END $function$;

