-- Native source combat_panel_private.multiplication_target_figure(uuid,uuid,uuid,bigint,integer) MD5 05bdfab8c01966de7b16f5465bc6f010

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_target_figure(p_actor uuid, p_target uuid, p_formation uuid, p_version bigint, p_index integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE geometry jsonb; figure jsonb;
BEGIN
 geometry:=combat_panel_private.multiplication_target_geometry(p_actor,p_target);
 IF geometry IS NULL OR geometry->>'formation_id' IS DISTINCT FROM p_formation::text
   OR geometry->>'state_version' IS DISTINCT FROM p_version::text THEN
   RAISE EXCEPTION 'panel_multiplication_target_stale' USING ERRCODE='40001'; END IF;
 SELECT value INTO figure FROM jsonb_array_elements(geometry->'figures')
   WHERE (value->>'figure_index')::integer=p_index;
 IF figure IS NULL THEN RAISE EXCEPTION 'panel_multiplication_target_figure_invalid' USING ERRCODE='22023'; END IF;
 -- Nessun ripiego sulla figura più vicina, su un sorteggio o sull'originale.
 RETURN (geometry-'figures')||jsonb_build_object('figure',figure);
END $function$;

