CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_target_in_range(p_actor uuid, p_target uuid, p_formation uuid, p_version bigint, p_index integer, p_range numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE selected jsonb;
BEGIN
 IF p_range IS NULL OR p_range<0 OR p_range IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
   RAISE EXCEPTION 'panel_multiplication_target_range_invalid' USING ERRCODE='22023'; END IF;
 selected:=combat_panel_private.multiplication_target_figure(p_actor,p_target,p_formation,p_version,p_index);
 RETURN (selected#>>'{figure,distance_m}')::numeric<=p_range
   AND (selected#>>'{figure,path_clear}')::boolean;
END $function$;

