-- Native source combat_panel_private.normalize_ordinary(uuid,uuid,jsonb) MD5 658e504cc0b70c90188be9eaa2007c7c

CREATE OR REPLACE FUNCTION combat_panel_private.normalize_ordinary(p_location uuid, p_actor uuid, src jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE multiplication jsonb; is_master boolean:=coalesce(public.master_v2_is_master(auth.uid()),false);
 is_admin boolean:=coalesce(public.combat_v2_is_admin(auth.uid()),false);
 c combat_panel_private.contexts%ROWTYPE; actor uuid; sid uuid; map_instance uuid;
 closed_arena combat_spatial.arena_instances%ROWTYPE; closed_body combat_spatial.actor_states%ROWTYPE;
 closed_config combat_panel_private.instance_terrain_configs%ROWTYPE; closed_regions jsonb; terminal_source_version bigint;
 rid uuid; phase text; simulated boolean; roster jsonb:='[]'; controlled jsonb:='[]';
 item jsonb; body_only boolean; selected boolean; map_view jsonb:=null; narrative_view jsonb:=null; narrative_meta jsonb; details jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000'; END IF;
 -- src proviene dalla RPC autenticata di stato o dalla sua ricevuta appena
 -- restituita. Questo helper privato non accetta documenti dal client.
 IF src->>'status' IS DISTINCT FROM 'ready' THEN
   RETURN jsonb_build_object('schema_version','combat-panel/1','status','blocked',
     'reason_code',coalesce(src->>'reason_code','source_not_ready'),'context',null,
     'viewer',jsonb_build_object('command_actor_id',null,'controlled_actors','[]'::jsonb,
       'is_master',is_master,'is_admin',is_admin,'can_command',false),
     'actors','[]'::jsonb,'map',null,'offers','[]'::jsonb,'movement_explanations',null,
     'multiplication',null,'companion',null,'sabaku_transport',null,'narrative',null,'round_details',null,'receipt',null);
 END IF;
 actor:=(src#>>'{viewer,actor_id}')::uuid;
 IF p_actor IS NOT NULL AND p_actor IS DISTINCT FROM actor THEN
   RAISE EXCEPTION 'panel_actor_not_controlled' USING ERRCODE='42501'; END IF;
 sid:=(src#>>'{context,activity_id}')::uuid;
 rid:=(src#>>'{context,exchange_id}')::uuid;
 phase:=CASE src#>>'{context,phase}' WHEN 'waiting_join' THEN 'setup'
   WHEN 'action' THEN 'action' WHEN 'defense' THEN 'defense' WHEN 'resolved' THEN 'resolved'
   WHEN 'closed' THEN 'closed' ELSE NULL END;
 simulated:=CASE src#>>'{context,policy_id}'
   WHEN 'staff_test_no_persistent_resources_v1' THEN true
   WHEN 'free_duel_nonlethal_real_resources_v1' THEN false ELSE NULL END;
 IF phase IS NULL OR simulated IS NULL THEN
   RAISE EXCEPTION 'panel_source_context_unsupported' USING ERRCODE='22023'; END IF;
 IF phase='closed' THEN
   -- La vista Sabaku e' catturata prima del close; il contesto della ricevuta e' quello successivo.
   terminal_source_version:=(src#>>'{receipt,context_version_before}')::bigint;
   IF src#>>'{receipt,operation}' IS DISTINCT FROM 'close'
     OR jsonb_typeof(src#>'{receipt,context_version_before}') IS DISTINCT FROM 'number'
     OR src#>'{receipt,context_version_before}' IS DISTINCT FROM to_jsonb(terminal_source_version)
     OR terminal_source_version NOT BETWEEN 0 AND 9007199254740990
     OR src#>'{context,version}' IS DISTINCT FROM to_jsonb(terminal_source_version+1)
     OR src#>'{receipt,context_version_after}' IS DISTINCT FROM src#>'{context,version}' THEN
     RAISE EXCEPTION 'panel_terminal_source_version_invalid' USING ERRCODE='22023'; END IF;
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(src->'actors') LOOP
   IF item->>'state' NOT IN ('active','out','withdrawn') OR item->>'state' IS NULL THEN
     RAISE EXCEPTION 'panel_actor_state_unsupported' USING ERRCODE='22023'; END IF;
   body_only:=coalesce((item->>'body_only')::boolean,false);
   selected:=(item->>'actor_id')::uuid IS NOT DISTINCT FROM actor AND actor IS NOT NULL;
   roster:=roster||jsonb_build_array(jsonb_build_object(
     'actor_id',item->'actor_id','kind',CASE WHEN body_only THEN 'companion' ELSE 'pg' END,
     'body_only',body_only,'display_name',item->'display_name','team',null,'state',item->'state',
     'mine',selected,
     'action_due',NOT body_only AND item->>'state'='active' AND phase='action'
       AND coalesce((item->>'is_turn_owner')::boolean,false),
     'defense_due',NOT body_only AND item->>'state'='active' AND phase='defense'
       AND NOT coalesce((item->>'is_turn_owner')::boolean,false),
     'resources',CASE WHEN selected THEN src#>'{viewer,resources}' ELSE NULL END,
     'distance_from_viewer_m',item->'distance_from_viewer_m'));
   IF selected AND NOT body_only THEN
     controlled:=controlled||jsonb_build_array(jsonb_build_object(
       'actor_id',item->'actor_id','label',item->'display_name'));
   END IF;
 END LOOP;
 IF jsonb_typeof(src->'map')='object' THEN
   IF src#>>'{map,schema_version}' IS DISTINCT FROM 'combat-map/1' THEN
     RAISE EXCEPTION 'panel_map_source_unsupported' USING ERRCODE='22023'; END IF;
   map_view:=jsonb_build_object('schema_version','combat-map/2',
     'map_version',src#>'{map,map_version}','readonly',true,'label',src#>'{map,label}',
     'bounds',src#>'{map,bounds}','pov',src#>'{map,pov}',
     'actors',(SELECT coalesce(jsonb_agg(jsonb_build_object(
       'actor_id',b->'actor_id','x_m',b->'x_m','y_m',b->'y_m','radius_m',b->'radius_m',
       'body_only',coalesce((b->>'body_only')::boolean,false)) ORDER BY ord),'[]'::jsonb)
       FROM jsonb_array_elements(src#>'{map,actors}') WITH ORDINALITY AS bodies(b,ord)),
     'objects',(SELECT coalesce(jsonb_agg(obj||jsonb_build_object('is_impervious',false,'shape_kind','circle',
       'shape',jsonb_build_object('cx',obj->'x_m','cy',obj->'y_m','radius',obj->'radius_m')) ORDER BY ord),'[]'::jsonb)
       FROM jsonb_array_elements(src#>'{map,objects}') WITH ORDINALITY AS objects(obj,ord)));
   IF phase='closed' THEN
     -- Solo la ricevuta server della chiusura puo usare l'arena conclusa.
     -- Nessuna riapertura, helper di movimento o lettura di un'altra scena.
     IF src#>>'{receipt,operation}' IS DISTINCT FROM 'close'
       OR (src#>>'{receipt,activity_id}')::uuid IS DISTINCT FROM sid THEN
       RAISE EXCEPTION 'panel_terminal_map_receipt_invalid' USING ERRCODE='22023'; END IF;
     SELECT i.* INTO STRICT closed_arena FROM combat_spatial.arena_instances i
       JOIN public.combat_v2_sessions s ON s.id=i.encounter_id
       JOIN combat_consumer_private.activities ac ON ac.session_id=s.id AND ac.location_id=s.location_id
       WHERE i.encounter_id=sid AND i.context_source='ordinary' AND i.state='closed'
         AND s.location_id=p_location AND s.state IN ('chiuso','annullato') AND s.closed_at IS NOT NULL
         AND ac.phase='closed' AND ac.closed_at IS NOT NULL
         AND i.map_version=(src#>>'{map,map_version}')::integer+1;
     SELECT b.* INTO STRICT closed_body FROM combat_spatial.actor_states b
       JOIN public.combat_v2_actors a ON a.id=b.actor_id AND a.session_id=sid
       WHERE b.instance_id=closed_arena.instance_id AND b.actor_id=actor
         AND b.controller_principal_id=auth.uid() AND a.controller_user=auth.uid();
     IF EXISTS(SELECT 1 FROM combat_spatial.viewer_grants g
       WHERE g.instance_id=closed_arena.instance_id AND g.viewer_principal_id=auth.uid()
         AND g.can_view_map AND g.can_view_objects) THEN
     -- Stesse forme, ID e distanze della vista aperta; soltanto dati conservati.
     SELECT coalesce(jsonb_agg(jsonb_build_object(
       'object_id',md5(closed_arena.instance_id::text||o.object_key||os.state_version)::uuid,
       'label',o.semantic_label,'state',os.state,'shape_kind',o.shape_kind,'shape',o.shape,
       'x_m',center.x,'y_m',center.y,
       'radius_m',CASE WHEN o.shape_kind='circle' THEN (o.shape->>'radius')::numeric ELSE NULL END,
       'distance_from_viewer_m',round(combat_spatial.distance_m(closed_body.x_m,closed_body.y_m,center.x,center.y),2),
       'substitution_anchor_available',false,'is_impervious',true) ORDER BY o.object_key),'[]'::jsonb)
     INTO closed_regions FROM combat_spatial.arena_objects o
       JOIN combat_spatial.object_states os ON os.instance_id=closed_arena.instance_id AND os.object_key=o.object_key
       CROSS JOIN LATERAL (SELECT (combat_spatial.shape_center(o.shape_kind,o.shape))[0]::numeric AS x,
         (combat_spatial.shape_center(o.shape_kind,o.shape))[1]::numeric AS y) center
       WHERE o.template_key=closed_arena.template_key AND o.template_version=closed_arena.template_version
         AND o.is_impervious AND os.state='available';
     map_view:=jsonb_set(map_view,'{objects}',(map_view->'objects')||closed_regions);
     SELECT * INTO closed_config FROM combat_panel_private.instance_terrain_configs
       WHERE instance_id=closed_arena.instance_id ORDER BY map_version DESC LIMIT 1;
     SELECT coalesce(jsonb_agg(jsonb_build_object(
       'object_id',md5('instance-terrain:'||closed_arena.instance_id::text||':'||closed_config.map_version||':'||(region.value->>'key'))::uuid,
       'label',region.value->>'label','state','available','shape_kind',region.value->>'shape_kind','shape',region.value->'shape',
       'x_m',center.x,'y_m',center.y,
       'radius_m',CASE WHEN region.value->>'shape_kind'='circle' THEN (region.value#>>'{shape,radius}')::numeric ELSE NULL END,
       'distance_from_viewer_m',round(combat_spatial.distance_m(closed_body.x_m,closed_body.y_m,center.x,center.y),2),
       'substitution_anchor_available',false,'is_impervious',true) ORDER BY region.value->>'key'),'[]'::jsonb)
     INTO closed_regions FROM jsonb_array_elements(coalesce(closed_config.regions,'[]'::jsonb)) AS region(value)
       CROSS JOIN LATERAL (SELECT (combat_spatial.shape_center(region.value->>'shape_kind',region.value->'shape'))[0]::numeric AS x,
         (combat_spatial.shape_center(region.value->>'shape_kind',region.value->'shape'))[1]::numeric AS y) center;
     map_view:=jsonb_set(map_view,'{objects}',(map_view->'objects')||closed_regions);
     END IF;
   ELSE
     SELECT instance_id INTO STRICT map_instance FROM combat_spatial.arena_instances
       WHERE encounter_id=sid AND context_source='ordinary' AND state='open';
     map_view:=jsonb_set(map_view,'{objects}',(map_view->'objects')
       ||combat_panel_private.impervious_map_objects(map_instance,actor));
   END IF;
 END IF;
 IF sid IS NOT NULL AND rid IS NOT NULL THEN
   narrative_meta:=combat_panel_private.narrative_details(p_location,sid,rid);
   narrative_view:=jsonb_build_object('schema_version','combat-panel-narrative/1',
     'activity_id',sid,'round_id',rid,'mode','automatic',
     'state',coalesce(src#>>'{narrative,state}','idle'),'reason_code',src#>'{narrative,reason_code}',
     'report_id',narrative_meta->'report_id','report_sha256',narrative_meta->'report_sha256',
     'last_published',narrative_meta->'last_published');
 END IF;
 multiplication:=combat_panel_private.multiplication_view(p_location,map_view->'actors');
 map_view:=combat_panel_private.multiplication_mask_map(map_view,multiplication);
 roster:=combat_panel_private.multiplication_mask_roster(roster,multiplication);
 details:=combat_panel_private.ordinary_round_details(rid,actor,roster);
 -- Nessun contatore del vecchio consumer viene spacciato per nuova versione.
 -- Il fingerprint comprende la versione sorgente e il POV gia autorizzato.
 c:=combat_panel_private.refresh_context(p_location,actor,
   CASE WHEN sid IS NULL THEN NULL ELSE 'ordinary_v2' END,sid,rid,
   (src#>>'{context,scene_version}')::bigint,jsonb_build_object('map',map_view,'multiplication',multiplication,'is_master',is_master,'is_admin',is_admin,'source',src-ARRAY['offers','receipt','entry'],'narrative',narrative_view,'round_details',details));
 RETURN jsonb_build_object('schema_version','combat-panel/1','status','ready','reason_code',null,
   'context',jsonb_build_object('activity_id',sid,'activity_kind',c.activity_kind,
     'location_id',p_location,'round_id',rid,'round_no',src#>'{context,round_no}',
     'phase',phase,'phase_label',CASE phase WHEN 'setup' THEN 'Invito allo scontro'
       WHEN 'action' THEN 'Dichiarazione azione' WHEN 'defense' THEN 'Dichiarazione difesa'
       WHEN 'resolved' THEN 'Esito dello scambio' ELSE 'Scontro concluso' END,
     'version',c.context_version,'scene_version',c.scene_version,
     'policy_id',src#>'{context,policy_id}','simulated',simulated),
   'viewer',jsonb_build_object('command_actor_id',actor,'controlled_actors',controlled,
     'is_master',is_master,'is_admin',is_admin,'can_command',src#>'{viewer,can_command}'),
   'actors',roster,'map',map_view,'offers','[]'::jsonb,'movement_explanations',null,
   'multiplication',multiplication,'companion',src->'companion','sabaku_transport',
   clan_sabaku_private.panel_view_from_ordinary(src->'sabaku_transport',
     CASE WHEN phase='closed' THEN terminal_source_version ELSE (src#>>'{context,version}')::bigint END,
     c.context_version,rid,simulated),'narrative',narrative_view,'round_details',details,'receipt',null);
END $function$;

