CREATE OR REPLACE FUNCTION combat_panel_private.offer_context_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_panel_private.contexts%ROWTYPE;
BEGIN
 SELECT * INTO STRICT c FROM combat_panel_private.contexts WHERE id=NEW.context_id;
 IF NEW.principal_user IS DISTINCT FROM c.principal_user
  OR (NEW.actor_id IS DISTINCT FROM c.command_actor_id AND NOT (NEW.kind='administration' AND NEW.actor_id IS NULL))
  OR NEW.context_version IS DISTINCT FROM c.context_version
  OR NEW.scene_version IS DISTINCT FROM c.scene_version
  OR NEW.source_fingerprint IS DISTINCT FROM c.source_fingerprint THEN
   RAISE EXCEPTION 'panel_offer_context_mismatch' USING ERRCODE='22023'; END IF;
 RETURN NEW;
END $function$;

