-- Native source combat_panel_private.ordinary_round_details(uuid,uuid,jsonb) MD5 0d2a886af8e6eaef8f048f4f985121e9

CREATE OR REPLACE FUNCTION combat_panel_private.ordinary_round_details(p_round uuid, p_actor uuid, p_roster jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; r public.combat_v2_rounds%ROWTYPE; location uuid; source jsonb;
BEGIN
 IF p_round IS NULL OR p_actor IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO r FROM public.combat_v2_rounds WHERE id=p_round;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=p_actor AND session_id=r.session_id
   AND controller_user=auth.uid() AND companion_id IS NULL;
 IF a.id IS NULL THEN RAISE EXCEPTION 'panel_actor_not_controlled' USING ERRCODE='42501'; END IF;
 SELECT location_id INTO location FROM combat_consumer_private.activities WHERE session_id=a.session_id AND exchange_id=r.id;
 IF location IS NULL OR NOT coalesce(public._combat_presente(auth.uid(),location),false) THEN RETURN NULL; END IF;
 -- Solo testi già pubblicati dalla dichiarazione, leggibili con la policy
 -- messages_read. Non esporre bozze o scelta/rating che il vecchio consumer tace.
 SELECT jsonb_build_object('round',jsonb_build_object('id',r.id),'declarations',coalesce(jsonb_agg(jsonb_build_object(
   'id',d.id,'actor_id',d.actor_id,'kind',d.kind,'text',m.body,'choice','{}'::jsonb,
   'targets','[]'::jsonb,'coverage','[]'::jsonb,'rating',NULL) ORDER BY d.created_at,d.id),'[]')) INTO source
   FROM public.combat_v2_declarations d JOIN combat_consumer_private.declaration_messages dm ON dm.declaration_id=d.id
   JOIN public.messages m ON m.id=dm.message_id AND m.location_id=location
   WHERE d.round_id=r.id AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d.actor_id::text)
     AND (m.kind<>'whisper' OR m.sender_user=auth.uid() OR m.recipient_user=auth.uid() OR public.is_staff())
     AND (m.kind<>'motore' OR public.is_staff());
 -- Un referto ordinario diventa leggibile dopo la pubblicazione narrativa;
 -- il formatter conserva soltanto risultati degli attori visibili.
 source:=source||jsonb_build_object('report',(SELECT jsonb_build_object('id',id,'mechanics',mechanics)
   FROM public.combat_v2_round_reports WHERE round_id=r.id AND narration_state='pubblicata'));
 RETURN combat_panel_private.round_details_from_source(source,p_roster);
END $function$;

