-- Native source combat_panel_private.owner_turn_context(uuid) MD5 56291b63933136f509c818dd58c4bf10

CREATE OR REPLACE FUNCTION combat_panel_private.owner_turn_context(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; ordinary combat_consumer_private.activities%ROWTYPE;
 s public.combat_v2_sessions%ROWTYPE; m public.master_v2_sessions%ROWTYPE;
 r public.combat_v2_rounds%ROWTYPE; t combat_panel_private.actor_turns%ROWTYPE;
BEGIN
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=p_actor AND companion_id IS NULL;
 IF a.id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO ordinary FROM combat_consumer_private.activities WHERE session_id=a.session_id;
 IF FOUND THEN
   RETURN jsonb_build_object('activity_kind','ordinary_v2','session_id',a.session_id,
     'round_id',ordinary.exchange_id,'personal_turn_id',ordinary.exchange_id,
     'can_move',a.state='attivo' AND ordinary.phase='action' AND ordinary.turn_actor_id=a.id);
 END IF;
 SELECT s0.* INTO s FROM public.combat_v2_sessions s0
   JOIN combat_panel_private.master_panel_sessions p ON p.master_session_id=s0.master_session_id
   WHERE s0.id=a.session_id AND s0.source_kind='master' AND s0.closed_at IS NULL;
 IF s.id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=s.master_session_id;
 SELECT * INTO r FROM public.combat_v2_rounds WHERE session_id=s.id ORDER BY round_no DESC LIMIT 1;
 SELECT * INTO t FROM combat_panel_private.actor_turns WHERE round_id=r.id AND actor_id=a.id;
 RETURN jsonb_build_object('activity_kind','master_v2','session_id',s.id,
   'round_id',r.id,'personal_turn_id',t.id,'can_move',coalesce(a.state='attivo'
     AND s.state='in_corso' AND m.stato='in_corso' AND t.state='ready'
     AND r.phase='raccolta_azioni' AND combat_panel_private.has_master_geometry(s.id),false));
END $function$;

