-- Native source combat_panel_private.prepare_master_companion(uuid) MD5 8fa803281e8c3f6635eae1d0b655ec78

CREATE OR REPLACE FUNCTION combat_panel_private.prepare_master_companion(p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ctx jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.combat_v2_actors
   WHERE id=p_actor AND controller_user=auth.uid() AND actor_kind='pg' AND companion_id IS NULL) THEN RETURN; END IF;
 ctx:=combat_panel_private.owner_turn_context(p_actor);
 IF ctx->>'activity_kind' IS DISTINCT FROM 'master_v2'
   OR NOT coalesce((ctx->>'can_move')::boolean,false) THEN RETURN; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.combat_v2_actors b
   JOIN clan_marionettisti_private.sources src ON src.id=b.companion_id AND src.is_active
   JOIN public.combat_v2_actors owner_actor ON owner_actor.id=p_actor
     AND owner_actor.session_id=b.session_id AND owner_actor.character_id=src.owner_character_id) THEN RETURN; END IF;
 PERFORM clan_marionettisti_private.ensure_initial_link(p_actor);
 PERFORM clan_marionettisti_private.start_command_window((ctx->>'round_id')::uuid);
END $function$;

