-- Native source combat_panel_private.round_details_from_source(jsonb,jsonb,jsonb) MD5 a694f93accfb3f889d5fca0eb4559e21

CREATE OR REPLACE FUNCTION combat_panel_private.round_details_from_source(p_source jsonb, p_roster jsonb, p_offers jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE d jsonb; item jsonb; child jsonb; report jsonb; outcome jsonb; actor_name text; target_name text;
 declarations jsonb:='[]'; targets jsonb; coverage jsonb; lines jsonb:='[]'; label text; rating text; offer_id uuid;
 rid uuid; report_view jsonb:=NULL; line text; target_id text;
BEGIN
 rid:=(p_source#>>'{round,id}')::uuid; IF rid IS NULL THEN RETURN NULL; END IF;
 FOR d IN SELECT value FROM jsonb_array_elements(coalesce(p_source->'declarations','[]')) LOOP
   SELECT value->>'display_name' INTO actor_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d->>'actor_id';
   IF actor_name IS NULL THEN CONTINUE; END IF;
   targets:='[]'; coverage:='[]';
   FOR item IN SELECT value FROM jsonb_array_elements(coalesce(d->'targets','[]')) LOOP
     SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=item->>'target_actor_id';
     IF target_name IS NOT NULL THEN targets:=targets||jsonb_build_array(jsonb_build_object('actor_id',item->'target_actor_id','display_name',target_name)); END IF;
   END LOOP;
   FOR item IN SELECT value FROM jsonb_array_elements(coalesce(d->'coverage','[]')) LOOP
     SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=item->>'protected_actor_id';
     IF target_name IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coverage) WHERE value->>'actor_id'=item->>'protected_actor_id') THEN
       coverage:=coverage||jsonb_build_array(jsonb_build_object('actor_id',item->'protected_actor_id','display_name',target_name));
     END IF;
   END LOOP;
   label:=coalesce(nullif(d#>>'{choice,ability_name}',''),CASE coalesce(d#>>'{choice,reaction}',d->>'kind')
     WHEN 'attacco' THEN 'Attacco' WHEN 'movimento' THEN 'Movimento' WHEN 'utilita' THEN 'Azione non offensiva'
     WHEN 'passa' THEN 'Passa' WHEN 'schivata' THEN 'Schivata' WHEN 'parata' THEN 'Parata'
     WHEN 'sostituzione' THEN 'Sostituzione' WHEN 'nessuna' THEN 'Nessuna difesa' ELSE 'Difesa' END);
   rating:=NULL;
   IF jsonb_typeof(d#>'{rating,value}')='number' THEN
     rating:='Valutazione '||(d#>>'{rating,value}')||CASE WHEN length(coalesce(d#>>'{rating,reason}',''))>0 THEN ' · '||(d#>>'{rating,reason}') ELSE '' END;
   END IF;
   SELECT (value->>'offer_id')::uuid INTO offer_id FROM jsonb_array_elements(p_offers)
     WHERE value->>'declaration_id'=d->>'id' LIMIT 1;
   declarations:=declarations||jsonb_build_array(jsonb_build_object('declaration_id',d->'id','actor_id',d->'actor_id',
     'display_name',actor_name,'kind',d->'kind','label',label,'text',coalesce(d->>'text',''),
     'targets',targets,'coverage',coverage,'rating_label',rating,'rating_offer_id',offer_id));
 END LOOP;
 report:=p_source->'report';
 IF jsonb_typeof(report)='object' AND report->>'id' IS NOT NULL THEN
   FOR d IN SELECT value FROM jsonb_array_elements(coalesce(report#>'{mechanics,declarations}','[]')) LOOP
     IF d->>'kind' IN ('difesa','nessuna') THEN CONTINUE; END IF;
     SELECT value->>'display_name' INTO actor_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d->>'actor';
     IF actor_name IS NULL THEN CONTINUE; END IF;
     outcome:=d->'outcome';
     IF jsonb_typeof(outcome->'children')='array' THEN
       FOR child IN SELECT value FROM jsonb_array_elements(outcome->'children') LOOP
         SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=child->>'target_actor_id';
         IF target_name IS NULL THEN CONTINUE; END IF;
         line:=actor_name||' → '||target_name;
         IF jsonb_typeof(child->'success')='boolean' THEN line:=line||CASE WHEN (child->>'success')::boolean THEN ': attacco riuscito' ELSE ': attacco non riuscito' END; END IF;
         IF jsonb_typeof(child->'damage_applied')='number' THEN line:=line||' · danno '||(child->>'damage_applied'); END IF;
         line:=line||combat_panel_private.multiplication_result_label(child);
         lines:=lines||jsonb_build_array(line);
       END LOOP;
     ELSE
       line:=actor_name||' · '||CASE d->>'kind' WHEN 'movimento' THEN 'Movimento' WHEN 'passa' THEN 'Passa' WHEN 'utilita' THEN 'Azione non offensiva' ELSE 'Attacco' END;
       SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d->>'target';
       IF d->>'target' IS NOT NULL AND target_name IS NULL THEN CONTINUE; END IF;
       IF target_name IS NOT NULL THEN line:=line||' → '||target_name; END IF;
       IF jsonb_typeof(outcome->'movement_m')='number' THEN line:=line||': '||(outcome->>'movement_m')::numeric::integer::text||' m'; END IF;
       IF jsonb_typeof(outcome->'success')='boolean' THEN line:=line||CASE WHEN (outcome->>'success')::boolean THEN ': riuscito' ELSE ': non riuscito' END; END IF;
       IF jsonb_typeof(outcome->'damage_applied')='number' THEN line:=line||' · danno '||(outcome->>'damage_applied'); END IF;
       line:=line||combat_panel_private.multiplication_result_label(outcome);
       line:=line||combat_panel_private.immobilization_result_label(outcome);
       lines:=lines||jsonb_build_array(line);
     END IF;
   END LOOP;
   report_view:=jsonb_build_object('report_id',report->'id','title','Risultati del round','lines',lines);
 END IF;
 RETURN jsonb_build_object('schema_version','combat-panel-round-details/1','round_id',rid,'declarations',declarations,'report',report_view);
END $function$;

