-- Native source combat_panel_private.validate_command(jsonb) MD5 344b7fcd8dc0c0d9d58095737c0fb9c9

CREATE OR REPLACE FUNCTION combat_panel_private.validate_command(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE keys constant text[]:=ARRAY['schema_version','request_key','location_id','activity_id',
 'context_version','offer_id','selected_option_ids','inputs','narrative_text'];
 uuid_pattern constant text:='^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
 k text; item jsonb; n numeric; ids uuid[]:='{}'; field_ids uuid[]:='{}'; canonical_inputs jsonb:='[]';
BEGIN
 IF p IS NULL OR jsonb_typeof(p) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'panel_command_shape_invalid' USING ERRCODE='22023'; END IF;
 IF NOT(p ?& keys) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p) AS x(k) WHERE NOT(x.k=ANY(keys))) THEN
   RAISE EXCEPTION 'panel_command_keys_invalid' USING ERRCODE='22023'; END IF;
 IF p->>'schema_version' IS DISTINCT FROM 'combat-panel-command/1' THEN
   RAISE EXCEPTION 'panel_contract_version_invalid' USING ERRCODE='22023'; END IF;
 FOREACH k IN ARRAY ARRAY['request_key','location_id','activity_id','offer_id'] LOOP
   IF k='activity_id' AND p->k='null'::jsonb THEN CONTINUE; END IF;
   IF jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR (p->>k)!~uuid_pattern THEN
     RAISE EXCEPTION 'panel_identifier_invalid' USING ERRCODE='22023'; END IF;
   p:=jsonb_set(p,ARRAY[k],to_jsonb(((p->>k)::uuid)::text),false);
 END LOOP;
 IF jsonb_typeof(p->'context_version') IS DISTINCT FROM 'number' THEN
   RAISE EXCEPTION 'panel_context_version_invalid' USING ERRCODE='22023'; END IF;
 n:=(p->>'context_version')::numeric;
 IF n<1 OR n<>trunc(n) OR n>9007199254740991 THEN
   RAISE EXCEPTION 'panel_context_version_invalid' USING ERRCODE='22023'; END IF;
 p:=jsonb_set(p,'{context_version}',to_jsonb(n::bigint),false);
 IF jsonb_typeof(p->'narrative_text') IS DISTINCT FROM 'string'
   OR jsonb_typeof(p->'selected_option_ids') IS DISTINCT FROM 'array'
   OR jsonb_typeof(p->'inputs') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'panel_command_values_invalid' USING ERRCODE='22023'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p->'selected_option_ids') LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'string' OR (item#>>'{}')!~uuid_pattern THEN
     RAISE EXCEPTION 'panel_option_identifier_invalid' USING ERRCODE='22023'; END IF;
   ids:=array_append(ids,(item#>>'{}')::uuid);
 END LOOP;
 IF cardinality(ids)<>(SELECT count(DISTINCT x) FROM unnest(ids) AS x) THEN
   RAISE EXCEPTION 'panel_duplicate_selection' USING ERRCODE='22023'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p->'inputs') LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'panel_input_shape_invalid' USING ERRCODE='22023'; END IF;
   IF NOT(item ?& ARRAY['input_id','value'])
     OR EXISTS(SELECT 1 FROM jsonb_object_keys(item) AS x(k) WHERE x.k NOT IN ('input_id','value'))
     OR jsonb_typeof(item->'input_id') IS DISTINCT FROM 'string' OR (item->>'input_id')!~uuid_pattern
     OR jsonb_typeof(item->'value') NOT IN ('string','boolean') THEN
     RAISE EXCEPTION 'panel_input_shape_invalid' USING ERRCODE='22023'; END IF;
   field_ids:=array_append(field_ids,(item->>'input_id')::uuid);
   canonical_inputs:=canonical_inputs||jsonb_build_array(jsonb_build_object(
     'input_id',((item->>'input_id')::uuid)::text,'value',item->'value'));
 END LOOP;
 IF cardinality(field_ids)<>(SELECT count(DISTINCT x) FROM unnest(field_ids) AS x) THEN
   RAISE EXCEPTION 'panel_duplicate_input' USING ERRCODE='22023'; END IF;
 -- Le selezioni sono insiemi; l'ordine degli effetti proviene dagli ordinali
 -- server, non dall'ordine dei click. Canonicalizzare anche per il replay.
 p:=jsonb_set(p,'{selected_option_ids}',coalesce((SELECT jsonb_agg(x ORDER BY x) FROM unnest(ids) AS x),'[]'::jsonb),false);
 p:=jsonb_set(p,'{inputs}',coalesce((SELECT jsonb_agg(value ORDER BY value->>'input_id')
   FROM jsonb_array_elements(canonical_inputs)),'[]'::jsonb),false);
 RETURN p;
END $function$;

