-- Native source combat_panel_private.validate_instance_terrain(jsonb,numeric,numeric) MD5 6ff7dd3279da511493109aa4a95451c6

CREATE OR REPLACE FUNCTION combat_panel_private.validate_instance_terrain(p_regions jsonb, p_width numeric, p_height numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r jsonb;s jsonb; seen text[]:=ARRAY[]::text[];result jsonb;
BEGIN
 IF jsonb_typeof(p_regions) IS DISTINCT FROM 'array' OR p_width IS NULL OR p_height IS NULL
   OR p_width<=0 OR p_height<=0 OR p_width IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
   OR p_height IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
  RAISE EXCEPTION 'panel_terrain_config_invalid' USING ERRCODE='22023'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_regions) LOOP
  IF jsonb_typeof(r) IS DISTINCT FROM 'object'
    OR r-ARRAY['key','label','shape_kind','shape']<>'{}'::jsonb
    OR NOT r?&ARRAY['key','label','shape_kind','shape']
    OR jsonb_typeof(r->'key') IS DISTINCT FROM 'string'
    OR jsonb_typeof(r->'label') IS DISTINCT FROM 'string'
    OR jsonb_typeof(r->'shape_kind') IS DISTINCT FROM 'string'
    OR btrim(r->>'key')='' OR btrim(r->>'label')='' OR (r->>'key')=ANY(seen) THEN
   RAISE EXCEPTION 'panel_terrain_config_invalid' USING ERRCODE='22023'; END IF;
  seen:=array_append(seen,r->>'key');s:=r->'shape';
  PERFORM combat_panel_private.impervious_segment_interval(0,0,0,0,r->>'shape_kind',s);
  IF ((r->>'shape_kind')='aabb' AND ((s->>'min_x')::numeric<0 OR (s->>'min_y')::numeric<0
    OR (s->>'max_x')::numeric>p_width OR (s->>'max_y')::numeric>p_height))
    OR ((r->>'shape_kind')='circle' AND ((s->>'cx')::numeric-(s->>'radius')::numeric<0
    OR (s->>'cy')::numeric-(s->>'radius')::numeric<0
    OR (s->>'cx')::numeric+(s->>'radius')::numeric>p_width
    OR (s->>'cy')::numeric+(s->>'radius')::numeric>p_height)) THEN
   RAISE EXCEPTION 'panel_terrain_config_outside_arena' USING ERRCODE='22023'; END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'key'),'[]'::jsonb) INTO result
  FROM jsonb_array_elements(p_regions);
 RETURN result;
END $function$;

