-- Native source combat_spatial.exam_substitution_context_v1(uuid,uuid) MD5 3aac7c35e496b57f06bd0d99d427750a

CREATE OR REPLACE FUNCTION combat_spatial.exam_substitution_context_v1(p_prova uuid, p_source uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.esame_prove%rowtype; s combat_spatial.exam_substitution_sources_v1%rowtype;
  c public.characters%rowtype; prof public.esame_png_profili%rowtype;
  nin integer; chakra integer; owned boolean; profile text; actor_id uuid; source_sha text;
begin
  select * into strict p from public.esame_prove where id=p_prova and stato='aperta';
  select * into strict s from combat_spatial.exam_substitution_sources_v1
   where source_application_id=p_source and prova_id=p_prova and state in ('open','selected');
  if p.scambio<>s.round_no or p.fase is distinct from s.phase_snapshot
     or p.meta is distinct from s.meta_snapshot then
    raise exception using errcode='23514',message='exam_substitution_parent_window_invalid';
  end if;
  if s.defender_key='candidate' then
    select * into strict c from public.characters where id=p.candidate_character and user_id=p.candidate_user;
    nin:=c.ninjutsu; chakra:=p.ck_cand; actor_id:=s.defender_actor_id;
    select exists(select 1 from public.character_jutsu cj join public.jutsu j on j.id=cj.jutsu_id
      where cj.user_id=p.candidate_user and j.id='31b15861-fb78-4f8a-ac1c-ebf2d957c32e'::uuid
        and j.is_active and j.chakra_cost=5 and j.action_type='reazione'
        and j.uso='difesa' and j.difensiva) into owned;
  else
    select * into strict prof from public.esame_png_profili where id=p.profilo_id and is_active;
    nin:=prof.ninjutsu; chakra:=p.ck_png; actor_id:=s.defender_actor_id;
    owned:='31b15861-fb78-4f8a-ac1c-ebf2d957c32e'::uuid=any(prof.repertorio);
  end if;
  if not owned then raise exception using errcode='23514',message='exam_substitution_source_not_owned_or_active'; end if;
  if chakra<5 then raise exception using errcode='23514',message='exam_substitution_resource_unavailable'; end if;
  profile:=combat_spatial.substitution_range_profile_v1(nin);
  source_sha:=encode(extensions.digest(convert_to('exam-substitution-source/1.0:'||
    jsonb_build_object('prova',p.id,'source',s.source_application_id,'round',p.scambio,
      'phase',p.fase,'meta',p.meta,'defender',s.defender_key,'actor',actor_id,
      'ninjutsu',nin,'chakra',chakra,'profile',profile)::text,'UTF8'),'sha256'),'hex');
  return jsonb_build_object('prova_id',p.id,'instance_id',s.instance_id,
    'source_application_id',s.source_application_id,'round_no',p.scambio,
    'defender_key',s.defender_key,'defender_actor_id',actor_id,'ninjutsu',nin,
    'chakra',chakra,'source_profile_id',profile,'source_snapshot_sha256',source_sha);
end
$function$;

