-- Native source combat_spatial.integer_path_points(numeric,numeric,numeric,numeric) MD5 3014ab0ec6107b6e769fcd6281673062

CREATE OR REPLACE FUNCTION combat_spatial.integer_path_points(p_x0 numeric, p_y0 numeric, p_x1 numeric, p_y1 numeric)
 RETURNS TABLE(step integer, x_m numeric, y_m numeric, distance_m numeric)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE sx numeric;sy numeric;ex numeric;ey numeric;n integer;k integer;x numeric;y numeric;px numeric;py numeric;v numeric;
BEGIN
 FOREACH v IN ARRAY ARRAY[p_x0,p_y0,p_x1,p_y1] LOOP
  IF v IS NULL OR v IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN
   RAISE EXCEPTION 'integer_path_coordinate_invalid' USING ERRCODE='22023';END IF;
 END LOOP;
 sx:=round(p_x0);sy:=round(p_y0);ex:=round(p_x1);ey:=round(p_y1);
 IF abs(ex-sx)+abs(ey-sy)>10000 THEN RAISE EXCEPTION 'integer_path_too_long' USING ERRCODE='22023';END IF;
 n:=(abs(ex-sx)+abs(ey-sy))::integer;
 FOR k IN 0..n LOOP
  x:=CASE WHEN n=0 THEN sx ELSE round(sx+(ex-sx)*k/n) END;
  y:=CASE WHEN n=0 THEN sy ELSE round(sy+(ey-sy)*k/n) END;
  IF px IS NOT NULL AND (x,y)=(px,py) THEN CONTINUE;END IF;
  step:=k;x_m:=x;y_m:=y;distance_m:=abs(x-sx)+abs(y-sy);RETURN NEXT;px:=x;py:=y;
 END LOOP;
END $function$;

