CREATE OR REPLACE FUNCTION combat_spatial.map_projection(p_instance uuid, p_viewer_principal uuid, p_round integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i combat_spatial.arena_instances%rowtype; t combat_spatial.arena_templates%rowtype;
begin
  select * into strict i from combat_spatial.arena_instances where instance_id=p_instance and state='open';
  select * into strict t from combat_spatial.arena_templates where template_key=i.template_key and template_version=i.template_version;
  if not exists(select 1 from combat_spatial.viewer_grants where instance_id=p_instance and viewer_principal_id=p_viewer_principal and can_view_map) then raise exception 'spatial_viewer_not_authorized'; end if;
  return jsonb_build_object('map_version',i.map_version,'readonly',true,
    'bounds',jsonb_build_object('width_m',t.width_m,'height_m',t.height_m,'grid_m',1,'reference_grid_m',5),
    'actors',(select coalesce(jsonb_agg(jsonb_build_object('subject',a.projection_subject_id,'x_m',a.x_m,'y_m',a.y_m,'radius_m',a.footprint_radius_m) order by a.slot_key),'[]')
      from combat_spatial.actor_states a join combat_spatial.viewer_grants g on g.instance_id=a.instance_id and g.subject_actor_id=a.actor_id
      where a.instance_id=p_instance and a.state='active' and g.viewer_principal_id=p_viewer_principal and g.can_view_map),
    'objects',(select case when exists(select 1 from combat_spatial.viewer_grants where instance_id=p_instance and viewer_principal_id=p_viewer_principal and can_view_objects)
      then coalesce(jsonb_agg(jsonb_build_object(
        'object',md5(p_instance::text||o.object_key||s.state_version)::uuid,
        'label',o.semantic_label,'state',s.state,'substitutable',o.substitutable,
        'shape_kind',o.shape_kind,'shape',o.shape,
        'reachability',case when o.substitutable then (
          select coalesce(jsonb_agg(jsonb_build_object(
            'subject',a.projection_subject_id,
            'distance_m',round(combat_spatial.distance_m(a.x_m,a.y_m,(combat_spatial.shape_center(o.shape_kind,o.shape))[0]::numeric,(combat_spatial.shape_center(o.shape_kind,o.shape))[1]::numeric),2),
            'legal_profiles',(select coalesce(jsonb_agg(r.profile_id order by r.max_range_m),'[]') from combat_spatial.source_range_profiles r where r.source_family='substitution' and combat_spatial.anchor_is_legal(p_instance,a.actor_id,o.object_key,r.profile_id,p_round))
          ) order by a.slot_key),'[]')
          from combat_spatial.actor_states a where a.instance_id=p_instance and a.state='active' and a.controller_principal_id=p_viewer_principal
        ) else '[]'::jsonb end
      ) order by o.object_key),'[]') else '[]'::jsonb end
      from combat_spatial.object_states s join combat_spatial.arena_objects o on o.template_key=i.template_key and o.template_version=i.template_version and o.object_key=s.object_key where s.instance_id=p_instance));
end $function$;

