-- Native source combat_spatial.movement_options(uuid,uuid,numeric) MD5 cea9561628547a87b83cbda9e69822c3

CREATE OR REPLACE FUNCTION combat_spatial.movement_options(p_instance uuid, p_actor uuid, p_budget numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i combat_spatial.arena_instances%rowtype; a combat_spatial.actor_states%rowtype; c record; id uuid; out jsonb:='[]'; t numeric; d numeric; shared boolean; regions jsonb; terrain jsonb; regions_fp text; accepted_budget numeric;endpoint jsonb;
begin
  shared:=combat_panel_private.shared_movement_scope(p_instance);
  if shared and (p_budget is null or p_budget<0 or p_budget in ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)) then
    raise exception 'panel_movement_budget_invalid' using errcode='22023'; end if;
  if shared
    and combat_panel_private.movement_block_reason(p_actor) is not null then return '[]'::jsonb; end if;
  select * into strict i from combat_spatial.arena_instances where instance_id=p_instance and state='open' for update;
  select * into strict a from combat_spatial.actor_states where instance_id=p_instance and actor_id=p_actor and state='active' for update;
  if shared then regions:=combat_panel_private.movement_regions_for_body(p_instance,p_actor);regions_fp:=md5(regions::text);end if;
  if shared then
    -- Storia immutabile dei numeri: si ritirano le offerte superate, non si
    -- riscrivono budget/coordinate sotto un ID già consegnato al client.
    update combat_spatial.movement_capabilities cap set state='stale'
    where cap.instance_id=p_instance and cap.actor_id=p_actor and cap.state='offered'
      and not exists(select 1 from combat_spatial.movement_semantic_choices ch
        join combat_panel_private.movement_cost_capabilities cost on cost.capability_id=cap.capability_id
        where ch.instance_id=p_instance and ch.actor_id=p_actor and ch.choice_key=cap.choice_key
          and ch.enabled and cap.actor_body_version=a.body_version
          and cap.choice_version=ch.choice_version and cap.map_version=i.map_version
          and cost.regions_fingerprint=regions_fp and cost.budget_m=least(p_budget,ch.max_budget_m));
  end if;
  for c in select * from combat_spatial.movement_semantic_choices where instance_id=p_instance and actor_id=p_actor and enabled order by choice_key loop
    d:=combat_spatial.distance_m(a.x_m,a.y_m,c.endpoint_x_m,c.endpoint_y_m);
    if d<=least(p_budget,c.max_budget_m) then
      accepted_budget:=floor(least(p_budget,c.max_budget_m));
      endpoint:=combat_panel_private.integer_movement_endpoint(p_instance,p_actor,a.x_m,a.y_m,
        c.endpoint_x_m,c.endpoint_y_m,accepted_budget,CASE WHEN shared THEN regions ELSE '[]'::jsonb END);
      t:=CASE WHEN (endpoint->>'distance_m')::numeric>0 THEN 1 ELSE 0 END;
      if t>0 then
        if shared then
          select capability_id into id from combat_spatial.movement_capabilities
            where instance_id=p_instance and actor_id=p_actor and choice_key=c.choice_key and state='offered';
          if not found then id:=gen_random_uuid(); end if;
        else
          id:=md5(p_instance::text||p_actor::text||c.choice_key||a.body_version||c.choice_version||i.map_version)::uuid;
        end if;
        insert into combat_spatial.movement_capabilities values(id,p_instance,p_actor,c.choice_key,a.x_m,a.y_m,
          (endpoint->>'x_m')::numeric,(endpoint->>'y_m')::numeric,a.body_version,c.choice_version,i.map_version,'offered')
        on conflict (capability_id) do nothing;
        if shared then
          insert into combat_panel_private.movement_cost_capabilities(capability_id,budget_m,regions_fingerprint)
            values(id,accepted_budget,regions_fp) on conflict do nothing;
        end if;
        -- The capability columns are the authoritative stored coordinates.
        -- Clipping then centimetre storage may differ from the continuous d*t.
        select round(combat_spatial.distance_m(cap.start_x_m,cap.start_y_m,cap.end_x_m,cap.end_y_m))
          into strict d from combat_spatial.movement_capabilities cap where cap.capability_id=id;
        out:=out||jsonb_build_array(jsonb_build_object('option_id',id,'intent',c.choice_key,'distance_m',d));
      end if;
    end if;
  end loop;
  return out;
end $function$;

