-- Native source combat_spatial.segment_aabb_first_t(numeric,numeric,numeric,numeric,numeric,numeric,numeric,numeric,numeric) MD5 9d10a911ad42bf57a6dffa5da3ef9a87

CREATE OR REPLACE FUNCTION combat_spatial.segment_aabb_first_t(p_x1 numeric, p_y1 numeric, p_x2 numeric, p_y2 numeric, p_min_x numeric, p_min_y numeric, p_max_x numeric, p_max_y numeric, p_expand numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare dx numeric:=p_x2-p_x1; dy numeric:=p_y2-p_y1;
  lo numeric:=0; hi numeric:=1; a numeric; b numeric; tmp numeric;
begin
  if p_x1 between p_min_x-p_expand and p_max_x+p_expand
     and p_y1 between p_min_y-p_expand and p_max_y+p_expand then return 0; end if;
  if dx=0 then
    if p_x1<p_min_x-p_expand or p_x1>p_max_x+p_expand then return null; end if;
  else
    a:=(p_min_x-p_expand-p_x1)/dx; b:=(p_max_x+p_expand-p_x1)/dx;
    if a>b then tmp:=a;a:=b;b:=tmp;end if; lo:=greatest(lo,a);hi:=least(hi,b);
    if lo>hi then return null; end if;
  end if;
  if dy=0 then
    if p_y1<p_min_y-p_expand or p_y1>p_max_y+p_expand then return null; end if;
  else
    a:=(p_min_y-p_expand-p_y1)/dy; b:=(p_max_y+p_expand-p_y1)/dy;
    if a>b then tmp:=a;a:=b;b:=tmp;end if; lo:=greatest(lo,a);hi:=least(hi,b);
    if lo>hi then return null; end if;
  end if;
  if hi<0 or lo>1 then return null; end if;
  return greatest(0,lo);
end $function$;

