-- Native source combat_spatial.segment_circle_first_t(numeric,numeric,numeric,numeric,numeric,numeric,numeric) MD5 9974101440eb57320b750e06db50cb18

CREATE OR REPLACE FUNCTION combat_spatial.segment_circle_first_t(p_x1 numeric, p_y1 numeric, p_x2 numeric, p_y2 numeric, p_cx numeric, p_cy numeric, p_radius numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare dx numeric:=p_x2-p_x1; dy numeric:=p_y2-p_y1;
  fx numeric:=p_x1-p_cx; fy numeric:=p_y1-p_cy;
  a numeric:=dx*dx+dy*dy; b numeric; c numeric; d numeric; t numeric;
begin
  if fx*fx+fy*fy<=p_radius*p_radius then return 0; end if;
  if a=0 then return null; end if;
  b:=2*(fx*dx+fy*dy); c:=fx*fx+fy*fy-p_radius*p_radius; d:=b*b-4*a*c;
  if d<0 then return null; end if;
  t:=(-b-sqrt(d))/(2*a);
  if t between 0 and 1 then return t; end if;
  t:=(-b+sqrt(d))/(2*a);
  if t between 0 and 1 then return t; end if;
  return null;
end $function$;

