-- Native source combat_spatial.substitution_commit(uuid,uuid,uuid) MD5 8930462fa9e17aced83bc41cc14a786a

CREATE OR REPLACE FUNCTION combat_spatial.substitution_commit(p_capability uuid, p_request_key uuid, p_root uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c combat_spatial.substitution_capabilities%rowtype; i combat_spatial.arena_instances%rowtype; w combat_spatial.defense_windows%rowtype;
  a combat_spatial.actor_states%rowtype; os combat_spatial.object_states%rowtype; o combat_spatial.arena_objects%rowtype; q point;
  fp text; replay jsonb; eid uuid; result jsonb;
begin
  fp:=combat_spatial.server_fingerprint('substitution_commit',jsonb_build_object('capability',p_capability,'root',p_root));
  replay:=combat_spatial.receipt_replay(p_request_key,'substitution_commit',fp); if replay is not null then return replay; end if;
  select * into strict c from combat_spatial.substitution_capabilities where capability_id=p_capability;
  select * into strict i from combat_spatial.arena_instances where instance_id=c.instance_id for update;
  select * into strict w from combat_spatial.defense_windows where instance_id=c.instance_id and defense_window_id=c.defense_window_id for update;
  select * into strict a from combat_spatial.actor_states where instance_id=c.instance_id and actor_id=c.defender_actor_id for update;
  select * into strict os from combat_spatial.object_states where instance_id=c.instance_id and object_key=c.object_key for update;
  select * into strict o from combat_spatial.arena_objects where template_key=i.template_key and template_version=i.template_version and object_key=c.object_key;
  if c.state<>'offered' or w.state<>'open' or w.window_version<>c.window_version or a.body_version<>c.actor_body_version or os.state_version<>c.object_state_version or i.map_version<>c.map_version
     or not combat_spatial.anchor_is_legal(c.instance_id,c.defender_actor_id,c.object_key,c.source_profile_id,c.round_no) then raise exception 'spatial_capability_stale'; end if;
  q:=combat_spatial.integer_anchor_point(o.shape_kind,o.shape); eid:=md5(c.instance_id::text||p_root::text||p_capability::text)::uuid;
  update combat_spatial.defense_windows set state='committed',window_version=window_version+1 where instance_id=c.instance_id and defense_window_id=c.defense_window_id;
  update combat_spatial.object_states set state='consumed_non_substitutable',state_version=state_version+1,reserved_by=c.defender_actor_id,consumed_event_id=eid,proxy_x_m=a.x_m,proxy_y_m=a.y_m where instance_id=c.instance_id and object_key=c.object_key;
  update combat_spatial.actor_states set x_m=q[0]::numeric,y_m=q[1]::numeric,body_version=body_version+1 where instance_id=c.instance_id and actor_id=c.defender_actor_id;
  update combat_spatial.arena_instances set map_version=map_version+1 where instance_id=c.instance_id;
  insert into combat_spatial.substitution_cooldowns values(c.instance_id,c.defender_actor_id,c.round_no,1) on conflict(instance_id,actor_id) do update set last_commit_round=excluded.last_commit_round,version=combat_spatial.substitution_cooldowns.version+1;
  update combat_spatial.substitution_capabilities set state='committed' where capability_id=p_capability;
  update combat_spatial.substitution_capabilities set state='expired' where instance_id=c.instance_id and defense_window_id=c.defense_window_id and capability_id<>p_capability and state='offered';
  insert into combat_spatial.spatial_events values(eid,c.instance_id,'substitution_committed',p_root,c.defender_actor_id,c.object_key,
    jsonb_build_object('body_version',a.body_version,'anchor_version',os.state_version),jsonb_build_object('body_version',a.body_version+1,'anchor_state','consumed_non_substitutable'),
    jsonb_build_object('before','impatto imminente','impact','sostituzione riuscita','anchor_semantic_label',o.semantic_label,'after','riapparizione al punto di scambio','substitution_link',eid),clock_timestamp());
  result:=jsonb_build_object('event_id',eid,'status','committed','replayed',false);
  insert into combat_spatial.request_receipts values(p_request_key,'substitution_commit',fp,result,clock_timestamp()); return result;
end $function$;

