-- Native source combat_spatial.substitution_options(uuid,uuid,uuid,text,integer) MD5 1ac773e2a6869947807ac4c81081fde8

CREATE OR REPLACE FUNCTION combat_spatial.substitution_options(p_instance uuid, p_window uuid, p_actor uuid, p_profile text, p_round integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i combat_spatial.arena_instances%rowtype; a combat_spatial.actor_states%rowtype; w combat_spatial.defense_windows%rowtype; o record; q point; id uuid; out jsonb:='[]';
begin
  select * into strict i from combat_spatial.arena_instances where instance_id=p_instance and state='open';
  select * into strict a from combat_spatial.actor_states where instance_id=p_instance and actor_id=p_actor and state='active';
  select * into strict w from combat_spatial.defense_windows where instance_id=p_instance and defense_window_id=p_window and defender_actor_id=p_actor and round_no=p_round and state='open';
  if not exists(select 1 from combat_spatial.source_range_profiles where profile_id=p_profile) then raise exception 'spatial_profile_not_ready'; end if;
  for o in select x.*,s.state_version from combat_spatial.arena_objects x join combat_spatial.object_states s using(object_key)
    where x.template_key=i.template_key and x.template_version=i.template_version and s.instance_id=p_instance and x.substitutable and s.state='available' order by x.object_key
  loop
    if combat_spatial.anchor_is_legal(p_instance,p_actor,o.object_key,p_profile,p_round) then
      id:=md5(p_instance::text||p_window::text||p_actor::text||o.object_key||a.body_version||o.state_version||w.window_version||i.map_version||p_profile)::uuid;
      insert into combat_spatial.substitution_capabilities values(id,p_instance,p_window,p_actor,o.object_key,p_profile,p_round,a.body_version,o.state_version,w.window_version,i.map_version,'offered',clock_timestamp()) on conflict do nothing;
      q:=combat_spatial.shape_center(o.shape_kind,o.shape);
      out:=out||jsonb_build_array(jsonb_build_object('option_id',id,'label',o.semantic_label,'distance_m',round(combat_spatial.distance_m(a.x_m,a.y_m,q[0]::numeric,q[1]::numeric),2)));
    end if;
  end loop;
  return out;
end $function$;

