-- Native source combat_spatial.substitution_rebase_selected_internal_v1(uuid) MD5 a2d7485c1f5304c02b858bfb52060701

CREATE OR REPLACE FUNCTION combat_spatial.substitution_rebase_selected_internal_v1(p_defense uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare x record; i combat_spatial.arena_instances%rowtype;
begin
  if current_user not in ('postgres','service_role') then
    raise exception using errcode='42501',message='service_role_required';
  end if;
  select o.state option_state,l.state link_state,c.*,w.state window_state,w.window_version current_window,
    a.body_version current_body,os.state object_state,os.state_version current_object
  into strict x
  from combat_spatial.substitution_activity_options o
  join combat_spatial.substitution_activity_links l using(link_id)
  join combat_spatial.substitution_capabilities c using(capability_id)
  join combat_spatial.defense_windows w on w.instance_id=c.instance_id and w.defense_window_id=c.defense_window_id
  join combat_spatial.actor_states a on a.instance_id=c.instance_id and a.actor_id=c.defender_actor_id
  join combat_spatial.object_states os on os.instance_id=c.instance_id and os.object_key=c.object_key
  where o.selected_defense_declaration_id=p_defense
  for update of o,l,c,w,a,os;
  select * into strict i from combat_spatial.arena_instances where instance_id=x.instance_id for update;
  if x.option_state<>'selected' or x.link_state<>'selected' or x.state<>'offered'
     or x.window_state<>'open' or x.current_window<>x.window_version
     or x.current_body<>x.actor_body_version or x.object_state<>'available'
     or x.current_object<>x.object_state_version
     or not combat_spatial.anchor_is_legal(x.instance_id,x.defender_actor_id,x.object_key,x.source_profile_id,x.round_no)
  then raise exception using errcode='23514',message='substitution_option_stale'; end if;
  -- Solo la versione globale viene riallineata: option id, anchor, body,
  -- object e parent window restano gli stessi e sono stati rivalidati sopra.
  update combat_spatial.substitution_capabilities set map_version=i.map_version
  where capability_id=x.capability_id;
end
$function$;

