-- Native source combat_spatial.template_errors(text,integer) MD5 1f75a8db55e0de027552b3b0dd26d55b

CREATE OR REPLACE FUNCTION combat_spatial.template_errors(p_template text, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t combat_spatial.arena_templates%rowtype; e text[]:=array[]::text[]; n integer; s record;
begin
  select * into t from combat_spatial.arena_templates where template_key=p_template and template_version=p_version;
  if not found then return jsonb_build_array('spatial_template_missing'); end if;
  if t.status<>'ready' then e:=array_append(e,'spatial_template_not_ready'); end if;
  if combat_spatial.geometry_fingerprint(p_template,p_version)<>t.geometry_hash then e:=array_append(e,'spatial_geometry_hash_mismatch'); end if;
  if exists(select 1 from unnest(t.required_shape_keys) k where not exists(
    select 1 from combat_spatial.arena_objects o where o.template_key=p_template and o.template_version=p_version and o.object_key=k
  )) then e:=array_append(e,'spatial_required_shape_missing'); end if;
  if p_template='ordinary_neutral_v1' and p_version=1 then
    -- Gli altri template percorrono esattamente il validatore precedente.
    if t.width_m<>20 or t.height_m<>20 or t.actor_radius_m<>0.5
      or t.required_shape_keys IS DISTINCT FROM ARRAY['LOG-A','LOG-B']::text[] then
      e:=array_append(e,'neutral_bounds_or_required_shapes');
    end if;
    select count(*) into n from combat_spatial.arena_slots where template_key=p_template and template_version=p_version;
    if n<>2 then e:=array_append(e,'neutral_slots_not_exact2'); end if;
    select count(*) into n from combat_spatial.arena_slots
    where template_key=p_template and template_version=p_version and actor_kind='PG'
      and ((slot_key='PG-A' and x_m=7.5 and y_m=10) or (slot_key='PG-B' and x_m=12.5 and y_m=10));
    if n<>2 then e:=array_append(e,'neutral_spawns_mismatch'); end if;
    select count(*) into n from combat_spatial.arena_objects where template_key=p_template and template_version=p_version;
    if n<>2 then e:=array_append(e,'neutral_objects_not_exact2'); end if;
    select count(*) into n from combat_spatial.arena_objects
    where template_key=p_template and template_version=p_version
      and object_kind='substitution_anchor' and lifecycle='portable_single_use'
      and substitutable and blocks_movement and shape_kind='circle' and geometry_version=1
      and ((object_key='LOG-A' and semantic_label='Tronchetto A' and shape='{"cx":7.5,"cy":12,"radius":0.25}'::jsonb)
        or (object_key='LOG-B' and semantic_label='Tronchetto B' and shape='{"cx":12.5,"cy":8,"radius":0.25}'::jsonb));
    if n<>2 then e:=array_append(e,'neutral_anchors_mismatch'); end if;
    -- Bounds e piena clearance degli spawn: disco PG0.5 e supporto0.25.
    if exists(select 1 from combat_spatial.arena_slots slot_row
      where slot_row.template_key=p_template and slot_row.template_version=p_version
        and (slot_row.x_m<0.5 or slot_row.x_m>19.5 or slot_row.y_m<0.5 or slot_row.y_m>19.5
          or exists(select 1 from combat_spatial.arena_objects o
            where o.template_key=p_template and o.template_version=p_version
              and combat_spatial.distance_m(slot_row.x_m,slot_row.y_m,(o.shape->>'cx')::numeric,(o.shape->>'cy')::numeric)<0.75))) then
      e:=array_append(e,'neutral_spawn_clearance');
    end if;
    return to_jsonb(e);
  end if;
  select count(*) into n from combat_spatial.arena_slots where template_key=p_template and template_version=p_version;
  if n<>4 then e:=array_append(e,'spatial_slots_not_exact4'); end if;
  select count(*) into n from combat_spatial.arena_objects where template_key=p_template and template_version=p_version and substitutable and lifecycle='portable_single_use';
  if n<>4 then e:=array_append(e,'spatial_anchors_not_exact4'); end if;
  for s in select * from combat_spatial.arena_slots where template_key=p_template and template_version=p_version loop
    select count(*) into n from combat_spatial.arena_objects o
    where o.template_key=p_template and o.template_version=p_version and o.substitutable
      and combat_spatial.distance_m(s.x_m,s.y_m,(combat_spatial.shape_center(o.shape_kind,o.shape))[0]::numeric,(combat_spatial.shape_center(o.shape_kind,o.shape))[1]::numeric)<=3;
    if n<>1 then e:=array_append(e,'spatial_slot_anchor3_not_exact1:'||s.slot_key); end if;
  end loop;
  return to_jsonb(e);
end $function$;

