CREATE OR REPLACE FUNCTION combat_v2_composite_internal.authorize(p_round uuid, p_actor uuid, p_scope text, p_request_key uuid, p_ai_capability uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.combat_v2_rounds%rowtype;a public.combat_v2_actors%rowtype;cap combat_v2_composite_internal.ai_capabilities%rowtype;
begin
 select * into r from public.combat_v2_rounds where id=p_round;select * into a from public.combat_v2_actors where id=p_actor;
 if r.id is null or a.id is null or a.session_id<>r.session_id then perform public.combat_v2_fail('scope_non_valido','Round o attore non valido.',409,p_request_key,'{}');end if;
 if p_ai_capability is null then
   if auth.uid() is null or a.controller_user is distinct from auth.uid() then perform public.combat_v2_fail('attore_non_controllato','Non controlli questo attore.',403,p_request_key,'{}');end if;return 'human';
 end if;
 if not public.combat_v2_is_service() then perform public.combat_v2_fail('capability_non_autorizzata','Capability IA riservata al servizio.',403,p_request_key,'{}');end if;
 select * into cap from combat_v2_composite_internal.ai_capabilities where capability_id=p_ai_capability for update;
 if cap.capability_id is null or cap.master_session_id is distinct from (select master_session_id from public.combat_v2_sessions where id=r.session_id) or cap.combat_session_id<>r.session_id or cap.round_id<>p_round or cap.actor_id<>p_actor or cap.controller_version<>a.controller_version or cap.scope<>p_scope or cap.state='revoked' then perform public.combat_v2_fail('capability_scope_mismatch','Capability IA fuori scope o revocata.',403,p_request_key,'{}');end if;
 if not exists(select 1 from public.mission_run_state mrs join public.mission_run_canary_bindings b on b.master_session_id=mrs.master_session_id join public.master_v2_sessions ms on ms.id=mrs.master_session_id where mrs.master_session_id=cap.master_session_id and b.state='active' and b.selected_by_kind='ai_service' and b.selected_by_service_capability=cap.source_capability_id and ms.owner_kind='ai_service' and ms.stato in('aperta','in_corso') and mrs.run_phase not in('closed','aborted','completed')) then perform public.combat_v2_fail('capability_authority_missing','Autorità Mission Run non più valida.',403,p_request_key,'{}');end if;
 if cap.state='consumed' and cap.consumed_request_key is distinct from p_request_key then perform public.combat_v2_fail('capability_consumed','Capability IA già consumata.',409,p_request_key,'{}');end if;
 if cap.state='offered' then update combat_v2_composite_internal.ai_capabilities set state='consumed',consumed_request_key=p_request_key,consumed_at=clock_timestamp() where capability_id=p_ai_capability;end if;
 return 'ai_service';
end $function$;

