 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.combat_v2_rounds%rowtype;a public.combat_v2_actors%rowtype;t public.clan_techniques%rowtype;common_result jsonb;result jsonb;principal text;
begin
 if p_request_key is null then perform public.combat_v2_fail('autenticazione_richiesta','Autenticazione richiesta.',401,p_request_key,'{}');end if;perform public.combat_v2_lock_round(p_round);
 select * into r from public.combat_v2_rounds where id=p_round for update;select * into a from public.combat_v2_actors where id=p_actor for update;principal:=combat_v2_composite_internal.authorize(p_round,p_actor,'innate_toggle',p_request_key,p_ai_capability);
 if r.id is null or a.id is null or a.session_id<>r.session_id or r.phase not in('raccolta_azioni','raccolta_difese') then perform public.combat_v2_fail('toggle_non_disponibile','Toggle Innata non disponibile.',409,p_request_key,'{}');end if;
 select * into t from public.clan_techniques where id=p_technique and is_active and is_innata and consumption_type='per_turno';if t.id is null or public.combat_v2_actor_ability(p_actor,'clan',p_technique,false) is null then perform public.combat_v2_fail('innata_non_offerta','Innata non offerta.',422,p_request_key,'{}');end if;
 if principal<>'human' then perform public.combat_v2_fail('common_authority_receipt_required','Il toggle IA richiede una receipt narrativa Common exact; il wire legacy non la trasporta.',409,p_request_key,'{}');end if;
 if clan_innata_private.current_actor() is distinct from a.character_id then perform public.combat_v2_fail('common_actor_scope_mismatch','La capability Common non appartiene al personaggio del combat actor.',403,p_request_key,'{}');end if;
 common_result:=public.clan_genin_innata_state_set_v1(p_technique,p_enabled,p_request_key,coalesce((select (x->>'state_version')::bigint from jsonb_array_elements(public.clan_genin_innata_state_get_v1())x where (x->>'technique_id')::uuid=p_technique),0));
 if common_result->>'schema_version' is distinct from 'clan-innata-state/1.0'
 or (common_result->>'technique_id')::uuid is distinct from p_technique
 or coalesce((common_result->>'main_action_consumed')::boolean,true) then perform public.combat_v2_fail('common_receipt_drift','Receipt Common non compatibile.',409,p_request_key,'{}');end if;
 result:=public.combat_v2_envelope(p_request_key,jsonb_build_object('schema_version','combat-v2-innate-toggle-result/1.0','active',(common_result->>'active')::boolean,'changed',coalesce((common_result->>'state_version')::bigint,0)>0,'inherited',false,'chakra_cost',coalesce((common_result->>'chakra_spent')::int,0),'main_action_consumed',false,'state_version',(common_result->>'state_version')::bigint,'common_request_key',p_request_key));
 return result;
end $function$;

