-- Native source combat_v2_private.rng_seal(uuid,uuid,uuid,text,text,bytea,jsonb) MD5 af3ffe3edd7e2503d1fccd3fa5e30fb8

CREATE OR REPLACE FUNCTION combat_v2_private.rng_seal(p_session uuid, p_round uuid, p_declaration uuid, p_purpose text, p_context text, p_entropy bytea, p_mechanics jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_key combat_v2_private.rng_keys%rowtype;
  v_commitment text;
  v_payload jsonb;
  v_proof text;
begin
  if octet_length(p_entropy)<>32 or p_purpose not in ('order','attack','escape')
     or (p_purpose in ('attack','escape'))<>(p_declaration is not null)
     or jsonb_typeof(coalesce(p_mechanics,'null'::jsonb))<>'object' then
    raise exception 'COMBAT_V2_RNG_INPUT_INTERNO_INVALIDO';
  end if;
  select * into v_key from combat_v2_private.rng_keys order by key_version desc limit 1;
  if v_key.key_id is null then raise exception 'COMBAT_V2_RNG_KEY_ASSENTE'; end if;
  v_commitment:=encode(extensions.digest(p_entropy,'sha256'),'hex');
  v_payload:=jsonb_build_object(
    'scheme','hmac-sha256-jsonb-pg17/1',
    'key_id',v_key.key_id,
    'key_version',v_key.key_version,
    'session_id',p_session,
    'round_id',p_round,
    'declaration_id',p_declaration,
    'purpose',p_purpose,
    'context',p_context,
    'commitment',v_commitment,
    'mechanics',p_mechanics
  );
  v_proof:=encode(extensions.hmac(convert_to(v_payload::text,'UTF8'),v_key.key_secret,'sha256'),'hex');
  insert into combat_v2_private.rng_material(
    session_id,round_id,declaration_id,purpose,context,key_id,entropy,
    commitment,public_payload,proof
  ) values(
    p_session,p_round,p_declaration,p_purpose,p_context,v_key.key_id,p_entropy,
    v_commitment,v_payload,v_proof
  );
  return v_payload||jsonb_build_object('proof',v_proof);
end $function$;

