CREATE OR REPLACE FUNCTION mission_ai_board_owner.booking_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s mission_ai_board_owner.mission_seals%rowtype;a mission_ai_board_owner.activations%rowtype;p public.nb_mission_packages%rowtype;has_a boolean;
begin
 select*into a from mission_ai_board_owner.activations where mission_id=new.mission_id for update;has_a:=found;
 if tg_op='UPDATE'and old.status='iscritto'and new.status<>'iscritto'then
  if has_a and a.state<>'enrollment_open'then raise exception'MAB_STATE';end if;
  return new;
 end if;
 if new.status='iscritto'and(tg_op='INSERT'or old.status<>'iscritto')then
  select*into s from mission_ai_board_owner.mission_seals where mission_id=new.mission_id and state='active'for share;
  if not found then if has_a then raise exception'MAB_OWNER_SEAL_DRIFT';end if;return new;end if;
  perform mission_ai_board_owner.owner_snapshot(new.mission_id,s.package_id,s.location_id,s.seal_sha256);
  if not has_a then
   insert into mission_ai_board_owner.activations(mission_id,package_id,location_id,mission_seal_sha256,state)values(new.mission_id,s.package_id,s.location_id,s.seal_sha256,'enrollment_open')on conflict(mission_id)do nothing;
   select*into strict a from mission_ai_board_owner.activations where mission_id=new.mission_id for update;
  end if;
  if a.package_id<>s.package_id or a.location_id<>s.location_id or a.mission_seal_sha256<>s.seal_sha256 then raise exception'MAB_OWNER_SEAL_DRIFT';end if;
  if a.state<>'enrollment_open'then raise exception'MAB_STATE';end if;
  select*into strict p from public.nb_mission_packages where id=a.package_id for share;
  if(select count(*)from public.mission_bookings where mission_id=new.mission_id and status='iscritto')>=p.team_exact then raise exception'Squadra al completo';end if;
 end if;
 return new;
end$function$;

