CREATE OR REPLACE FUNCTION mission_ai_board_owner.booking_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a mission_ai_board_owner.activations%rowtype;
begin
 select*into a from mission_ai_board_owner.activations where mission_id=new.mission_id for update;if not found then return null;end if;
 if tg_op='UPDATE'and old.status='iscritto'and new.status<>'iscritto'then
  update mission_ai_board_owner.applicants set decision='withdrawn',ready=false,ready_at=null where activation_id=a.id and character_id=new.character_id;
  update mission_ai_board_owner.activations set all_ready=coalesce((select bool_and(coalesce(ap.ready,false))from public.mission_bookings b left join mission_ai_board_owner.applicants ap on ap.activation_id=a.id and ap.character_id=b.character_id where b.mission_id=new.mission_id and b.status='iscritto'),false),control_version=control_version+1 where id=a.id;
 elsif new.status='iscritto'and(tg_op='INSERT'or old.status<>'iscritto')then
  insert into mission_ai_board_owner.applicants(activation_id,character_id,decision,ready)values(a.id,new.character_id,'joined',false)on conflict(activation_id,character_id)do update set decision='joined',ready=false,ready_at=null,ordinal=null,decided_at=null;
  update mission_ai_board_owner.activations set all_ready=false,control_version=control_version+1 where id=a.id;
 end if;
 return null;
end$function$;

