CREATE OR REPLACE FUNCTION mission_ai_board_owner.owner_snapshot(mid uuid, pid uuid, lid uuid, sealsha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s mission_ai_board_owner.mission_seals%rowtype;p public.nb_mission_packages%rowtype;png jsonb;total int;valid int;
begin
 select*into strict s from mission_ai_board_owner.mission_seals where mission_id=mid and package_id=pid and location_id=lid and state='active'for share;
 select*into strict p from public.nb_mission_packages where id=pid for share;
 if s.seal_sha256<>sealsha or s.seal_sha256<>mission_ai_board_owner.sha(jsonb_build_object('mission',mid,'package',pid,'package_seal',p.seal_sha256,'location',lid))
    or p.lifecycle_state<>'approved'or not p.active or p.test_only or p.mission_id<>mid or p.plan_id is null or p.plan_version_id is null or p.seal_sha256 is null
    or not exists(select 1 from public.missions m where m.id=mid and p.team_exact between m.team_min and m.team_max)
    or not exists(select 1 from public.locations l where l.id=lid and l.is_active and not l.is_test)
    or not exists(select 1 from public.mission_plan_bindings b join public.mission_plan_versions v on v.id=b.plan_version_id and v.plan_id=b.plan_id where b.mission_id=mid and b.plan_id=p.plan_id and b.plan_version_id=p.plan_version_id and b.enabled and v.stato='approvata'and v.plan_sha256~'^[0-9a-f]{64}$')
 then raise exception'MAB_OWNER_SEAL_DRIFT';end if;
 select count(*),count(*)filter(where b.status='certified'and'narrator_adapter'=any(b.consumer_scopes)
   and exists(select 1 from png_builder_internal.readiness rd where rd.bundle_id=b.id)
   and not exists(select 1 from png_builder_internal.readiness rd where rd.bundle_id=b.id and(rd.state<>'staged'or not rd.enabled))
   and pb.binding_sha256=mission_ai_board_owner.sha(jsonb_build_object('package',pb.package_id,'phase',pb.phase_key,'ordinal',pb.ordinal,'bundle',pb.bundle_id,'bundle_sha256',b.bundle_sha256))),
   jsonb_agg(jsonb_build_object('phase_key',pb.phase_key,'ordinal',pb.ordinal,'bundle_id',b.id,'bundle_sha256',b.bundle_sha256,'media_ids',to_jsonb(b.media_ids),'binding_sha256',pb.binding_sha256)order by pb.phase_key,pb.ordinal)
 into total,valid,png from mission_ai_board_owner.package_png_bindings pb join png_builder_internal.bundles b on b.id=pb.bundle_id where pb.package_id=pid;
 if total=0 or valid<>total then raise exception'MAB_BUILDER_NOT_READY';end if;
 return jsonb_build_object('package_id',pid,'package_seal_sha256',p.seal_sha256,'plan_id',p.plan_id,'plan_version_id',p.plan_version_id,'location_id',lid,'png_media_phases',png,'png_count',total);
exception when no_data_found then raise exception'MAB_OWNER_SEAL_DRIFT';end$function$;

