CREATE OR REPLACE FUNCTION mission_internal.bind(p_session uuid, p_plan_version uuid, p_request_key uuid, p_expected_master_control_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_master public.master_v2_sessions%rowtype;
  v_version public.mission_plan_versions%rowtype;
  v_plan public.mission_plans%rowtype;
  v_binding public.mission_plan_bindings%rowtype;
  v_run public.mission_run_state%rowtype;
  v_event public.mission_run_events%rowtype;
  v_key text := mission_internal.request_key_sha256(p_request_key);
  v_request jsonb;
  v_fingerprint text;
  v_result jsonb;
  v_event_id uuid := gen_random_uuid();
begin
  select * into v_master from public.master_v2_sessions where id=p_session for update;
  if v_master.id is null or v_master.tipo <> 'quest' or v_master.stato <> 'preparazione'
     or v_master.mission_id is null then
    perform mission_internal.fail('MISSION_MASTER_STATE_CONFLICT');
  end if;
  select * into v_version from public.mission_plan_versions where id=p_plan_version;
  select * into v_plan from public.mission_plans where id=v_version.plan_id;
  select * into v_binding from public.mission_plan_bindings where mission_id=v_master.mission_id;
  if v_version.id is null or v_version.stato <> 'approvata' or v_plan.mission_id <> v_master.mission_id
     or v_binding.enabled is not true or v_binding.plan_version_id <> v_version.id
     or mission_internal.plan_fingerprint(v_version.id) <> v_version.plan_sha256 then
    perform mission_internal.fail('MISSION_PLAN_NOT_APPROVED');
  end if;
  v_request := jsonb_build_object(
    'schema_version','mission-request-fingerprint/1.2','operation','bind',
    'master_session_id',p_session::text,'mission_id',v_master.mission_id::text,
    'plan_id',v_plan.id::text,'plan_version_id',v_version.id::text,
    'plan_version',v_version.versione,'plan_sha256',v_version.plan_sha256,
    'expected_master_control_version',p_expected_master_control_version
  );
  v_fingerprint := mission_internal.fingerprint(v_request);
  select * into v_run from public.mission_run_state where master_session_id=p_session for update;
  if v_run.master_session_id is not null then
    select * into v_event from public.mission_run_events
    where master_session_id=p_session and request_key_sha256=v_key;
    if v_event.id is null or v_event.operation_kind <> 'bind' or v_event.request_fingerprint <> v_fingerprint then
      perform mission_internal.fail('MISSION_REQUEST_KEY_CONFLICT');
    end if;
    return v_event.result;
  end if;
  if v_master.control_version <> p_expected_master_control_version then
    perform mission_internal.fail('MISSION_RUN_STATE_CONFLICT');
  end if;
  v_result := jsonb_build_object(
    'master_session_id',p_session,'step',v_version.initial_step_key,
    'run_control_version',1,'master_control_version',v_master.control_version
  );
  insert into public.mission_run_state(
    master_session_id,mission_id,plan_id,plan_version_id,plan_version,plan_sha256,
    current_step_key,run_phase,control_version
  ) values (
    p_session,v_master.mission_id,v_plan.id,v_version.id,v_version.versione,v_version.plan_sha256,
    v_version.initial_step_key,'preparazione',1
  );
  insert into public.mission_run_events(
    id,master_session_id,operation_kind,request_key_sha256,request_fingerprint,status,result
  ) values (v_event_id,p_session,'bind',v_key,v_fingerprint,'committed',v_result);
  update public.mission_run_state set last_event_id=v_event_id where master_session_id=p_session;
  return v_result;
end
$function$;

