-- Native source mission_internal.canonical_json(jsonb) MD5 cd43c68164cbd294cf90871a3e8602bb

CREATE OR REPLACE FUNCTION mission_internal.canonical_json(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare
  v_type text := jsonb_typeof(p_value);
  v_result text;
  v_number numeric;
begin
  if v_type in ('null', 'boolean', 'string') then
    return p_value::text;
  elsif v_type = 'number' then
    v_number := (p_value #>> '{}')::numeric;
    if v_number <> trunc(v_number)
       or v_number < -9007199254740991::numeric
       or v_number > 9007199254740991::numeric then
      perform mission_internal.fail('MISSION_FINGERPRINT_INVALID');
    end if;
    return trunc(v_number)::text;
  elsif v_type = 'array' then
    select '[' || coalesce(string_agg(mission_internal.canonical_json(x.value), ',' order by x.ordinality), '') || ']'
      into v_result
    from jsonb_array_elements(p_value) with ordinality as x(value, ordinality);
    return v_result;
  elsif v_type = 'object' then
    select '{' || coalesce(string_agg(to_jsonb(x.key)::text || ':' || mission_internal.canonical_json(x.value), ',' order by convert_to(x.key, 'UTF8')), '') || '}'
      into v_result
    from jsonb_each(p_value) as x(key, value);
    return v_result;
  end if;
  perform mission_internal.fail('MISSION_FINGERPRINT_INVALID');
  return null;
end
$function$;

