-- Native source mission_internal.close_from_master(uuid,uuid,bigint,text,text) MD5 51b05c8d6c2a82a30a04cd7648d3d4ca

CREATE OR REPLACE FUNCTION mission_internal.close_from_master(p_session uuid, p_request_key uuid, p_expected_master_control_version bigint, p_outcome text, p_outcome_payload_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_master public.master_v2_sessions%rowtype;
  v_run public.mission_run_state%rowtype;
  v_old public.mission_run_events%rowtype;
  v_key text:=mission_internal.request_key_sha256(p_request_key);
  v_fp text;
  v_event uuid:=gen_random_uuid();
  v_phase text;
  v_result jsonb;
begin
  if p_outcome not in ('success','failure') or coalesce(p_outcome_payload_sha256,'') !~ '^[0-9a-f]{64}$' then perform mission_internal.fail('MISSION_EVENT_NOT_ALLOWED'); end if;
  select * into v_master from public.master_v2_sessions where id=p_session for update;
  select * into v_run from public.mission_run_state where master_session_id=p_session for update;
  if v_run.master_session_id is null then perform mission_internal.fail('MISSION_RUN_NOT_BOUND'); end if;
  v_fp:=mission_internal.fingerprint(jsonb_build_object(
    'schema_version','mission-request-fingerprint/1.2','operation','close','master_session_id',p_session::text,
    'mission_id',v_run.mission_id::text,'plan_id',v_run.plan_id::text,'plan_version_id',v_run.plan_version_id::text,
    'step_key',v_run.current_step_key,'expected_master_control_version',p_expected_master_control_version,
    'expected_run_control_version',v_run.control_version,'outcome',p_outcome,'outcome_payload_sha256',p_outcome_payload_sha256
  ));
  select * into v_old from public.mission_run_events where master_session_id=p_session and request_key_sha256=v_key;
  if v_old.id is not null then
    if v_old.operation_kind<>'close' or v_old.request_fingerprint<>v_fp then perform mission_internal.fail('MISSION_REQUEST_KEY_CONFLICT'); end if;
    return v_old.result;
  end if;
  if v_master.stato<>'chiusura' or v_master.control_version<>p_expected_master_control_version or v_run.run_phase<>'in_corso' then perform mission_internal.fail('MISSION_RUN_STATE_CONFLICT'); end if;
  v_phase:=case when p_outcome='success' then 'conclusa' else 'fallita' end;
  v_result:=jsonb_build_object('run_phase',v_phase,'run_control_version',v_run.control_version+1,'outcome_payload_sha256',p_outcome_payload_sha256);
  update public.mission_run_state set run_phase=v_phase,control_version=control_version+1,updated_at=clock_timestamp() where master_session_id=p_session;
  insert into public.mission_run_events(id,master_session_id,operation_kind,request_key_sha256,request_fingerprint,status,version_before,version_after,result)
  values(v_event,p_session,'close',v_key,v_fp,'committed',v_run.control_version,v_run.control_version+1,v_result);
  update public.mission_run_state set last_event_id=v_event where master_session_id=p_session;
  return v_result;
end
$function$;

