CREATE OR REPLACE FUNCTION mission_internal.committed_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_table_name='mission_run_outbox' then
    if tg_op='UPDATE' and old.state='pending' and new.state='published'
       and current_setting('app.mission_outbox_publish',true)='on'
       and old.event_id=new.event_id and old.master_session_id=new.master_session_id
       and old.surface_kind=new.surface_kind and old.event_version_after=new.event_version_after
       and old.step_key=new.step_key and old.context_fingerprint=new.context_fingerprint then
      return new;
    end if;
  end if;
  perform mission_internal.fail('MISSION_COMMITTED_ROW_IMMUTABLE');
  return null;
end
$function$;

