-- Native source mission_internal.nb029h_package_guard() MD5 fdb765897299fb62ecadb7b80024aacc

CREATE OR REPLACE FUNCTION mission_internal.nb029h_package_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare d text; n integer;
begin
 if tg_op='DELETE' then perform mission_internal.fail('MISSION_029H_PACKAGE_DELETE_FORBIDDEN'); end if;
 if old.id is distinct from new.id or old.package_key is distinct from new.package_key then perform mission_internal.fail('MISSION_029H_PACKAGE_ID_IMMUTABLE'); end if;
 if old.lifecycle_state<>'draft' and (old.payload is distinct from new.payload or old.expected_segment_manifest is distinct from new.expected_segment_manifest
  or old.source_manifest_sha256 is distinct from new.source_manifest_sha256
  or old.miyo_template_id is distinct from new.miyo_template_id
  or old.miyo_template_version_id is distinct from new.miyo_template_version_id or old.miyo_template_control_version is distinct from new.miyo_template_control_version
  or old.miyo_version_control_version is distinct from new.miyo_version_control_version or old.miyo_content_sha256 is distinct from new.miyo_content_sha256)
 then perform mission_internal.fail('MISSION_029H_PACKAGE_SEALED'); end if;
 if not (new.lifecycle_state=old.lifecycle_state or (old.lifecycle_state,new.lifecycle_state) in (('draft','sealed'),('sealed','review'),('review','approved'),('approved','inactive')))
 then perform mission_internal.fail('MISSION_029H_STATE_TRANSITION'); end if;
 if new.lifecycle_state in ('sealed','review','approved') then
  perform mission_internal.nb029k_validate_source(new);
  perform mission_internal.nb029h_validate_owner(new);
  select count(*) into n from public.nb_mission_segments where package_id=new.id;
  if n<>11 or mission_internal.nb029i_segment_manifest(new.id) is distinct from new.expected_segment_manifest
  then perform mission_internal.fail('MISSION_029I_SEGMENT_MANIFEST_MISMATCH'); end if;
  d:=mission_internal.nb029h_segment_digest(new.id);
  if new.segment_set_sha256 is distinct from d or new.seal_sha256 is distinct from mission_internal.nb029h_expected_seal(new,d)
  then perform mission_internal.fail('MISSION_029H_SEAL_MISMATCH'); end if;
 end if;
 return new;
end $function$;

