-- Native source mission_internal.nb029h_segment_guard() MD5 7ccd81c1778855448105b61bc48ace13

CREATE OR REPLACE FUNCTION mission_internal.nb029h_segment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a uuid; b uuid; p public.nb_mission_packages%rowtype;
begin
 a:=case when tg_op='INSERT' then new.package_id else old.package_id end;
 b:=case when tg_op='DELETE' then old.package_id else new.package_id end;
 if tg_op='UPDATE' and old.package_id is distinct from new.package_id then perform mission_internal.fail('MISSION_029H_REPARENT_FORBIDDEN'); end if;
 select * into strict p from public.nb_mission_packages where id=a;
 if p.lifecycle_state<>'draft' then
  if not (tg_op='UPDATE' and old.package_id=new.package_id and old.segment_key=new.segment_key
    and old.classification=new.classification and old.segment_schema_version=new.segment_schema_version and old.visibility=new.visibility
    and old.content_sha256=new.content_sha256 and old.recipient_spec=new.recipient_spec
    and old.grant_state='none' and new.grant_state='none'
    and ((p.lifecycle_state='review' and old.lifecycle_state='sealed' and new.lifecycle_state='review')
      or (p.lifecycle_state='approved' and old.lifecycle_state='review' and new.lifecycle_state='approved')))
  then perform mission_internal.fail('MISSION_029H_SEGMENTS_SEALED'); end if;
 end if;
 return case when tg_op='DELETE' then old else new end;
end $function$;

