CREATE OR REPLACE FUNCTION mission_internal.nb029h_validate_owner(p nb_mission_packages)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.nb_templates%rowtype; v public.nb_template_versions%rowtype;
begin
 select * into strict t from public.nb_templates where id=p.miyo_template_id for share;
 select * into strict v from public.nb_template_versions where id=p.miyo_template_version_id and template_id=t.id for share;
 if t.template_key<>'nb029_miyo_arakida' or t.lifecycle_state not in ('approved','inactive') or t.current_version_id is distinct from v.id
    or t.control_version<>p.miyo_template_control_version or v.review_state not in ('approved','inactive')
    or v.control_version<>p.miyo_version_control_version or v.content_sha256<>p.miyo_content_sha256
 then raise exception 'MISSION_029H_MIYO_OWNER_DRIFT'; end if;
end $function$;

