 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
  begin
   if tg_op='DELETE'then raise exception 'NB032_A14_DELETE_FORBIDDEN';end if;
   if tg_table_name='mission_run_canary_bindings'then
    if old.state='frozen'and new.state='frozen'and old.adapter_request_key is null and new.adapter_request_key is not null
      and(to_jsonb(old)-array['adapter_schema','adapter_request_key','adapter_catalog_digest','adapter_binding_digest'])=(to_jsonb(new)-array['adapter_schema','adapter_request_key','adapter_catalog_digest','adapter_binding_digest'])then return new;end if;
    if old.state='frozen'and new.state='unbound'and new.control_version=old.control_version+1
      and(to_jsonb(old)-array['state','control_version','terminal_request_key','terminal_mode','terminal_result','terminal_full_state_sha256','adapter_disarmed_at'])=(to_jsonb(new)-array['state','control_version','terminal_request_key','terminal_mode','terminal_result','terminal_full_state_sha256','adapter_disarmed_at'])then return new;end if;
    if old.state='unbound'and new.state='unbound'and old.terminal_full_state_sha256=repeat('0',64)and new.terminal_full_state_sha256~'^[0-9a-f]{64}$'
      and(to_jsonb(old)-'terminal_full_state_sha256')=(to_jsonb(new)-'terminal_full_state_sha256')then return new;end if;
   else
    if old.adapter_state='active'and new.adapter_state='revoked'and new.adapter_revoked_at is not null
      and(to_jsonb(old)-array['adapter_state','adapter_revoked_at'])=(to_jsonb(new)-array['adapter_state','adapter_revoked_at'])then return new;end if;
   end if;
   raise exception 'NB032_A14_IMMUTABLE_OR_TRANSITION';
  end$function$;

