-- Native source mission_internal.plan_version_guard() MD5 f94568c85f3a13b30a78f51992b169a5

CREATE OR REPLACE FUNCTION mission_internal.plan_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_version uuid;
  v_old_version uuid;
  v_new_version uuid;
  v_state text;
begin
  if tg_table_name = 'mission_plan_versions' then
    v_version := coalesce(old.id, new.id);
    if tg_op in ('UPDATE', 'DELETE') and old.stato = 'approvata' then
      perform mission_internal.fail('MISSION_PLAN_IMMUTABLE');
    end if;
    return coalesce(new, old);
  end if;

  if tg_op = 'UPDATE' then
    v_old_version := old.plan_version_id;
    v_new_version := new.plan_version_id;
    -- Anche il tentativo di reparenting acquisisce entrambe le versioni nello
    -- stesso ordine totale usato dalla barriera statement-level. L'identità
    -- del padre è parte dell'identità canonica della riga e non è mutabile.
    perform id from public.mission_plan_versions
      where id in (v_old_version, v_new_version) order by id for update;
    if not exists(select 1 from public.mission_plan_versions where id=v_old_version)
       or not exists(select 1 from public.mission_plan_versions where id=v_new_version) then
      perform mission_internal.fail('MISSION_PLAN_VERSION_NOT_FOUND');
    end if;
    if v_old_version is distinct from v_new_version then
      perform mission_internal.fail('MISSION_PLAN_REPARENT_FORBIDDEN');
    end if;
    v_version := v_old_version;
  else
    v_version := coalesce(new.plan_version_id, old.plan_version_id);
  end if;
  -- Il lock della versione precede la lettura dello stato. Il trigger statement
  -- ha già acquisito tutte le righe versione prima che PostgreSQL tocchi le
  -- righe figlie; questo lock specifico rende esplicita la stessa relazione.
  select stato into v_state from public.mission_plan_versions
  where id=v_version for update;
  if v_state is null then
    perform mission_internal.fail('MISSION_PLAN_VERSION_NOT_FOUND');
  end if;
  if v_state = 'approvata' then
    perform mission_internal.fail('MISSION_PLAN_IMMUTABLE');
  end if;
  return coalesce(new, old);
end
$function$;

