     or new.schema_version is distinct from old.schema_version or new.mission_id is distinct from old.mission_id
     or new.pg_character_ids is distinct from old.pg_character_ids
     or new.narrative_template_ids is distinct from old.narrative_template_ids
     or new.narrative_version_ids is distinct from old.narrative_version_ids
     or new.mechanical_template_ids is distinct from old.mechanical_template_ids
     or new.mechanical_version_ids is distinct from old.mechanical_version_ids
     or new.import_history_version is distinct from old.import_history_version
     or new.import_statement_sha256 is distinct from old.import_statement_sha256
     or new.binding_sha256 is distinct from old.binding_sha256
     or new.created_at is distinct from old.created_at
     or new.control_version<>old.control_version+1 then
    raise exception using errcode='P0001',message='RONDA_BINDING_IMMUTABLE_DRIFT';
  end if;
  new.updated_at:=clock_timestamp(); return new;
end $function$;

