-- Native source mission_internal.sync_lifecycle(uuid,uuid,bigint,bigint,text) MD5 ad704d1ecc114662924d47faa712cdb8

CREATE OR REPLACE FUNCTION mission_internal.sync_lifecycle(p_session uuid, p_request_key uuid, p_expected_master_control_version bigint, p_expected_run_control_version bigint, p_new_phase text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_master public.master_v2_sessions%rowtype;
  v_run public.mission_run_state%rowtype;
  v_old public.mission_run_events%rowtype;
  v_key text := mission_internal.request_key_sha256(p_request_key);
  v_request jsonb;
  v_fp text;
  v_event uuid := gen_random_uuid();
  v_result jsonb;
begin
  select * into v_master from public.master_v2_sessions where id=p_session for update;
  select * into v_run from public.mission_run_state where master_session_id=p_session for update;
  if v_run.master_session_id is null then perform mission_internal.fail('MISSION_RUN_NOT_BOUND'); end if;
  v_request := jsonb_build_object(
    'schema_version','mission-request-fingerprint/1.2','operation','sync_lifecycle',
    'master_session_id',p_session::text,'expected_master_control_version',p_expected_master_control_version,
    'expected_run_control_version',p_expected_run_control_version,'new_phase',p_new_phase
  );
  v_fp := mission_internal.fingerprint(v_request);
  select * into v_old from public.mission_run_events where master_session_id=p_session and request_key_sha256=v_key;
  if v_old.id is not null then
    if v_old.request_fingerprint <> v_fp then perform mission_internal.fail('MISSION_REQUEST_KEY_CONFLICT'); end if;
    return v_old.result;
  end if;
  if v_master.control_version <> p_expected_master_control_version
     or v_run.control_version <> p_expected_run_control_version
     or p_new_phase <> v_master.stato
     or (v_run.run_phase,p_new_phase) not in (('preparazione','in_corso'),('preparazione','sospesa'),('in_corso','sospesa'),('sospesa','preparazione'),('sospesa','in_corso'),('preparazione','annullata'),('in_corso','annullata'),('sospesa','annullata')) then
    perform mission_internal.fail('MISSION_RUN_STATE_CONFLICT');
  end if;
  v_result := jsonb_build_object('run_phase',p_new_phase,'run_control_version',v_run.control_version+1,'master_control_version',v_master.control_version);
  update public.mission_run_state set run_phase=p_new_phase,control_version=control_version+1,updated_at=clock_timestamp() where master_session_id=p_session;
  insert into public.mission_run_events(id,master_session_id,operation_kind,request_key_sha256,request_fingerprint,status,version_before,version_after,result)
  values(v_event,p_session,'lifecycle',v_key,v_fp,'committed',v_run.control_version,v_run.control_version+1,v_result);
  update public.mission_run_state set last_event_id=v_event where master_session_id=p_session;
  return v_result;
end
$function$;

