CREATE OR REPLACE FUNCTION ninja_book_internal.guard_approved_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.approved_at is not null then
    if new.review_state<>'inactive' or new.control_version<>old.control_version+1
       or new.updated_at<=old.updated_at or
       (new.template_id,new.version_no,new.schema_version,new.supersedes_version_id,new.mechanical_template_id,
        new.skeleton,new.knowledge_boundary,new.fallback_profile,new.content_sha256,
        new.reviewed_by,new.reviewed_at,new.approved_by,new.approved_at,new.created_by,new.created_at)
       is distinct from
       (old.template_id,old.version_no,old.schema_version,old.supersedes_version_id,old.mechanical_template_id,
        old.skeleton,old.knowledge_boundary,old.fallback_profile,old.content_sha256,
        old.reviewed_by,old.reviewed_at,old.approved_by,old.approved_at,old.created_by,old.created_at) then
      raise exception using errcode='P0001',message='NB_APPROVED_IMMUTABLE';
    end if;
  end if;
  return new;
end $function$;

