-- Native source ninja_book_internal.ronda_ability_refs_resolve_v1(uuid,jsonb) MD5 45a9811c51725f731c97d8d867591305

CREATE OR REPLACE FUNCTION ninja_book_internal.ronda_ability_refs_resolve_v1(p_template uuid, p_refs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer; v_distinct integer; v_out jsonb; v_keys text[]; v_expected text[];
begin
  if jsonb_typeof(p_refs)<>'array' or jsonb_array_length(p_refs)<1 or jsonb_array_length(p_refs)>20 then
    raise exception using errcode='P0001',message='RONDA_ABILITY_REFS_INVALID';
  end if;
  if exists(select 1 from jsonb_array_elements(p_refs) x
    where jsonb_typeof(x)<>'object'
       or (select array_agg(k order by k) from jsonb_object_keys(x) k)<>array['id','source']::text[]
       or x->>'source' not in('clan','jutsu')
       or coalesce(x->>'id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') then
    raise exception using errcode='P0001',message='RONDA_ABILITY_REF_SHAPE_INVALID';
  end if;
  select count(*),count(distinct (x->>'source',x->>'id')) into v_count,v_distinct
    from jsonb_array_elements(p_refs) x;
  if v_count<>v_distinct then raise exception using errcode='P0001',message='RONDA_ABILITY_REF_DUPLICATE'; end if;
  select array_agg((x->>'source')||':'||(x->>'id') order by (x->>'source')||':'||(x->>'id'))
    into v_keys from jsonb_array_elements(p_refs)x;
  select array_agg(source||':'||ability_id::text order by source||':'||ability_id::text) into v_expected
   from public.nb_mechanical_ability_profile_refs_v1
   where mechanical_template_id=p_template and lifecycle_state='approved' and active;
  if v_expected is null then raise exception using errcode='P0001',message='NB_ABILITY_PROFILE_NOT_REGISTERED'; end if;
  if v_keys is distinct from v_expected then raise exception using errcode='P0001',message='NB_ABILITY_ALLOWLIST_MISMATCH'; end if;
  with refs as(select x->>'source' source,(x->>'id')::uuid id from jsonb_array_elements(p_refs)x),
  resolved as(
    select jsonb_build_object('source','clan','id',t.id,'name',t.name,'kind',coalesce(t.category,'fisico'),
      'usage',t.uso,'defensive',coalesce(t.difensiva,false),'di_scena',coalesce(t.di_scena,false),
      'diversivo',false,'consumption_type',coalesce(t.consumption_type,'ad_utilizzo'),'range',t.gittata,
      'chakra_cost',coalesce(t.chakra_cost,0),'damage_base',coalesce(t.danno_base,0),
      'element',case when jsonb_typeof(to_jsonb(t.req_elements))='array' then to_jsonb(t.req_elements)->>0 end)x
    from refs r join public.clan_techniques t on r.source='clan' and t.id=r.id and t.is_active
    union all
    select jsonb_build_object('source','jutsu','id',j.id,'name',j.name_it,'kind',coalesce(j.category,'fisico'),
      'usage',j.uso,'defensive',coalesce(j.difensiva,false),'di_scena',coalesce(j.di_scena,false),
      'diversivo',coalesce(j.diversivo,false),'consumption_type','ad_utilizzo','range',j.gittata,
      'chakra_cost',coalesce(j.chakra_cost,0),'damage_base',coalesce(j.damage_base,0),'element',j.nature)x
    from refs r join public.jutsu j on r.source='jutsu' and j.id=r.id and j.is_active)
  select jsonb_agg(x order by x->>'name'),count(*) into v_out,v_count from resolved;
  if v_count<>jsonb_array_length(p_refs) then raise exception using errcode='P0001',message='RONDA_CATALOG_DRIFT'; end if;
  return v_out;
end
$function$;

