-- Native source public._academy_overflow_sync() MD5 865398c58578762baf0ebb614be3574b

CREATE OR REPLACE FUNCTION public._academy_overflow_sync()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.locations l
     set is_active = t.serve
    from (
      select x.id,
             ( exists (select 1 from public.academy_class_sessions s
                        where s.state <> 'closed' and s.location_id = x.overflow_of)
            or exists (select 1 from public.academy_class_sessions s2
                        where s2.state <> 'closed' and s2.location_id = x.id) ) as serve
        from public.locations x
       where x.overflow_of is not null
    ) t
   where l.id = t.id and l.is_active is distinct from t.serve;
end $function$;

