-- Native source public._assegna_xp(uuid,integer,text) MD5 6effbb7032597a54b49b0ff06fc1c1f2

CREATE OR REPLACE FUNCTION public._assegna_xp(p_character uuid, p_amount integer, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exp int; v_life int;
begin
  if p_character is null or coalesce(p_amount,0) = 0 then return; end if;
  perform set_config('app.allow_exp_delta','1', true);
  update public.characters
     set exp = coalesce(exp,0) + p_amount,
         xp_lifetime = greatest(0, coalesce(xp_lifetime,0) + greatest(p_amount,0))
   where id = p_character
   returning exp, xp_lifetime into v_exp, v_life;
  if not found then return; end if;
  insert into public.xp_log(character_id, delta, motivo, exp_after, lifetime_after)
    values (p_character, p_amount, coalesce(nullif(btrim(p_motivo),''),'—'), v_exp, v_life);
end; $function$;

