-- Native source public._attivita_impegno(uuid) MD5 385cf5e53b6a643a36a6cdf5451f6c86

CREATE OR REPLACE FUNCTION public._attivita_impegno(p_character uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user   uuid;
  v_id     uuid;
  v_loc    uuid;
  v_nome   text;
  v_ha_col boolean;
begin
  if p_character is null then
    return jsonb_build_object('impegnato', false, 'modalita', null, 'attivita_id', null,
                              'luogo_id', null, 'luogo_nome', null, 'testo', null);
  end if;

  select c.user_id into v_user from public.characters c where c.id = p_character;
  if v_user is null then
    return jsonb_build_object('impegnato', false, 'modalita', null, 'attivita_id', null,
                              'luogo_id', null, 'luogo_nome', null, 'testo', null);
  end if;

  -- RAMO 1 · scontro. Sostrato vivo.
  select s.id, s.location_id, l.name
    into v_id, v_loc, v_nome
    from public.combat_participants p
    join public.combat_sessions s on s.id = p.session_id
    join public.locations l on l.id = s.location_id
   where p.user_id = v_user
     and p.character_id = p_character
     and p.ruolo = 'combattente'
     and s.state = 'aperto'
   order by s.created_at
   limit 1;
  if v_id is not null then
    return jsonb_build_object(
      'impegnato', true, 'modalita', 'scontro', 'attivita_id', v_id,
      'luogo_id', v_loc, 'luogo_nome', v_nome,
      'testo', 'sei in uno scontro a ' || coalesce(v_nome,'un luogo') || '.');
  end if;

  -- RAMO 2 · allenamento. Substrato di Training V2, non ancora applicato.
  -- Si interroga solo se la colonna esiste: senza questa guardia il piano
  -- verrebbe compilato contro una colonna assente e la funzione solleverebbe.
  select exists (
    select 1 from information_schema.columns
     where table_schema='public' and table_name='training_sessions' and column_name='stato'
  ) into v_ha_col;
  if v_ha_col then
    v_id := null;
    execute 'select ts.id from public.training_sessions ts '
         || ' where ts.character_id = $1 and ts.stato = ''dichiarata'' limit 1'
      into v_id using p_character;
    if v_id is not null then
      return jsonb_build_object(
        'impegnato', true, 'modalita', 'allenamento', 'attivita_id', v_id,
        'luogo_id', null, 'luogo_nome', null,
        'testo', 'hai un allenamento dichiarato.');
    end if;
  end if;

  -- RAMO 3 · quest. La sorgente non è congelabile oggi: dipende da OPEN-R1-A.
  -- Il ramo esiste, non legge niente e degrada a false. Quando T5 deciderà
  -- dove vive l'incontro programmato, si accende qui e in nessun altro posto.
  -- (nessuna query: non c'è ancora una tabella da interrogare)

  -- RAMO 4 · esame. [EXAM-GENIN-DB-003] Risponde vero quando esiste una riga
  -- esame_prove con stato='aperta' per questo personaggio. La stessa regola di
  -- degradazione del RAMO 2: finché la tabella non esiste, falso senza errore.
  select exists (
    select 1 from information_schema.tables
     where table_schema='public' and table_name='esame_prove'
  ) into v_ha_col;
  if v_ha_col then
    v_id := null; v_loc := null; v_nome := null;
    execute 'select e.id, s.location_id, l.name'
         || '  from public.esame_prove e'
         || '  join public.academy_class_sessions s on s.id = e.class_session_id'
         || '  left join public.locations l on l.id = s.location_id'
         || ' where e.candidate_character = $1 and e.stato = ''aperta'''
         || ' order by e.created_at limit 1'
      into v_id, v_loc, v_nome using p_character;
    if v_id is not null then
      return jsonb_build_object(
        'impegnato', true, 'modalita', 'esame', 'attivita_id', v_id,
        'luogo_id', v_loc, 'luogo_nome', v_nome,
        'testo', 'sei nella prova dell''esame a ' || coalesce(v_nome,'un luogo') || '.');
    end if;
  end if;

  return jsonb_build_object('impegnato', false, 'modalita', null, 'attivita_id', null,
                            'luogo_id', null, 'luogo_nome', null, 'testo', null);
end
$function$;

