-- Native source public._combat_avanza(uuid) MD5 7f12a461513c3b2b6dd4c6df80943987

CREATE OR REPLACE FUNCTION public._combat_avanza(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_s public.combat_sessions%rowtype; v_next uuid; v_round int; v_char uuid;
begin
  select * into v_s from public.combat_sessions where id = p_session;
  if v_s.id is null or v_s.state <> 'aperto' then return; end if;
  if (select count(*) from public.combat_participants where session_id = p_session and ruolo='combattente' and not fuori) <= 1 then
    perform public.combat_close(p_session, 'un solo combattente ancora in piedi');
    return;
  end if;
  select p.user_id into v_next from public.combat_participants p
   where p.session_id = p_session and p.ruolo='combattente' and not p.fuori
     and (p.round_speso <> v_s.round or not p.usato_principale)
   order by p.iniziativa desc, p.joined_at asc limit 1;
  if v_next is null then
    v_round := v_s.round + 1;
    perform public._combat_round_tick(p_session, v_s.round);
    select p.user_id, p.character_id into v_next, v_char from public.combat_participants p
     where p.session_id = p_session and p.ruolo='combattente' and not p.fuori
     order by p.iniziativa desc, p.joined_at asc limit 1;
    -- Le copie non attraversano il successivo turno d'attacco del proprietario.
    update public.combat_participants
       set copie_attive = false, copie_round = null
     where session_id = p_session and user_id = v_next and copie_attive;
    update public.combat_sessions set round = v_round, fase='attacco', turn_of = v_next, last_action_at = now() where id = p_session;
    perform public._combat_dice(p_session, v_char, 'Scontro', '— Round ' || v_round || ' —', true);
  else
    update public.combat_participants
       set copie_attive = false, copie_round = null
     where session_id = p_session and user_id = v_next and copie_attive;
    update public.combat_sessions set fase='attacco', turn_of = v_next, last_action_at = now() where id = p_session;
  end if;
end; $function$;

