-- Native source public._combat_dice(uuid,uuid,text,text,boolean) MD5 6059ce7966e616eaee865c04be55305e

CREATE OR REPLACE FUNCTION public._combat_dice(p_session uuid, p_char uuid, p_nome text, p_testo text, p_motore boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_loc uuid;
begin
  select location_id into v_loc from public.combat_sessions where id = p_session;
  insert into public.messages(location_id, character_id, author_name, kind, sender_user, body, created_at)
    values (v_loc, p_char, coalesce(p_nome,'Scontro'),
            case when p_motore then 'motore' else 'sistema' end,
            auth.uid(), p_testo, clock_timestamp());
end; $function$;

