-- Native source public._combat_leggi_comandi(text) MD5 e580863764c468b235e62ee387ba4b56

CREATE OR REPLACE FUNCTION public._combat_leggi_comandi(p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare b text; i int := 1; p int; q int; s1 int; s2 int; v text; v_low text; s text;
  v_bers text := null; v_sposta int := null; v_reaz text := null; v_rap text := null;
  v_colpo boolean := false; v_tec text := null; v_cons jsonb := '[]'::jsonb;
  v_err text[] := '{}'; v_avv text[] := '{}'; v_num int := 0;
begin
  b := public._combat_normalizza(p_body);
  loop
    p := strpos(substr(b, i), '[');
    exit when p = 0;
    s1 := i + p - 1;
    q := strpos(substr(b, s1 + 1), ']');
    exit when q = 0;
    s2 := s1 + q;
    v := substr(b, s1 + 1, s2 - s1 - 1);
    if position('[' in v) > 0 then i := s1 + 1; continue; end if;
    if length(v) < 1 or length(v) > 80 then i := s2 + 1; continue; end if;
    v := btrim(v); v_low := lower(v);

    if v_low like 'figura:%' or v_low in ('fine','fine turno','fine azione','ooc','off') then
      i := s2 + 1; continue;
    end if;

    if v_low in ('contrasto','contrasta','contromossa') then
      v_err := array_append(v_err, 'la Contromossa non e'' in vigore in questa versione: usa [schivata], [parata], [copie] o una tecnica difensiva');
    elsif v_low in ('schivata','schivo','parata','paro','copie') then
      if v_reaz is not null then v_err := array_append(v_err, 'hai dichiarato due difese diverse: tienine una'); end if;
      v_reaz := case when v_low in ('schivata','schivo') then 'schivata' when v_low in ('parata','paro') then 'parata' else 'copie' end;
      v_num := v_num + 1; v_cons := v_cons || jsonb_build_object('i', s1, 'n', s2 - s1 + 1, 't', v);
    elsif v_low = 'colpo' then
      if v_colpo then v_err := array_append(v_err, 'hai dichiarato due volte il colpo: se ne tira uno per turno'); end if;
      v_colpo := true; v_num := v_num + 1; v_cons := v_cons || jsonb_build_object('i', s1, 'n', s2 - s1 + 1, 't', v);
    elsif v_low like 'tecnica:%' or v_low like 'tecnica %' then
      if v_tec is not null then v_err := array_append(v_err, 'hai nominato due tecniche: nel tuo turno se ne gioca una'); end if;
      v_tec := btrim(substr(v, 9)); v_num := v_num + 1;
      if v_tec = '' then
        v_err := array_append(v_err, 'quale tecnica? per esempio [tecnica: Grande sfera di fuoco]'); v_tec := null;
      else
        v_cons := v_cons || jsonb_build_object('i', s1, 'n', s2 - s1 + 1, 't', v);
      end if;
    elsif v_low = 'tecnica' then
      v_err := array_append(v_err, 'quale tecnica? per esempio [tecnica: Grande sfera di fuoco]');
    elsif v_low = 'guardia' then
      v_err := array_append(v_err, 'Guardia è stata ritirata: usa una difesa disponibile oppure [copie] se il Diversivo le ha attivate');
      v_num := v_num + 1; v_cons := v_cons || jsonb_build_object('i', s1, 'n', s2 - s1 + 1, 't', v);
    elsif v_low in ('mira','lancio') then
      if v_rap is not null then v_err := array_append(v_err, 'hai dichiarato due azioni rapide: se ne fa una sola per turno'); end if;
      v_rap := v_low; v_num := v_num + 1; v_cons := v_cons || jsonb_build_object('i', s1, 'n', s2 - s1 + 1, 't', v);
    elsif v_low like 'bersaglio %' then
      if v_bers is not null then v_err := array_append(v_err, 'hai dichiarato due bersagli: nel tuo turno se ne attacca uno'); end if;
      v_bers := btrim(substr(v, 11)); v_num := v_num + 1;
      if v_bers = '' then v_err := array_append(v_err, 'il bersaglio è vuoto: scrivi per esempio [bersaglio Aoi]'); v_bers := null;
      else v_cons := v_cons || jsonb_build_object('i', s1, 'n', s2 - s1 + 1, 't', v); end if;
    elsif v_low = 'bersaglio' then
      v_err := array_append(v_err, 'il bersaglio è vuoto: scrivi per esempio [bersaglio Aoi]');
    elsif v_low like 'sposta%' then
      s := btrim(replace(replace(replace(replace(v_low,'spostamento',''),'sposta',''),'metri',''),'metro',''));
      s := btrim(replace(replace(s,'m',''),' ',''));
      if s ~ '^[+-]?[0-9]{1,3}$' then
        if v_sposta is not null then v_err := array_append(v_err, 'hai dichiarato due spostamenti: se ne fa uno per turno'); end if;
        v_sposta := s::int; v_num := v_num + 1; v_cons := v_cons || jsonb_build_object('i', s1, 'n', s2 - s1 + 1, 't', v);
      else
        v_err := array_append(v_err, '«'||v||'»: quanti metri? per esempio [sposta +10] per avvicinarti, [sposta -5] per staccarti');
      end if;
    else
      v_avv := array_append(v_avv, 'non ho capito «'||v||'»: se era un comando, guarda la legenda');
    end if;
    i := s2 + 1;
  end loop;
  return jsonb_build_object(
    'bersaglio', v_bers, 'sposta', v_sposta, 'reazione', v_reaz, 'rapida', v_rap,
    'colpo', v_colpo, 'tecnica', v_tec, 'consumati', v_cons,
    'comandi', v_num, 'errori', to_jsonb(v_err), 'avvisi', to_jsonb(v_avv));
end; $function$;

