-- Native source public._combat_nuovo_round(uuid,integer) MD5 278ae58d6a49d7407a1956859c0af18b

CREATE OR REPLACE FUNCTION public._combat_nuovo_round(p_part uuid, p_round integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.combat_participants
     set round_speso = p_round, usato_principale = false, usato_rapida = false,
         usato_reazione = false, usato_spostamento = false
   where id = p_part and round_speso <> p_round;
end; $function$;

