-- Native source public._combat_risolvi(uuid,text,boolean,uuid) MD5 06960283ffc7a08028dbb7b282a9b8b6

CREATE OR REPLACE FUNCTION public._combat_risolvi(p_pending uuid, p_reazione text, p_colto boolean, p_dif_tech uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pe public.combat_pending%rowtype; a public.characters%rowtype; d public.characters%rowtype;
  pa public.combat_participants%rowtype; pd public.combat_participants%rowtype;
  v_test boolean; v_scrive boolean; v_scen text; v_da int; v_dd int;
  v_mira int := 0; c jsonb;
  v_dif_nome text; v_dif_disc text; v_dif_elem text; testo text; ck int := 0;
  v_pv int; v_ko boolean := false; v_gen boolean; v_ko_txt text;
  v_slancio int := 0; v_slancio_next int := 0;
  v_colpito boolean; v_striscio boolean; v_appl int; v_grez int;
  v_copie_attive boolean := false; v_esito_copie text;
  v_copie_n int := 0; v_mod_copie int := 0;
  v_copie_assalto int := 0; v_mod_assalto int := 0; v_esito_assalto text;
begin
  select * into pe from public.combat_pending where id = p_pending for update;
  if not found then raise exception 'il colpo è già stato risolto'; end if;
  if pe.formazione_id is not null then
    select f.copie_n, sc.bonus_assalto, sc.esito
      into v_copie_assalto, v_mod_assalto, v_esito_assalto
      from public.combat_formazione f
      join public.combat_formazione_scelta sc on sc.formazione_id=f.id
     where f.id=pe.formazione_id and f.modalita='assalto';
    if not found then raise exception 'Assalto senza scelta autoritativa della figura.'; end if;
  end if;
  -- [042-B0] una tecnica di scena non si risolve come attacco. Vale per i
  -- pending nati prima della guardia nel dichiaratore.
  if pe.technique_id is not null and (
       exists (select 1 from public.jutsu j
                where j.id = pe.technique_id and coalesce(j.di_scena,false))
    or exists (select 1 from public.clan_techniques t
                where t.id = pe.technique_id and coalesce(t.di_scena,false))) then
    raise exception 'Una tecnica di scena non può essere risolta come attacco: il colpo è mal composto.';
  end if;
  select * into pa from public.combat_participants where session_id = pe.session_id and user_id = pe.attacker_user for update;
  select * into pd from public.combat_participants where session_id = pe.session_id and user_id = pe.defender_user for update;
  select * into a from public.characters where id = pa.character_id;
  select * into d from public.characters where id = pd.character_id;
  select coalesce(l.is_test,false), s.scenario into v_test, v_scen
    from public.combat_sessions s join public.locations l on l.id = s.location_id where s.id = pe.session_id;
  v_scrive := public._combat_scrive_valori(pe.session_id);
  v_gen := (pe.kind = 'genjutsu');
  -- [V1.1 · trappola 2 del piano] 'sostituzione' entra nell'elenco delle
  -- reazioni ammesse. Senza questa riga la Sostituzione si degraderebbe IN
  -- SILENZIO a schivata, con tanto di danno.
  if p_reazione not in ('schivata','parata','tecnica','sostituzione','copie') then
    raise exception 'reazione non valida';
  end if;
  v_copie_attive := coalesce(pd.copie_attive,false);
  v_copie_n := case when v_copie_attive then greatest(0, coalesce(pd.copie_n,0)) else 0 end;
  if p_reazione = 'copie' and not v_copie_attive then
    raise exception 'le copie non sono più attive';
  end if;
  -- Il primo attacco diretto le consuma anche se si sceglie un'altra difesa.
  if v_copie_attive then
    update public.combat_participants
       set copie_attive = false, copie_round = null, copie_n = 0
     where id = pd.id;
  end if;
  if p_dif_tech is not null then
    -- [ELEM-CONSERVATO] [TASK-COMBAT-ELEMENTI-JUTSU-001, 10/08/2026] oltre a
    -- nome e disciplina si legge la natura della tecnica difensiva: e' l'unico
    -- elemento che ha diritto di comparire dalla parte della difesa. Le due
    -- sorgenti sono clan_techniques.req_elements[1] e jutsu.nature.
    select t.name, t.disciplina, (t.req_elements)[1] into v_dif_nome, v_dif_disc, v_dif_elem
      from public.clan_techniques t where t.id = p_dif_tech;
    if v_dif_nome is null then
      select j.name_it, j.category, j.nature into v_dif_nome, v_dif_disc, v_dif_elem
        from public.jutsu j where j.id = p_dif_tech;
    end if;
    -- [V1.1] la Sostituzione NON si degrada a 'tecnica' se qualcuno le passa
    -- il proprio uuid: resta riconoscibile nel referto.
    if p_reazione <> 'sostituzione' then p_reazione := 'tecnica'; end if;
  end if;
  -- [ELEM-CONSERVATO] Tre condizioni insieme, altrimenti nessun elemento in
  -- difesa: parata, schivata, Sostituzione neutrale e tecnica senza natura
  -- valgono zero.
  if p_reazione <> 'tecnica' or p_dif_tech is null then v_dif_elem := null; end if;
  v_dif_elem := nullif(btrim(coalesce(v_dif_elem,'')),'');
  if pa.mira_round = pe.round then v_mira := 3; end if;
  -- [V1.1] lo Slancio maturato dall'attaccante entra in questo confronto.
  v_slancio := case when pe.formazione_id is not null then 0
                    else least(9, greatest(0, coalesce(pa.slancio,0))) end;
  if v_scen is not null then
    select f.dado_att, f.dado_dif into v_da, v_dd from public.test_room_fixture f where f.codice = v_scen;
  end if;
  -- [V1.1 · decisione 1] il dado del confronto e' 2d10, non 1d20. Le fixture
  -- della Test Room continuano a fornire il TOTALE gia' fatto (2..20).
  v_da := coalesce(v_da, (floor(random()*10)+1)::int + (floor(random()*10)+1)::int);
  v_dd := coalesce(v_dd, (floor(random()*10)+1)::int + (floor(random()*10)+1)::int);
  c := public._combat_calcola(
    pe.kind,
    -- [ELEM-CONSERVATO] il JSON dell'attaccante NON porta element/element2.
    -- La V1.1 aggiunge 'slancio' a QUESTO json ridotto, non al vecchio.
    jsonb_build_object('forza',a.forza,'velocita',a.velocita,'mente',a.mente,'resistenza',a.resistenza,
                       'taijutsu',a.taijutsu,'ninjutsu',a.ninjutsu,'genjutsu',a.genjutsu,'fuuinjutsu',a.fuuinjutsu,
                       'slancio',v_slancio),
    -- [ELEM-CONSERVATO] il JSON del difensore porta SOLO 'tech_element'.
    jsonb_build_object('forza',d.forza,'velocita',d.velocita,'mente',d.mente,'resistenza',d.resistenza,
                       'taijutsu',d.taijutsu,'ninjutsu',d.ninjutsu,'genjutsu',d.genjutsu,'fuuinjutsu',d.fuuinjutsu,
                       'tech_element',v_dif_elem,'copie_n',v_copie_n),
    p_reazione, v_dif_disc, pe.base, pe.elemento, v_da, v_dd, v_mira + v_mod_assalto, 0, coalesce(p_colto,false));
  if v_mod_assalto<>0 then
    c:=jsonb_set(c,'{mod_mira}',to_jsonb(coalesce((c->>'mod_mira')::int,0)-v_mod_assalto),true);
  end if;
  v_colpito  := (c->>'colpito')::boolean;
  v_striscio := (c->>'striscio')::boolean and not v_gen;
  v_grez     := case when v_gen then 0 else (c->>'danno_grezzo')::int end;
  v_appl     := case when v_gen then 0 else (c->>'danno_applicato')::int end;
  v_esito_copie := nullif(c->>'esito_copie','');
  v_mod_copie   := coalesce((c->>'mod_copie')::int, 0);
  if pe.chakra_cost > 0 and coalesce(a.chakra_max,0) > 0 then
    ck := pe.chakra_cost;
    if v_scrive then
      perform set_config('app.allow_chakra_delta','1', true);
      update public.characters set chakra = greatest(0, chakra - ck) where id = a.id;
    end if;
  end if;
  v_pv := coalesce(d.vita, d.vita_max, 0);
  if v_esito_copie = 'copia_colpita' then
    testo := a.name || ' usa «' || pe.tech_name || '»: colpisce una copia di ' || d.name ||
             ', che si dissolve. L''originale non subisce danni.';
  elsif v_gen then
    if v_colpito then
      testo := a.name || ' usa «' || pe.tech_name || '»: ' || d.name || ' non regge l''illusione e ci cade dentro.';
    else
      testo := a.name || ' usa «' || pe.tech_name || '»: ' || d.name || ' riconosce l''inganno e spezza l''illusione.';
    end if;
  elsif p_reazione = 'sostituzione' then
    -- [V1.1] negazione totale: nessun danno, nemmeno di sfioramento.
    testo := d.name || ' si scambia di posto all''ultimo istante: «' || pe.tech_name ||
             '» trova un tronco al suo posto. Nessun danno.';
  elsif v_striscio then
    -- [V1.1] lo sfioramento toglie Punti Vita pur non essendo un colpo a segno:
    -- da qui in avanti la coda 〈Nome: −PV〉 compare a ogni scambio.
    v_pv := greatest(0, v_pv - v_appl);
    v_ko := (v_pv <= 0);
    if v_scrive then
      perform set_config('app.allow_vita_delta','1', true);
      update public.characters set vita = v_pv where id = d.id;
    end if;
    testo := a.name || ' usa «' || pe.tech_name || '»: ' || d.name || ' ' ||
      (case p_reazione when 'parata'  then 'para'
                       when 'tecnica' then 'oppone «' || coalesce(v_dif_nome,'una tecnica') || '»'
                       else 'schiva' end) ||
      ', ma il colpo lo sfiora e lascia il segno.';
    if v_ko then
      v_ko_txt := '〈' || d.name || ' è fuori combattimento!〉';
      update public.combat_participants set fuori = true where id = pd.id;
    end if;
  elsif not v_colpito then
    -- Ramo residuo: margine negativo senza sfioramento fuori dal genjutsu e
    -- dalla Sostituzione. Oggi non e' raggiungibile; resta per non perdere il
    -- testo storico se un domani nascesse una terza negazione.
    testo := a.name || ' usa «' || pe.tech_name || '»: ' || d.name || ' ' ||
      (case p_reazione when 'parata' then 'para in pieno e regge'
                       when 'tecnica' then 'copre il colpo con «' || coalesce(v_dif_nome,'una tecnica') || '»'
                       else 'schiva' end) || ' — nessun danno.';
  else
    v_pv := greatest(0, v_pv - v_appl);
    v_ko := (v_pv <= 0);
    if v_scrive then
      perform set_config('app.allow_vita_delta','1', true);
      update public.characters set vita = v_pv where id = d.id;
    end if;
    testo := a.name || ' usa «' || pe.tech_name || '»: ' || d.name || ' ' ||
      (case p_reazione when 'parata' then 'para ma incassa: '
                       when 'tecnica' then 'oppone «' || coalesce(v_dif_nome,'una tecnica') || '» ma '
                       when 'copie' then 'prova a confonderlo con le copie, ma l''originale viene individuato e '
                       else 'prova a schivare ma ' end) ||
      (case when (c->>'margine')::int < 5 then 'è colpito di striscio'
            when (c->>'margine')::int < 15 then 'è colpito in pieno'
            else 'subisce un colpo devastante' end) || '.';
    if v_ko then
      v_ko_txt := '〈' || d.name || ' è fuori combattimento!〉';
      update public.combat_participants set fuori = true where id = pd.id;
    end if;
  end if;
  if (c->>'mod_elem_att')::int > 0 then testo := testo || '  〈vantaggio elementale a ' || a.name || '〉'; end if;
  if (c->>'mod_elem_dif')::int > 0 then testo := testo || '  〈vantaggio elementale a ' || d.name || '〉'; end if;
  if v_test then testo := testo || '  〈prova: nessun valore è stato modificato〉'; end if;
  -- [V1.1 · decisione 3 e decisione 10] Ogni scambio che NON e' un colpo a
  -- segno da' Slancio +3 all'attaccante, tetto 9: lo sfioramento, il genjutsu
  -- spezzato e anche la Sostituzione subita. Un colpo a segno lo azzera.
  if v_colpito then v_slancio_next := 0; else v_slancio_next := least(9, v_slancio + 3); end if;
  update public.combat_participants set slancio = v_slancio_next where id = pa.id;
  insert into public.combat_referto(
    session_id, round, ordine, scenario, attacker_character, defender_character,
    attacker_name, defender_name, kind, tech_name, base, elemento, gittata, distanza,
    reazione, dif_tech_name, dif_disciplina,
    pool_att, pool_dif, dado_att, dado_dif, mod_mira, mod_guardia, mod_colto,
    mod_elem_att, mod_elem_dif, atk_tot, def_tot, margine, bonus_margine, off,
    riduzione_div, riduzione, danno_grezzo, danno_applicato, cap_attivo, colpito, ko,
    chakra_dichiarato, is_test, valori_scritti,
    mod_slancio, slancio_successivo, striscio, esito_copie, copie_n, mod_copie,
    attack_message_id, defense_message_id, narrative_attack_sha, narrative_defense_sha,
    formazione_id, esito_assalto, copie_assalto, mod_assalto)
  values (
    pe.session_id, pe.round, pe.ordine, v_scen, a.id, d.id,
    a.name, d.name, pe.kind, pe.tech_name, pe.base, pe.elemento, pe.gittata, pe.distanza,
    p_reazione, v_dif_nome, v_dif_disc,
    (c->>'pool_att')::int, (c->>'pool_dif')::int, (c->>'dado_att')::int, (c->>'dado_dif')::int,
    (c->>'mod_mira')::int, (c->>'mod_guardia')::int, (c->>'mod_colto')::int,
    (c->>'mod_elem_att')::int, (c->>'mod_elem_dif')::int,
    (c->>'atk_tot')::int, (c->>'def_tot')::int, (c->>'margine')::int, (c->>'bonus_margine')::int,
    (c->>'off')::int, nullif(c->>'riduzione_div','')::int, (c->>'riduzione')::int,
    v_grez, v_appl,
    case when v_gen then false else (c->>'cap_attivo')::boolean end,
    v_colpito, v_ko, ck, v_test, v_scrive,
    v_slancio, v_slancio_next, v_striscio, v_esito_copie, v_copie_n, v_mod_copie,
    pe.attack_message_id,
    nullif(current_setting('app.combat_action_message_id',true),'')::uuid,
    public._combat_narrative_sha(pe.attack_message_id),
    public._combat_narrative_sha(nullif(current_setting('app.combat_action_message_id',true),'')::uuid),
    pe.formazione_id, v_esito_assalto, v_copie_assalto, v_mod_assalto);
  perform public._combat_dice(pe.session_id, a.id, a.name, testo, true);
  if v_ko_txt is not null then
    perform public._combat_dice(pe.session_id, null, null, v_ko_txt, false);
  end if;
  delete from public.combat_pending where id = p_pending;
  return testo;
end; $function$;

