GRANT EXECUTE ON FUNCTION public._combat_risolvi(uuid,text,boolean,uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION public._combat_risolvi(uuid,text,boolean,uuid) TO "service_role";

