-- Native source public._combat_round_tick(uuid,integer) MD5 6d2dcd9dab8c86f610a62ce4d00af27a

CREATE OR REPLACE FUNCTION public._combat_round_tick(p_session uuid, p_round integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_test boolean; v_scrive boolean; v_ck int;
begin
  select l.is_test into v_test from public.locations l
    join public.combat_sessions s on s.location_id = l.id where s.id = p_session;
  v_scrive := public._combat_scrive_valori(p_session);

  for r in select ca.*, c.name as pg_nome, c.chakra as pg_chakra, c.id as pg_id
             from public.character_active ca join public.characters c on c.id = ca.character_id
            where ca.session_id = p_session loop
    v_ck := coalesce(r.chakra_per_round,0);
    if v_ck <= 0 then continue; end if;
    if coalesce(r.pg_chakra,0) < v_ck then
      delete from public.character_active where id = r.id;
      perform public._combat_dice(p_session, r.pg_id, 'Scontro',
        'Il chakra di ' || r.pg_nome || ' non basta più: «' || r.tech_name || '» si spegne.', true);
    else
      if v_scrive then
        perform set_config('app.allow_chakra_delta','1', true);
        update public.characters set chakra = greatest(0, chakra - v_ck) where id = r.pg_id;
      end if;
      perform public._combat_dice(p_session, r.pg_id, 'Scontro',
        r.pg_nome || ' mantiene «' || r.tech_name || '»: −' || v_ck || ' chakra'
        || (case when coalesce(v_test,false) then '  〈prova: nessun valore è stato modificato〉' else '' end), true);
    end if;
  end loop;

  update public.combat_effects set round_rimanenti = round_rimanenti - 1 where session_id = p_session;
  delete from public.combat_effects where session_id = p_session and round_rimanenti <= 0;
end; $function$;

