-- Native source public._combat_togli_trigger(text,jsonb) MD5 9c4c60de026cd9efe39024badab588be

CREATE OR REPLACE FUNCTION public._combat_togli_trigger(p_body text, p_consumati jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare r record; out_txt text := coalesce(p_body,'');
begin
  if p_consumati is null or jsonb_array_length(p_consumati) = 0 then return out_txt; end if;
  -- si ritaglia dall'ultimo al primo, così le posizioni davanti restano valide
  for r in select (e->>'i')::int as i, (e->>'n')::int as n
             from jsonb_array_elements(p_consumati) e
            order by (e->>'i')::int desc loop
    out_txt := substr(out_txt, 1, r.i - 1) || substr(out_txt, r.i + r.n);
  end loop;
  return btrim(regexp_replace(out_txt, '[ \t]{2,}', ' ', 'g'));
end; $function$;

