-- Native source public._combat_trova_tecnica(text,boolean,uuid) MD5 ba87f6aeec3d0723b434358f909c01ad

CREATE OR REPLACE FUNCTION public._combat_trova_tecnica(p_nome text, p_libero boolean DEFAULT false, p_char uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare k text; k2 text; liv int; v_id uuid; v_nome text; n int; n_liv int; v_alt text;
begin
  k := public._nome_chiave(coalesce(p_nome,''));
  if k = '' then return jsonb_build_object('errore','quale tecnica? per esempio [tecnica: Grande sfera di fuoco]'); end if;
  if k ~ ' [1-9]$' then liv := right(k,1)::int; k2 := btrim(left(k, length(k)-1)); end if;

  -- A · catalogo, chiave intera
  select count(*) into n from public.clan_techniques t
   where t.is_active and public._nome_chiave(t.name) = k
     and (p_libero or exists (select 1 from public.character_abilities ca
                               where ca.technique_id=t.id and ca.character_id=p_char and ca.state='attiva'));
  if n = 1 then
    select t.id, t.name into v_id, v_nome from public.clan_techniques t
     where t.is_active and public._nome_chiave(t.name) = k
       and (p_libero or exists (select 1 from public.character_abilities ca
                                 where ca.technique_id=t.id and ca.character_id=p_char and ca.state='attiva')) limit 1;
    return jsonb_build_object('id', v_id, 'fonte','clan','nome', v_nome);
  elsif n > 1 then
    select count(distinct t.level) into n_liv from public.clan_techniques t
     where t.is_active and public._nome_chiave(t.name) = k;
    if n_liv = n then
      return jsonb_build_object('errore','«'||btrim(p_nome)||'» esiste su '||n||' livelli: scegli quale, per esempio [tecnica: '||btrim(p_nome)||' 2]');
    end if;
    select string_agg(distinct coalesce(t.clan,'generica'), ' · ') into v_alt
      from public.clan_techniques t where t.is_active and public._nome_chiave(t.name) = k;
    return jsonb_build_object('errore','«'||btrim(p_nome)||'» esiste in più versioni ('||v_alt||'): non so quale intendi');
  end if;

  -- B · nome con il livello scritto in coda
  if liv is not null then
    select count(*) into n from public.clan_techniques t
     where t.is_active and public._nome_chiave(t.name) = k2 and t.level = liv
       and (p_libero or exists (select 1 from public.character_abilities ca
                                 where ca.technique_id=t.id and ca.character_id=p_char and ca.state='attiva'));
    if n = 1 then
      select t.id, t.name into v_id, v_nome from public.clan_techniques t
       where t.is_active and public._nome_chiave(t.name) = k2 and t.level = liv
         and (p_libero or exists (select 1 from public.character_abilities ca
                                   where ca.technique_id=t.id and ca.character_id=p_char and ca.state='attiva')) limit 1;
      return jsonb_build_object('id', v_id, 'fonte','clan','nome', v_nome, 'livello', liv);
    end if;
    select count(*) into n from public.clan_techniques t where t.is_active and public._nome_chiave(t.name) = k2;
    if n > 0 then
      return jsonb_build_object('errore','«'||btrim(p_nome)||'»: quel livello non c''è, i livelli disponibili sono '||n);
    end if;
  end if;

  -- C · basi d'Accademia
  select count(*) into n from public.jutsu j
   where j.is_active and public._nome_chiave(j.name_it) = k
     and (p_libero or exists (select 1 from public.character_jutsu cj where cj.jutsu_id=j.id and cj.user_id=auth.uid()));
  if n = 1 then
    select j.id, j.name_it into v_id, v_nome from public.jutsu j
     where j.is_active and public._nome_chiave(j.name_it) = k
       and (p_libero or exists (select 1 from public.character_jutsu cj where cj.jutsu_id=j.id and cj.user_id=auth.uid())) limit 1;
    return jsonb_build_object('id', v_id, 'fonte','jutsu','nome', v_nome);
  end if;

  -- D · niente: i nomi più vicini
  select string_agg(x,' · ') into v_alt from
    (select t.name as x from public.clan_techniques t
      where t.is_active and public._nome_chiave(t.name) like '%'||k||'%' order by t.name limit 3) s;
  if v_alt is null then
    select string_agg(x,' · ') into v_alt from
      (select t.name as x from public.clan_techniques t
        where t.is_active and public._nome_chiave(t.name) like '%'||split_part(k,' ',1)||'%' order by t.name limit 3) s;
  end if;
  return jsonb_build_object('errore','Non trovo «'||btrim(p_nome)||'»'||coalesce('. Forse: '||v_alt,'.'));
end; $function$;

