-- Native source public._companions_guard() MD5 dbeca7e5f4bb57c28356cfcc6b69f2e1

CREATE OR REPLACE FUNCTION public._companions_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_staff() then
    if new.grado is distinct from old.grado then raise exception 'La taglia del compagno la assegna lo staff'; end if;
    if new.kind is distinct from old.kind then raise exception 'Il tipo del compagno non si cambia'; end if;
    if new.famiglia is distinct from old.famiglia then raise exception 'La famiglia dell''evocazione non si cambia'; end if;
    if new.character_id is distinct from old.character_id then raise exception 'operazione non consentita'; end if;
  end if;
  return new;
end $function$;

