-- Native source public._esame_profilo_guard() MD5 1add8b81de7b3ec90ce79554fc03828c

CREATE OR REPLACE FUNCTION public._esame_profilo_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int; v_aperte int;
begin
  if new.is_active then
    select count(*) into v_n from public.esame_png_profili
     where is_active and villaggio = new.villaggio and id <> new.id;
    if v_n >= 3 then
      raise exception 'Nel villaggio % ci sono già tre avversari attivi: non se ne accende un quarto.', new.villaggio;
    end if;
  end if;

  if tg_op = 'UPDATE' and old.is_active and not new.is_active then
    select count(*) into v_aperte from public.esame_prove
     where profilo_id = new.id and stato = 'aperta';
    if v_aperte > 0 then
      raise exception 'Questo avversario sta giocando % prove aperte: si ritira dopo, non adesso.', v_aperte;
    end if;
    raise notice 'Avversario % ritirato: nel villaggio % restano % attivi.', new.nome, new.villaggio,
      (select count(*) from public.esame_png_profili where is_active and villaggio = new.villaggio and id <> new.id);
  end if;

  new.updated_at := now();
  return new;
end
$function$;

