-- Native source public._esame_prova_immutabile() MD5 da9ec65ed2ec3d67edd53eaccd421204

CREATE OR REPLACE FUNCTION public._esame_prova_immutabile()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.profilo_id is distinct from old.profilo_id then
    raise exception 'L''avversario di una prova non si cambia: è scritto all''apertura.';
  end if;
  if new.seme is distinct from old.seme then
    raise exception 'Il seme di una prova non si cambia: la prova smetterebbe di essere riproducibile.';
  end if;
  if new.candidate_user is distinct from old.candidate_user
     or new.candidate_character is distinct from old.candidate_character
     or new.class_session_id is distinct from old.class_session_id then
    raise exception 'Il candidato e la sessione di una prova non si cambiano.';
  end if;
  new.updated_at := now();
  return new;
end
$function$;

