-- Native source public._esame_supervisione_associa() MD5 52d32562340e277e45ec8a13d5efa864

CREATE OR REPLACE FUNCTION public._esame_supervisione_associa()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.esame_supervisione_prenotazioni%rowtype; v_loc uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('esame_supervisione:'||new.candidate_character::text,0));
  select * into r from public.esame_supervisione_prenotazioni
    where personaggio=new.candidate_character and is_active and prova is null for update;
  if found then
    select location_id into v_loc from public.academy_class_sessions where id=new.class_session_id;
    if v_loc is distinct from r.luogo then raise exception 'La prova supervisionata deve aprirsi nel luogo prenotato'; end if;
    insert into public.esame_supervisione(prova,prenotazione) values(new.id,r.id);
    update public.esame_supervisione_prenotazioni set prova=new.id where id=r.id;
  end if;
  return new;
end; $function$;

