-- Native source public._narrative_exam_persona(jsonb,text) MD5 fef3512bef6f5ace85f1724f3219670b

CREATE OR REPLACE FUNCTION public._narrative_exam_persona(p_persona jsonb, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_traits jsonb;
  v_drives jsonb;
  v_stress jsonb;
  v_physical jsonb;
  v_id text;
begin
  if jsonb_typeof(p_persona->'tratti') <> 'array'
     or jsonb_typeof(p_persona->'condotta') <> 'object'
     or jsonb_typeof(p_persona->'reazioni') <> 'object'
     or jsonb_typeof(p_persona->'aspetto') <> 'object' then
    raise exception using errcode='22023', message='persona Exam non strutturata';
  end if;

  select coalesce(jsonb_agg(left(value,160) order by ordinal),'[]'::jsonb)
    into v_traits
    from jsonb_array_elements_text(p_persona->'tratti') with ordinality x(value,ordinal)
   where btrim(value) <> '' and ordinal <= 8;

  v_drives := jsonb_build_array(
    left(coalesce(nullif(btrim(p_persona#>>'{condotta,apertura}'),''),'affronta la prova con attenzione'),160),
    left(coalesce(nullif(btrim(p_persona#>>'{condotta,in_difesa}'),''),'adatta la difesa alla scena'),160),
    left(coalesce(nullif(btrim(p_persona#>>'{condotta,quando_e_indietro}'),''),'reagisce alla pressione senza uscire dalle opzioni offerte'),160)
  );
  v_stress := jsonb_build_array(
    left(coalesce(nullif(btrim(p_persona#>>'{reazioni,pressione}'),''),'la pressione modifica il ritmo senza cancellare la persona'),160),
    left(coalesce(nullif(btrim(p_persona#>>'{reazioni,errore}'),''),'un errore lascia una reazione visibile prima del recupero'),160),
    left(coalesce(nullif(btrim(p_persona#>>'{reazioni,successo}'),''),'una riuscita non cancella la fatica accumulata'),160)
  );
  v_physical := jsonb_build_array(
    left(coalesce(nullif(btrim(p_persona#>>'{aspetto,eta}'),''),'giovane allievo dell''Accademia'),160),
    left(coalesce(nullif(btrim(p_persona#>>'{aspetto,corporatura}'),''),'corporatura giovane ancora in crescita'),160),
    left(coalesce(nullif(btrim(p_persona#>>'{aspetto,capelli}'),''),'capelli ordinati per la prova'),160),
    left(coalesce(nullif(btrim(p_persona#>>'{aspetto,occhi}'),''),'sguardo rivolto alla figura avversaria'),160)
  );
  if jsonb_array_length(v_traits) < 2 then
    v_traits := jsonb_build_array('presenza riconoscibile durante la prova','attenzione rivolta alla persona avversaria');
  end if;
  v_id := 'persona.' || lower(regexp_replace(public._narrative_surface_label(p_name,'avversario'),'[^[:alnum:]]+','','g'));
  return jsonb_build_object(
    'id',v_id,
    'stable_traits',v_traits,
    'combat_drives',v_drives,
    'stress_curve',v_stress,
    'physical_traits',v_physical
  );
end
$function$;

