-- Native source public._role_finalize(uuid,text) MD5 d5804b8a994de02330ce30b3d795a375

CREATE OR REPLACE FUNCTION public._role_finalize(p_session uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sess    public.role_sessions%rowtype;
  v_cnt     int;
  v_prec    int;                            -- righe gia' in snapshot che il predicato di oggi terrebbe
  v_tot     int;                            -- righe gia' in snapshot, tutte
  v_close   timestamptz := now();
begin
  -- [ROLE-REC-INTEGRITY-005] Il lock serializza i percorsi di chiusura fra loro
  -- (role_close, role_salva, role_maintenance) e il retry del cron: chi arriva
  -- secondo trova closed_at valorizzato e torna senza scrivere.
  select * into v_sess from public.role_sessions where id=p_session for update;
  if v_sess.id is null then return; end if;

  -- CONSERVATO. REC gia' finalizzata: non si tocca niente e non si alza niente.
  -- E' il caso della seconda finalizzazione, del retry e della doppia chiusura
  -- ravvicinata. Lo snapshot, il close_reason e il msg_count restano quelli.
  if v_sess.closed_at is not null then return; end if;

  -- SOSTITUITO. REC aperta che ha gia' uno snapshot: succede solo dopo
  -- role_scongela, che azzera closed_at e lascia le righe dov'erano. Lo
  -- snapshot e' una derivazione pura di messages U messages_archive sulla
  -- finestra [record_from, v_close], quindi si ricostruisce per intero invece
  -- di accodare: accodare duplicherebbe il contenuto della prima chiusura.
  select count(*)::int,
         count(*) filter (where public._role_msg_scena(rm.kind, null))::int
    into v_tot, v_prec
    from public.role_messages rm
   where rm.session_id = p_session;

  if v_tot > 0 then
    delete from public.role_messages where session_id = p_session;
  end if;

  with src as (
    select id, author_name, body, kind, dice_sides, dice_result, created_at
      from public.messages
      where location_id=v_sess.location_id and created_at >= v_sess.record_from and created_at <= v_close
        and public._role_msg_scena(kind, recipient_user)
    union all
    select id, author_name, body, kind, dice_sides, dice_result, created_at
      from public.messages_archive
      where location_id=v_sess.location_id and created_at >= v_sess.record_from and created_at <= v_close
        and public._role_msg_scena(kind, recipient_user)
  ), ord as (
    -- l'id spareggia i pari merito: dentro una transazione now() e' costante e
    -- piu' righe condividono created_at. Senza spareggio la ricostruzione non
    -- sarebbe ripetibile, e l'idempotenza non si potrebbe dimostrare.
    select row_number() over (order by created_at asc, id asc) as seq, * from src
  )
  insert into public.role_messages(session_id,seq,author_name,body,kind,dice_sides,dice_result,created_at)
  select p_session, seq, author_name, body, kind, dice_sides, dice_result, created_at from ord;
  get diagnostics v_cnt = row_count;

  -- Guardia di non regressione: la ricostruzione non puo' contenere MENO righe
  -- di quelle che il predicato di oggi avrebbe tenuto nello snapshot vecchio.
  -- Se accade, la fonte e' stata svuotata sotto i piedi della REC: si alza, e
  -- l'annullamento del blocco rimette in piedi lo snapshot precedente.
  -- Non e' un'eccezione ignorata: e' l'unico caso in cui si rifiuta di chiudere.
  if v_cnt < v_prec then
    raise exception 'REC %: ricostruzione dello snapshot in regressione (% righe contro %). Snapshot precedente conservato, REC non chiusa.',
      p_session, v_cnt, v_prec using errcode = 'data_exception';
  end if;

  update public.role_sessions set closed_at=v_close, close_reason=p_reason, msg_count=v_cnt where id=p_session;

  -- il contributo si ricostruisce dalla fonte; il salvataggio no, quello e'
  -- un atto del giocatore
  perform public._role_ricalcola(p_session, v_close);
end; $function$;

