-- Native source public._role_ricalcola(uuid,timestamp with time zone) MD5 235a7fa99c3b047b5a72fb0cc1c7482e

CREATE OR REPLACE FUNCTION public._role_ricalcola(p_session uuid, p_fino timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  update public.role_session_participants rsp
     set message_count    = greatest(coalesce(rsp.message_count,0), k.n),
         first_message_at = least(   coalesce(rsp.first_message_at, k.primo),  k.primo),
         last_message_at  = greatest(coalesce(rsp.last_message_at,  k.ultimo), k.ultimo)
    from public._role_contributi(p_session, p_fino) k
   where rsp.session_id = p_session
     and rsp.character_id = k.character_id;
  get diagnostics v_n = row_count;
  return v_n;   -- registrazioni riconosciute come reali
end $function$;

