-- Native source public._test_room_azzera(uuid) MD5 434484f2c6487560647181ffa8668281

CREATE OR REPLACE FUNCTION public._test_room_azzera(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_s public.combat_sessions%rowtype;
begin
  select * into v_s from public.combat_sessions where id = p_session;
  if v_s.id is null then return; end if;
  delete from public.combat_pending  where session_id = p_session;
  delete from public.character_active where session_id = p_session;
  update public.combat_sessions set scenario = null, round = 1 where id = p_session;
  update public.combat_participants p
     set round_speso = 0, usato_principale = false, usato_rapida = false,
         usato_reazione = false, usato_spostamento = false,
         guardia_round = null, mira_round = null, sostituzione_round = null,
         mossa_pendente = null, fuori = false,
         slancio = 0,
         pos_m = case when p.ruolo <> 'combattente' then p.pos_m
                      when p.user_id = v_s.opened_by then 0
                      else greatest(0, least(60, coalesce(v_s.distanza_ingaggio, 0))) end
   where p.session_id = p_session;
end; $function$;

