-- Native source public._training_nonlethal_resource_guard() MD5 75e939d05fd630e03df146379ab7cd6c

CREATE OR REPLACE FUNCTION public._training_nonlethal_resource_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_combat uuid; v_reason text;
begin
  if new.vita is distinct from old.vita and new.vita<=0 then v_reason:='K.O. non letale';
  elsif new.chakra is distinct from old.chakra and new.chakra<=0 then v_reason:='fatica: chakra esaurito';
  else return null; end if;
  select s.id into v_combat
  from public.combat_sessions s join public.combat_participants cp on cp.session_id=s.id
  where cp.character_id=new.id and cp.ruolo='combattente' and s.state='aperto' and s.kind='allenamento' and s.lesiva
    and exists(select 1 from public.training_sessions x where x.combat_session_id=s.id and x.stato in ('dichiarata','sospetta','valida'))
  order by s.created_at limit 1;
  if v_combat is not null then perform public._training_sparring_close(v_combat,v_reason,new.id); end if;
  return null;
end $function$;

