-- Native source public._training_sparring_close(uuid,text,uuid) MD5 d07a2c2060b6007d9d7d2249ee8d3f77

CREATE OR REPLACE FUNCTION public._training_sparring_close(p_combat uuid, p_reason text, p_character uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.combat_sessions%rowtype; v_spente int;
begin
  select * into s from public.combat_sessions where id=p_combat for update;
  if not found or s.state<>'aperto' then return false; end if;
  if s.kind<>'allenamento' or not s.lesiva or not exists(
    select 1 from public.training_sessions x where x.combat_session_id=s.id
      and x.stato in ('dichiarata','sospetta','valida')) then return false; end if;
  if p_character is not null then
    update public.combat_participants set fuori=true where session_id=s.id and character_id=p_character;
  end if;
  select count(*) into v_spente from public.character_active where session_id=s.id;
  delete from public.character_active where session_id=s.id;
  delete from public.combat_pending where session_id=s.id;
  update public.combat_sessions set state='chiuso',closed_at=now(),closed_reason=p_reason,turn_of=null where id=s.id;
  perform public._combat_dice(s.id,(select character_id from public.combat_participants where session_id=s.id order by joined_at limit 1),
    'Scontro','Lo sparring si chiude ('||p_reason||').' || case when v_spente>0 then ' Le arti innate accese si spengono.' else '' end,true);
  return true;
end $function$;

