CREATE OR REPLACE FUNCTION public.characters_align_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(current_setting('app.allow_align_delta', true),'') = '1' then return new; end if;
  if new.lealta is distinct from old.lealta then
    insert into public.allineamento_log(character_id, asse, delta, valore_dopo, motivo)
      values (new.id,'lealta', coalesce(new.lealta,50)-coalesce(old.lealta,50), new.lealta, 'intervento dello staff');
  end if;
  if new.via is distinct from old.via then
    insert into public.allineamento_log(character_id, asse, delta, valore_dopo, motivo)
      values (new.id,'via', coalesce(new.via,50)-coalesce(old.via,50), new.via, 'intervento dello staff');
  end if;
  if new.fama is distinct from old.fama then
    insert into public.allineamento_log(character_id, asse, delta, valore_dopo, motivo)
      values (new.id,'fama', coalesce(new.fama,50)-coalesce(old.fama,50), new.fama, 'intervento dello staff');
  end if;
  return new;
end; $function$;

