-- Native source public.characters_check_name() MD5 55b0661a872f653b76af8abe3c3ea006

CREATE OR REPLACE FUNCTION public.characters_check_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (tg_op = 'INSERT') or (new.name is distinct from old.name) then
    if new.name !~ '^[A-Za-zÀ-ÿ''’-]{2,15}$' then
      raise exception 'Nome non valido: 2–15 lettere (accenti, apostrofo e trattino ammessi), senza numeri né spazi';
    end if;
  end if;
  if public.name_is_blocked(new.name) then
    raise exception 'Nome personaggio non consentito';
  end if;

  new.cognome := nullif(btrim(new.cognome), '');

  if tg_op = 'UPDATE' and old.cognome is not null and new.cognome is null then
    raise exception 'Il cognome non si svuota: per cambiarlo se ne scrive un altro';
  end if;

  if new.cognome is not null and ((tg_op = 'INSERT') or (new.cognome is distinct from old.cognome)) then
    if new.cognome !~ '^[A-Za-zÀ-ÿ''’-]{2,15}$' then
      raise exception 'Cognome non valido: 2–15 lettere (accenti, apostrofo e trattino ammessi), senza numeri né spazi';
    end if;
    if public.name_is_blocked(new.cognome) then
      raise exception 'Cognome non consentito';
    end if;
    if ((tg_op = 'INSERT') or (old.cognome is null)) and not public._cognome_idoneo(new.clan) then
      raise exception 'Il cognome si assegna solo a chi non ne ha gia uno dal clan: Marionettisti o nessun clan';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$function$;

