 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public._grade_rank(coalesce(new.rank,'Deshi')) >= 1
     and public._grade_rank(coalesce(old.rank,'Deshi')) < 1 then
    insert into public.character_jutsu(user_id, jutsu_id, source)
      select new.user_id, j.id, 'promozione'
        from public.jutsu j
       where j.is_active
      on conflict (user_id, jutsu_id) do nothing;
  end if;
  return new;
end $function$;

