-- Native source public.characters_grant_pool() MD5 5b8037786f31ea6aa80b534951d43a38

CREATE OR REPLACE FUNCTION public.characters_grant_pool()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_gia int; v_ora int; v_delta int;
begin
  v_gia := coalesce(new.pool_concesso, 60);
  v_ora := public._pool_del_grado(new.rank);
  v_delta := v_ora - v_gia;
  if v_delta > 0 then
    perform set_config('app.allow_points_delta','1', true);
    update public.characters
       set unspent_points = coalesce(unspent_points,0) + v_delta,
           pool_concesso = v_ora
     where id = new.id;
    perform set_config('app.allow_points_delta','', true);
  end if;
  return null;
end; $function$;

