CREATE OR REPLACE FUNCTION public.characters_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_staff() then
    return new;  -- service_role/superuser (Eredità, seed) e staff possono inserire valori personalizzati
  end if;
  new.rank := 'Deshi';
  new.money := 0;
  new.exp := 0;
  new.xp_lifetime := 0;
  new.last_daily_xp := null;
  new.slot_extra := 0;
  new.unspent_points := 60;
  new.lealta := 50; new.via := 50; new.fama := 50;
  new.clan := 'Nessuno'; new.clan_role := null; new.corporation := null; new.epithet := null; new.cognome := null;
  new.taijutsu := 10; new.ninjutsu := 10; new.genjutsu := 10;
  new.forza := 10; new.velocita := 10; new.mente := 10;
  new.resistenza := 10; new.fuuinjutsu := 10; new.kekkei_genkai := 10;
  return new;
end; $function$;

ALTER FUNCTION public.characters_insert_guard() OWNER TO "postgres";

