-- Native source public.clan_genin_catalog_function_resolve_v1(uuid,text) MD5 31fd05ded1b425b5430618a4509a2204

CREATE OR REPLACE FUNCTION public.clan_genin_catalog_function_resolve_v1(p_catalog_technique uuid, p_function_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;
begin
  select m.*, p.clan, p.route_id, p.resolver_signature, p.readiness, p.numeric_status, p.is_simulated
    into r
  from public.clan_genin_catalog_function_map_v1 m
  join public.clan_genin_spatial_profile_registry_v1 p
    on (p.profile_id,p.profile_version)=(m.profile_id,m.profile_version)
  where m.catalog_technique_id=p_catalog_technique and m.function_id=p_function_id;
  if not found or r.blocked then raise exception 'clan_fixture_profile_unavailable'; end if;
  if r.readiness <> 'ready' or to_regprocedure(r.resolver_signature) is null then
    raise exception 'clan_fixture_dependency_not_ready';
  end if;
  return jsonb_build_object('function_id',r.function_id,'profile_id',r.profile_id,
    'profile_version',r.profile_version,'route_id',r.route_id,'resolver_signature',r.resolver_signature,
    'exposure_mode',r.exposure_mode,'numeric_status',r.numeric_status,'is_simulated',r.is_simulated);
end $function$;

