-- Native source public.clan_genin_runtime_gate_context_v1(uuid,uuid) MD5 4f1ca97ae1c0d573dc1337b6f6143f4b

CREATE OR REPLACE FUNCTION public.clan_genin_runtime_gate_context_v1(p_round uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g public.clan_genin_runtime_gate_v1%rowtype;
begin
  if not public.is_staff() then raise exception 'clan_fixture_forbidden'; end if;
  if not exists (
    select 1 from public.combat_v2_rounds r
    join public.combat_v2_sessions s on s.id=r.session_id
    join public.combat_v2_actors a on a.session_id=s.id and a.id=p_actor
    join public.locations l on l.id=s.location_id
    where r.id=p_round and l.is_test and coalesce(l.is_active,false)
  ) then raise exception 'clan_fixture_forbidden'; end if;
  select * into strict g from public.clan_genin_runtime_gate_v1
   where gate_id='staff_room_genin_spatial_smoke_v1';
  if not g.enabled then raise exception 'clan_fixture_disabled'; end if;
  return jsonb_build_object('gate_id',g.gate_id,'config_version',g.config_version,'readiness_pin',g.readiness_pin,
    'staff_only',g.staff_only,'public_offer',g.public_offer,'progression_write',g.progression_write,
    'is_simulated',g.is_simulated,'numeric_status',g.numeric_status);
end $function$;

