-- Native source public.clan_genin_runtime_gate_set_v1(bigint,boolean,text,uuid) MD5 29b653737a70d02cdc2b67985b376435

CREATE OR REPLACE FUNCTION public.clan_genin_runtime_gate_set_v1(p_expected_version bigint, p_enabled boolean, p_reason text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  g public.clan_genin_runtime_gate_v1%rowtype;
  prior public.clan_genin_runtime_gate_audit_v1%rowtype;
  v_bad integer;
  v_old_enabled boolean;
  v_old_version bigint;
  v_registry_fp text;
  v_inventory_fp text;
  v_mapping_fp text;
begin
  if p_request_key is null or nullif(btrim(p_reason),'') is null then
    raise exception 'invalid_gate_request';
  end if;

  select * into prior
  from public.clan_genin_runtime_gate_audit_v1
  where request_key=p_request_key;
  if found then
    if prior.old_version=p_expected_version and prior.new_enabled=p_enabled and prior.reason=btrim(p_reason) then
      return jsonb_build_object('gate_id',prior.gate_id,'enabled',prior.new_enabled,
        'config_version',prior.new_version,'replay',true);
    end if;
    raise exception 'gate_request_key_conflict';
  end if;

  select * into strict g from public.clan_genin_runtime_gate_v1
  where gate_id='staff_room_genin_spatial_smoke_v1' for update;
  if g.config_version<>p_expected_version then raise exception 'stale_gate_version'; end if;
  v_old_enabled := g.enabled;
  v_old_version := g.config_version;

  if p_enabled then
    if not g.staff_only or g.public_offer or g.progression_write or not g.is_simulated
       or g.numeric_status<>'RED_SIMULATION'
       or g.readiness_pin<>'hyuga_genin_runtime_readiness_pin_v1' then
      raise exception 'clan_fixture_isolation_marker_drift';
    end if;

    select md5(string_agg(concat_ws('|',profile_id,profile_version,clan,route_id,
      resolver_signature,numeric_status,is_simulated,contract_version),E'\n'
      order by profile_id,profile_version)) into v_registry_fp
    from public.clan_genin_spatial_profile_registry_v1;
    select md5(string_agg(concat_ws('|',catalog_technique_id,clan,expected_name,
      inventory_scope,runtime_projection,readiness_pin),E'\n'
      order by catalog_technique_id)) into v_inventory_fp
    from public.clan_genin_live_inventory_pin_v1;
    select md5(string_agg(concat_ws('|',catalog_technique_id,function_id,profile_id,
      profile_version,exposure_mode,expected_clan,expected_name,blocked,
      coalesce(block_reason,''),mapping_version),E'\n'
      order by catalog_technique_id,function_id)) into v_mapping_fp
    from public.clan_genin_catalog_function_map_v1;

    if v_registry_fp<>'5a53c11430c1add08bbdb77e77e86ed5'
       or v_inventory_fp<>'bfc43a2a3f3e273acb103330b0019b58'
       or v_mapping_fp<>'e043faf24a4dedf905155d5bc4354367' then
      raise exception 'clan_fixture_configuration_drift';
    end if;

    if (select count(*) from public.clan_genin_spatial_profile_registry_v1)<>44
       or (select count(*) from public.clan_genin_live_inventory_pin_v1)<>30
       or (select count(*) from public.clan_genin_live_inventory_pin_v1 where runtime_projection)<>29
       or (select count(*) from public.clan_genin_catalog_function_map_v1 where exposure_mode='catalog_offer')<>29
       or (select count(*) from public.clan_genin_catalog_function_map_v1 where exposure_mode<>'catalog_offer')<>16
       or exists(select 1 from public.clan_genin_catalog_function_map_v1 where blocked) then
      raise exception 'clan_fixture_configuration_cardinality_drift';
    end if;

    if (select count(*) from public.clan_genin_catalog_function_map_v1
        where expected_clan='Hyuga' and exposure_mode='catalog_offer')<>3
       or exists (
         (select catalog_technique_id from public.clan_genin_catalog_function_map_v1
          where expected_clan='Hyuga' and exposure_mode='catalog_offer')
         except
         (values ('4a527ff2-0420-4da9-bc1f-5489c753b285'::uuid),
                 ('11f66832-ce46-4802-b20f-f4e0b3fd4af0'::uuid),
                 ('031d5ecc-86ee-4d21-85f1-6b76fc57cef9'::uuid))
       )
       or exists (
         (values ('4a527ff2-0420-4da9-bc1f-5489c753b285'::uuid),
                 ('11f66832-ce46-4802-b20f-f4e0b3fd4af0'::uuid),
                 ('031d5ecc-86ee-4d21-85f1-6b76fc57cef9'::uuid))
         except
         (select catalog_technique_id from public.clan_genin_catalog_function_map_v1
          where expected_clan='Hyuga' and exposure_mode='catalog_offer')
       )
       or exists(select 1 from public.clan_genin_catalog_function_map_v1
         where catalog_technique_id in
           ('6f47860d-4b7a-4ade-88f0-627541ef135d'::uuid,
            '755d4ed6-0f27-4c3a-acbe-11917a524aa6'::uuid)) then
      raise exception 'hyuga_runtime_projection_drift';
    end if;

    select count(*) into v_bad from public.clan_genin_spatial_profile_registry_v1 p
    where p.readiness<>'ready' or to_regprocedure(p.resolver_signature) is null;
    if v_bad<>0 then raise exception 'clan_fixture_dependency_not_ready'; end if;
  end if;

  update public.clan_genin_runtime_gate_v1
  set enabled=p_enabled,config_version=config_version+1,
      changed_at=clock_timestamp(),changed_reason=btrim(p_reason)
  where gate_id=g.gate_id returning * into g;
  insert into public.clan_genin_runtime_gate_audit_v1
    (gate_id,request_key,old_enabled,new_enabled,old_version,new_version,reason)
  values(g.gate_id,p_request_key,v_old_enabled,p_enabled,v_old_version,g.config_version,btrim(p_reason));
  return jsonb_build_object('gate_id',g.gate_id,'enabled',g.enabled,
    'config_version',g.config_version,'replay',false);
end $function$;

