-- Native source public.clan_marionettisti_control_v1(uuid,uuid) MD5 f734db49d67da778bb795f6f837a4153

CREATE OR REPLACE FUNCTION public.clan_marionettisti_control_v1(p_option uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o clan_marionettisti_private.relink_offers%rowtype;a public.combat_v2_actors%rowtype;r public.combat_v2_rounds%rowtype;
 l clan_marionettisti_private.links%rowtype;e clan_marionettisti_private.control_events%rowtype;
 fp text;eid uuid;v_values boolean;balance integer;result jsonb;
begin
 if auth.uid() is null or p_option is null or p_request is null then raise exception 'relink_authentication_required' using errcode='42501';end if;
 select * into strict o from clan_marionettisti_private.relink_offers where offer_id=p_option;
 perform public.combat_v2_lock_round(o.round_id);
 select * into strict r from public.combat_v2_rounds where id=o.round_id for update;
 perform 1 from public.combat_v2_sessions where id=r.session_id for update;
 select * into strict a from public.combat_v2_actors where id=o.owner_actor_id for update;
 if a.controller_user is distinct from auth.uid() or a.session_id<>r.session_id then raise exception 'relink_actor_not_owned' using errcode='42501';end if;
 fp:=public.combat_v2_sha256(jsonb_build_object('operation','relink/1','option',p_option,'round',r.id,'owner',a.id,'version',o.expected_link_version));
 select * into e from clan_marionettisti_private.control_events where owner_actor_id=a.id and kind='relinked' and request_key=p_request;
 if found then
  if e.fingerprint<>fp then raise exception 'relink_request_conflict';end if;
  return e.payload||jsonb_build_object('replay',true);
 end if;
 if not clan_marionettisti_private.owner_eligible(a.id,false) then raise exception 'relink_not_offered';end if;
 perform 1 from public.characters where id=a.character_id for update;
 select * into strict l from clan_marionettisti_private.links where owner_actor_id=a.id for update;
 perform 1 from clan_marionettisti_private.sources where id=(select companion_id from public.combat_v2_actors where id=l.companion_actor_id) for update;
 perform clan_marionettisti_private.assert_companion_actor(l.companion_actor_id);
 if l.link_version<>o.expected_link_version or not clan_marionettisti_private.relink_ready(r.id,a.id) then raise exception 'relink_offer_stale_or_not_ready';end if;
 v_values:=public.combat_v2_values_written(r.session_id);balance:=(a.mechanics_snapshot->>'chakra')::integer;
 eid:=gen_random_uuid();
 result:=jsonb_build_object('event_id',eid,'owner_actor_id',a.id,'link_version',l.link_version+1,
  'chakra_cost',5,'main_cost',0,'simulated',not v_values,'replay',false);
 insert into clan_marionettisti_private.control_events(event_id,session_id,round_id,owner_actor_id,kind,request_key,fingerprint,payload)
  values(eid,r.session_id,r.id,a.id,'relinked',p_request,fp,result);
 insert into public.combat_v2_resource_ledger(session_id,round_id,declaration_id,control_event_id,actor_id,resource_kind,
  expected_amount,committed_amount,applied_amount,is_simulated,balance_before,balance_after,idempotency_key)
 values(r.session_id,r.id,null,eid,a.id,'chakra',5,5,case when v_values then 5 else 0 end,
  not v_values,balance,balance-5,p_request);
 update public.combat_v2_actors set mechanics_snapshot=jsonb_set(mechanics_snapshot,'{chakra}',to_jsonb(balance-5),false) where id=a.id;
 if v_values then
  perform set_config('app.allow_chakra_delta','1',true);
  update public.characters set chakra=chakra-5 where id=a.character_id;
  perform set_config('app.allow_chakra_delta','0',true);
 end if;
 -- Il link simulato resta marcato simulato e vincolato alla sua scena.
 update clan_marionettisti_private.links set state='connected',link_version=link_version+1 where owner_actor_id=a.id;
 return result;
end;
$function$;

