-- Native source public.combat_close(uuid,text) MD5 6b15cfc7cb5c33c0bb2204a853b1b0cf

CREATE OR REPLACE FUNCTION public.combat_close(p_session uuid, p_motivo text DEFAULT 'chiuso'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_s public.combat_sessions%rowtype; v_spente int; v_test boolean;
        v_io_combatto boolean; v_soli int;
begin
  select * into v_s from public.combat_sessions where id = p_session;
  if v_s.id is null or v_s.state = 'chiuso' then return; end if;

  if auth.uid() is not null
     and auth.uid() <> v_s.opened_by
     and coalesce(v_s.master_user, '00000000-0000-0000-0000-000000000000'::uuid) <> auth.uid()
     and not public.is_staff()
  then
    -- [APERTURA] La scorciatoia per motivo non è più una parola magica: vale
    -- solo se il fatto che dichiara è vero.
    select count(*) into v_soli from public.combat_participants p
      where p.session_id = p_session and p.ruolo = 'combattente' and not p.fuori;
    if p_motivo = 'un solo combattente ancora in piedi' and v_soli <= 1 then
      null;  -- il motore sta chiudendo un KO: passa
    else
      -- [APERTURA] la via d'uscita di chi è piantato: dieci minuti di silenzio
      select true into v_io_combatto from public.combat_participants p
        where p.session_id = p_session and p.user_id = auth.uid()
          and p.ruolo = 'combattente' and not p.fuori;
      if not coalesce(v_io_combatto,false) then
        raise exception 'può chiudere lo scontro chi l''ha aperto, il master o lo staff';
      end if;
      if v_s.turn_of = auth.uid() then
        raise exception 'Tocca a te: non puoi abbandonare uno scontro che stai facendo aspettare.';
      end if;
      if v_s.last_action_at > now() - interval '10 minutes' then
        raise exception 'Devi aspettare: si abbandona uno scontro dopo dieci minuti di silenzio dell''avversario.';
      end if;
      p_motivo := 'abbandonato: dieci minuti senza risposta';
    end if;
  end if;

  select count(*) into v_spente from public.character_active where session_id = p_session;
  select coalesce(l.is_test,false) into v_test from public.locations l where l.id = v_s.location_id;
  delete from public.character_active where session_id = p_session;
  delete from public.combat_pending where session_id = p_session;
  if coalesce(v_test,false) then perform public._test_room_azzera(p_session); end if;
  update public.combat_sessions set state='chiuso', closed_at = now(), closed_reason = p_motivo, turn_of = null where id = p_session;
  perform public._combat_dice(p_session, (select character_id from public.combat_participants where session_id=p_session order by joined_at limit 1),
    'Scontro', 'Lo scontro si chiude (' || p_motivo || ').' || (case when v_spente > 0 then ' Le arti innate accese si spengono.' else '' end));
end; $function$;

