-- Native source public.combat_dichiara_attacco(uuid,uuid,text,uuid,text,text,integer,boolean) MD5 d71b96d8718376dfbf21ae14d8867307

CREATE OR REPLACE FUNCTION public.combat_dichiara_attacco(p_session uuid, p_target_user uuid, p_kind text DEFAULT 'fisico'::text, p_technique uuid DEFAULT NULL::uuid, p_fonte text DEFAULT NULL::text, p_name text DEFAULT ''::text, p_base integer DEFAULT 0, p_rapida boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_s public.combat_sessions%rowtype; v_pa public.combat_participants%rowtype; v_pd public.combat_participants%rowtype;
  v_a public.characters%rowtype; v_dist int; v_g text; v_el text; v_base int; v_ck int := 0;
  v_nome text; v_uso text; v_ord int; v_max int; v_disc text; v_marker text;
  v_test boolean; v_libero boolean;
  v_innata_clan boolean := false;
  v_diversivo boolean := false;   -- [017-R1]
  v_di_scena boolean := false;    -- [042-B0]
begin
  if coalesce(p_rapida,false) then
    raise exception 'Le azioni rapide offensive sono ritirate: dichiara una sola azione principale.';
  end if;
  select * into v_s from public.combat_sessions where id = p_session;
  if v_s.id is null or v_s.state <> 'aperto' then raise exception 'scontro non aperto'; end if;
  if v_s.turn_of <> auth.uid() or v_s.fase <> 'attacco' then raise exception 'non è il tuo turno d''attacco'; end if;
  select * into v_pa from public.combat_participants where session_id = p_session and user_id = auth.uid();
  if v_pa.id is null or v_pa.ruolo <> 'combattente' then raise exception 'non sei fra i combattenti'; end if;
  select * into v_pd from public.combat_participants where session_id = p_session and user_id = p_target_user;
  if v_pd.id is null or v_pd.ruolo <> 'combattente' then raise exception 'bersaglio non valido'; end if;
  if v_pd.fuori then raise exception '% è già fuori combattimento', v_pd.character_name; end if;
  perform public._combat_nuovo_round(v_pa.id, v_s.round);
  select * into v_pa from public.combat_participants where id = v_pa.id;
  if v_pa.usato_principale then raise exception 'hai già speso l''azione principale'; end if;
  select * into v_a from public.characters where id = v_pa.character_id;
  select coalesce(l.is_test,false) into v_test from public.locations l where l.id = v_s.location_id;
  v_libero := coalesce(v_test,false) and public._puo_test_room();
  v_nome  := 'colpo';
  v_base  := 10;
  v_g     := 'contatto';
  v_marker := 'fisico';
  if p_technique is not null then
    if coalesce(p_fonte,'clan') = 'jutsu' then
      -- [TASK-COMBAT-ELEMENTI-JUTSU-001, 10/08/2026] si carica anche j.nature:
      -- prima il ramo jutsu non leggeva alcun elemento e v_el restava NULL,
      -- quindi ogni jutsu accademico era neutrale per costruzione e non per
      -- scelta. Oggi le otto basi attive hanno tutte nature = NULL e il
      -- risultato non cambia; domani una base elementale sara' riconosciuta.
      -- [TECH-DEFENSE-FLAGS-004] il ramo jutsu non ha ne' is_innata ne' macro:
      -- v_innata_clan resta false, e la guardia non lo tocca.
      select j.name_it, j.chakra_cost, j.damage_base, j.gittata, j.uso, j.nature, j.category,
             coalesce(j.diversivo,false), coalesce(j.di_scena,false)
        into v_nome, v_ck, v_base, v_g, v_uso, v_el, v_disc, v_diversivo, v_di_scena
        from public.jutsu j
        left join public.character_jutsu cj on cj.jutsu_id = j.id and cj.user_id = auth.uid()
       where j.id = p_technique and j.is_active and (cj.user_id is not null or v_libero);
    else
      select t.name, t.chakra_cost, t.danno_base, t.gittata, t.uso, (t.req_elements)[1], t.disciplina,
             (coalesce(t.is_innata,false) and t.macro = 'clan'), coalesce(t.di_scena,false)
        into v_nome, v_ck, v_base, v_g, v_uso, v_el, v_disc, v_innata_clan, v_di_scena
        from public.clan_techniques t
        left join public.character_abilities ca
               on ca.technique_id = t.id and ca.character_id = v_a.id and ca.state = 'attiva'
       where t.id = p_technique and t.is_active and (ca.character_id is not null or v_libero);
    end if;
    if v_nome is null then raise exception 'tecnica non disponibile o non ancora attiva'; end if;
    if v_uso = 'passiva' or v_uso = 'fuori_scontro' then raise exception '«%» non è una mossa da usare in scontro', v_nome; end if;
    if v_uso = 'difesa' then raise exception '«%» è una tecnica di difesa: si gioca quando ti difendi', v_nome; end if;
    if v_uso = 'rapida' then raise exception '«%» appartiene a una categoria ritirata: non è un attacco principale', v_nome; end if;
    -- [TECH-DEFENSE-FLAGS-004] Le arti innate di clan si accendono, non si
    -- dichiarano. Con danno_base = 0 il motore calcolerebbe comunque un colpo
    -- vero da ⌊off/4⌋, e otto di quelle righe arrivano a 60 metri: il pulsante
    -- sbagliato e' piu' forte di quello giusto. Vale anche in Test Room:
    -- l'accensione ha gia' la sua deroga dentro innata_accendi.
    -- ⚠️ Il perimetro NON e' `is_innata`: 29 evocazioni su 30 sono
    -- consumption_type='ad_utilizzo' e innata_accendi le rifiuta. Bloccarle
    -- le lascerebbe senza nessuna porta, famiglia Richiamo compresa.
    -- ⚠️ E la guardia sta DOPO i controlli su `uso`, non prima: le 28 righe
    -- sono uso='principale' e quei controlli non le toccano, mentre le 8
    -- innate di clan `uso='passiva'` (Arte dell'Espansione, Simbiosi coi
    -- Ninken) devono sentirsi dire «non e' una mossa da usare in scontro» e
    -- non «si accende», perche' consumption_type='passiva' e innata_accendi
    -- le rifiuta espressamente. Il banco in replica locale ha trovato questo
    -- messaggio bugiardo con la guardia messa prima.
    -- [017-R1] decisione PM 8: la tecnica non deve MAI infliggere danno, nemmeno
    -- inviata a mano come attacco. Questa è la porta da cui il pulsante di oggi
    -- la manda, e da qui in poi riceve un rifiuto parlante invece di 1,5-7 PV.
    -- ⚠️ Sta DOPO i controlli su `uso` per la stessa ragione della guardia
    -- gemella: prima, darebbe il messaggio sbagliato alle righe che `uso` deve
    -- fermare per prime.
    -- [042-B0] decisione PM 042-A3: tecnica ESCLUSIVAMENTE di scena.
    -- Nessun danno, nessun pending, nessun referto offensivo. Questa è la
    -- porta da cui il client può forzarla anche senza vederla in elenco.
    if v_di_scena then
      raise exception '«%» è una tecnica di scena: si usa fuori dallo scontro e non può essere dichiarata come attacco.', v_nome;
    end if;
    if v_diversivo then
      raise exception '«%» non è un attacco: crea copie illusorie per coprire uno spostamento. Si gioca scegliendo una direzione.', v_nome;
    end if;
    if v_innata_clan then
      raise exception '«%» è un''arte innata del tuo clan: si accende, non si dichiara come attacco.', v_nome;
    end if;
    v_base := coalesce(v_base,0); v_ck := coalesce(v_ck,0); v_g := coalesce(v_g,'media');
    v_marker := public._combat_marker(v_disc);
  end if;
  v_el := nullif(btrim(coalesce(v_el,'')),'');
  if v_marker = 'fisico' then v_el := null; end if;
  v_dist := abs(v_pa.pos_m - v_pd.pos_m);
  v_max := public._fascia_metri(v_g);
  if v_dist > v_max then raise exception '% è a % metri: «%» arriva a %.', v_pd.character_name, v_dist, v_nome, v_max; end if;
  if not v_test and v_ck > 0 and coalesce(v_a.chakra_max,0) > 0 and coalesce(v_a.chakra,0) < v_ck then
    raise exception 'Chakra insufficiente: servono % (ne hai %)', v_ck, coalesce(v_a.chakra,0); end if;
  v_ord := 1;
  insert into public.combat_pending(session_id, round, ordine, attacker_user, defender_user, kind,
      technique_id, fonte, tech_name, base, chakra_cost, elemento, gittata, distanza, attack_message_id, formazione_id)
    values (p_session, v_s.round, v_ord, auth.uid(), p_target_user, v_marker,
      p_technique, p_fonte, v_nome, v_base, v_ck, v_el, v_g, v_dist,
      nullif(current_setting('app.combat_action_message_id',true),'')::uuid,
      (select f.id from public.combat_formazione f
        where f.session_id=p_session and f.owner_user=p_target_user
          and f.modalita='copertura' and f.stato='viva'
        order by f.created_at desc limit 1));
  update public.combat_participants set usato_principale = true where id = v_pa.id;
  update public.combat_sessions set fase = 'difesa', turn_of = p_target_user, last_action_at = now() where id = p_session;
  perform public._combat_dice(p_session, v_a.id, v_a.name,
    v_a.name || ' dichiara «' || v_nome || '» contro ' || v_pd.character_name || ' a ' || v_dist || ' metri. Tocca a ' || v_pd.character_name || ' difendersi.', true);
  return v_a.name || ' dichiara «' || v_nome || '»: ' || v_pd.character_name || ' deve rispondere.';
end; $function$;

ALTER FUNCTION public.combat_dichiara_attacco(uuid,uuid,text,uuid,text,text,integer,boolean) OWNER TO "postgres";

SET LOCAL ROLE "postgres";

REVOKE ALL ON FUNCTION public.combat_dichiara_attacco(uuid,uuid,text,uuid,text,text,integer,boolean) FROM PUBLIC,"anon","authenticated","postgres","service_role";

GRANT EXECUTE ON FUNCTION public.combat_dichiara_attacco(uuid,uuid,text,uuid,text,text,integer,boolean) TO "postgres";

GRANT EXECUTE ON FUNCTION public.combat_dichiara_attacco(uuid,uuid,text,uuid,text,text,integer,boolean) TO "service_role";

RESET ROLE;

-- Native source public.combat_dichiara_difesa(uuid,text,uuid,integer) MD5 90b82d078d7881152254784937f77609

CREATE OR REPLACE FUNCTION public.combat_dichiara_difesa(p_session uuid, p_reazione text DEFAULT 'schivata'::text, p_technique uuid DEFAULT NULL::uuid, p_posizione integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_s public.combat_sessions%rowtype; v_pd public.combat_participants%rowtype;
  r record; n int := 0; esiti text := ''; v_nome text; v_uso text;
  v_dif boolean := false;
  v_di_scena boolean := false;    -- [042-B0]
  v_ck int := 0; v_reaz_jutsu boolean := false; v_c public.characters%rowtype;
  v_test boolean; v_scrive boolean; v_libero boolean;
  v_pos int := 0; v_maxpos int := 0; v_ninja int := 0;
  v_alt int; v_passi int; v_new int; v_prima int; v_nome_alt text; v_fascia text;
begin
  select * into v_s from public.combat_sessions where id = p_session for update;
  if v_s.id is null or v_s.state <> 'aperto' then raise exception 'scontro non aperto'; end if;
  if v_s.fase <> 'difesa' or v_s.turn_of <> auth.uid() then raise exception 'non è il tuo turno di difesa'; end if;
  select * into v_pd from public.combat_participants where session_id = p_session and user_id = auth.uid() for update;
  if v_pd.id is null then raise exception 'non sei in questo scontro'; end if;
  select coalesce(l.is_test,false) into v_test from public.locations l where l.id = v_s.location_id;
  v_scrive := public._combat_scrive_valori(p_session);
  v_libero := coalesce(v_test,false) and public._puo_test_room();
  if p_reazione in ('contrasto','contromossa') then
    raise exception 'La Contromossa non è in vigore in questa versione: schiva, para o gioca una tecnica difensiva.';
  end if;
  if p_reazione = 'guardia' then
    raise exception 'La Guardia è stata ritirata: scegli Schivata, Parata, Sostituzione, una tecnica difensiva o le copie già attive.';
  end if;
  if p_reazione = 'copie' and p_technique is not null then
    raise exception 'Le copie non accettano una tecnica: sono uno stato già creato dal Diversivo.';
  end if;
  if p_technique is not null then
    -- [TECH-DEFENSE-FLAGS-004] la ricerca chiede id, is_active e POSSESSO.
    -- `difensiva` e `uso` non stanno piu' qui: sono controlli, non filtri di
    -- ricerca, e servono a dare il motivo giusto invece di un errore generico.
    select t.name, t.uso, coalesce(t.difensiva,false), t.chakra_cost, coalesce(t.di_scena,false)
      into v_nome, v_uso, v_dif, v_ck, v_di_scena
      from public.clan_techniques t
      left join public.character_abilities ca
             on ca.technique_id = t.id and ca.character_id = v_pd.character_id and ca.state = 'attiva'
     where t.id = p_technique and t.is_active and (ca.character_id is not null or v_libero);
    if v_nome is null then
      select j.name_it, j.uso, coalesce(j.difensiva,false), j.chakra_cost, (j.action_type = 'reazione'), coalesce(j.di_scena,false)
        into v_nome, v_uso, v_dif, v_ck, v_reaz_jutsu, v_di_scena
        from public.jutsu j
        left join public.character_jutsu cj on cj.jutsu_id = j.id and cj.user_id = auth.uid()
       where j.id = p_technique and j.is_active and (cj.user_id is not null or v_libero);
    end if;
    -- 1 · inesistente, inattiva o non posseduta: un solo messaggio, che non
    --     distingue i tre casi e quindi non rivela niente
    if v_nome is null then raise exception 'quella tecnica non si può giocare in difesa'; end if;
    -- 2·3·4 · caselle del turno che non sono la reazione. La deroga della
    --     Test Room copre il possesso, MAI `uso`: una passiva non diventa una
    --     reazione neanche in prova.
    if v_uso = 'passiva' then
      raise exception '«%» è una tecnica passiva: agisce da sé, non si dichiara come reazione.', v_nome; end if;
    if v_uso = 'fuori_scontro' then
      raise exception '«%» non si usa durante uno scontro.', v_nome; end if;
    -- [042-B0] dopo i controlli su `uso`, come le guardie gemelle.
    if v_di_scena then
      raise exception '«%» è una tecnica di scena: non è una difesa e non si gioca in uno scontro.', v_nome;
    end if;
    if v_uso = 'rapida' then
      raise exception '«%» è un''azione rapida: si gioca nel tuo turno, non in difesa.', v_nome; end if;
    -- 5 · riga non classificata: rete per il futuro, oggi nessuna riga attiva
    if v_uso is null then raise exception 'quella tecnica non si può giocare in difesa'; end if;
    -- 6 · non appartiene al menu' della difesa
    if not v_dif then
      raise exception '«%» non è una tecnica di difesa: si gioca nel tuo turno d''attacco.', v_nome; end if;
    -- 7·8 · ammesse: `difesa`, e `principale` col doppio uso dichiarato (D1b).
    --     Il `not in` e' la terza rete: un valore nuovo di `uso` nasce chiuso.
    if v_uso not in ('difesa','principale') then
      raise exception '«%» non è una tecnica di difesa: si gioca nel tuo turno d''attacco.', v_nome; end if;
    if lower(v_nome)='dispersione' and (
         not exists (select 1 from public.combat_pending p
                      where p.session_id=p_session and p.round=v_s.round and p.defender_user=auth.uid())
         or exists (select 1 from public.combat_pending p
                     where p.session_id=p_session and p.round=v_s.round and p.defender_user=auth.uid()
                       and lower(coalesce(p.kind,'')) <> 'genjutsu')) then
      raise exception 'Dispersione si usa soltanto come difesa da un Genjutsu.';
    end if;
    if v_reaz_jutsu then p_reazione := 'sostituzione'; else p_reazione := 'tecnica'; end if;
  end if;
  if p_reazione not in ('schivata','parata','sostituzione','tecnica','copie') then
    raise exception 'reazione non valida';
  end if;
  if p_reazione = 'copie' then
    if not coalesce(v_pd.copie_attive,false) then
      raise exception 'Non hai copie attive: prima devi creare il Diversivo.';
    end if;
    if (select count(*) from public.combat_pending
         where session_id = p_session and round = v_s.round and defender_user = auth.uid()) <> 1 then
      raise exception 'Le copie possono confondere un solo attacco diretto alla volta.';
    end if;
  end if;
  -- [V1.1 · decisione 4] una volta ogni TRE turni difensivi: usata al round R,
  -- rifiutata a R+1 e R+2, riammessa a R+3. Lo stesso confine e' scritto in
  -- combat_opzioni (R5): i due si muovono insieme, o il pannello offre quello
  -- che il server rifiuta.
  if p_reazione = 'sostituzione' and v_pd.sostituzione_round is not null and v_pd.sostituzione_round >= v_s.round - 2 then
    raise exception 'La Sostituzione si usa una volta ogni tre turni difensivi.'; end if;

  -- [V1.1 · decisione 7] la scelta di posizione. Convenzione IDENTICA a
  -- combat_muovi: positivo avvicina, negativo allontana. Il tetto lo da' il
  -- Ninjutsu, come gia' scrive §4.5 di REGOLE.md. Il client manda solo il
  -- numero scelto: il calcolo e' tutto qui.
  if p_reazione = 'sostituzione' then
    select * into v_c from public.characters where id = v_pd.character_id;
    v_ninja  := coalesce(v_c.ninjutsu,0);
    v_maxpos := case when v_ninja < 25 then 0 when v_ninja < 50 then 5
                     when v_ninja < 75 then 10 else 15 end;
    v_pos := coalesce(p_posizione, 0);
    if v_pos not in (-15,-10,-5,0,5,10,15) then
      raise exception 'La Sostituzione sposta di 0, 5, 10 o 15 metri: % non è una scelta ammessa.', v_pos;
    end if;
    if abs(v_pos) > v_maxpos then
      if v_maxpos = 0 then
        raise exception 'Con Ninjutsu sotto 25 la Sostituzione ti riporta dove eri: nessuno spostamento.';
      else
        raise exception 'Il tuo Ninjutsu ti porta al massimo a % metri: % non è ammesso.', v_maxpos, abs(v_pos);
      end if;
    end if;
  else
    -- ignorato per le altre reazioni, senza errore
    v_pos := 0;
  end if;

  v_ck := coalesce(v_ck, 0);
  if v_ck > 0 and v_scrive then
    select * into v_c from public.characters where id = v_pd.character_id;
    if coalesce(v_c.chakra_max,0) > 0 then
      if coalesce(v_c.chakra,0) < v_ck then
        raise exception 'Chakra insufficiente per «%»: servono % (ne hai %)', v_nome, v_ck, coalesce(v_c.chakra,0); end if;
      perform set_config('app.allow_chakra_delta','1', true);
      update public.characters set chakra = greatest(0, chakra - v_ck) where id = v_c.id;
    end if;
  end if;
  perform public._combat_nuovo_round(v_pd.id, v_s.round);
  select * into v_pd from public.combat_participants where id = v_pd.id;
  for r in select * from public.combat_pending
            where session_id = p_session and round = v_s.round and defender_user = auth.uid() order by ordine asc loop
    -- [V1.1] La Sostituzione non cancella piu' il pending: passa da
    -- _combat_risolvi come ogni altra reazione e produce il suo referto.
    -- ⚠️ p_dif_tech resta NULL per la Sostituzione: passarle il proprio uuid
    -- la degraderebbe a 'tecnica' e il referto non direbbe piu' 'sostituzione'.
    -- [V1.1 · decisione 6] «colto in azione» e' sospeso: si passa sempre false.
    esiti := esiti || public._combat_risolvi(r.id, p_reazione, false,
                        case when p_reazione = 'tecnica' then p_technique else null end) || E'\n';
    n := n + 1;
  end loop;
  if n = 0 then raise exception 'non c''è nessun colpo da parare'; end if;
  if p_reazione = 'sostituzione' then
    update public.combat_participants set sostituzione_round = v_s.round where id = v_pd.id;
  end if;
  update public.combat_participants set usato_reazione = true where id = v_pd.id;
  if v_pd.mossa_pendente is not null then
    update public.combat_participants set pos_m = greatest(0, least(60, pos_m + v_pd.mossa_pendente)), mossa_pendente = null where id = v_pd.id;
  end if;

  -- La posizione si applica DOPO la negazione, e non consuma lo spostamento
  -- del round: e' la deroga difensiva della Sostituzione, non una mossa.
  if p_reazione = 'sostituzione' and v_pos <> 0 then
    select * into v_pd from public.combat_participants where id = v_pd.id;
    select p.pos_m, p.character_name into v_alt, v_nome_alt
      from public.combat_participants p
     where p.session_id = p_session and p.user_id <> auth.uid()
       and p.ruolo = 'combattente' and not p.fuori
     order by abs(p.pos_m - v_pd.pos_m) asc limit 1;
    if v_alt is not null then
      v_prima := abs(v_pd.pos_m - v_alt);
      v_passi := abs(v_pos);
      if v_pos >= 0 then
        if v_pd.pos_m <= v_alt then v_new := least(v_alt, v_pd.pos_m + v_passi);
        else v_new := greatest(v_alt, v_pd.pos_m - v_passi); end if;
      else
        if v_pd.pos_m <= v_alt then v_new := v_pd.pos_m - v_passi;
        else v_new := v_pd.pos_m + v_passi; end if;
      end if;
      v_new := greatest(0, least(60, v_new));
      update public.combat_participants set pos_m = v_new where id = v_pd.id;
      v_fascia := case when abs(v_new - v_alt) <= 2 then 'a contatto'
                       when abs(v_new - v_alt) <= 10 then 'a corta distanza'
                       when abs(v_new - v_alt) <= 30 then 'a media distanza'
                       else 'a lunga distanza' end;
      perform public._combat_dice(p_session, v_pd.character_id, v_pd.character_name,
        v_pd.character_name || ' riappare ' || v_fascia || ' da ' || v_nome_alt ||
        ': da ' || v_prima || ' a ' || abs(v_new - v_alt) || ' metri.', true);
    end if;
  end if;

  -- [ciclo prova] la fixture e' un solo scambio: consegnato l'esito la stanza
  -- torna pulita, e per un'altra prova serve una nuova selezione
  if coalesce(v_test,false) and v_s.scenario is not null then
    perform public._test_room_azzera(p_session);
    perform public._combat_dice(p_session, v_pd.character_id, 'Prova',
      'Prova «' || v_s.scenario || '» conclusa: la stanza torna pulita. Per un''altra prova scegli un nuovo scenario.', true);
  end if;
  perform public._combat_avanza(p_session);
  return coalesce(nullif(esiti,''),'risolto');
end; $function$;

