-- Native source public.combat_formazione_pubblica(uuid) MD5 f27c643f42bc812144ae8ca61d6392fd

CREATE OR REPLACE FUNCTION public.combat_formazione_pubblica(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_out jsonb;
begin
  if v_uid is null or not exists (
    select 1 from public.combat_participants where session_id=p_session and user_id=v_uid
  ) then raise exception 'non partecipi allo scontro'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'formazione_id',f.id,'modalita',f.modalita,'copie_vive',(select count(*) from public.combat_formazione_figura x where x.formazione_id=f.id and x.viva),
      'copie_svanite',(select count(*) from public.combat_formazione_figura x where x.formazione_id=f.id and not x.viva),
      'round_creazione',f.round_creazione,'round_scadenza',f.round_scadenza,'stato',f.stato,'sigillo_sha',f.sigillo_sha,
      'figure',(select jsonb_agg(jsonb_build_object('idx',x.idx,'etichetta',x.etichetta,'posizione_m',x.pos_m,'viva',x.viva,'svanita_causa',x.svanita_causa) order by x.idx)
                 from public.combat_formazione_figura x where x.formazione_id=f.id)
    ) order by f.created_at),'[]'::jsonb) into v_out
  from public.combat_formazione f where f.session_id=p_session and f.stato='viva';
  return v_out;
end
$function$;

