-- Native source public.combat_muovi(uuid,integer) MD5 eed73d8c2916e2c56d01484192505020

CREATE OR REPLACE FUNCTION public.combat_muovi(p_session uuid, p_metri integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_p public.combat_participants%rowtype; v_c public.characters%rowtype; v_s public.combat_sessions%rowtype;
  v_max int; v_new int; v_alt int; v_passi int; v_dist int; v_prima int; v_nome text; v_txt text; v_fascia text;
begin
  select * into v_s from public.combat_sessions where id = p_session;
  if v_s.id is null or v_s.state <> 'aperto' then raise exception 'scontro non aperto'; end if;
  select * into v_p from public.combat_participants where session_id = p_session and user_id = auth.uid();
  if v_p.id is null then raise exception 'non sei in questo scontro'; end if;
  if v_p.ruolo <> 'combattente' then raise exception 'i partecipanti non combattenti non hanno posizione'; end if;
  if v_s.turn_of <> auth.uid() then raise exception 'non è il tuo turno'; end if;
  -- [UI-PASSO1] la difesa e' sola reazione
  if v_s.fase = 'difesa' then
    raise exception 'In difesa si risponde e basta: lo spostamento si dichiara nel tuo turno d''attacco.';
  end if;
  perform public._combat_nuovo_round(v_p.id, v_s.round);
  select * into v_p from public.combat_participants where id = v_p.id;
  if v_p.usato_spostamento then raise exception 'hai già usato lo spostamento in questo round'; end if;
  select * into v_c from public.characters where id = v_p.character_id;
  v_max := (coalesce(v_c.velocita,0)/10)*5;
  v_passi := abs(p_metri);
  if v_passi = 0 then raise exception 'di quanti metri?'; end if;
  if v_passi > v_max then raise exception 'La tua Velocità ti porta al massimo a % metri per turno', v_max; end if;
  select p.pos_m, p.character_name into v_alt, v_nome
    from public.combat_participants p
   where p.session_id = p_session and p.user_id <> auth.uid() and p.ruolo='combattente' and not p.fuori
   order by abs(p.pos_m - v_p.pos_m) asc limit 1;
  if v_alt is null then raise exception 'non c''è nessun avversario da cui avvicinarsi o allontanarsi'; end if;
  v_prima := abs(v_p.pos_m - v_alt);
  if p_metri >= 0 then
    if v_p.pos_m <= v_alt then v_new := least(v_alt, v_p.pos_m + v_passi);
    else v_new := greatest(v_alt, v_p.pos_m - v_passi); end if;
  else
    if v_p.pos_m <= v_alt then v_new := v_p.pos_m - v_passi;
    else v_new := v_p.pos_m + v_passi; end if;
  end if;
  v_new := greatest(0, least(60, v_new));
  -- [017 ADDENDUM] uno spostamento che non muove nessuno si RIFIUTA, e prima di
  -- consumare: `usato_spostamento` non viene toccato e nessuna battuta esce.
  -- ⚠️ Il ramo di narrazione «si muove, ma % resta %» qui sotto diventa
  -- irraggiungibile e resta apposta: è la rete che si accenderebbe se un giorno
  -- il campo o il verso cambiassero, e toglierla adesso vorrebbe dire toglierla
  -- proprio quando ricomincia a servire.
  if v_new = v_p.pos_m then
    raise exception 'Da lì quello spostamento non cambierebbe la posizione: sei già %.',
      case when v_p.pos_m <= v_alt and v_p.pos_m = 0 then 'contro il bordo del campo'
           when v_p.pos_m >= v_alt and v_p.pos_m = 60 then 'contro il bordo del campo'
           when abs(v_p.pos_m - v_alt) = 0 then 'addosso a ' || v_nome
           else 'nel punto in cui finiresti' end;
  end if;
  v_dist := abs(v_new - v_alt);
  v_fascia := case when v_dist <= 2 then 'a contatto' when v_dist <= 10 then 'a corta distanza'
                   when v_dist <= 30 then 'a media distanza' when v_dist <= 60 then 'a lunga distanza'
                   else 'fuori portata' end;
  update public.combat_participants set pos_m = v_new, usato_spostamento = true where id = v_p.id;
  if v_dist = v_prima then
    v_txt := v_c.name || ' si muove, ma ' || v_nome || ' resta ' || v_fascia || ' (' || v_dist || ' m).';
  else
    v_txt := v_c.name || (case when v_dist < v_prima then ' chiude la distanza su ' else ' prende le distanze da ' end)
             || v_nome || ': da ' || v_prima || ' a ' || v_dist || ' metri, ' || v_fascia || '.';
  end if;
  perform public._combat_dice(p_session, v_c.id, v_c.name, v_txt, true);
  return v_txt;
end; $function$;

ALTER FUNCTION public.combat_muovi(uuid,integer) OWNER TO "postgres";

SET LOCAL ROLE "postgres";

REVOKE ALL ON FUNCTION public.combat_muovi(uuid,integer) FROM PUBLIC,"anon","authenticated","postgres","service_role";

GRANT EXECUTE ON FUNCTION public.combat_muovi(uuid,integer) TO "postgres";

GRANT EXECUTE ON FUNCTION public.combat_muovi(uuid,integer) TO "service_role";

RESET ROLE;

-- Native source public.combat_opzioni(uuid) MD5 d8bf9d175216ef52e48391a55d942f8f

CREATE OR REPLACE FUNCTION public.combat_opzioni(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_s public.combat_sessions%rowtype; v_p public.combat_participants%rowtype;
  v_c public.characters%rowtype; v_test boolean; v_libero boolean; v_staff boolean;
  v_alt int; v_dist int; v_maxm int; v_ck int; v_out jsonb;
  -- [017-R2] il diversivo e le sue direzioni
  v_div jsonb := '[]'::jsonb; v_div_id uuid; v_div_nome text; v_div_ck int := 0;
  v_div_ok boolean; v_copie_max int := 0; v_copie_off jsonb := '[]'::jsonb;
  v_princ jsonb; v_inn jsonb; v_rap jsonb; v_reaz jsonb; v_sost uuid; v_sost_ok boolean;
  v_speso boolean; v_sost_ck int := 0; v_maxpos int := 0; v_posizioni jsonb;
begin
  select * into v_s from public.combat_sessions where id = p_session;
  if v_s.id is null or v_s.state <> 'aperto' then raise exception 'scontro non aperto'; end if;
  select * into v_p from public.combat_participants where session_id = p_session and user_id = auth.uid();
  if v_p.id is null or v_p.ruolo <> 'combattente' then raise exception 'non sei fra i combattenti di questo scontro'; end if;
  if v_p.fuori then raise exception 'sei fuori combattimento'; end if;
  select * into v_c from public.characters where id = v_p.character_id;
  select coalesce(l.is_test,false) into v_test from public.locations l where l.id = v_s.location_id;
  v_staff  := public.is_staff();
  v_libero := coalesce(v_test,false) and public._puo_test_room();
  v_speso  := v_p.usato_principale and v_p.round_speso = v_s.round;

  select p.pos_m into v_alt from public.combat_participants p
   where p.session_id = p_session and p.user_id <> auth.uid() and p.ruolo='combattente' and not p.fuori
   order by abs(p.pos_m - v_p.pos_m) asc limit 1;
  v_dist := abs(coalesce(v_alt, v_p.pos_m) - v_p.pos_m);
  v_maxm := (coalesce(v_c.velocita,0)/10)*5;
  v_ck   := coalesce(v_c.chakra,0);

  -- ── [017-R2] il diversivo: DUE direzioni, e solo se muovono davvero ──────
  -- Le condizioni sono le stesse che `combat_diversivo` ricontrolla: chi esegue
  -- non si fida di chi offre. E `_diversivo_cambia` è la stessa funzione che
  -- l'Esame interroga — una sede sola per «questa direzione fa qualcosa?».
  select j.id, j.name_it, coalesce(j.chakra_cost,0)
    into v_div_id, v_div_nome, v_div_ck
    from public.jutsu j
    join public.character_jutsu cj on cj.jutsu_id = j.id and cj.user_id = auth.uid()
   where j.is_active and coalesce(j.diversivo,false)
   order by j.name_it limit 1;

  -- [040-R1] stesso `_copie_cap` che usa `combat_diversivo`: una sede sola.
  v_copie_max := public._copie_cap(coalesce(v_c.ninjutsu,0), v_c.rank);

  v_div_ok := v_div_id is not null
              and v_s.fase = 'attacco'
              and not v_speso
              and (v_test or v_div_ck = 0 or v_ck >= v_div_ck)
              and (v_p.diversivo_round is null or v_p.diversivo_round < v_s.round)
              and v_copie_max >= 1;

  if v_div_ok then
    -- zero offerte morte anche sul numero: si offrono solo i gradini che il
    -- chakra regge davvero, con lo stesso costo unitario del catalogo.
    select coalesce(jsonb_agg(k order by k), '[]'::jsonb) into v_copie_off
      from generate_series(1, v_copie_max) as k
     where v_test or v_div_ck = 0 or (v_div_ck + 5 * k) <= v_ck;
    select coalesce(jsonb_agg(x order by x->>'chiave'), '[]'::jsonb) into v_div from (
      select jsonb_build_object(
        'chiave',    d.dir,
        'nome',      case d.dir when 'avvicinamento' then 'Coprire un avvicinamento'
                                else 'Coprire una ritirata' end,
        'tecnica',   v_div_nome,
        'id',        v_div_id,
        'chakra',    v_div_ck,
        'costo_base', v_div_ck,
        'costo_per_copia', 5,
        'modalita_offerte', jsonb_build_array('copertura','assalto'),
        'copie_max', v_copie_max,
        'copie_offerte', v_copie_off,
        'distanza_dopo', q.m,
        -- [047] fascia_dopo NON è un secondo calcolo: è la stessa `q.m` passata
        -- per l'unica sede delle soglie. Il client non deve più proiettare.
        'fascia_dopo', public._fascia_da_metri(q.m),
        'disponibile', true) as x
        from (values ('avvicinamento'),('ritirata')) as d(dir)
        cross join lateral (
          select abs(public._diversivo_posizione(v_p.pos_m, v_alt, d.dir, v_maxm, 2, 5) - v_alt)
        ) as q(m)
       -- zero offerte morte: una direzione che non cambia la posizione non si
       -- presenta. Vale anche contro il bordo del campo.
       where public._diversivo_cambia(v_p.pos_m, v_alt, d.dir, v_maxm, 2)
    ) s;
  end if;

  -- principali: tecniche di clan + jutsu. Stessa forma, campo `fonte` a distinguerle.
  -- [TECH-DEFENSE-FLAGS-004] `not (is_innata and macro='clan')` e' lo STESSO
  -- predicato della guardia in combat_dichiara_attacco: i due si muovono
  -- insieme, o il pannello offre quello che il server rifiuta. Le 28 righe
  -- restano nel blocco `innate` qui sotto.
  select jsonb_agg(x order by x->>'nome') into v_princ from (
    select jsonb_build_object(
      'id', t.id, 'fonte', 'clan', 'nome', t.name, 'clan', t.clan, 'livello', t.level,
      'grado', t.grado, 'disciplina', t.disciplina, 'gittata', t.gittata,
      'portata_m', public._fascia_metri(t.gittata), 'chakra', coalesce(t.chakra_cost,0),
      'posseduta', (ca.character_id is not null),
      'disponibile', (v_dist <= public._fascia_metri(t.gittata))
                     and (v_test or coalesce(t.chakra_cost,0) = 0 or v_ck >= coalesce(t.chakra_cost,0))
                     and not v_speso,
      'motivo_no', case
        when v_speso then 'hai già speso l''azione principale'
        when v_dist > public._fascia_metri(t.gittata)
          then 'a ' || v_dist || ' metri non arriva: copre ' || public._fascia_metri(t.gittata)
        when not v_test and coalesce(t.chakra_cost,0) > v_ck
          then 'servono ' || t.chakra_cost || ' chakra, ne hai ' || v_ck
        end) as x
      from public.clan_techniques t
      left join public.character_abilities ca
             on ca.technique_id = t.id and ca.character_id = v_c.id and ca.state='attiva'
     where t.is_active and t.uso = 'principale'
       -- [042-B0] una tecnica di scena non è un attacco: esce dalle
       -- principali per discriminante server, mai per nome.
       and not coalesce(t.di_scena,false)
       and not (coalesce(t.is_innata,false) and t.macro = 'clan')
       and (ca.character_id is not null or v_libero)
    union all
    select jsonb_build_object(
      'id', j.id, 'fonte', 'jutsu', 'nome', j.name_it, 'clan', null, 'livello', null,
      'grado', j.rank, 'disciplina', j.category, 'gittata', coalesce(j.gittata,'media'),
      'portata_m', public._fascia_metri(coalesce(j.gittata,'media')), 'chakra', coalesce(j.chakra_cost,0),
      'posseduta', (cj.user_id is not null),
      'disponibile', (v_dist <= public._fascia_metri(coalesce(j.gittata,'media')))
                     and (v_test or coalesce(j.chakra_cost,0) = 0 or v_ck >= coalesce(j.chakra_cost,0))
                     and not v_speso,
      'motivo_no', case
        when v_speso then 'hai già speso l''azione principale'
        when v_dist > public._fascia_metri(coalesce(j.gittata,'media'))
          then 'a ' || v_dist || ' metri non arriva: copre ' || public._fascia_metri(coalesce(j.gittata,'media'))
        when not v_test and coalesce(j.chakra_cost,0) > v_ck
          then 'servono ' || j.chakra_cost || ' chakra, ne hai ' || v_ck
        end) as x
      from public.jutsu j
      left join public.character_jutsu cj on cj.jutsu_id = j.id and cj.user_id = auth.uid()
     where j.is_active and j.uso = 'principale' and not coalesce(j.difensiva,false)
       -- [017-R2] i diversivi hanno regole proprie e stanno sotto `diversivi`
       and not coalesce(j.diversivo,false)
       -- [042-B0] e nemmeno una tecnica di scena
       and not coalesce(j.di_scena,false)
       and (cj.user_id is not null or v_libero)
  ) s;

  -- arti innate: accenderle costa la principale, quindi stanno accanto alle altre.
  -- La deroga della stanza di prova e' la stessa di innata_accendi: test + staff.
  select jsonb_agg(x order by x->>'nome') into v_inn from (
    select jsonb_build_object(
      'id', t.id, 'fonte', 'innata', 'nome', t.name, 'clan', t.clan, 'livello', t.level,
      'chakra', coalesce(t.chakra_cost,0), 'per_round', true,
      'posseduta', (ca.character_id is not null),
      'accesa', exists (select 1 from public.character_active k
                         where k.character_id = v_c.id and k.technique_id = t.id),
      'disponibile', not v_speso
                     and not exists (select 1 from public.character_active k
                                      where k.character_id = v_c.id and k.technique_id = t.id)
                     and (coalesce(t.chakra_cost,0) = 0 or v_ck >= coalesce(t.chakra_cost,0)),
      'motivo_no', case
        when v_speso then 'hai già speso l''azione principale'
        when exists (select 1 from public.character_active k
                      where k.character_id = v_c.id and k.technique_id = t.id) then 'è già accesa'
        when coalesce(t.chakra_cost,0) > v_ck
          then 'servono ' || t.chakra_cost || ' chakra, ne hai ' || v_ck
        end) as x
      from public.clan_techniques t
      left join public.character_abilities ca
             on ca.technique_id = t.id and ca.character_id = v_c.id and ca.state='attiva'
     where t.is_active and t.is_innata and t.consumption_type = 'per_turno'
       and (ca.character_id is not null or (coalesce(v_test,false) and v_staff))
  ) s;

  -- [R3] Guardia è ritirata: nessun riquadro rapido fantasma.
  v_rap := '[]'::jsonb;

  -- [V1.1 · decisione 11] il costo si legge dalla riga vera, non si scrive 0.
  select j.id, coalesce(j.chakra_cost,0) into v_sost, v_sost_ck from public.jutsu j
    left join public.character_jutsu cj on cj.jutsu_id = j.id and cj.user_id = auth.uid()
   where j.is_active and j.difensiva and j.action_type = 'reazione'
     and (cj.user_id is not null or v_libero) limit 1;
  -- [V1.1 · decisione 4] stesso confine di combat_dichiara_difesa: una ogni tre.
  v_sost_ok := v_sost is not null
           and (v_p.sostituzione_round is null or v_p.sostituzione_round < v_s.round - 2)
           and (v_test or coalesce(v_sost_ck,0) = 0 or v_ck >= coalesce(v_sost_ck,0));
  -- [V1.1 · decisione 7] le posizioni offerte le filtra il Ninjutsu, e le
  -- decide il server: il browser sceglie fra queste, non ne inventa altre.
  v_maxpos := case when coalesce(v_c.ninjutsu,0) < 25 then 0
                   when coalesce(v_c.ninjutsu,0) < 50 then 5
                   when coalesce(v_c.ninjutsu,0) < 75 then 10 else 15 end;
  select coalesce(jsonb_agg(m order by m), '[]'::jsonb) into v_posizioni
    from unnest(array[0,5,10,15]) as m where m <= v_maxpos;

  v_reaz := jsonb_build_array(
    jsonb_build_object('chiave','schivata','nome','Schivata','chakra',0,'disponibile',true),
    jsonb_build_object('chiave','parata','nome','Parata','chakra',0,'disponibile',true),
    jsonb_build_object('chiave','copie','nome','Confondere con le copie','chakra',0,
      'disponibile', v_s.fase = 'difesa' and coalesce(v_p.copie_attive,false),
      'motivo_no', case when not coalesce(v_p.copie_attive,false)
                        then 'prima devi creare le copie con Moltiplicazione' end),
    jsonb_build_object('chiave','sostituzione','nome','Sostituzione','id',v_sost,
      'chakra', coalesce(v_sost_ck,0),
      'disponibile', v_sost_ok,
      'posizioni', v_posizioni,
      'max_metri', v_maxpos,
      'motivo_posizione', case when v_maxpos = 0
        then 'con Ninjutsu sotto 25 riappari dove eri: nessuno spostamento' end,
      'motivo_no', case when v_sost is null then 'non la conosci'
                        when v_p.sostituzione_round is not null and v_p.sostituzione_round >= v_s.round - 2
                          then 'si usa una volta ogni tre turni difensivi'
                        when not v_test and coalesce(v_sost_ck,0) > v_ck
                          then 'servono ' || v_sost_ck || ' chakra, ne hai ' || v_ck end));
  v_reaz := v_reaz || coalesce((
    select jsonb_agg(jsonb_build_object(
      'chiave','tecnica','id', d.technique_id, 'nome', d.name, 'fonte', d.fonte,
      'disciplina', d.disciplina, 'chakra', d.chakra_cost,
      'disponibile', (v_test or d.chakra_cost = 0 or v_ck >= d.chakra_cost),
      'motivo_no', case when not v_test and d.chakra_cost > v_ck
                        then 'servono ' || d.chakra_cost || ' chakra, ne hai ' || v_ck end)
      order by d.name)
    from public.my_defenses(v_s.location_id) d), '[]'::jsonb);

  if v_s.fase='difesa'
     and exists (select 1 from public.combat_pending p
                  where p.session_id=p_session and p.round=v_s.round and p.defender_user=auth.uid())
     and not exists (select 1 from public.combat_pending p
                      where p.session_id=p_session and p.round=v_s.round and p.defender_user=auth.uid()
                        and lower(coalesce(p.kind,'')) <> 'genjutsu') then
    v_reaz := v_reaz || coalesce((
      select jsonb_agg(jsonb_build_object(
        'chiave','tecnica','id',j.id,'nome',j.name_it,'fonte','jutsu',
        'disciplina',j.category,'chakra',coalesce(j.chakra_cost,0),
        'disponibile',(v_test or coalesce(j.chakra_cost,0)=0 or v_ck>=coalesce(j.chakra_cost,0)),
        'motivo_no',case when not v_test and coalesce(j.chakra_cost,0)>v_ck
          then 'servono '||j.chakra_cost||' chakra, ne hai '||v_ck end))
        from public.jutsu j
        left join public.character_jutsu cj on cj.jutsu_id=j.id and cj.user_id=auth.uid()
       where j.is_active and j.name_it='Dispersione'
         and (cj.user_id is not null or v_libero)), '[]'::jsonb);
  end if;

  v_out := jsonb_build_object(
    'session_id', v_s.id, 'round', v_s.round, 'fase', v_s.fase,
    'tuo_turno', (v_s.turn_of = auth.uid()),
    'azione_richiesta', case when v_s.fase = 'difesa' then 'reazione' else 'principale' end,
    'is_test', coalesce(v_test,false),
    'distanza', v_dist,
    -- [V1.1] lo Slancio proprio, in testa: il pannello lo mostra, non lo calcola.
    'slancio', coalesce(v_p.slancio,0),
    -- [048] La sede delle soglie è UNA. Il token è quello canonico:
    -- `contatto`, non «a contatto» — la locuzione italiana appartiene alla
    -- presentazione del consumer, non al contratto del server.
    'fascia', public._fascia_da_metri(v_dist),
    'chakra', jsonb_build_object('ora', v_ck, 'max', coalesce(v_c.chakra_max,0)),
    'spostamento', jsonb_build_object(
      'disponibile', v_s.fase = 'attacco' and not (v_p.usato_spostamento and v_p.round_speso = v_s.round),
      'max_metri', v_maxm,
      'motivo_no', case when v_s.fase = 'difesa' then 'in difesa si risponde e basta'
                        when v_p.usato_spostamento and v_p.round_speso = v_s.round then 'già speso in questo round' end),
    'colpo', jsonb_build_object('nome','Colpo a mani nude','fonte','colpo','gittata','contatto','portata_m',2,'chakra',0,
      'disponibile', v_dist <= 2 and not v_speso,
      'motivo_no', case when v_speso then 'hai già speso l''azione principale'
                        when v_dist > 2 then 'a ' || v_dist || ' metri non lo raggiungi: serve il contatto' end),
    'principali', coalesce(v_princ,'[]'::jsonb),
    'diversivi', v_div,
    'innate', coalesce(v_inn,'[]'::jsonb),
    'rapide', v_rap,
    'reazioni', v_reaz,
    'formazioni', public.combat_formazione_pubblica(p_session));
  return v_out;
end; $function$;

ALTER FUNCTION public.combat_opzioni(uuid) OWNER TO "postgres";

SET LOCAL ROLE "postgres";

REVOKE ALL ON FUNCTION public.combat_opzioni(uuid) FROM PUBLIC,"anon","authenticated","postgres","service_role";

GRANT EXECUTE ON FUNCTION public.combat_opzioni(uuid) TO "postgres";

GRANT EXECUTE ON FUNCTION public.combat_opzioni(uuid) TO "service_role";

GRANT EXECUTE ON FUNCTION public.combat_opzioni(uuid) TO "authenticated";

RESET ROLE;

-- Native source public.combat_panel_commit_v1(jsonb) MD5 cff710fa9c152019ef520c0bc701754b

CREATE OR REPLACE FUNCTION public.combat_panel_commit_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p jsonb; uid uuid:=auth.uid(); key uuid; fp text; adapter text; reason text;
 prior combat_panel_private.request_receipts%ROWTYPE; offer combat_panel_private.offers%ROWTYPE;
 code text; message text; recovery text;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'panel_authentication_required' USING ERRCODE='28000'; END IF;
 p:=combat_panel_private.validate_command(p_command); key:=(p->>'request_key')::uuid; fp:=public.combat_v2_sha256(p);
 PERFORM pg_advisory_xact_lock(hashtextextended('panel-request:'||uid::text||':'||key::text,731));
 SELECT * INTO prior FROM combat_panel_private.request_receipts WHERE principal_user=uid AND request_key=key;
 IF prior.request_key IS NOT NULL THEN
   IF prior.command_fingerprint<>fp THEN RAISE EXCEPTION 'panel_request_key_conflict' USING ERRCODE='22023'; END IF;
   RETURN jsonb_set(prior.viewer_envelope,'{receipt,replayed}','true',false);
 END IF;
 SELECT * INTO offer FROM combat_panel_private.offers WHERE id=(p->>'offer_id')::uuid AND principal_user=uid;
 IF offer.id IS NULL THEN RAISE EXCEPTION 'panel_offer_not_available' USING ERRCODE='42501'; END IF;
 adapter:=offer.source_payload->>'adapter';
 reason:=combat_panel_private.access_reason((p->>'location_id')::uuid,adapter);
 IF reason IS NOT NULL THEN RAISE EXCEPTION 'panel_access_rejected' USING ERRCODE='42501'; END IF;
 IF adapter IS DISTINCT FROM combat_panel_private.location_adapter((p->>'location_id')::uuid) THEN
   RAISE EXCEPTION 'panel_context_stale' USING ERRCODE='40001'; END IF;
 IF offer.kind='administration' AND offer.operation='open'
   AND offer.source_payload->>'dispatch'='master_session_open' THEN
   RETURN combat_panel_private.commit_master_open(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='sabaku_clone' THEN
   RETURN clan_sabaku_private.commit_clone(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='immobilization_escape' THEN
   RETURN combat_panel_private.commit_immobilization_escape(p); END IF;
 IF offer.kind='action' AND offer.operation='declare' AND offer.source_payload->>'dispatch'='multiplication' THEN
   RETURN combat_panel_private.commit_multiplication(p); END IF;
 IF adapter='ordinary_v2' THEN RETURN combat_panel_private.commit_ordinary(p); END IF;
 IF adapter='master_v2' THEN
   IF offer.kind='control' AND offer.source_payload->>'dispatch'='sabaku_control' THEN
     RETURN clan_sabaku_private.commit_master_control(p); END IF;
   IF offer.kind='control' AND offer.source_payload->>'dispatch'='companion_control' THEN
     RETURN combat_panel_private.commit_master_companion(p); END IF;
   IF offer.kind='administration' THEN RETURN combat_panel_private.commit_master_admin(p); END IF;
   RETURN combat_panel_private.commit_master_actor(p);
 END IF;
 RAISE EXCEPTION 'panel_dispatch_not_available' USING ERRCODE='22023';
EXCEPTION WHEN OTHERS THEN
 -- Questo ramo viene raggiunto dopo il rollback dell'intera sottotransazione
 -- della richiesta. Non comprende timeout/disconnessioni senza risposta DB.
 code:=CASE WHEN SQLSTATE='28000' THEN 'authentication_required'
   WHEN SQLERRM='panel_request_key_conflict' THEN 'request_key_conflict'
   WHEN SQLSTATE='42501' THEN 'not_authorized'
   WHEN SQLSTATE='40001' THEN 'context_changed'
   WHEN SQLSTATE LIKE '22%' THEN 'selection_rejected' ELSE 'operation_rejected' END;
 message:=CASE code WHEN 'authentication_required' THEN 'Accedi nuovamente per continuare.'
   WHEN 'request_key_conflict' THEN 'Questa richiesta è già associata a un altro invio. Verifica lo stato prima di continuare.'
   WHEN 'not_authorized' THEN 'Questa operazione non è disponibile per il tuo accesso.'
   WHEN 'context_changed' THEN 'Lo scontro è cambiato. Rileggi lo stato e scegli di nuovo.'
   WHEN 'selection_rejected' THEN 'Le scelte non sono più valide. Rileggi le opzioni.'
   ELSE 'Il server ha rifiutato l’operazione. Rileggi lo stato; se il problema resta, informa lo staff.' END;
 recovery:=CASE WHEN code='authentication_required' THEN 'authenticate'
   WHEN code='request_key_conflict' THEN 'contact_staff' ELSE 'refresh' END;
 RETURN jsonb_build_object('schema_version','combat-panel-error/1','status','rejected','request_key',key,
   'code',code,'message',message,'recovery',recovery);
END $function$;

