-- Native source public.combat_sabaku_staff_profile_bind_v1(uuid,bigint,uuid) MD5 63bb89da437a33555c0f4740387437a8

CREATE OR REPLACE FUNCTION public.combat_sabaku_staff_profile_bind_v1(p_session uuid, p_expected_context bigint, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE; c combat_consumer_private.activities%ROWTYPE;
  old_profile clan_sabaku_private.staff_profiles%ROWTYPE; principals uuid[];
  receipt uuid; result jsonb;
BEGIN
 IF auth.uid() IS NULL OR p_request IS NULL OR p_expected_context IS NULL
   OR p_session IS NULL THEN
   RAISE EXCEPTION 'sabaku_staff_request_invalid' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=p_session FOR UPDATE;
 SELECT * INTO STRICT c FROM combat_consumer_private.activities WHERE session_id=p_session FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_actors WHERE session_id=p_session ORDER BY id FOR UPDATE;
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE session_id=p_session
   AND character_id='6bceee99-974f-426b-8d92-38b43b4a4267'::uuid AND controller_user=auth.uid() AND actor_kind='pg';
 IF NOT coalesce(a.character_id='6bceee99-974f-426b-8d92-38b43b4a4267'::uuid
   AND c.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
   AND c.policy_id='staff_test_no_persistent_resources_v1' AND c.phase<>'closed'
   AND c.closed_at IS NULL AND NOT public.combat_v2_values_written(a.session_id)
   AND EXISTS(SELECT 1 FROM public.combat_v2_sessions ss WHERE ss.id=a.session_id
     AND ss.location_id=c.location_id AND ss.closed_at IS NULL
     AND ss.state NOT IN ('chiusa','annullata'))
   AND (SELECT count(*) FROM public.combat_v2_actors x
     WHERE x.session_id=a.session_id AND x.actor_kind='pg')=2
   AND (SELECT count(*) FROM combat_consumer_private.members m WHERE m.session_id=a.session_id)=2
   AND EXISTS(SELECT 1 FROM combat_consumer_private.members m
     JOIN public.combat_v2_actors x ON x.id=m.actor_id AND x.session_id=m.session_id
       AND x.character_id=m.character_id AND x.actor_kind='pg'
     JOIN public.characters staff_pg ON staff_pg.id=x.character_id AND staff_pg.user_id=x.controller_user
     WHERE m.session_id=a.session_id
     HAVING count(*)=2 AND count(DISTINCT x.controller_user)=2
       AND array_agg(DISTINCT x.character_id ORDER BY x.character_id)=ARRAY[
         '2a877f02-4993-4e65-9172-7d29f08c5b86'::uuid,'6bceee99-974f-426b-8d92-38b43b4a4267'::uuid]
       AND combat_consumer_private.staff_test_allowed(c.location_id,
         array_agg(DISTINCT x.controller_user ORDER BY x.controller_user),false)),false) THEN
   RAISE EXCEPTION 'sabaku_staff_scope_invalid' USING ERRCODE='42501'; END IF;
 SELECT * INTO old_profile FROM clan_sabaku_private.staff_profiles WHERE session_id=p_session AND actor_id=a.id;
 IF FOUND THEN
   IF old_profile.request_id IS DISTINCT FROM p_request
     OR (old_profile.bind_result->>'context_version')::bigint-1 IS DISTINCT FROM p_expected_context THEN
     RAISE EXCEPTION 'sabaku_staff_already_bound' USING ERRCODE='22023'; END IF;
   RETURN old_profile.bind_result||jsonb_build_object('replayed',true);
 END IF;
 IF c.policy_id<>'staff_test_no_persistent_resources_v1' OR public.combat_v2_values_written(p_session)
   OR c.phase<>'action' OR c.turn_actor_id<>a.id OR a.state<>'attivo'
   OR c.context_version<>p_expected_context
   OR NOT EXISTS(SELECT 1 FROM clan_sabaku_private.release_gate WHERE singleton AND staff_enabled) THEN
   RAISE EXCEPTION 'sabaku_staff_not_ready' USING ERRCODE='40001'; END IF;
 SELECT array_agg(DISTINCT x.controller_user ORDER BY x.controller_user) INTO principals
   FROM combat_consumer_private.members m JOIN public.combat_v2_actors x
     ON x.id=m.actor_id AND x.session_id=m.session_id AND x.character_id=m.character_id
   JOIN public.characters pg ON pg.id=x.character_id AND pg.user_id=x.controller_user
   WHERE m.session_id=p_session AND x.actor_kind='pg';
 IF cardinality(principals) IS DISTINCT FROM 2
   OR EXISTS(SELECT 1 FROM clan_marionettisti_private.sources WHERE session_id=p_session AND owner_actor_id=a.id)
   OR (SELECT count(*) FROM public.combat_v2_actors WHERE session_id=p_session AND actor_kind='pg')<>2
   OR NOT combat_consumer_private.staff_test_allowed(c.location_id,principals,false)
   OR clan_sabaku_private.narrative_pending(p_session)
   OR EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=c.exchange_id AND actor_id=a.id) THEN
   RAISE EXCEPTION 'sabaku_staff_scope_invalid' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(a.mechanics_snapshot->'chakra') IS DISTINCT FROM 'number'
   OR jsonb_typeof(a.mechanics_snapshot->'vita') IS DISTINCT FROM 'number'
   OR (a.mechanics_snapshot->>'chakra')::integer<0 OR (a.mechanics_snapshot->>'vita')::integer<=0 THEN
   RAISE EXCEPTION 'sabaku_staff_resources_invalid' USING ERRCODE='22023'; END IF;
 receipt:=gen_random_uuid();
 INSERT INTO clan_sabaku_private.staff_profiles(session_id,actor_id,request_id,receipt_id)
   VALUES(p_session,a.id,p_request,receipt);
 INSERT INTO clan_sabaku_private.reserves(character_id,session_id,actor_id,is_test,capacity,current_amount)
   VALUES(a.character_id,p_session,a.id,true,15,15);
 PERFORM clan_innata_private.combat_state_ensure(a.id);
 UPDATE combat_consumer_private.activities SET context_version=context_version+1 WHERE session_id=p_session
   RETURNING context_version INTO c.context_version;
 result:=jsonb_build_object('contract_version','sabaku-staff-bind/1','receipt_id',receipt,
   'context_version',c.context_version,'replayed',false,'is_test',true,'values_written',false,
   'sabaku_transport',jsonb_build_object('contract_version','sabaku-transport-view/1',
     'context_version',c.context_version,'is_test',true,
     'innata',jsonb_build_object('active',false,'activation_chakra',5,'upkeep_chakra',5,'deactivation_chakra',0),
     'reserve',jsonb_build_object('current',15,'committed',0,'capacity',15,'available',15),
     'transport',jsonb_build_object('active',false,'activation_chakra',5,'sand_commit',5,'upkeep_chakra',0,
       'movement_bonus_m',0,'expires_round_id',NULL)));
 UPDATE clan_sabaku_private.staff_profiles SET bind_result=result WHERE session_id=p_session AND actor_id=a.id;
 RETURN result;
END $function$;

