-- Native source public.combat_v2_assert_operational(uuid,uuid,boolean) MD5 beae04c35fda2ab8429cacdd2c52a067

CREATE OR REPLACE FUNCTION public.combat_v2_assert_operational(p_round uuid, p_request_key uuid, p_allow_resolved boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_combat_state text; v_master_state text;
begin
  select s.state,m.stato into v_combat_state,v_master_state
    from public.combat_v2_rounds r
    join public.combat_v2_sessions s on s.id=r.session_id
    left join public.master_v2_sessions m on m.id=s.master_session_id
   where r.id=p_round;
  if v_combat_state is null then
    perform public.combat_v2_fail('sessione_inesistente','Round inesistente.',404,p_request_key,'{}');
  end if;
  if v_combat_state='sospeso' or v_master_state='sospesa' then
    perform public.combat_v2_fail('sessione_sospesa','Sessione sospesa.',409,p_request_key,'{}');
  end if;
  if (not p_allow_resolved and v_combat_state<>'in_corso')
     or (p_allow_resolved and v_combat_state not in ('in_corso','risolto'))
     or (v_master_state is not null and v_master_state not in ('preparazione','in_corso','chiusura')) then
    perform public.combat_v2_fail('sessione_non_operativa','Sessione non operativa.',409,p_request_key,
      jsonb_build_object('combat_state',v_combat_state,'master_state',v_master_state));
  end if;
end $function$;

