-- Native source public.combat_v2_clan_genin_marionettisti_resolve_v1(jsonb) MD5 e2b7f73dadadf327a33a6f6f01e90567

CREATE OR REPLACE FUNCTION public.combat_v2_clan_genin_marionettisti_resolve_v1(j jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d uuid;k uuid;p clan_marionettisti_private.offensive_profiles%rowtype;source jsonb;
begin
 if jsonb_typeof(j) is distinct from 'object' or (j-array['contract_version','declaration_id','request_key'])<>'{}'::jsonb
  or not (j?&array['contract_version','declaration_id','request_key'])
  or j->>'contract_version'<>'marionetta-round-hook/1' then raise exception 'marionetta_hook_shape_invalid';end if;
 d:=(j->>'declaration_id')::uuid;k:=(j->>'request_key')::uuid;
 if d is null or k is null then raise exception 'marionetta_hook_identity_invalid';end if;
 select * into strict p from clan_marionettisti_private.offensive_profiles where declaration_id=d for share;
 if p.profile_sha256 is distinct from public.combat_v2_sha256(p.profile) then raise exception 'marionetta_profile_corrupt';end if;
 source:=combat_panel_private.multiplication_companion_frozen_source(d);
 if (source->>'companion_actor_id',source->>'link_version',source->>'instance_id')
  is distinct from(p.profile->>'companion_actor_id',p.profile->>'link_version',p.profile->>'instance_id') then raise exception 'marionetta_source_stale' using errcode='22023';end if;
 return jsonb_build_object('declaration_id',d,'request_key',k,'profile',p.profile,'profile_sha256',p.profile_sha256,
  'source_now',source,'values_written',false);
end;
$function$;

