-- Native source public.combat_v2_has_forbidden_key(jsonb) MD5 e463aab05fd9b561d3d80e4e3612038c

CREATE OR REPLACE FUNCTION public.combat_v2_has_forbidden_key(p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_key text; v_child jsonb;
begin
  if p_value is null then return false; end if;
  if jsonb_typeof(p_value)='object' then
    for v_key,v_child in select key,value from jsonb_each(p_value) loop
      if lower(v_key) in ('base','damage','danno','pool','dice','dado','mod','quality','qualita','lesiva','vita','pv','chakra','cost','costo','xp','ryo','statistiche','role','ruolo','authorization','autorizzazione')
         or public.combat_v2_has_forbidden_key(v_child) then return true; end if;
    end loop;
  elsif jsonb_typeof(p_value)='array' then
    for v_child in select value from jsonb_array_elements(p_value) loop
      if public.combat_v2_has_forbidden_key(v_child) then return true; end if;
    end loop;
  end if;
  return false;
end $function$;

