-- Native source public.combat_v2_innate_state_v1(uuid,uuid) MD5 a7114ca4758f67379cff3f20057b1331

CREATE OR REPLACE FUNCTION public.combat_v2_innate_state_v1(p_round uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.combat_v2_actors%rowtype;begin select * into a from public.combat_v2_actors where id=p_actor;
 if a.id is null or not exists(select 1 from public.combat_v2_rounds r where r.id=p_round and r.session_id=a.session_id) or a.controller_user is distinct from auth.uid() then perform public.combat_v2_fail('attore_non_controllato','Non controlli questo attore.',403,null,'{}');end if;
 if clan_innata_private.current_actor() is distinct from a.character_id then perform public.combat_v2_fail('common_actor_scope_mismatch','La capability Common non appartiene al personaggio del combat actor.',403,null,'{}');end if;
 return public.clan_genin_innata_state_get_v1();end $function$;

