-- Native source public.combat_v2_ordinary_open(uuid,uuid,integer,uuid) MD5 961e70689211dcae05e277f2f7bb1fe9

CREATE OR REPLACE FUNCTION public.combat_v2_ordinary_open(p_location uuid, p_opponent_character uuid, p_distance integer, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_me public.characters%rowtype; v_opp public.characters%rowtype; v_event jsonb; v_event_id uuid;
  v_enc uuid; v_round uuid; v_result jsonb;
begin
  if not public.combat_v2_is_service() and not combat_consumer_private.can_open(p_location,p_opponent_character,p_distance,p_request_key) then perform public.combat_v2_fail('controllo_revocato','La porta ordinary V2 non è esposta prima del cutover.',403,p_request_key,'{}'); end if;
  perform 1 from public.locations l where l.id=p_location order by l.id for update;
  select * into v_me from public.characters where user_id=v_uid;
  select * into v_opp from public.characters where id=p_opponent_character;
  if v_me.id is null or v_opp.id is null or v_me.id=v_opp.id or (p_distance not in (0,5,10,15) and not combat_consumer_private.can_open(p_location,p_opponent_character,p_distance,p_request_key)) then
    perform public.combat_v2_fail('intento_non_valido','Parametri duello non validi.',422,p_request_key,'{}');
  end if;
  if public._personaggio_impegnato_meccanicamente(v_me.id)
     or public._personaggio_impegnato_meccanicamente(v_opp.id) then
    perform public.combat_v2_fail('personaggio_impegnato','Uno dei personaggi è già impegnato in un’attività meccanica.',409,p_request_key,'{}');
  end if;
  v_event:=public.combat_v2_event_begin(p_location,p_request_key,'combat_v2_ordinary_open',jsonb_build_object('opponent',p_opponent_character,'distance',p_distance));
  if (v_event->>'replay')::boolean then return v_event->'result'; end if;
  v_event_id:=(v_event->>'event_id')::uuid;
  if exists(select 1 from public.master_v2_sessions where location_id=p_location and stato not in ('chiusa','annullata'))
     or exists(select 1 from public.combat_sessions where location_id=p_location and state='aperto')
     or exists(select 1 from public.combat_v2_sessions where location_id=p_location and state not in ('chiuso','annullato')) then
    perform public.combat_v2_fail('scontro_gia_aperto_nel_luogo','Esiste già uno scontro nel luogo.',409,p_request_key,'{}'); end if;
  insert into public.combat_v2_sessions(source_kind,location_id,state,lesiva) values('ordinary',p_location,'in_corso',true) returning id into v_enc;
  perform 1 from public.characters c where c.id in (v_me.id,v_opp.id) order by c.id for key share;
  insert into public.combat_v2_actors(session_id,actor_kind,character_id,controller_user,team_key,position_m,initiative_snapshot,mechanics_snapshot)
  values(v_enc,'pg',v_me.id,v_me.user_id,'A',0,v_me.velocita,public.combat_v2_character_snapshot(v_me.id)),
        (v_enc,'pg',v_opp.id,v_opp.user_id,'B',p_distance,v_opp.velocita,public.combat_v2_character_snapshot(v_opp.id));
  insert into public.combat_v2_rounds(session_id,round_no,evaluation_mode) values(v_enc,1,'neutra') returning id into v_round;
  v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object('encounter_id',v_enc,'round_id',v_round));
  return public.combat_v2_event_complete(v_event_id,v_result);
end $function$;

