-- Native source public.combat_v2_rating_save(uuid,smallint,text,uuid) MD5 4676e2e2618856461af7ac72fa242d6c

CREATE OR REPLACE FUNCTION public.combat_v2_rating_save(p_declaration uuid, p_value smallint, p_reason text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_d public.combat_v2_declarations%rowtype; v_r public.combat_v2_rounds%rowtype; v_s public.combat_v2_sessions%rowtype;
  v_a public.combat_v2_actors%rowtype; v_m public.master_v2_sessions%rowtype; v_event jsonb; v_event_id uuid; v_id uuid; v_result jsonb;
begin
  if v_uid is null then perform public.combat_v2_fail('autenticazione_richiesta','Autenticazione richiesta.',401,p_request_key,'{}'); end if;
  if p_value is null then perform public.combat_v2_fail('voto_non_intero','Il voto deve essere intero.',422,p_request_key,'{}'); end if;
  if p_value not between -3 and 3 then perform public.combat_v2_fail('voto_fuori_intervallo','Il voto deve essere tra -3 e +3.',422,p_request_key,'{}'); end if;
  perform public.combat_v2_lock_round((select d.round_id from public.combat_v2_declarations d where d.id=p_declaration));
  select * into v_d from public.combat_v2_declarations where id=p_declaration for update;
  select * into v_r from public.combat_v2_rounds where id=v_d.round_id for update;
  select * into v_s from public.combat_v2_sessions where id=v_r.session_id;
  select * into v_a from public.combat_v2_actors where id=v_d.actor_id;
  select * into v_m from public.master_v2_sessions where id=v_s.master_session_id for update;
  perform public.combat_v2_assert_operational(v_r.id,p_request_key,false);
  if v_d.id is null or v_a.actor_kind<>'pg' or v_d.kind not in ('attacco','difesa') then perform public.combat_v2_fail('voto_non_consentito','Dichiarazione non votabile.',422,p_request_key,'{}'); end if;
  if v_r.evaluation_mode<>'umana' or v_m.master_user<>v_uid then perform public.combat_v2_fail('voto_non_consentito','Solo il Master umano corrente può votare.',403,p_request_key,'{}'); end if;
  if v_r.state in ('congelato','risoluzione','risolto','narrazione','narrato') then perform public.combat_v2_fail('voto_congelato','Voto già congelato.',409,p_request_key,'{}'); end if;
  v_event:=public.combat_v2_event_begin(v_r.id,p_request_key,'combat_v2_rating_save',jsonb_build_object('declaration',p_declaration,'value',p_value,'reason',p_reason),v_m.control_version);
  if (v_event->>'replay')::boolean then return v_event->'result'; end if; v_event_id:=(v_event->>'event_id')::uuid;
  if exists(select 1 from public.combat_v2_ratings where declaration_id=p_declaration and is_active) then perform public.combat_v2_fail('rettifica_admin_richiesta','Un voto attivo esiste già.',409,p_request_key,'{}'); end if;
  insert into public.combat_v2_ratings(declaration_id,session_id,round_id,pg_character_id,rating_kind,value,source,evaluator_master_user,reason,request_key)
  values(p_declaration,v_s.id,v_r.id,v_a.character_id,v_d.kind,p_value,'master_umano',v_uid,nullif(btrim(coalesce(p_reason,'')),''),p_request_key) returning id into v_id;
  v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object('rating_id',v_id,'value',p_value));
  return public.combat_v2_event_complete(v_event_id,v_result);
end $function$;

