-- Native source public.combat_v2_report_immutable_guard() MD5 52b248e775113b0f1366f1980d360c21

CREATE OR REPLACE FUNCTION public.combat_v2_report_immutable_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op='DELETE' then raise exception 'combat_v2_referto_immutabile'; end if;
  if (to_jsonb(new)-array['narration_state','narrator_kind','message_id','narrated_at'])
     is distinct from (to_jsonb(old)-array['narration_state','narrator_kind','message_id','narrated_at']) then
    raise exception 'combat_v2_referto_immutabile';
  end if;
  return new;
end $function$;

