-- Native source public.combat_v2_substitution_resolve_internal_v1(uuid,uuid) MD5 471f2136e1ace180cb046d3e681d0c00

CREATE OR REPLACE FUNCTION public.combat_v2_substitution_resolve_internal_v1(p_defense_declaration uuid, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  multiplication_facts jsonb; multiplication_effect jsonb; multiplication_target uuid;
  x record; ctx jsonb; fp text; replay jsonb; spatial_result jsonb; internal_key uuid;
  ar public.combat_v2_actors%rowtype; sr public.combat_v2_rounds%rowtype;
  ss public.combat_v2_sessions%rowtype; ch integer; values_written boolean; eid uuid; result jsonb;
  q point; attacker_spatial combat_spatial.actor_states%rowtype; defender_after combat_spatial.actor_states%rowtype;
  anchor combat_spatial.arena_objects%rowtype; final_distance numeric;
begin
  if current_user not in ('postgres','service_role') then
    raise exception using errcode='42501',message='service_role_required';
  end if;
  if p_request_key is null then
    raise exception using errcode='22004',message='substitution_request_key_required';
  end if;
  -- La request key viene serializzata prima della prima lettura della receipt:
  -- due resolve identiche attendono lo stesso lock e la seconda vede il replay.
  perform pg_advisory_xact_lock(hashtextextended(
    'common-substitution-resolve-request:'||p_request_key::text,0));
  select o.capability_id,o.link_id,o.state option_state,l.*,c.object_key,c.state capability_state,
         d.sanitized_intent,d.state defense_state
    into strict x
  from combat_spatial.substitution_activity_options o
  join combat_spatial.substitution_activity_links l on l.link_id=o.link_id
  join combat_spatial.substitution_capabilities c on c.capability_id=o.capability_id
  join public.combat_v2_declarations d on d.id=o.selected_defense_declaration_id
  where o.selected_defense_declaration_id=p_defense_declaration and l.activity_kind='combat_v2';
  fp:=combat_spatial.server_fingerprint('combat_v2_substitution_resolve_internal_v1',
    jsonb_build_object('defense',p_defense_declaration,'option',x.capability_id,'attack',x.attack_declaration_id));
  replay:=combat_spatial.receipt_replay(p_request_key,'combat_v2_substitution_resolve_internal_v1',fp);
  if replay is not null then return replay-'replayed'; end if;
  perform pg_advisory_xact_lock(hashtextextended('common-substitution:'||x.instance_id::text||':'||x.defender_actor_id::text,0));
  if x.option_state<>'selected' or x.capability_state<>'offered' or x.state<>'selected'
     or x.defense_state not in ('inviata','congelata') then
    raise exception using errcode='23514',message='substitution_option_stale';
  end if;
  ctx:=combat_spatial.substitution_combat_context_v1(x.attack_declaration_id);
  if ctx->>'source_snapshot_sha256' is distinct from x.source_snapshot_sha256
     or ctx->>'source_profile_id' is distinct from x.source_profile_id
     or (ctx->>'round_no')::integer<>x.activity_round_no then
    raise exception using errcode='23514',message='substitution_body_route_stale';
  end if;
  SELECT id INTO STRICT multiplication_target FROM public.combat_v2_attack_targets WHERE attack_declaration_id=x.attack_declaration_id;
  multiplication_facts:=combat_panel_private.multiplication_attack_facts(multiplication_target);
  multiplication_effect:=combat_panel_private.multiplication_effect(multiplication_facts,'sostituzione');
  internal_key:=md5(p_request_key::text||'|spatial')::uuid;
  spatial_result:=combat_spatial.substitution_commit(x.capability_id,internal_key,x.attack_declaration_id);
  eid:=(spatial_result->>'event_id')::uuid;
  select * into strict sr from public.combat_v2_rounds where id=x.activity_round_id for update;
  select * into strict ss from public.combat_v2_sessions where id=sr.session_id for update;
  if sr.phase not in ('congelato','risoluzione') then
    raise exception using errcode='23514',message='substitution_parent_window_invalid';
  end if;
  select * into strict ar from public.combat_v2_actors where id=x.defender_actor_id for update;
  ch:=coalesce((ar.mechanics_snapshot->>'chakra')::integer,0);
  if ch<5 then raise exception using errcode='23514',message='substitution_resource_or_reaction_unavailable'; end if;
  if ar.actor_kind='pg' then perform 1 from public.characters where id=ar.character_id for update; end if;
  ctx:=combat_spatial.substitution_combat_context_v1(x.attack_declaration_id);
  if ctx->>'source_snapshot_sha256' is distinct from x.source_snapshot_sha256 then
    raise exception using errcode='23514',message='substitution_source_not_owned_or_active';
  end if;
  values_written:=public.combat_v2_values_written(ss.id);
  insert into public.combat_v2_resource_ledger(session_id,round_id,declaration_id,actor_id,resource_kind,
    expected_amount,committed_amount,applied_amount,is_simulated,balance_before,balance_after,idempotency_key)
  values(ss.id,sr.id,p_defense_declaration,ar.id,'chakra',5,5,case when values_written then 5 else 0 end,
    not values_written,ch,case when values_written or combat_panel_private.uses_simulated_pools(ss.id) then ch-5 else ch end,md5(p_request_key::text||'|chakra')::uuid),
    (ss.id,sr.id,p_defense_declaration,ar.id,'reazione',1,1,case when values_written then 1 else 0 end,
    not values_written,null,null,md5(p_request_key::text||'|reaction')::uuid);
  if values_written or combat_panel_private.uses_simulated_pools(ss.id) then
    update public.combat_v2_actors set mechanics_snapshot=jsonb_set(mechanics_snapshot,'{chakra}',to_jsonb(ch-5),false) where id=ar.id;
    if values_written and ar.actor_kind='pg' then
      perform set_config('app.allow_chakra_delta','1',true);
      update public.characters set chakra=chakra-5 where id=ar.character_id and chakra>=5;
      if not found then raise exception using errcode='23514',message='substitution_resource_or_reaction_unavailable'; end if;
      perform set_config('app.allow_chakra_delta','0',true);
    end if;
  end if;
  IF NOT (multiplication_effect->>'defense_spent_on_copy')::boolean THEN
  update public.combat_v2_declarations set state='risolta',outcome=jsonb_build_object(
    'success',false,'damage_applied',0,'canonical_outcome','negato_sostituzione',
    'substitution_link',eid,'defender_relocated',true,'proxy_non_actor',true)
    ||CASE WHEN jsonb_array_length(multiplication_facts)>0 THEN jsonb_build_object('multiplication',multiplication_facts,
        'multiplication_effect',multiplication_effect) ELSE '{}'::jsonb END where id=x.attack_declaration_id;
    PERFORM combat_panel_private.multiplication_attack_finish(multiplication_target);
  END IF;
  update public.combat_v2_declarations set state='risolta',outcome=jsonb_build_object(
    'linked_attack',x.attack_declaration_id,'canonical_outcome',CASE WHEN (multiplication_effect->>'defense_spent_on_copy')::boolean THEN 'reazione_spesa_su_copia' ELSE 'negato_sostituzione' END,
    'substitution_link',eid) where id=p_defense_declaration;
  update combat_spatial.substitution_activity_links set state='committed' where link_id=x.link_id;
  update combat_spatial.substitution_activity_options set state='committed' where capability_id=x.capability_id;
  select * into strict defender_after from combat_spatial.actor_states
   where instance_id=x.instance_id and actor_id=x.defender_actor_id;
  select * into strict attacker_spatial from combat_spatial.actor_states
   where instance_id=x.instance_id and actor_id=(select actor_id from public.combat_v2_declarations where id=x.attack_declaration_id);
  select * into strict anchor from combat_spatial.arena_objects o
   join combat_spatial.arena_instances i on i.template_key=o.template_key and i.template_version=o.template_version
   where i.instance_id=x.instance_id and o.object_key=x.object_key;
  final_distance:=combat_spatial.distance_m(defender_after.x_m,defender_after.y_m,attacker_spatial.x_m,attacker_spatial.y_m);
  update combat_spatial.spatial_events set narrator_payload=jsonb_build_object(
    'schema_version','common-substitution-narrator/1.0',
    'before',jsonb_build_object('state','impact_imminent'),
    'impact',jsonb_build_object('outcome',CASE WHEN (multiplication_effect->>'defense_spent_on_copy')::boolean THEN 'reazione_spesa_su_copia' ELSE 'negato_sostituzione' END,'proxy','semantic_non_actor'),
    'anchor',jsonb_build_object('semantic_label',anchor.semantic_label,'state','consumed_non_substitutable'),
    'after',jsonb_build_object('state','defender_relocated','final_relative_distance_m',round(final_distance,2),
      'semantic_region',anchor.semantic_label),
    'substitution_link',eid)
   where event_id=eid;
  result:=jsonb_build_object('schema_version','common-substitution-resolution/1.0','status','committed',
    'event_id',eid,'canonical_outcome',CASE WHEN (multiplication_effect->>'defense_spent_on_copy')::boolean THEN 'reazione_spesa_su_copia' ELSE 'negato_sostituzione' END,'damage_applied',0,'chakra_committed',5,
    'values_written',values_written);
  insert into combat_spatial.request_receipts values(p_request_key,'combat_v2_substitution_resolve_internal_v1',fp,result,clock_timestamp());
  return result;
end
$function$;

