-- Native source public.combat_v2_substitution_round_offers_v1(uuid,uuid) MD5 f01fce65e05b485fbe445cd96e64f32a

CREATE OR REPLACE FUNCTION public.combat_v2_substitution_round_offers_v1(p_round uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d record; one jsonb; outv jsonb:='[]'::jsonb; phasev text;
begin
  select phase into phasev from public.combat_v2_rounds where id=p_round;
  if phasev is distinct from 'raccolta_difese' then return outv; end if;
  for d in
    select a.id from public.combat_v2_declarations a
    where a.round_id=p_round and a.kind='attacco' and a.target_actor_id=p_actor
      and not exists(select 1 from public.combat_v2_declarations x
                     where x.parent_attack_id=a.id and x.kind in ('difesa','nessuna'))
    order by a.id
  loop
    begin
      one:=public.combat_v2_substitution_options_v1(d.id);
      if coalesce((one->>'available')::boolean,false) then
        outv:=outv||jsonb_build_array(jsonb_build_object(
          'attack_declaration_id',d.id,'offer',one));
      end if;
    exception when no_data_found then null;
      when others then
        if sqlerrm not in ('substitution_source_not_owned_or_active',
          'substitution_resource_or_reaction_unavailable',
          'substitution_parent_window_invalid') then raise; end if;
    end;
  end loop;
  return outv;
end
$function$;

