CREATE OR REPLACE FUNCTION public.exam_substitution_instance_prepare_v1(p_prova uuid, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.esame_prove%rowtype; cs public.academy_class_sessions%rowtype;
  route combat_spatial.exam_arena_routes_v1%rowtype; t combat_spatial.arena_templates%rowtype;
  iid uuid; ca uuid; pa uuid; result jsonb; fp text; replay jsonb;
begin
  if current_user not in ('postgres','service_role') then raise exception using errcode='42501',message='service_role_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('exam-substitution-instance:'||p_prova::text,0));
  fp:=combat_spatial.server_fingerprint('exam_substitution_instance_prepare_v1',jsonb_build_object('prova',p_prova));
  replay:=combat_spatial.receipt_replay(p_request_key,'exam_substitution_instance_prepare_v1',fp);
  if replay is not null then return replay-'replayed'; end if;
  select * into strict p from public.esame_prove where id=p_prova and stato='aperta' for update;
  select * into strict cs from public.academy_class_sessions where id=p.class_session_id;
  select * into strict route from combat_spatial.exam_arena_routes_v1 where class_location_id=cs.location_id and enabled;
  select * into strict t from combat_spatial.arena_templates where template_key=route.template_key and template_version=route.template_version and status='ready';
  iid:=md5('exam-instance|'||p.id::text)::uuid; ca:=md5('exam-candidate|'||p.id::text)::uuid; pa:=md5('exam-png|'||p.id::text)::uuid;
  insert into combat_spatial.arena_instances(instance_id,master_session_id,encounter_id,binding_id,template_key,template_version,map_version,state)
  values(iid,md5('exam-master|'||p.id::text)::uuid,p.id,route.binding_id,route.template_key,route.template_version,1,'open');
  insert into combat_spatial.actor_states
  select iid,ca,'PG',route.candidate_slot_key,p.candidate_user,p.candidate_character,s.x_m,s.y_m,t.actor_radius_m,1,'active'
  from combat_spatial.arena_slots s where s.template_key=route.template_key and s.template_version=route.template_version and s.slot_key=route.candidate_slot_key;
  insert into combat_spatial.actor_states
  select iid,pa,'PNG',route.png_slot_key,md5('exam-service-controller')::uuid,p.profilo_id,s.x_m,s.y_m,t.actor_radius_m,1,'active'
  from combat_spatial.arena_slots s where s.template_key=route.template_key and s.template_version=route.template_version and s.slot_key=route.png_slot_key;
  insert into combat_spatial.object_states(instance_id,object_key,state,state_version)
  select iid,o.object_key,case when o.substitutable then 'available' else 'blocked' end,1
  from combat_spatial.arena_objects o where o.template_key=route.template_key and o.template_version=route.template_version;
  insert into combat_spatial.viewer_grants values(iid,p.candidate_user,ca,true,true,1),(iid,p.candidate_user,pa,true,true,1);
  result:=jsonb_build_object('schema_version','exam-substitution-instance/1.0','prova_id',p.id,'instance_id',iid,'status','prepared');
  insert into combat_spatial.request_receipts values(p_request_key,'exam_substitution_instance_prepare_v1',fp,result,clock_timestamp());
  return result;
end
$function$;

