CREATE OR REPLACE FUNCTION public.exam_substitution_options_v1(p_prova uuid, p_source_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx jsonb; iid uuid; wid uuid; lid uuid; raw jsonb; item jsonb;
begin
  if current_user not in ('postgres','service_role') then raise exception using errcode='42501',message='service_role_required'; end if;
  ctx:=combat_spatial.exam_substitution_context_v1(p_prova,p_source_application_id);
  iid:=(ctx->>'instance_id')::uuid; wid:=md5(iid::text||p_source_application_id::text||(ctx->>'defender_actor_id'))::uuid;
  lid:=md5('exam_genin|'||iid::text||'|'||p_source_application_id::text)::uuid;
  insert into combat_spatial.defense_windows values(iid,wid,(ctx->>'defender_actor_id')::uuid,(ctx->>'round_no')::integer,'open',1)
    on conflict(instance_id,defense_window_id) do nothing;
  insert into combat_spatial.substitution_activity_links(link_id,activity_kind,instance_id,defense_window_id,
    activity_session_id,activity_round_id,attack_declaration_id,defender_actor_id,source_jutsu_id,
    source_profile_id,source_ninjutsu,source_chakra,source_snapshot_sha256,activity_round_no,activity_version,state)
  values(lid,'exam_genin',iid,wid,p_prova,p_prova,p_source_application_id,(ctx->>'defender_actor_id')::uuid,
    '31b15861-fb78-4f8a-ac1c-ebf2d957c32e',ctx->>'source_profile_id',(ctx->>'ninjutsu')::integer,
    (ctx->>'chakra')::integer,ctx->>'source_snapshot_sha256',(ctx->>'round_no')::integer,1,'offered')
  on conflict(activity_kind,activity_round_id,attack_declaration_id,defender_actor_id) do nothing;
  raw:=combat_spatial.substitution_options(iid,wid,(ctx->>'defender_actor_id')::uuid,ctx->>'source_profile_id',(ctx->>'round_no')::integer);
  for item in select value from jsonb_array_elements(raw) loop
    insert into combat_spatial.substitution_activity_options values((item->>'option_id')::uuid,lid,null,null,'offered',clock_timestamp()) on conflict(capability_id) do nothing;
  end loop;
  return jsonb_build_object('schema_version','common-substitution-options/1.0','available',jsonb_array_length(raw)>0,
    'reason_code',case when jsonb_array_length(raw)=0 then 'substitution_no_legal_anchor' end,'options',raw);
end
$function$;

