CREATE OR REPLACE FUNCTION public.exam_substitution_source_open_v1(p_prova uuid, p_source_application_id uuid, p_attacker_key text, p_defender_key text, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.esame_prove%rowtype; i combat_spatial.arena_instances%rowtype;
  aa uuid; da uuid; fp text; replay jsonb; sha text; result jsonb;
begin
  if current_user not in ('postgres','service_role') then raise exception using errcode='42501',message='service_role_required'; end if;
  if p_attacker_key not in ('candidate','png') or p_defender_key not in ('candidate','png') or p_attacker_key=p_defender_key
  then raise exception using errcode='23514',message='exam_substitution_actor_route_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('exam-substitution-source:'||p_source_application_id::text,0));
  fp:=combat_spatial.server_fingerprint('exam_substitution_source_open_v1',jsonb_build_object('prova',p_prova,'source',p_source_application_id,'attacker',p_attacker_key,'defender',p_defender_key));
  replay:=combat_spatial.receipt_replay(p_request_key,'exam_substitution_source_open_v1',fp);
  if replay is not null then return replay-'replayed'; end if;
  select * into strict p from public.esame_prove where id=p_prova and stato='aperta' and fase='difesa' for update;
  select * into strict i from combat_spatial.arena_instances where encounter_id=p.id and state='open';
  select actor_id into strict aa from combat_spatial.actor_states where instance_id=i.instance_id and slot_key=case p_attacker_key when 'candidate' then (select candidate_slot_key from combat_spatial.exam_arena_routes_v1 where binding_id=i.binding_id) else (select png_slot_key from combat_spatial.exam_arena_routes_v1 where binding_id=i.binding_id) end;
  select actor_id into strict da from combat_spatial.actor_states where instance_id=i.instance_id and slot_key=case p_defender_key when 'candidate' then (select candidate_slot_key from combat_spatial.exam_arena_routes_v1 where binding_id=i.binding_id) else (select png_slot_key from combat_spatial.exam_arena_routes_v1 where binding_id=i.binding_id) end;
  sha:=encode(extensions.digest(convert_to(jsonb_build_object('prova',p.id,'source',p_source_application_id,'round',p.scambio,'phase',p.fase,'meta',p.meta,'attacker',aa,'defender',da)::text,'UTF8'),'sha256'),'hex');
  insert into combat_spatial.exam_substitution_sources_v1 values(p_source_application_id,p.id,i.instance_id,p_attacker_key,p_defender_key,aa,da,p.scambio,p.fase,p.meta,sha,p_request_key,'open',null,null,clock_timestamp());
  result:=jsonb_build_object('schema_version','exam-substitution-source/1.0','source_application_id',p_source_application_id,'status','open');
  insert into combat_spatial.request_receipts values(p_request_key,'exam_substitution_source_open_v1',fp,result,clock_timestamp());
  return result;
end
$function$;

