-- Native source public.handle_new_user() MD5 f7c1b67845c19e2e07200a5e73e50484

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uname   text    := regexp_replace(btrim(coalesce(new.raw_user_meta_data->>'username', 'shinobi_' || substr(new.id::text,1,8))), '\s+', ' ', 'g');
  v_adult boolean := coalesce((new.raw_user_meta_data->>'is_adult')::boolean, false);
  v_ver   text    := nullif(btrim(coalesce(new.raw_user_meta_data->>'consent_version','')), '');
begin
  if char_length(uname) < 2 or char_length(uname) > 40 then
    raise exception 'username non valido';
  end if;
  if public.name_is_blocked(uname) then raise exception 'username non consentito'; end if;
  insert into public.profiles (id, username, is_adult, adult_confirmed_at, terms_accepted_at, consent_version)
  values (new.id, uname, v_adult,
          case when v_adult then now() else null end,
          case when v_adult then now() else null end,
          coalesce(v_ver, '2026-07'));
  return new;
end; $function$;

