CREATE OR REPLACE FUNCTION public.master_v2_close(p_session uuid, p_mission_outcome text, p_mission_note text, p_close_role boolean, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin perform mission_ai_service_owner.assert_not_ai_service(p_session);return public.master_v2_close_human_ai_core(p_session,p_mission_outcome,p_mission_note,p_close_role,p_expected_control_version,p_request_key);end$function$;

