-- Native source public.master_v2_handover(uuid,uuid,text,bigint,uuid) MD5 bf998babe91645b64414b91e645037c3

CREATE OR REPLACE FUNCTION public.master_v2_handover(p_session uuid, p_new_master uuid, p_reason text, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_m public.master_v2_sessions%rowtype; v_event jsonb; v_event_id uuid; v_cp uuid; v_result jsonb;
begin
  perform public.master_v2_lock_scope(p_session);
  select * into v_m from public.master_v2_sessions where id=p_session for update;
  if v_m.id is null then perform public.combat_v2_fail('sessione_inesistente','Sessione inesistente.',404,p_request_key,'{}'); end if;
  if v_m.master_user<>v_uid then perform public.combat_v2_fail('master_non_proprietario','Solo il Master corrente può consegnare.',403,p_request_key,'{}'); end if;
  if v_m.control_version<>p_expected_control_version then perform public.combat_v2_fail('versione_controllo_obsoleta','Versione controllo obsoleta.',409,p_request_key,'{}'); end if;
  if p_new_master=v_uid or not public.master_v2_is_master(p_new_master) then perform public.combat_v2_fail('nuovo_master_non_valido','Nuovo Master non valido.',422,p_request_key,'{}'); end if;
  v_event:=public.combat_v2_event_begin(p_session,p_request_key,'master_v2_handover',jsonb_build_object('new_master',p_new_master,'reason',p_reason,'expected',p_expected_control_version),p_expected_control_version);
  if (v_event->>'replay')::boolean then return v_event->'result'; end if; v_event_id:=(v_event->>'event_id')::uuid;
  if v_m.stato<>'sospesa' then v_cp:=public.master_v2_make_checkpoint(p_session,'emergenza','Consegna Master: '||p_reason); else select id into v_cp from public.master_v2_mechanical_checkpoints where master_session_id=p_session and active; end if;
  update public.master_v2_sessions set master_user=p_new_master,control_version=control_version+1,stato_pre_sospensione=case when stato='sospesa' then stato_pre_sospensione else stato end,stato='sospesa',suspended_at=coalesce(suspended_at,clock_timestamp()) where id=p_session;
  update public.combat_v2_sessions set state_before_suspend=case when state='sospeso' then state_before_suspend else state end,state='sospeso' where master_session_id=p_session and state not in ('chiuso','annullato');
  update public.combat_v2_actors set controller_user=p_new_master,controller_version=controller_version+1 where session_id in (select id from public.combat_v2_sessions where master_session_id=p_session) and actor_kind='png';
  insert into public.master_v2_transfers(session_id,kind,previous_master,new_master,initiated_by,reason,version_before,version_after,checkpoint_id,request_key)
  values(p_session,'consegna',v_uid,p_new_master,v_uid,btrim(p_reason),p_expected_control_version,p_expected_control_version+1,v_cp,p_request_key);
  v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object('new_master',p_new_master,'control_version',p_expected_control_version+1,'state','sospesa','checkpoint_id',v_cp));
  return public.combat_v2_event_complete(v_event_id,v_result);
end $function$;

