-- Native source public.master_v2_scene_close(uuid,text,bigint,uuid) MD5 3b6a21ef7468900e6093a53b9992eae1

CREATE OR REPLACE FUNCTION public.master_v2_scene_close(p_session uuid, p_reason text, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_m public.master_v2_sessions%rowtype; v_event jsonb; v_event_id uuid; v_result jsonb; v_n int:=0; v_reason text:=btrim(coalesce(p_reason,''));
begin
  if v_uid is null then perform public.combat_v2_fail('autenticazione_richiesta','Autenticazione richiesta.',401,p_request_key,'{}'); end if;
  if exists(select 1 from combat_consumer_private.narrative_authorities where master_session_id=p_session) then return combat_consumer_private.close_from_master(p_session,p_expected_control_version,p_request_key,jsonb_build_object('via','scene_close','reason',p_reason,'expected',p_expected_control_version)); end if;
  perform public.master_v2_lock_scope(p_session);
  select * into v_m from public.master_v2_sessions where id=p_session for update;
  if v_m.id is null then perform public.combat_v2_fail('sessione_inesistente','Sessione inesistente.',404,p_request_key,'{}'); end if;
  if v_m.master_user is distinct from v_uid and not public.combat_v2_is_admin(v_uid) then perform public.combat_v2_fail('master_non_proprietario','Solo il Master corrente o un Admin può chiudere la scena.',403,p_request_key,'{}'); end if;
  if v_m.control_version<>p_expected_control_version then perform public.combat_v2_fail('versione_controllo_obsoleta','Versione controllo obsoleta.',409,p_request_key,'{}'); end if;
  if v_m.stato not in ('preparazione','in_corso','sospesa') then perform public.combat_v2_fail('sessione_non_operativa','La sessione non è chiudibile in questo stato.',409,p_request_key,'{}'); end if;
  if (v_m.tipo='quest' and v_m.mission_id is not null) or exists(select 1 from public.mission_run_state x where x.master_session_id=p_session) then
    perform public.combat_v2_fail('missione_non_finalizzabile','Una missione si chiude con «Chiudi attività» e un esito.',422,p_request_key,'{}'); end if;
  if length(v_reason)<3 then perform public.combat_v2_fail('intento_non_valido','Indica il motivo della chiusura.',422,p_request_key,'{}'); end if;
  v_event:=public.combat_v2_event_begin(p_session,p_request_key,'master_v2_scene_close',jsonb_build_object('reason',v_reason,'expected',p_expected_control_version),p_expected_control_version);
  if (v_event->>'replay')::boolean then return v_event->'result'; end if; v_event_id:=(v_event->>'event_id')::uuid;
  update public.combat_v2_sessions set state='annullato', closed_at=coalesce(closed_at,clock_timestamp()) where master_session_id=p_session and state not in ('chiuso','annullato');
  get diagnostics v_n=row_count;
  update public.master_v2_participants set engagement_state='concluso', left_at=coalesce(left_at,clock_timestamp()) where session_id=p_session and engagement_state<>'concluso';
  update public.master_v2_closure_steps set state='completato', completed_at=clock_timestamp(), result=jsonb_build_object('ok',true,'via','scene_close') where session_id=p_session and state<>'completato';
  update public.master_v2_sessions set stato='annullata', closed_at=clock_timestamp(), close_reason='chiusa_dal_master' where id=p_session;
  v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object('state','annullata','combat_annullati',v_n,'reason',v_reason));
  return public.combat_v2_event_complete(v_event_id,v_result);
end $function$;

