SET LOCAL ROLE "postgres";

REVOKE ALL ON FUNCTION public.master_v2_scene_close(uuid,text,bigint,uuid) FROM PUBLIC,"anon","authenticated","postgres","service_role";

GRANT EXECUTE ON FUNCTION public.master_v2_scene_close(uuid,text,bigint,uuid) TO "postgres";

