-- Native source public.master_v2_session_open(uuid,text,uuid,text,uuid,text) MD5 8c33e3371621782b10ad207246bb7931

CREATE OR REPLACE FUNCTION public.master_v2_session_open(p_location uuid, p_tipo text, p_mission uuid, p_titolo text, p_request_key uuid, p_quest_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_event jsonb; v_event_id uuid; v_id uuid; v_result jsonb;
begin
  if v_uid is null then perform public.combat_v2_fail('autenticazione_richiesta','Autenticazione richiesta.',401,p_request_key,'{}'); end if;
  perform 1 from public.locations l where l.id=p_location order by l.id for update;
  if not public.master_v2_is_master(v_uid) then perform public.combat_v2_fail('master_richiesto','Ruolo Master richiesto.',403,p_request_key,'{}'); end if;
  if not exists(select 1 from public.locations l where l.id=p_location and l.is_active and not l.is_exam_room) then
    perform public.combat_v2_fail('sessione_inesistente','Luogo non valido o riservato all’Esame.',422,p_request_key,'{}');
  end if;
  if lower(coalesce(p_tipo,'')) not in ('duello','quest') then
    perform public.combat_v2_fail('missione_non_collegata','Tipo non valido.',422,p_request_key,'{}');
  end if;
  if p_quest_kind is not null and lower(p_quest_kind) not in ('one_shot','trama') then
    perform public.combat_v2_fail('missione_non_collegata','Tipologia quest non valida.',422,p_request_key,'{}');
  end if;
  if lower(p_tipo)='duello' and (p_mission is not null or p_quest_kind is not null) then
    perform public.combat_v2_fail('missione_non_collegata','Un duello non collega missione o tipologia.',422,p_request_key,'{}');
  end if;
  if lower(p_tipo)='quest' and ((p_mission is not null)=(p_quest_kind is not null)) then
    perform public.combat_v2_fail('missione_non_collegata','Una quest vuole la missione collegata oppure la tipologia, non entrambe.',422,p_request_key,'{}');
  end if;
  if p_mission is not null and not exists(select 1 from public.missions m where m.id=p_mission and m.status in ('aperta','programmata')) then
    perform public.combat_v2_fail('missione_non_collegata','Missione non collegabile.',409,p_request_key,'{}');
  end if;
  if lower(p_tipo)='duello' and exists(select 1 from combat_consumer_private.activities where location_id=p_location and phase<>'closed') then return combat_consumer_private.attach_master(p_location,p_titolo,p_request_key); end if;
  v_event:=public.combat_v2_event_begin(p_location,p_request_key,'master_v2_session_open',jsonb_build_object('location',p_location,'tipo',p_tipo,'mission',p_mission,'titolo',p_titolo,'quest_kind',p_quest_kind));
  if (v_event->>'replay')::boolean then return v_event->'result'; end if;
  v_event_id:=(v_event->>'event_id')::uuid;
  if exists(select 1 from public.master_v2_sessions where location_id=p_location and stato not in ('chiusa','annullata'))
     or exists(select 1 from public.combat_sessions where location_id=p_location and state='aperto')
     or exists(select 1 from public.combat_v2_sessions where location_id=p_location and state not in ('chiuso','annullato')) then
    perform public.combat_v2_fail('scontro_gia_aperto_nel_luogo','Esiste già un’attività meccanica nel luogo.',409,p_request_key,'{}');
  end if;
  insert into public.master_v2_sessions(location_id,tipo,master_user,mission_id,titolo,quest_kind)
  values(p_location,lower(p_tipo),v_uid,p_mission,btrim(p_titolo),case when lower(p_tipo)='quest' and p_mission is null then lower(p_quest_kind) end) returning id into v_id;
  if lower(p_tipo)='quest' and p_mission is not null and mission_internal.runtime_enabled() then
    insert into public.master_v2_closure_steps(session_id,position,step_name,request_key)
    values (v_id,1,'encounter_resolved',p_request_key),(v_id,2,'final_report_published',p_request_key),
           (v_id,3,'mission_run_terminalized',p_request_key),(v_id,4,'mission_finalized',p_request_key),
           (v_id,5,'role_segment_finalized',p_request_key),(v_id,6,'master_session_closed',p_request_key);
    perform mission_internal.bind_auto(v_id,p_request_key);
  else
    insert into public.master_v2_closure_steps(session_id,position,step_name,request_key)
    values (v_id,1,'encounter_resolved',p_request_key),(v_id,2,'final_report_published',p_request_key),
           (v_id,3,'mission_finalized',p_request_key),(v_id,4,'role_segment_finalized',p_request_key),
           (v_id,5,'master_session_closed',p_request_key);
  end if;
  v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object('master_session_id',v_id,'control_version',1,'state','preparazione'));
  return public.combat_v2_event_complete(v_event_id,v_result);
end $function$;

