-- Native source public.missione_esito(uuid,boolean,text) MD5 e7e016791a9b24a3962ca6d7e697b699

CREATE OR REPLACE FUNCTION public.missione_esito(p_mission uuid, p_successo boolean, p_nota text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m public.missions%rowtype; r record; v_bal int;
begin
  if not public.is_staff() then raise exception 'solo lo staff conferma gli esiti'; end if;
  select * into m from public.missions where id = p_mission for update;
  if m.id is null then raise exception 'Missione inesistente'; end if;
  if m.status not in ('aperta','programmata') then raise exception 'Missione già conclusa'; end if;
  for r in select b.character_id from public.mission_bookings b where b.mission_id=p_mission and b.status='iscritto' loop
    if p_successo then
      perform public._assegna_xp(r.character_id, m.xp_reward, 'missione '||m.grado||': '||m.title);
      perform set_config('app.allow_money_delta','1', true);
      update public.characters set money = coalesce(money,0) + m.ryo_reward
        where id = r.character_id returning money into v_bal;
      insert into public.transactions(character_id, kind, quantity, ryo_delta, balance_after, note)
        values (r.character_id, 'missione', 1, m.ryo_reward, v_bal, 'Missione '||m.grado||' — '||m.title);
    end if;
    update public.mission_bookings set status = case when p_successo then 'completata' else 'fallita' end
      where mission_id = p_mission and character_id = r.character_id;
  end loop;
  update public.missions
     set status = case when p_successo then 'completata' else 'fallita' end,
         esito_nota = nullif(btrim(coalesce(p_nota,'')),''),
         master_id = coalesce(master_id, auth.uid())
   where id = p_mission;
end; $function$;

