-- Native source public.my_defenses(uuid) MD5 a057b38e0aafbf50f2b0ce719e63ba57

CREATE OR REPLACE FUNCTION public.my_defenses(p_location uuid DEFAULT NULL::uuid)
 RETURNS TABLE(technique_id uuid, name text, fonte text, gittata text, disciplina text, chakra_cost integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_libero boolean;
begin
  if p_location is null then
    v_libero := public._in_test_room();
  else
    v_libero := public._puo_test_room()
            and exists (select 1 from public.locations l where l.id=p_location and coalesce(l.is_test,false));
  end if;
  return query
    select t.id,t.name,'clan'::text,t.gittata,t.disciplina,coalesce(t.chakra_cost,0)
      from public.character_abilities ca
      join public.characters c on c.id=ca.character_id
      join public.clan_techniques t on t.id=ca.technique_id
     where c.user_id=auth.uid() and ca.state='attiva' and t.is_active and t.difensiva
       and t.uso in ('difesa','principale') and not coalesce(t.di_scena,false)
    union all
    select j.id,j.name_it,'jutsu'::text,j.gittata,j.category,coalesce(j.chakra_cost,0)
      from public.character_jutsu cj join public.jutsu j on j.id=cj.jutsu_id
     where cj.user_id=auth.uid() and j.is_active and j.difensiva
       and j.uso in ('difesa','principale') and not coalesce(j.di_scena,false)
       and j.name_it <> 'Dispersione'
    union all
    select t.id,t.name,'clan'::text,t.gittata,t.disciplina,coalesce(t.chakra_cost,0)
      from public.clan_techniques t
     where v_libero and t.is_active and t.difensiva
       and t.uso in ('difesa','principale') and not coalesce(t.di_scena,false)
       and not exists (select 1 from public.character_abilities ca2
                       join public.characters c2 on c2.id=ca2.character_id
                       where c2.user_id=auth.uid() and ca2.technique_id=t.id)
    union all
    select j.id,j.name_it,'jutsu'::text,j.gittata,j.category,coalesce(j.chakra_cost,0)
      from public.jutsu j
     where v_libero and j.is_active and j.difensiva
       and j.uso in ('difesa','principale') and not coalesce(j.di_scena,false)
       and j.name_it <> 'Dispersione'
       and not exists (select 1 from public.character_jutsu cj2
                       where cj2.user_id=auth.uid() and cj2.jutsu_id=j.id)
    order by 2;
end $function$;

