-- Native source public.profiles_guard() MD5 618b661364ee483f074246ce2c3a1980

CREATE OR REPLACE FUNCTION public.profiles_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or public.is_staff() then
    return new;
  end if;
  new.id := old.id;
  new.role := old.role;
  new.is_adult := old.is_adult;
  new.adult_confirmed_at := old.adult_confirmed_at;
  new.terms_accepted_at := old.terms_accepted_at;
  new.consent_version := old.consent_version;
  new.created_at := old.created_at;
  return new;
end; $function$;

