-- Native source clan_sabaku_private.clone_movement_interruption(uuid) MD5 4cf9e5f0797fd362c4e339ecb7815808

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_movement_interruption(p_capability uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT jsonb_build_object('event_id',settled.event_id,'distance_m',cost.distance_m,
   'reason','immobilized','main_action_available',true)
 FROM combat_panel_private.movement_cost_receipts cost
 JOIN combat_spatial.spatial_events settled ON settled.event_id=cost.event_id AND settled.event_kind='movement_settled'
 WHERE cost.capability_id=p_capability AND EXISTS(
   SELECT 1 FROM clan_sabaku_private.clone_captures receipt
   JOIN combat_spatial.spatial_events contact ON contact.event_id=receipt.trigger_event_id
   WHERE receipt.trigger_kind='movement' AND NOT receipt.copy_hit AND receipt.result->'success'='true'::jsonb
     AND contact.event_kind='sabaku_clone_contact' AND contact.instance_id=settled.instance_id
     AND contact.actor_id=settled.actor_id AND contact.before_state->>'capability_id'=p_capability::text
     AND contact.before_state->>'movement_root'=settled.root_id::text);
$function$;

