-- Native source clan_sabaku_private.narrative_pending(uuid) MD5 5c6789ab411bcc7d775f60c3f0ed81ff

CREATE OR REPLACE FUNCTION clan_sabaku_private.narrative_pending(p_session uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT EXISTS (
SELECT 1 FROM combat_consumer_private.narrative_claims pending
     WHERE pending.session_id=p_session AND pending.state='claimed'
       AND NOT EXISTS (
         SELECT 1 FROM combat_consumer_private.recovery_claims_v1 recovered
         JOIN combat_consumer_private.recovery_attempts_v1 attempt
           ON attempt.claim_id=recovered.id AND attempt.request_key=recovered.request_key
           AND attempt.round_id=recovered.round_id AND attempt.session_id=recovered.session_id
         JOIN public.combat_v2_round_reports report
           ON report.id=recovered.report_id AND report.round_id=recovered.round_id
           AND report.mechanics_sha256=recovered.report_sha256 AND report.narration_state='pubblicata'
         JOIN public.combat_v2_narratives fato
           ON fato.round_id=recovered.round_id AND fato.report_id=recovered.report_id
           AND fato.request_key=recovered.request_key
           AND fato.id::text=recovered.completion_result#>>'{data,narrative_id}'
         WHERE recovered.parent_claim_id=pending.id AND recovered.session_id=pending.session_id
           AND recovered.round_id=pending.round_id AND recovered.report_id=pending.report_id
           AND recovered.report_sha256=pending.report_sha256
           AND recovered.state='completed' AND attempt.state='published'
           AND recovered.completion_result->>'ok'='true'
           AND attempt.completion=recovered.completion_result)
 );
$function$;

