CREATE OR REPLACE FUNCTION combat_panel_private.master_entry_policy(p_location uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT CASE WHEN l.is_test THEN 'staff_test_no_persistent_resources_v1' ELSE 'master_game_resources_v1' END
 FROM public.locations l CROSS JOIN combat_panel_private.release_gate g
 WHERE l.id=p_location AND l.is_active AND NOT l.is_exam_room AND g.singleton
   AND CASE WHEN l.is_test THEN g.staff_enabled ELSE g.master_enabled END
   AND EXISTS(SELECT 1 FROM combat_panel_private.master_scene_profiles p
     JOIN combat_spatial.arena_templates t ON t.template_key=p.template_key AND t.template_version=p.template_version
     WHERE p.location_id=l.id AND p.enabled AND t.status='ready' AND p.geometry_fingerprint=t.geometry_hash
       AND p.policy_id=CASE WHEN l.is_test THEN 'staff_test_no_persistent_resources_v1' ELSE 'master_game_resources_v1' END)
$function$;

