 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT CASE WHEN p_view IS NULL THEN p_roster ELSE (
   SELECT coalesce(jsonb_agg(CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(p_view->'formations') f
     WHERE f->'original_index'='null'::jsonb AND f->>'actor_id'=a->>'actor_id')
     THEN jsonb_set(a,'{distance_from_viewer_m}','null'::jsonb) ELSE a END ORDER BY ordinal),'[]'::jsonb)
   FROM jsonb_array_elements(p_roster) WITH ORDINALITY actors(a,ordinal)) END
$function$;

