-- Native source combat_panel_private.multiplication_result_label(jsonb) MD5 c2345109dec7d5b44b0044f78fcf6172

CREATE OR REPLACE FUNCTION combat_panel_private.multiplication_result_label(p_outcome jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 SELECT
   CASE WHEN p_outcome#>'{multiplication_effect,copy_intercepted}'='true'::jsonb
     THEN ' · colpita una copia; originale illeso' ELSE '' END
   ||CASE WHEN p_outcome#>'{multiplication_effect,defense_spent_on_copy}'='true'::jsonb
     THEN CASE WHEN p_outcome#>>'{multiplication_effect,declared_reaction}'='sostituzione'
       THEN ' · Sostituzione spesa su una copia dell’Assalto; nessuna seconda difesa'
       ELSE ' · reazione spesa su una copia dell’Assalto; nessuna seconda difesa' END
     WHEN p_outcome->>'canonical_outcome'='reazione_spesa_su_copia'
       THEN ' · reazione spesa su una copia dell’Assalto; nessuna seconda difesa'
     WHEN p_outcome->>'canonical_outcome'='negato_sostituzione'
       THEN ' · colpo negato dalla Sostituzione' ELSE '' END
$function$;

