-- Native source mission_internal.plan_snapshot(uuid) MD5 e540507c71962da4fecbc68f26346a69

CREATE OR REPLACE FUNCTION mission_internal.plan_snapshot(p_plan_version uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'schema_version', 'mission-plan-snapshot/1.0',
    'plan_id', p.id::text,
    'plan_version_id', v.id::text,
    'plan_version', v.versione,
    'mission_id', p.mission_id::text,
    'initial_step', v.initial_step_key,
    'steps', coalesce((
      select jsonb_agg(jsonb_build_object(
        'plan_id', p.id::text,
        'plan_version_id', v.id::text,
        'key', s.step_key,
        'kind', s.kind,
        'public_objective', s.public_objective
      ) order by s.ordinal)
      from public.mission_plan_steps s where s.plan_version_id = v.id
    ), '[]'::jsonb),
    'transitions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'plan_id', p.id::text,
        'plan_version_id', v.id::text,
        'key', t.transition_key,
        'from', t.from_step_key,
        'to', t.to_step_key,
        'event', t.event_kind,
        'priority', t.priority,
        'requirements', coalesce((
          select jsonb_agg(jsonb_build_object(
            'ordinal', r.ordinal,
            'step_kind', r.step_kind,
            'provider_owner', r.provider_owner,
            'domain', r.domain,
            'source_kind', r.source_kind,
            'capability_key', r.capability_key,
            'feature_version', r.feature_version,
            'provider_contract_version', r.provider_contract_version,
            'projection_version', r.projection_version,
            'fact_code', r.fact_code,
            'max_age_ms', r.max_age_ms
          ) order by r.ordinal)
          from public.mission_plan_requirements r
          where r.plan_version_id = t.plan_version_id
            and r.transition_key = t.transition_key
        ), '[]'::jsonb)
      ) order by t.from_step_key, t.event_kind, t.priority, t.transition_key)
      from public.mission_plan_transitions t where t.plan_version_id = v.id
    ), '[]'::jsonb)
  )
  from public.mission_plan_versions v
  join public.mission_plans p on p.id = v.plan_id
  where v.id = p_plan_version
$function$;

