    -- spazi che non sono lo spazio: insecabile, cifra, stretto insecabile, sottile
    || chr(160) || chr(8199) || chr(8239) || chr(8201)
    -- trattini tipografici: en dash, em dash, meno matematico, figure dash, barra, hyphen
    || '–—−‒―‐'
    -- più e cifre a larghezza piena
    || '＋０１２３４５６７８９',
    '[][][][]' || '    ' || '------' || '+0123456789');
$function$;

