-- Native source public._esame_muove(integer,integer,integer,boolean) MD5 d7ad9290898efa6fd09172243d739c90

CREATE OR REPLACE FUNCTION public._esame_muove(p_pos integer, p_pos_altro integer, p_metri integer, p_avvicina boolean)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  with g as (
    select coalesce(p_pos,0) as pos, coalesce(p_pos_altro,0) as altro,
           case
             when coalesce(p_metri, 0) <= 0 then coalesce(p_pos, 0)
             when coalesce(p_avvicina, true) then
               -- 1 · ci si ferma ADDOSSO, non oltre
               case when coalesce(p_pos,0) <= coalesce(p_pos_altro,0)
                    then least(coalesce(p_pos_altro,0),    coalesce(p_pos,0) + p_metri)
                    else greatest(coalesce(p_pos_altro,0), coalesce(p_pos,0) - p_metri)
               end
             else
               -- 2 · si cede terreno, e il solo limite è il campo
               case when coalesce(p_pos,0) <= coalesce(p_pos_altro,0)
                    then coalesce(p_pos,0) - p_metri
                    else coalesce(p_pos,0) + p_metri
               end
           end as grezza
  )
  -- 3 · il campo: la separazione non supera mai i 60 metri della fascia «lunga».
  --     L'avvicinamento non ci arriva mai (si ferma a 0), quindi in pratica
  --     morde solo sulla ritirata — ma è scritto per entrambi, perché una
  --     guardia che vale «solo dove serve» è una guardia che smette di valere
  --     il giorno in cui serve altrove.
  select case
           when abs(g.grezza - g.altro) > 60
             then g.altro + sign(g.grezza - g.altro)::int * 60
           else g.grezza
         end
    from g;
$function$;

