-- Native source public._narrative_exam_utterances(text) MD5 0ec49a2993c84a99b0b316fcb6c4f5be

CREATE OR REPLACE FUNCTION public._narrative_exam_utterances(p_text text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  with found as (
    select ordinal,
           btrim(coalesce(parts[1],parts[2])) as utterance
      from regexp_matches(
        left(coalesce(p_text,''),5000),
        '«([^»\n]+)»|"([^"\n]+)"',
        'g'
      ) with ordinality as hit(parts,ordinal)
     where length(btrim(coalesce(parts[1],parts[2]))) between 1 and 1200
     limit 4
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id','utterance.' || ordinal,
        'text',utterance,
        'sha256',encode(extensions.digest(utterance,'sha256'),'hex')
      ) order by ordinal
    ) filter (where utterance <> ''),
    '[]'::jsonb
  )
  from found
$function$;

