 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(
    select 1 from public.blocked_terms b
    where (b.match = 'contains' and position(b.term in lower(p_name)) > 0)
       or (b.match = 'exact'    and lower(p_name) = b.term)
  );
$function$;

