-- Native source clan_sabaku_private.clone_nearby_candidates(uuid,uuid) MD5 96ff4901f57f304e93a9a5dcd79c31c5

CREATE OR REPLACE FUNCTION clan_sabaku_private.clone_nearby_candidates(p_clone uuid, p_actor uuid DEFAULT NULL::uuid)
 RETURNS TABLE(actor_id uuid, formation_id uuid, figure_index integer, distance_m numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT a.id,f.id,(figure.value->>'figure_index')::integer,
   combat_spatial.distance_m(c.x_m,c.y_m,(figure.value->>'x_m')::numeric,(figure.value->>'y_m')::numeric)
 FROM clan_sabaku_private.clones c
 JOIN public.combat_v2_actors owner_actor ON owner_actor.id=c.actor_id
 JOIN public.combat_v2_actors a ON a.session_id=c.session_id AND a.id<>c.actor_id AND a.team_key<>owner_actor.team_key
 JOIN combat_spatial.actor_states b ON b.instance_id=c.instance_id AND b.actor_id=a.id AND b.state='active'
 LEFT JOIN combat_panel_private.multiplication_formations f ON f.actor_id=a.id AND f.instance_id=c.instance_id AND f.state='active'
 CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN f.id IS NOT NULL THEN f.figures
   ELSE jsonb_build_array(jsonb_build_object('figure_index',NULL,'x_m',b.x_m,'y_m',b.y_m)) END) figure(value)
 WHERE c.id=p_clone AND c.state='armed' AND a.actor_kind='pg' AND a.companion_id IS NULL AND a.state='attivo'
   AND coalesce((a.mechanics_snapshot->>'vita')::numeric,0)>0 AND (p_actor IS NULL OR a.id=p_actor)
   AND combat_spatial.distance_m(c.x_m,c.y_m,(figure.value->>'x_m')::numeric,(figure.value->>'y_m')::numeric)<=2
 -- La scelta usa soltanto distanze e identità stabili; non consulta original_index.
 ORDER BY 4,1,3 NULLS FIRST;
$function$;

