CREATE OR REPLACE FUNCTION combat_consumer_private.melee_eligible(p_session uuid, p_actor uuid, p_target uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists(select 1 from combat_spatial.arena_instances i
    join combat_spatial.actor_states a on a.instance_id=i.instance_id and a.actor_id=p_actor and a.state='active'
    join combat_spatial.actor_states b on b.instance_id=i.instance_id and b.actor_id=p_target and b.state='active'
    where i.encounter_id=p_session and i.context_source='ordinary' and i.state='open'
      and a.actor_id<>b.actor_id and combat_spatial.distance_m(a.x_m,a.y_m,b.x_m,b.y_m)<=2
      and combat_spatial.path_first_block_t(i.instance_id,a.actor_id,a.x_m,a.y_m,b.x_m,b.y_m,b.actor_id)>=1)
$function$;

