CREATE OR REPLACE FUNCTION combat_panel_private.master_spatial_facts(p_master uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT jsonb_build_object('schema_version','combat-panel-spatial-checkpoint/1','arenas',coalesce(jsonb_agg(
   jsonb_build_object('instance_id',i.instance_id,'encounter_id',i.encounter_id,'state',i.state,'map_version',i.map_version,
     'template_key',i.template_key,'template_version',i.template_version,
     'geometry',combat_spatial.geometry_fingerprint(i.template_key,i.template_version),
     'actors',(SELECT coalesce(jsonb_agg(jsonb_build_object('actor_id',a.actor_id,'x_m',a.x_m,'y_m',a.y_m,
       'radius_m',a.footprint_radius_m,'state',a.state,'mobility',ca.mechanics_snapshot->'mobility') ORDER BY a.actor_id),'[]'::jsonb)
       FROM combat_spatial.actor_states a JOIN public.combat_v2_actors ca ON ca.id=a.actor_id
       WHERE a.instance_id=i.instance_id),
     'objects',(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.object_key),'[]'::jsonb)
       FROM combat_spatial.object_states o WHERE o.instance_id=i.instance_id),
     'movement_plans',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.request_key),'[]'::jsonb)
       FROM combat_panel_private.master_movement_plans p WHERE p.instance_id=i.instance_id),
     'movement_receipts',(SELECT coalesce(jsonb_agg(to_jsonb(mr) ORDER BY mr.declaration_id),'[]'::jsonb)
       FROM combat_panel_private.master_movement_receipts mr JOIN public.combat_v2_rounds r ON r.id=mr.round_id
       WHERE r.session_id=i.encounter_id),
     'companion_movement_receipts',(SELECT coalesce(jsonb_agg(to_jsonb(mr) ORDER BY mr.request_key),'[]'::jsonb)
       FROM clan_marionettisti_private.movement_receipts mr JOIN public.combat_v2_rounds r ON r.id=mr.round_id
       WHERE r.session_id=i.encounter_id),
     'coverage_geometry',(SELECT coalesce(jsonb_agg(to_jsonb(cg) ORDER BY cg.coverage_id),'[]'::jsonb)
       FROM combat_panel_private.coverage_geometry cg WHERE cg.instance_id=i.instance_id)) ORDER BY i.instance_id),'[]'::jsonb))
 FROM combat_spatial.arena_instances i WHERE i.master_session_id=p_master AND i.context_source='panel_master'
$function$;

