-- Native source public._diversivo_posizione(integer,integer,text,integer,integer,integer) MD5 982caa705bb62c49849b6b3a20e0a92d

CREATE OR REPLACE FUNCTION public._diversivo_posizione(p_pos integer, p_pos_altro integer, p_direzione text, p_passo integer, p_portata integer, p_nominale integer DEFAULT 5)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  with s as (
    select abs(coalesce(p_pos,0) - coalesce(p_pos_altro,0))          as dist,
           coalesce(p_portata,2) + greatest(0, coalesce(p_passo,0))  as tetto,
           greatest(0, coalesce(p_nominale,5))                       as nominale,
           lower(btrim(coalesce(p_direzione,'diversivo')))           as dir
  )
  select case s.dir
    when 'avvicinamento' then
      public._esame_muove(p_pos, p_pos_altro, s.nominale, true)
    when 'ritirata' then
      case
        -- regola 3: chi è già oltre il tetto resta dov'è
        when s.dist >= s.tetto then coalesce(p_pos,0)
        -- regola 2: i metri sono quelli che mancano al tetto, mai più del nominale
        else public._esame_muove(p_pos, p_pos_altro,
                                 least(s.nominale, s.tetto - s.dist), false)
      end
    -- `diversivo` e `confusione`: si resta dov'è. Sono due etichette diverse
    -- perché la scena è diversa, non perché il numero lo sia.
    else coalesce(p_pos,0)
  end
  from s;
$function$;

