-- Native source public._role_contributi(uuid,timestamp with time zone) MD5 0204494328267262f772852718011a06

CREATE OR REPLACE FUNCTION public._role_contributi(p_session uuid, p_fino timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(character_id uuid, n integer, primo timestamp with time zone, ultimo timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with s as (
    select location_id, record_from, coalesce(p_fino, closed_at, now()) as fine
      from public.role_sessions where id = p_session
  ), u as (
    select m.character_id as cid, m.created_at as ca
      from public.messages m, s
     where m.location_id = s.location_id
       and m.created_at >= s.record_from and m.created_at <= s.fine
       and public._role_msg_valido(m.kind, m.character_id, m.recipient_user)
    union all
    select a.character_id, a.created_at
      from public.messages_archive a, s
     where a.location_id = s.location_id
       and a.created_at >= s.record_from and a.created_at <= s.fine
       and public._role_msg_valido(a.kind, a.character_id, a.recipient_user)
  )
  select u.cid, count(*)::int, min(u.ca), max(u.ca) from u group by u.cid;
$function$;

