-- Native source public.character_elementi(uuid) MD5 1c79fc3cf152125d23937b68062b940a

CREATE OR REPLACE FUNCTION public.character_elementi(p_character uuid)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when exists (select 1 from public.character_perks p
                  where p.character_id = p_character and p.tipo = 'cinque_nature')
      then array['Fuoco','Vento','Fulmine','Terra','Acqua']::text[]
    else (
      select coalesce(array_agg(e order by ord), '{}'::text[])
        from (
          select distinct e,
                 case e when 'Fuoco' then 1 when 'Vento' then 2 when 'Fulmine' then 3
                        when 'Terra' then 4 when 'Acqua' then 5 else 9 end as ord
            from (
              select c.element as e from public.characters c where c.id = p_character
              union all
              select c.element2 from public.characters c where c.id = p_character
              union all
              select unnest(cl.elementi_innati)
                from public.characters c
                join public.clans cl on cl.name = c.clan
               where c.id = p_character
                 and public._grade_rank(coalesce(c.rank,'Deshi')) >= 1
              union all
              -- righe storiche: il vecchio premio «seconda natura», se ne esiste ancora
              select btrim(t)
                from public.character_perks p,
                     unnest(regexp_split_to_array(coalesce(p.dettaglio,''), '[,;·+/]| e ')) as t
               where p.character_id = p_character and p.tipo = 'seconda_natura'
            ) u
           where e in ('Fuoco','Vento','Fulmine','Terra','Acqua')
        ) s
    ) end;
$function$;

