CREATE OR REPLACE FUNCTION combat_consumer_private.recovery_current_guard(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT coalesce((SELECT approval.is_active AND approval.valid_until>statement_timestamp()
   AND approval.no_send_attested AND approval.no_worker_attested
   AND approval.parent_sha256=public.combat_v2_sha256(to_jsonb(parent))
   AND l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND l.is_test
   AND ctx.policy_id='staff_test_no_persistent_resources_v1'
   AND ctx.phase='resolved' AND ctx.exchange_id=c.round_id AND ctx.context_version=c.context_version
   AND authority.mode='ai_auto' AND authority.control_version=c.control_version
   AND report.mechanics_sha256=c.report_sha256 AND report.narration_state='attesa'
   AND combat_consumer_private.narrative_allowed(ctx.session_id)
 FROM combat_consumer_private.recovery_claims_v1 c
 JOIN combat_consumer_private.recovery_approvals_v1 approval ON approval.parent_claim_id=c.parent_claim_id
 JOIN combat_consumer_private.narrative_claims parent ON parent.id=c.parent_claim_id
 JOIN combat_consumer_private.activities ctx ON ctx.session_id=c.session_id
 JOIN combat_consumer_private.narrative_authorities authority ON authority.session_id=c.session_id
 JOIN public.combat_v2_round_reports report ON report.id=c.report_id AND report.round_id=c.round_id
 JOIN public.locations l ON l.id=ctx.location_id WHERE c.id=p_id),false)
$function$;

