CREATE OR REPLACE FUNCTION combat_panel_private.location_adapter(p_location uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT CASE WHEN EXISTS(SELECT 1 FROM public.master_v2_sessions m
   WHERE m.location_id=p_location AND m.stato NOT IN ('chiusa','annullata')
     AND NOT EXISTS(SELECT 1 FROM combat_consumer_private.activities c
       JOIN combat_consumer_private.narrative_authorities authority ON authority.session_id=c.session_id
         AND authority.master_session_id=m.id
       WHERE c.location_id=p_location AND c.phase<>'closed')) THEN 'master_v2'
 WHEN EXISTS(SELECT 1 FROM combat_consumer_private.activities
   WHERE location_id=p_location AND phase<>'closed') THEN 'ordinary_v2'
 WHEN combat_panel_private.master_open_available(p_location) AND (
   combat_panel_private.access_reason(p_location,'ordinary_v2') IS NOT NULL
   OR (combat_consumer_private.opening_state(p_location)->>'status') IS DISTINCT FROM 'ready')
 THEN 'master_v2' ELSE 'ordinary_v2' END
$function$;

