-- Native source combat_panel_private.narrative_details(uuid,uuid,uuid) MD5 b67de1ddb6baa4266b3cd37ec80faacd

CREATE OR REPLACE FUNCTION combat_panel_private.narrative_details(p_location uuid, p_session uuid, p_round uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT jsonb_build_object('report_id',current_report.id,'report_sha256',current_report.mechanics_sha256,
   'last_published',(SELECT jsonb_build_object('report_id',q.id,'round_id',r.id,'message_id',msg.id,'text',msg.body)
     FROM public.combat_v2_round_reports q JOIN public.combat_v2_rounds r ON r.id=q.round_id AND r.session_id=p_session
     JOIN public.messages msg ON msg.id=q.message_id AND msg.location_id=p_location
     WHERE auth.uid() IS NOT NULL AND q.narration_state='pubblicata'
       AND (msg.kind<>'whisper' OR msg.sender_user=auth.uid() OR msg.recipient_user=auth.uid() OR public.is_staff())
       AND (msg.kind<>'motore' OR public.is_staff())
     ORDER BY q.narrated_at DESC NULLS LAST,q.created_at DESC,q.id LIMIT 1))
 FROM (SELECT 1) AS seed LEFT JOIN LATERAL (
   SELECT q.id,q.mechanics_sha256 FROM public.combat_v2_round_reports q
     JOIN public.combat_v2_rounds r ON r.id=q.round_id AND r.session_id=p_session
     JOIN public.combat_v2_sessions s ON s.id=r.session_id AND s.location_id=p_location
   WHERE q.round_id=p_round AND auth.uid() IS NOT NULL
 ) current_report ON true
$function$;

