-- Native source combat_v2_elemental_internal.eligible_v1(uuid,uuid,boolean) MD5 3f14cb6692a80399de4087f3941d6d8e

CREATE OR REPLACE FUNCTION combat_v2_elemental_internal.eligible_v1(p_character uuid, p_technique uuid, p_defense boolean DEFAULT NULL::boolean)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select coalesce(exists(
   select 1
   from public.characters c
   join public.character_abilities ca on ca.character_id=c.id and ca.technique_id=p_technique and ca.state='attiva'
   join public.clan_techniques t on t.id=ca.technique_id
   where c.id=p_character
     and combat_v2_elemental_internal.is_target_v1(t.id)
     and t.is_active and t.macro='generica'
     and public._grade_rank(coalesce(c.rank,'Deshi'))>=public._grade_rank(coalesce(t.req_grade,'Genin'))
     and cardinality(t.req_elements)>0 and t.req_elements_mode in ('uno','tutti')
     and case t.req_elements_mode
       when 'uno' then t.req_elements && public.character_elementi(c.id)
       when 'tutti' then t.req_elements <@ public.character_elementi(c.id)
       else false end
     and not coalesce(t.colpisce_formazione,false)
     and not coalesce(t.rivela_originale,false)
     and (
       (not coalesce(t.difensiva,false) and t.uso='principale' and t.bersaglio='Nemico singolo' and t.gittata in ('contatto','corta','media','lunga'))
       or
       (coalesce(t.difensiva,false) and t.uso='difesa' and t.bersaglio='Sé stesso' and t.gittata='contatto')
     )
     and (p_defense is null or p_defense=coalesce(t.difensiva,false))
 ),false);
$function$;

