CREATE OR REPLACE FUNCTION combat_consumer_private.recovery_public_state_v1(p_round uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT jsonb_build_object('state',CASE
    WHEN a.state='published' THEN 'published'
    WHEN a.state='failed' THEN 'failed'
    WHEN NOT combat_consumer_private.recovery_current_guard(c.id) THEN 'failed'
    WHEN a.redelivery_state='failed' OR (a.state IN('claimed','generated') AND a.redelivery_at<statement_timestamp()-interval '55 seconds') THEN 'failed'
    WHEN a.state='generated' THEN 'waiting'
    WHEN c.expires_at<=statement_timestamp() THEN 'expired'
    WHEN a.state='claimed' THEN 'waiting' ELSE 'running' END,
   'reason_code',CASE WHEN a.state NOT IN('published','failed') AND NOT combat_consumer_private.recovery_current_guard(c.id) THEN 'context_changed' WHEN a.redelivery_state='failed' THEN 'narration_unavailable'
     WHEN a.state='failed' THEN coalesce(c.failure_code,'narration_unavailable')
     WHEN a.state IN('claimed','provider_reserved') AND c.expires_at<=statement_timestamp() THEN 'timeout'
     ELSE null END)
 FROM combat_consumer_private.recovery_attempts_v1 a JOIN combat_consumer_private.recovery_claims_v1 c ON c.id=a.claim_id
 WHERE a.round_id=p_round
$function$;

