-- Native source public._in_test_room() MD5 bd05748fc4827c2976a5de072cb1e8a7

CREATE OR REPLACE FUNCTION public._in_test_room()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public._puo_test_room() and exists (
    select 1 from public.presence pr
    join public.locations l on l.id = pr.location_id
    where pr.user_id = auth.uid() and coalesce(l.is_test,false)
  );
$function$;

