DO $seed$ DECLARE scene_sha text; BEGIN
 INSERT INTO combat_spatial.arena_templates
 (template_key,template_version,contract_version,width_m,height_m,actor_radius_m,
  geometry_contract_id,geometry_contract_version,geometry_hash,required_shape_keys,status,source_asset_sha256)
 VALUES('ordinary_neutral_v1',1,'ordinary-neutral/1',20,20,0.5,
   'ordinary-neutral-geometry',1,'pending',ARRAY['LOG-A','LOG-B'],'ready',
   encode(extensions.digest(convert_to('ordinary_neutral_v1/1;20x20;radius0.5;PG-A7.5,10;PG-B12.5,10;LOG-A7.5,12;LOG-B12.5,8;logradius0.25;portable_single_use','UTF8'),'sha256'),'hex'));
 INSERT INTO combat_spatial.arena_slots VALUES
 ('ordinary_neutral_v1',1,'PG-A','PG',7.5,10),('ordinary_neutral_v1',1,'PG-B','PG',12.5,10);
 INSERT INTO combat_spatial.arena_objects
 (template_key,template_version,object_key,object_kind,semantic_label,shape_kind,shape,shape_hash,
  blocks_movement,substitutable,lifecycle,geometry_version)
 SELECT 'ordinary_neutral_v1',1,key,'substitution_anchor',label,'circle',shape,
   encode(extensions.digest(convert_to(shape::text,'UTF8'),'sha256'),'hex'),true,true,'portable_single_use',1
 FROM (VALUES('LOG-A','Tronchetto A','{"cx":7.5,"cy":12,"radius":0.25}'::jsonb),
   ('LOG-B','Tronchetto B','{"cx":12.5,"cy":8,"radius":0.25}'::jsonb)) v(key,label,shape);
 UPDATE combat_spatial.arena_templates SET geometry_hash=combat_spatial.geometry_fingerprint(template_key,template_version)
 WHERE template_key='ordinary_neutral_v1' AND template_version=1;
 IF combat_spatial.template_errors('ordinary_neutral_v1',1) IS DISTINCT FROM '[]'::jsonb
 THEN RAISE EXCEPTION 'neutral_template_invalid'; END IF;
 scene_sha:=combat_consumer_private.scene_fingerprint('ordinary_neutral_v1',1);
 IF scene_sha IS DISTINCT FROM '1aea167b5dd4a97eae12cac1f0dd6efb9c0f040d6862c35c755a0d729bb01c26'
   OR (SELECT geometry_hash FROM combat_spatial.arena_templates WHERE template_key='ordinary_neutral_v1' AND template_version=1)
     IS DISTINCT FROM '1920b919137f4f58de6d71af2811061a'
 THEN RAISE EXCEPTION 'neutral_geometry_pin_drift'; END IF;

