-- Pending invitation is synthetic fixture input. Acceptance, session, actors, snapshot,
-- round, initiative, membership, scene claim and arena bodies are native product outputs.
INSERT INTO combat_consumer_private.invitations(id,location_id,scene_profile_id,opener_character_id,recipient_character_id,open_request_key,geometry_sha256,scene_version)
SELECT '50000000-0000-4000-8000-000000000001',location_id,id,
 '20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002',
 '60000000-0000-4000-8000-000000000001',geometry_sha256,producer_version
FROM combat_consumer_private.scene_profiles WHERE id='40000000-0000-4000-8000-000000000001';
SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
SELECT set_config('request.jwt.claim.role','authenticated',true);
SET LOCAL ROLE postgres;
DO $fixture$
DECLARE sid uuid; aid uuid; tid uuid; iid uuid; rid uuid; uid uuid; p jsonb; pr jsonb;
BEGIN
sid:=combat_consumer_private.accept_invitation('50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000002');
SELECT turn_actor_id,exchange_id INTO aid,rid FROM combat_consumer_private.activities WHERE session_id=sid;
SELECT id INTO STRICT tid FROM public.combat_v2_actors WHERE session_id=sid AND id<>aid;
SELECT controller_user INTO uid FROM public.combat_v2_actors WHERE id=aid;
SELECT instance_id INTO STRICT iid FROM combat_spatial.arena_instances WHERE encounter_id=sid AND state='open';
-- Use whichever actor won native initiative: no seed, reroll, selected outcome or turn override.
-- Set synthetic initial positions only; this is not a certified movement transition.
UPDATE combat_spatial.actor_states SET x_m=CASE actor_id WHEN aid THEN 10 ELSE 9 END,
 y_m=CASE actor_id WHEN aid THEN 9 ELSE 10 END,body_version=body_version+1 WHERE instance_id=iid;
PERFORM set_config('request.jwt.claim.sub',uid::text,true);
p:=combat_panel_private.multiplication_actor_profile(aid);
pr:=combat_consumer_private.state_projection('30000000-0000-4000-8000-000000000001');
IF p->>'available' IS DISTINCT FROM 'true' OR pr->>'status' IS DISTINCT FROM 'ready'
 OR combat_panel_private.body_visible_to_viewer(iid,tid) IS DISTINCT FROM true
 OR EXISTS(SELECT 1 FROM combat_spatial.viewer_grants WHERE instance_id=iid AND viewer_principal_id=uid AND subject_actor_id=tid AND can_view_map)
THEN RAISE EXCEPTION 'qa_native_fixture_not_ready';END IF;
INSERT INTO qa_visibility.context SELECT sid,rid,iid,aid,tid,uid,
 (SELECT jsonb_agg(to_jsonb(c) ORDER BY c.id) FROM public.characters c),
 (SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM public.combat_v2_actors a);
END $fixture$;
COMMIT;
